window.EXPL={"공인회2025_60-01-1":{"f":"상인이 영업을 위하여 하는 행위는 상행위로 본다.","w":"상인이 영업을 위하여 하는 행위는 상행위로 간주된다. 추정되는 것은 상인의 행위가 영업을 위한 것이라는 점이다(상법 제47조).","c":"상","v":1},"공인회2025_60-01-2":{"f":"미성년자가 법정대리인의 허락을 얻어 영업을 하는 때에는 등기를 하여야 한다.","w":"미성년자가 법정대리인의 허락을 얻어 영업을 할 때에는 등기를 해야 한다(상법 제6조). 법정대리인이 미성년자를 위하여 영업을 하는 경우도 등기사항이다(제8조).","c":"상","v":1},"공인회2025_60-01-3":{"f":"광물 또는 토석의 채취에 관한 행위는 기본적 상행위에 해당한다.","w":"광물 또는 토석의 채취에 관한 행위는 영업으로 하면 기본적 상행위다(상법 제46조 제18호).","c":"상","v":1},"공인회2025_60-01-4":{"f":"농업협동조합법에 의하여 설립된 조합이 그 사업의 일환으로 조합원이 생산하는 물자의 판매사업을 하는 경우에도 상인으로 인정되지 않는다.","w":"농업협동조합은 조합원의 생산물자 판매사업을 하더라도 영리를 목적으로 하는 단체가 아니어서 상인이 아니라는 것이 판례다.","c":"상","v":1},"공인회2025_60-02-1":{"f":"주식회사를 설립하고자 할 때에는 본점의 소재지를 관할하는 등기소에 상호의 가등기를 신청할 수 있다.","w":"상호의 가등기는 주식회사·유한회사·유한책임회사의 설립 때, 그리고 회사의 상호·목적 변경이나 본점 이전 때에 할 수 있다. 합명회사와 합자회사는 설립 단계에서는 가등기를 신청하지 못한다(상법 제22조의2).","c":"상","v":1},"공인회2025_60-02-2":{"f":"합자조합의 업무집행조합원은 조합 설립 후 2주 내에 조합의 주된 영업소의 소재지에서 등기할 사항을 등기하여야 하고, 등기사항이 변경된 경우에는 2주 내에 변경등기를 하여야 한다.","w":"합자조합은 설립등기와 변경등기 모두 2주 내에 해야 한다(상법 제86조의4 제1항·제2항).","c":"상","v":1},"공인회2025_60-02-3":{"f":"합명회사는 지배인의 선임과 그 대리권의 소멸에 관하여 본점 소재지에서 등기하여야 한다.","w":"회사는 지배인의 선임과 대리권 소멸을 지배인을 둔 곳이 아니라 본점 소재지에서 등기한다(상법 제13조). 회사 아닌 상인은 영업소 소재지에서 등기한다.","c":"상","v":1},"공인회2025_60-02-5":{"f":"상호를 등기한 자가 정당한 사유없이 2년간 상호를 사용하지 아니하는 때에는 이를 폐지한 것으로 본다.","w":"등기한 상호를 정당한 사유 없이 2년간 사용하지 않으면 폐지한 것으로 본다(상법 제26조). 기간은 1년이 아니라 2년이다.","c":"상","v":1},"공인회2026_61-01-2":{"f":"물건을 판매하는 점포의 사용인은 그 판매에 관한 모든 권한이 있는 것으로 본다.","w":"점포 사용인에게 인정되는 권한은 그 점포의 물건 판매에 관한 권한뿐이고, 영업주와 같은 권한을 갖는 것은 아니다(상법 제16조 제1항).","c":"상","v":1},"공인회2026_61-02-2":{"f":"주식회사를 설립하고자 할 때에는 본점의 소재지를 관할하는 등기소에 상호의 가등기를 신청할 수 있다.","w":"합명회사와 합자회사는 설립 때 상호의 가등기를 신청할 수 없다. 가등기는 주식회사·유한회사·유한책임회사의 설립 때와 회사의 상호·목적 변경, 본점 이전 때에 할 수 있다(상법 제22조의2).","c":"상","v":1},"공인회2026_61-05-1":{"f":"상인은 전표 또는 이와 유사한 서류를 5년간 보존하여야 한다.","w":"상업장부와 영업에 관한 중요서류는 10년, 전표 또는 이와 유사한 서류는 5년간 보존한다(상법 제33조 제1항).","c":"상","v":1},"공인회2026_61-05-2":{"f":"미성년자가 법정대리인의 허락을 얻어 영업을 하는 때에는 등기를 하여야 한다.","w":"법정대리인의 허락을 얻어 영업하는 미성년자는 그 사실을 등기해야 한다(상법 제6조).","c":"상","v":1},"공인회2026_61-05-4":{"f":"등기할 사항은 이를 등기하지 아니하면 선의의 제3자에게 대항하지 못한다.","w":"등기하지 않은 사항은 선의의 제3자에게만 대항하지 못한다. 악의의 제3자에게는 등기 없이도 대항할 수 있다(상법 제37조 제1항).","c":"상","v":1},"공인회2026_61-05-5":{"f":"등기할 사항은 이를 등기한 후에도 제3자가 정당한 사유로 이를 알지 못한 때에는 선의의 제3자에게 대항하지 못한다.","w":"등기한 뒤라도 제3자가 정당한 사유로 그 사실을 알지 못했다면 그 제3자에게 대항하지 못한다(상법 제37조 제2항).","c":"상","v":1},"공인회2016_51-01-1":{"f":"지배인은 영업주의 허락 없이 영업주를 위하여 다른 영업을 양수하고 그 영업의 지배인을 선임할 수 없다.","w":"지배인이 선임할 수 있는 사람은 지배인이 아닌 점원 기타 사용인뿐이다(상법 제11조 제2항). 새 영업의 양수도 영업주의 영업 범위를 바꾸는 일이라 영업주의 허락 없이는 하지 못한다.","c":"중","v":1},"공인회2016_51-01-3":{"f":"표현지배인은 재판 외의 행위에 관하여 그 영업소의 지배인과 동일한 권한을 가지며 재판상 행위에 관하여는 그러하지 아니하다.","w":"표현지배인은 재판상 행위에는 지배인과 동일한 권한이 의제되지 않는다(상법 제14조 제1항 단서).","c":"상","v":1},"공인회2016_51-01-4":{"f":"영업주는 상업사용인이 경업금지의무를 위반하여 한 거래행위가 제3자의 계산으로 한 경우 상업사용인에 대하여 그가 얻은 이득의 양도를 청구할 수 있다.","w":"거래가 제3자의 계산으로 이루어졌으면 영업주는 사용인에게 이득의 양도를 청구한다. 제3자를 상대로 청구하는 규정은 없다(상법 제17조 제2항).","c":"상","v":1},"공인회2016_51-01-5":{"f":"주식회사의 지배인은 당해 회사의 감사의 직무를 겸할 수 없으며 지배인은 의사능력을 갖춘 자연인이어야 한다.","w":"감사는 회사의 지배인 기타 사용인을 겸하지 못한다(상법 제411조). 지배인은 법인이 될 수 없고 의사능력 있는 자연인이어야 한다.","c":"상","v":1},"공인회2016_51-03-2":{"f":"판례에 의하면 법원의 등기관은 등기신청요건에 관한 형식적 심사권만 가지고 그 신청사항의 진위여부까지 심사할 실질적 심사권은 가지지 않는다.","w":"등기관의 심사권은 신청서류가 형식적 요건을 갖췄는지 보는 데 그치고 신청 내용이 진실한지까지 따지지 않는다는 것이 판례다.","c":"상","v":1},"공인회2016_51-03-3":{"f":"상인이 등기된 상호를 A, B순으로 이중양도한 경우 선의의 B가 먼저 등기하면 A에게 이를 대항할 수 있다.","w":"등기된 상호의 양도는 등기를 해야 제3자에게 대항할 수 있다(상법 제25조 제2항). 이중양도에서는 먼저 양도 등기를 마친 B가 A에게 대항한다.","c":"상","v":1},"공인회2016_51-03-4":{"f":"자본금액 2,000만원으로 미성년자가 법정대리인의 허락을 얻어 영업을 하는 때에는 등기를 하여야 하고 그 법정대리인이 미성년자를 위하여 영업을 하는 때에도 등기할 사항이다.","w":"허락을 받은 미성년자의 영업(제6조)과 법정대리인이 대신하는 영업(제8조) 모두 등기사항이다. 자본금 1천만원 이상이어서 소상인 특례도 받지 않는다.","c":"상","v":1},"공인회2016_51-03-5":{"f":"상인이 A를 지배인으로 선임하였으나 과실로 B를 지배인으로 선임등기한 경우 B가 지배인이 아니라는 사실을 선의의 제3자에게 대항할 수 없다.","w":"고의 또는 과실로 사실과 다른 사항을 등기한 사람은 그 다름을 선의의 제3자에게 대항하지 못한다(상법 제39조, 부실등기의 공신력).","c":"상","v":1},"공인회2017_52-01-1":{"f":"상인과 비상인 간의 상거래에 있어서 상인인 당사자와 비상인인 당사자 모두에게 상법이 적용된다.","w":"당사자 한쪽에게만 상행위인 일방적 상행위에는 당사자 전원에게 상법이 적용된다(상법 제3조).","c":"상","v":1},"공인회2017_52-01-2":{"f":"공법인의 상행위에 대하여는 법령에 다른 규정이 없는 경우에 한하여 상법이 적용된다.","w":"공법인의 상행위는 법령에 다른 규정이 없을 때에만 상법이 적용된다(상법 제2조). 다른 규정이 있으면 그 규정이 먼저다.","c":"상","v":1},"공인회2017_52-01-3":{"f":"상사에 관하여 상법에 규정이 없으면 상관습법에 의하고 상관습법이 없으면 민법에 의한다.","w":"상사에 관한 적용 순서는 상법, 상관습법, 민법 순이다(상법 제1조). 상관습법이 민법보다 앞선다.","c":"상","v":1},"공인회2017_52-01-5":{"f":"민사회사는 영리를 목적으로 하지만 상행위를 하지 않으므로 민법이 아니라 상법이 적용된다.","w":"회사는 상행위를 하지 않아도 상인으로 의제되므로 민사회사에도 상법이 적용된다(상법 제5조 제2항).","c":"상","v":1},"공인회2017_52-02-1":{"f":"B가 상인이 아니더라도 B는 책임을 부담한다.","w":"명의대여자의 책임은 대여자가 상인인지와 관계없이 성립한다. 영업을 할 것을 허락한 사실과 상대방의 선의·무중과실이 요건이다(상법 제24조).","c":"상","v":1},"공인회2017_52-02-2":{"f":"A가 C와의 거래를 위하여 B의 상호를 사용한 사실이 없었다면 B는 그 거래에 대한 책임을 부담하지 않는다.","w":"명의대여자 책임은 차용자가 대여자의 성명이나 상호를 사용하여 거래했을 때 생긴다. 사용한 사실이 없으면 외관이 없어 책임이 없다(상법 제24조).","c":"상","v":1},"공인회2017_52-02-3":{"f":"B는 영업과 관련없는 A의 불법행위로 인한 채무에 대하여 책임을 부담하지 않지만 어음행위에 의한 채무에 대해서는 그 책임을 부담한다.","w":"명의대여자의 책임은 거래 채무에 관한 것이어서 어음행위로 인한 채무도 포함되고, 영업과 관련 없는 불법행위 채무는 포함되지 않는다.","c":"상","v":1},"공인회2017_52-02-4":{"f":"A의 상업사용인이 아닌 피용자가 B의 상호를 사용하여 D로부터 사업과 무관하게 금원을 차용한 경우 B는 D에 대한 대여금 반환채무에 대하여 책임을 부담하지 않는다.","w":"명의대여자의 책임은 영업상 거래에 관한 것이다. 영업과 무관한 금전 차용에는 책임이 미치지 않는다.","c":"중","v":1},"공인회2017_52-05-1":{"f":"미성년자는 법정대리인의 허락 여부와 관계없이 영업을 개시한 때에 상인자격을 취득한다.","w":"상인자격은 행위능력과 관계없이 영업을 개시한 때 생긴다. 법정대리인이 미성년자를 위하여 영업을 해도 미성년자가 상인이 된다(상법 제8조 제1항).","c":"중","v":1},"공인회2017_52-05-2":{"f":"법정대리인이 피한정후견인을 위하여 영업을 하는 경우 영업을 개시한 때에 피한정후견인의 상인자격이 인정된다.","w":"상인자격은 영업을 실제로 하는 때에 생기고 등기 시점에 생기는 것이 아니다. 한정치산 제도는 폐지되어 현행법에서는 피한정후견인이 해당한다(상법 제8조).","c":"중","v":1},"공인회2017_52-05-3":{"f":"판례에 의하면 공익법인은 설립등기를 하더라도 영리 목적이 없어 상인자격을 취득하지 못한다.","w":"공익법인은 영리를 목적으로 하지 않는 법인이어서 설립등기를 해도 상인이 되지 않는다. 설립등기로 상인자격을 얻는 것은 회사다.","c":"중","v":1},"공인회2017_52-05-5":{"f":"자연인의 상인자격은 그 상인이 사망한 때 상실되며 법인의 상인자격은 청산이 종결된 때 상실된다.","w":"법인의 상인자격은 해산 후 청산이 종결될 때 상실된다. 행정관청에 폐업신고를 하는 것은 상실 시기가 아니다.","c":"중","v":1},"공인회2017_52-06-2":{"f":"판례에 의하면 표현지배인의 행위가 영업주의 영업에 관한 것인가의 여부는 표현지배인의 행위 당시의 주관적인 의사와 관계없이 그 행위의 객관적인 성질에 따라 추상적으로 판단하여야 한다.","w":"행위자의 주관적 의사가 아니라 행위의 객관적 성질을 기준으로 추상적으로 판단한다는 것이 판례다.","c":"상","v":1},"공인회2018_53-05-1":{"f":"개인 상인이 수개의 영업을 영위하는 경우에는 영업별로 각각 다른 상호를 사용할 수 있다.","w":"상호는 영업마다 정할 수 있고, 같은 영업에 대해서만 단일상호를 써야 한다(상법 제21조 참조).","c":"상","v":1},"공인회2018_53-05-2":{"f":"상인의 상호는 영업내용 및 영업주의 실질과 일치하지 않아도 된다.","w":"상법은 상호자유주의를 택해 상호를 자유롭게 정하게 한다(제18조). 다만 타인의 영업으로 오인시킬 부정한 목적의 사용은 금지된다(제23조).","c":"상","v":1},"공인회2018_53-05-4":{"f":"상호를 등기한 자가 정당한 사유없이 2년간 상호를 사용하지 아니하는 때에는 이를 폐지한 것으로 본다.","w":"상호 불사용 간주 기간은 2년이다(상법 제26조).","c":"상","v":1},"공인회2018_53-05-5":{"f":"상인의 상호의 등기 여부는 자유이며 등기하지 않은 상호도 상법에 의한 보호를 받는다.","w":"등기하지 않은 상호도 부정한 목적으로 쓰는 자에게 폐지와 손해배상을 청구할 수 있다(상법 제23조 제2항·제3항). 등기한 상호에는 여기에 더해 같은 특별시·광역시·시·군에서 동종영업의 상호로 등기하지 못하게 하는 효력이 있다(제22조).","c":"중","v":1},"공인회2018_53-06-1":{"f":"합명회사의 상호를 변경하고자 할 때에는 본점의 소재지를 관할하는 등기소에 상호의 가등기를 신청할 수 있다.","w":"합명회사와 합자회사는 설립 단계의 가등기는 불가하고 상호·목적 변경이나 본점 이전 때에는 가등기를 할 수 있다(상법 제22조의2).","c":"상","v":1},"공인회2018_53-08-1":{"f":"A가 운영하는 전기제품 판매점의 점원인 B가 그 판매점에서 외상으로 제품을 구매하였던 C의 사무실을 찾아가 A의 허락없이 C로부터 외상대금을 수령한 경우 C의 B에 대한 외상대금의 변제 행위는 효력이 없다.","w":"점포 사용인에게 간주되는 대리권은 점포 안에서의 물건 판매에 관한 것이다. 점포 밖에서 외상대금을 받는 행위는 그 범위를 벗어나 변제의 효력이 없다.","c":"중","v":1},"공인회2018_53-08-3":{"f":"甲회사의 공동지배인 A, B, C는 D와 물품매매계약을 체결하고 계약금을 공동으로 수령한 후 1개월 뒤 D가 B에게만 잔금을 지급하였더라도 甲회사에 대해서는 잔금지급의 효력이 인정된다.","w":"공동지배인 제도는 대리권의 행사(능동대리)를 공동으로 하게 할 뿐이고, 영업주에 대한 의사표시의 수령은 1인에게만 해도 효력이 있다(상법 제12조 제2항). 이 점에 비추어 B에게 한 지급도 유효한 것으로 본다.","c":"하","v":1},"공인회2018_53-08-4":{"f":"상업사용인은 영업주의 허락이 없으면 다른 회사의 무한책임사원이나 이사가 될 수 없다.","w":"상업사용인은 영업주의 허락 없이 다른 상인의 사용인이 되거나 회사의 무한책임사원·이사가 되지 못한다(상법 제17조 제1항).","c":"상","v":1},"공인회2018_53-08-5":{"f":"영업의 특정한 종류 또는 특정한 사항에 대한 위임을 받은 사용인은 이에 관한 재판 외의 모든 행위를 할 수 있다.","w":"부분적 포괄대리권을 가진 사용인의 권한은 재판 외의 행위에 한한다(상법 제15조 제1항). 재판상 행위는 포함되지 않는다.","c":"상","v":1},"공인회2019_54-01-1":{"f":"회사정관은 원칙적으로 상법의 임의규정에 우선하여 적용된다.","w":"적용 순위는 강행규정이 먼저고, 그 다음이 회사의 정관 등 자치법규, 그 다음이 상법의 임의규정이다.","c":"상","v":1},"공인회2019_54-02-4":{"f":"거래상대방이 영업주에게 하는 의사표시는 공동지배인 중 1인에게 하면 영업주에게 효력이 있다.","w":"공동지배인이 있어도 영업주에 대한 의사표시는 그중 1인에게만 하면 된다(상법 제12조 제2항, 수동대리의 단독).","c":"상","v":1},"공인회2020_55-01-3":{"f":"상업사용인이 경업금지의무를 위반하여 거래를 한 경우, 그 거래가 제3자의 계산으로 한 것인 때에는 영업주는 그 사용인에 대하여 그 거래로 취득한 이득의 양도를 청구할 수 있다.","w":"이득 양도의 청구 상대방은 거래를 한 사용인이다. 제3자에게 청구하지 못한다(상법 제17조 제2항).","c":"상","v":1},"공인회2020_55-02-2":{"f":"회사가 아닌 개인상인의 경우에도 동일한 영업에 대하여 단일상호를 사용하여야 한다.","w":"같은 영업에는 하나의 상호를 써야 하고, 이는 회사와 개인상인 모두에게 적용된다(상법 제21조).","c":"상","v":1},"공인회2021_56-01-4":{"f":"표현지배인은 영업주의 영업에 관한 재판 외의 행위에 관하여 그 영업소의 지배인과 동일한 권한이 있는 것으로 본다.","w":"표현지배인에게는 재판상 행위에 대한 권한이 인정되지 않는다(상법 제14조 제1항 단서).","c":"상","v":1},"공인회2022_57-01-3":{"f":"상인은 영업을 개시한 때와 매년 1회 이상 일정시기에, 회사는 성립한 때와 매 결산기에 회계장부에 의하여 대차대조표를 작성하여야 한다.","w":"회계장부를 먼저 작성하고 이를 바탕으로 대차대조표를 작성한다(상법 제30조 제2항).","c":"상","v":1},"공인회2022_57-04-4":{"f":"명의대여자가 상인이 아니더라도 명의차용자가 상인이면 상법상 명의대여자의 책임이 성립한다.","w":"명의대여자 책임은 대여자의 상인 여부와 관계없이 성립한다. 차용자가 영업을 하고 상대방이 대여 사실을 몰랐다면 성립한다(상법 제24조).","c":"상","v":1},"공인회2023_58-02-1":{"f":"지배인은 영업주의 소송대리인이 될 수 있고 영업과 관련하여 영업주의 소송대리인을 선임할 수 있다.","w":"지배인은 영업에 관한 재판상 행위를 할 수 있으므로 소송대리인으로 선임될 수 있고, 소송대리인을 선임하는 것도 가능하다(상법 제11조 제1항).","c":"상","v":1},"공인회2023_58-02-2":{"f":"부분적 포괄대리권을 가진 상업사용인은 영업의 특정한 종류 또는 특정한 사항에 대하여 위임을 받은 사항에 관한 재판 외의 모든 행위를 할 수 있다.","w":"부분적 포괄대리권을 가진 사용인은 재판 외의 행위만 할 수 있다(상법 제15조 제1항).","c":"상","v":1},"공인회2023_58-02-3":{"f":"표현지배인은 영업주의 영업에 관한 재판 외의 모든 행위에 관하여 그 영업소의 지배인과 동일한 권한이 있는 것으로 본다.","w":"표현지배인은 재판상 행위에 관한 권한이 인정되지 않고 재판 외의 행위에 관해서만 지배인과 동일한 권한이 있는 것으로 본다(상법 제14조).","c":"상","v":1},"공인회2023_58-02-4":{"f":"지배인의 대리권에 대한 제한은 등기 여부와 관계없이 선의의 제3자에게 대항하지 못한다.","w":"지배인의 대리권 제한은 선의의 제3자에게 대항할 수 없고, 등기를 해 두어도 마찬가지다(상법 제11조 제3항).","c":"상","v":1},"공인회2023_58-03-5":{"f":"등기신청인이 제대로 신청하였음에도 등기공무원의 과실로 인하여 사실과 상위한 사항이 등기된 때에는 그 상위를 선의의 제3자에게도 대항할 수 있다.","w":"선의의 제3자에 대한 대항 제한(제39조)은 등기신청인의 고의·과실로 사실과 다르게 등기한 경우에 적용된다. 신청인에게 귀책사유가 없는 등기공무원의 과실에는 적용되지 않는다.","c":"중","v":1},"공인회2024_59-01-5":{"f":"상인이 수인의 지배인에게 공동으로 대리권을 행사하게 한 경우 그 수인의 지배인은 선임등기 여부와 관계없이 지배인의 권한을 갖는다.","w":"지배인의 권한은 선임으로 생긴다. 공동지배인의 등기는 그 사실을 선의의 제3자에게 대항하기 위한 요건이다(상법 제13조, 제37조 제1항).","c":"중","v":1},"공인회2024_59-02-4":{"f":"영업주가 개입권을 행사한 경우에도 상업사용인에 대하여 손해배상의 청구를 할 수 있다.","w":"개입권의 행사는 영업주가 계약을 해지하거나 손해배상을 청구하는 것에 영향을 미치지 않는다(상법 제17조 제3항).","c":"상","v":1},"공인회2017_52-03-5":{"f":"A는 영업양수 후 2년이 경과하더라도 B의 C에 대한 채무를 변제할 책임이 있다.","w":"상호를 계속 사용하는 양수인은 양도인의 영업상 채무를 변제할 책임이 있다(상법 제42조 제1항). 영업양도 후 2년이 지나 소멸하는 것은 양도인의 채무이고 양수인의 책임은 남는다(제45조).","c":"중","v":1},"공인회2018_53-07-3":{"f":"채무인수를 광고한 양수인이 양도인의 영업상 채무에 대하여 변제책임을 부담하는 경우 채권자에 대한 양도인의 채무는 광고 후 2년이 경과하면 소멸한다.","w":"채무인수를 광고한 양수인이 책임을 지는 경우 양도인의 채무는 광고 후 2년이 지나면 소멸한다. 영업양도 후 2년이 기준인 것은 상호를 계속 사용하는 양수인이 책임을 지는 경우다(상법 제45조).","c":"상","v":1},"공인회2019_54-16-1":{"f":"의결권이 없거나 제한되는 주주도 영업양도를 승인하는 주주총회 결의에 반대하는 경우 주식매수청구권이 인정된다.","w":"의결권이 없거나 제한되는 주주도 주식매수청구권을 행사할 수 있다(상법 제374조의2 제1항).","c":"상","v":1},"공인회2019_54-16-2":{"f":"주주는 주주총회 전에 회사에 대하여 서면으로 그 결의에 반대하는 의사를 통지하고 그 총회의 결의일부터 20일 이내에 주식의 종류와 수를 적은 서면으로 주식의 매수를 청구할 수 있다.","w":"반대 통지와 매수청구는 모두 서면으로 하고, 청구 기간은 총회 결의일부터 20일이다(상법 제374조의2 제1항·제2항).","c":"상","v":1},"공인회2019_54-16-3":{"f":"판례에 의하면 주주가 회사에 대하여 주식매수청구를 하면 회사의 승낙 없이 주식에 관한 매매계약이 성립한다.","w":"주식매수청구권은 형성권이어서 청구가 회사에 도달한 때 회사의 승낙 없이 매매계약이 성립한다.","c":"상","v":1},"공인회2019_54-16-4":{"f":"주식매수청구를 받으면 회사는 매수청구기간이 종료하는 날부터 2개월 이내에 그 주식을 매수하여야 한다.","w":"회사의 매수 기한은 매수청구를 받은 날이 아니라 매수청구기간이 종료하는 날부터 2개월이다(상법 제374조의2 제2항).","c":"상","v":1},"공인회2021_56-02-1":{"f":"양수인이 양도인의 상호를 속용하는 경우에는 양도인의 영업으로 인한 채권의 채무자가 선의이며 중대한 과실없이 양수인에게 변제한 때에는 그 효력이 있다.","w":"상호를 속용하는 양수인에게 한 변제는 채무자가 선의·무중과실이면 유효하다(상법 제43조). 채권양도가 있는 것으로 간주되지도 않고 채무자가 반드시 양수인에게 변제해야 하는 것도 아니다.","c":"상","v":1},"공인회2021_56-02-2":{"f":"영업양도에서의 영업은 영리적 목적을 수행하기 위해 결합시킨 조직적 재산으로 개개의 영업용 재산 또는 단순한 영업용 재산만을 가리키는 것이 아니다.","w":"영업양도의 영업은 유기적으로 결합된 조직적 일체로서의 기능적 재산이다. 개별 재산의 합이 아니다.","c":"상","v":1},"공인회2021_56-02-4":{"f":"상호를 속용하는 양수인의 책임에 있어서, 영업으로 인하여 발생한 양도인의 채무에는 영업상의 활동과 관련하여 발생한 불법행위로 인한 채무도 포함된다.","w":"영업상의 활동과 관련하여 발생한 불법행위 채무도 양도인의 영업으로 인한 채무에 포함된다는 것이 판례다.","c":"상","v":1},"공인회2021_56-02-5":{"f":"당사자간에 다른 약정이 없으면 양도인은 10년간 동일한 특별시·광역시·시·군과 인접 특별시·광역시·시·군에서 동종영업을 하지 못한다.","w":"약정이 없으면 영업양도인의 경업금지 기간은 10년이고, 약정으로는 20년을 넘지 않는 범위에서 정할 수 있다(상법 제41조).","c":"상","v":1},"공인회2023_58-18-3":{"f":"주식매수청구를 받으면 해당 회사는 매수청구기간이 종료하는 날부터 2개월 이내에 그 주식을 매수하여야 한다.","w":"회사의 매수 기한은 매수청구기간이 종료하는 날부터 2개월이다(상법 제374조의2 제2항).","c":"상","v":1},"공인회2024_59-03-1":{"f":"양수인이 양도인의 상호를 계속 사용하는 경우 양도인과 양수인이 영업양도를 받은 후 지체없이 양도인의 채무에 대한 책임이 없음을 제3자에 대하여 통지한 때에는 그 통지를 받은 제3자에 대하여 그 채무를 변제할 책임이 없다.","w":"양수인 혼자 통지하는 것으로는 부족하다. 양도인과 양수인이 함께 통지해야 책임이 면제된다(상법 제42조 제2항). 등기로 면할 수도 있다.","c":"상","v":1},"공인회2025_60-04-4":{"f":"당사자가 채권채무의 각 항목을 기재한 계산서를 승인한 후에도 착오나 탈루가 있는 때에는 그 항목에 대하여 이의를 할 수 있다.","w":"계산서를 승인하면 그 항목에 이의를 하지 못하지만 착오나 탈루가 있으면 이의를 할 수 있다(상법 제75조).","c":"상","v":1},"공인회2026_61-08-1":{"f":"익명조합은 당사자의 일방이 상대방의 영업을 위하여 출자하고 상대방은 그 영업으로 인한 이익을 분배할 것을 약정함으로써 그 효력이 생긴다.","w":"익명조합은 약정만으로 성립하는 낙성계약이며 등기가 필요 없다(상법 제78조).","c":"상","v":1},"공인회2026_61-08-2":{"f":"익명조합원이 출자한 금전 기타의 재산은 영업자의 재산으로 본다.","w":"익명조합원의 출자는 영업자의 재산이 된다(상법 제79조).","c":"상","v":1},"공인회2026_61-08-3":{"f":"익명조합원은 금전 기타의 재산만을 출자의 목적으로 할 수 있고 신용 또는 노무는 출자할 수 없다.","w":"익명조합원은 금전 기타 재산만 출자할 수 있고 신용이나 노무는 출자하지 못한다(상법 제86조에 따라 준용되는 제272조).","c":"상","v":1},"공인회2026_61-08-5":{"f":"익명조합원의 파산은 익명조합계약의 종료사유에 해당한다.","w":"익명조합계약은 영업의 폐지·양도, 영업자의 사망·성년후견개시, 영업자나 익명조합원의 파산으로 종료한다(상법 제84조). 익명조합원의 성년후견개시는 종료사유가 아니다.","c":"상","v":1},"공인회2016_51-04-4":{"f":"A가 옆가게 음식점 주인 C에게 금전을 대여한 것은 영업을 위하여 하는 것으로 추정한다.","w":"상인의 행위는 영업을 위한 것으로 추정되며 간주되는 것은 아니다. 반증으로 번복할 수 있다(상법 제47조 제2항).","c":"상","v":1},"공인회2016_51-05-5":{"f":"어음으로 인한 채권채무가 상호계산에 계입된 경우 어음채무자가 변제하지 않으면 당사자는 그 채무의 항목을 상호계산에서 제거할 수 있다.","w":"어음 기타 상업증권의 채무자가 변제하지 않으면 그 항목을 상호계산에서 제거할 수 있다(상법 제73조).","c":"상","v":1},"공인회2016_51-07-3":{"f":"매수인이 상법의 규정대로 목적물을 검사하고 하자통지의무를 이행한 경우 선의의 매도인에게 손해배상 또는 대금감액을 청구할 수 있으며 계약해제도 할 수 있다.","w":"검사·통지의무를 이행하면 민법상 하자담보책임에 따라 해제·대금감액·손해배상을 청구할 수 있다(상법 제69조, 민법 제580조·제575조).","c":"상","v":1},"공인회2017_52-08-2":{"f":"당사자 간 다른 약정이 없는 한 위탁매매인은 매매로 인한 채권이 변제기에 있는 때에는 그 변제를 받을 때까지 위탁자를 위하여 점유하는 물건 또는 유가증권을 유치할 수 있다.","w":"중개인에게는 상법상 특별한 유치권 규정이 없다. 대리상(제91조)·위탁매매인(제111조)·운송주선인(제120조)·운송인(제147조)에게는 유치권이 인정된다.","c":"상","v":1},"공인회2018_53-02-4":{"f":"주채무가 상행위로 인한 것이면 그 보증이 상행위가 아닌 경우에도 보증인은 주채무자와 연대하여 책임을 진다.","w":"보증이 상행위이거나 주채무가 상행위로 인한 것이면 주채무자와 보증인은 연대하여 책임진다(상법 제57조 제2항).","c":"상","v":1},"공인회2019_54-04-1":{"f":"상호계산은 민법상 상계와 유사한 제도로서 상인 간 또는 상인과 비상인 간에 적용된다.","w":"상호계산은 상인 간 또는 상인과 비상인 간에 상시 거래관계가 있을 때 맺을 수 있다(상법 제72조).","c":"상","v":1},"공인회2019_54-04-2":{"f":"상호계산기간은 6개월로 하며 당사자가 특약으로 다르게 정할 수 있다.","w":"기간을 정하지 않으면 6개월이고, 당사자가 달리 정할 수 있다(상법 제74조).","c":"상","v":1},"공인회2019_54-04-3":{"f":"어음·수표로 인한 채권채무도 상호계산에 계입될 수 있다.","w":"어음 기타 상업증권으로 인한 채권채무도 상호계산에 넣을 수 있다. 증권채무자가 변제하지 않으면 그 항목을 제거할 수 있다(상법 제73조).","c":"상","v":1},"공인회2019_54-04-4":{"f":"상호계산제도는 하나의 계산단위로 하는 것이지만 상계로 인한 잔액에 대해 이자가 발생할 수 있다.","w":"상계로 인한 잔액에 대해 채권자는 계산폐쇄일 이후의 법정이자를 청구할 수 있다(상법 제76조 제1항).","c":"상","v":1},"공인회2019_54-05-3":{"f":"상행위로 인하여 생긴 채권을 담보하기 위하여 설정한 질권에 대해서 유질계약은 허용된다.","w":"민법의 유질계약 금지 규정은 상행위로 인한 채권을 담보하는 질권에는 적용되지 않는다(상법 제59조).","c":"상","v":1},"공인회2020_55-05-3":{"f":"매수인의 수령거부로 인하여 매도인이 목적물을 경매한 때에는, 그 대금에서 경매비용을 공제한 잔액을 공탁하여야 하고, 그 전부나 일부를 매매대금에 충당할 수 있다.","w":"매도인은 경매대금에서 경매비용을 뺀 잔액을 공탁하되 그 전부나 일부를 매매대금에 충당할 수 있다(상법 제67조 제3항).","c":"상","v":1},"공인회2020_55-08-5":{"f":"상인이 그 영업에 관하여 수여한 대리권은 본인의 사망으로 인하여 소멸하지 아니한다.","w":"상행위의 위임에 의한 대리권은 본인의 사망으로 소멸하지 않는다(상법 제50조).","c":"상","v":1},"공인회2021_56-07-1":{"f":"상인이 영업을 위하여 하는 행위는 상행위로 본다.","w":"영업을 위한 행위는 상행위로 간주된다. 추정되는 것은 상인의 행위가 영업을 위한 것이라는 점이다(상법 제47조).","c":"상","v":1},"공인회2021_56-07-2":{"f":"상인의 행위는 영업을 위하여 하는 것으로 추정한다.","w":"상인의 행위는 영업을 위한 것으로 추정될 뿐이어서 반증으로 번복할 수 있다(상법 제47조 제2항).","c":"상","v":1},"공인회2021_56-07-3":{"f":"상행위로 인하여 생긴 채권을 담보하기 위한 유질계약은 허용되고, 이 경우 질권설정자는 반드시 상인이어야 하는 것은 아니다.","w":"상법 제59조는 질권설정자가 상인일 것을 요구하지 않는다. 상행위로 생긴 채권을 담보하는 질권이면 유질계약이 허용된다.","c":"상","v":1},"공인회2021_56-07-4":{"f":"상인이 그 영업범위 내에서 이자를 약정하지 않고 타인을 위하여 금전을 체당하였을 때에는 체당한 날 이후의 법정이자를 청구할 수 있다.","w":"상인이 영업범위 내에서 타인을 위해 금전을 체당하면 이자 약정이 없어도 그날 이후의 법정이자를 청구할 수 있다(상법 제55조 제2항).","c":"상","v":1},"공인회2021_56-08-1":{"f":"익명조합은 당사자의 일방이 상대방의 영업을 위하여 출자하고 상대방은 그 영업으로 인한 이익을 분배할 것을 약정함으로써 그 효력이 생긴다.","w":"익명조합은 영업으로 생기는 이익을 분배하기로 하는 계약이다(상법 제78조). 손실 분담이 성립 요소는 아니다.","c":"상","v":1},"공인회2022_57-02-4":{"f":"채권자의 지점에서의 상거래로 인한 채무이행의 장소가 그 행위의 성질 또는 당사자의 의사표시에 의하여 특정되지 아니한 경우, 특정물 인도 외의 채무이행은 그 지점을 이행장소로 본다.","w":"지점 거래의 이행장소 간주는 특정물 인도 외의 채무에 대해서다. 특정물 인도 채무는 행위 당시 그 물건이 있던 장소에서 이행한다(상법 제56조, 민법 제467조).","c":"상","v":1},"공인회2022_57-03-3":{"f":"채무자 소유의 부동산에 관하여 이미 선행저당권이 설정되어 있는 상태에서 일반상사유치권이 성립한 경우, 그 상사유치권자는 선행저당권자에 대한 관계에서는 상사유치권으로 대항할 수 없다.","w":"선행저당권이 있는 부동산에 뒤늦게 성립한 상사유치권으로는 저당권자에게 대항하지 못한다는 것이 판례다(대법원 2013.2.28. 선고 2010다57350).","c":"상","v":1},"공인회2023_58-05-2":{"f":"채권자의 지점에서의 거래로 인한 채무이행의 장소가 그 행위의 성질 또는 당사자의 의사표시에 의하여 특정되지 아니한 경우 특정물 인도 외의 채무는 그 지점을 이행장소로 본다.","w":"특정물 인도 채무는 지점이 아니라 행위 당시 그 물건이 있던 장소에서 이행한다(상법 제56조).","c":"상","v":1},"공인회2024_59-04-5":{"f":"상법 제69조의 경우에 매수인이 계약을 해제한 때에는 매도인의 비용으로 매매의 목적물을 보관 또는 공탁하여야 한다.","w":"매수인은 계약을 해제한 경우 매도인의 비용으로 목적물을 보관하거나 공탁해야 한다(상법 제70조 제1항). 비용은 매도인이 부담한다.","c":"상","v":1},"공인회2025_60-05-1":{"f":"운송인은 송하인의 청구에 의하여 화물상환증을 교부하여야 한다.","w":"화물상환증은 송하인의 청구가 있을 때 교부한다(상법 제128조). 수하인이 청구하는 것이 아니다.","c":"상","v":1},"공인회2025_60-05-2":{"f":"화물상환증은 기명식인 경우에도 배서에 의하여 양도할 수 있다.","w":"화물상환증은 법률상 당연한 지시증권이어서 기명식이라도 배서로 양도할 수 있다. 배서금지의 뜻을 적은 경우에만 예외다(상법 제130조).","c":"상","v":1},"공인회2025_60-05-3":{"f":"화물상환증이 발행된 경우에는 운송인과 송하인 사이에 화물상환증에 적힌 대로 운송계약이 체결되고 운송물을 수령한 것으로 추정한다.","w":"송하인과 운송인 사이에서는 추정에 그친다. 선의의 소지인에 대해서는 적힌 대로 수령한 것으로 본다(간주, 상법 제131조).","c":"상","v":1},"공인회2025_60-05-5":{"f":"화물상환증을 선의로 취득한 소지인에 대하여 운송인은 화물상환증에 적힌 대로 운송물을 수령한 것으로 보아 화물상환증에 적힌 바에 따라 운송인으로서 책임을 진다.","w":"선의의 소지인에게는 추정이 아니라 수령한 것으로 간주하여 반증을 허용하지 않는다(상법 제131조 제2항).","c":"상","v":1},"공인회2025_60-06-1":{"f":"수하인이 운송물을 수령할 수 없는 경우 운송인은 수하인에 대하여 상당한 기간을 정하여 운송물의 수령을 최고한 후 다시 송하인에 대하여 운송물의 처분에 관한 지시를 최고하여야 운송물을 경매할 수 있다.","w":"수하인이 수령을 거부하거나 수령할 수 없으면 운송인은 수하인에게 수령을 최고한 뒤 송하인에게 처분 지시를 최고해야 경매할 수 있고, 송하인에 대한 최고는 생략하지 못한다(상법 제143조, 제142조 제2항).","c":"상","v":1},"공인회2025_60-07-3":{"f":"공중접객업자는 고객으로부터 임치받지 아니한 고객의 휴대물에 대하여 책임이 없음을 알린 때에도 그 사용인의 과실로 인하여 훼손되었을 경우 그 휴대물에 대한 손해를 배상할 책임이 있다.","w":"휴대물에 대하여 책임이 없다고 게시했더라도 공중접객업자는 책임을 면하지 못한다(상법 제152조 제3항).","c":"상","v":1},"공인회2026_61-06-1":{"f":"금융리스물건의 공급자는 공급계약에서 정한 시기에 그 물건을 금융리스이용자에게 인도하여야 한다.","w":"공급자는 금융리스업자가 아니라 금융리스이용자에게 물건을 인도한다(상법 제168조의4 제1항).","c":"상","v":1},"공인회2026_61-07-1":{"f":"자기의 명의로 물건운송의 주선을 영업으로 하는 자를 운송주선인이라 한다.","w":"운송주선인은 물건운송의 주선만 영업으로 하는 사람이고 여객운송의 주선은 포함되지 않는다(상법 제114조).","c":"상","v":1},"공인회2026_61-07-3":{"f":"운송주선인이 위탁자가 지정한 가액보다 염가로 운송계약을 체결한 경우 그 차액은 다른 약정이 없으면 위탁자의 이익으로 한다.","w":"위탁자가 지정한 가액보다 싸게 운송계약을 맺어 생긴 차액은 다른 약정이 없으면 위탁자의 이익으로 한다(상법 제123조에 따라 준용되는 제106조 제2항).","c":"상","v":1},"공인회2026_61-07-4":{"f":"여객운송인은 여객으로부터 인도를 받은 수하물에 관하여 운임을 받지 아니한 경우에도 물건운송인과 동일한 책임이 있다.","w":"여객으로부터 수하물을 인도받으면 운임을 따로 받지 않아도 물건운송인과 같은 책임을 진다(상법 제149조 제1항).","c":"상","v":1},"공인회2026_61-07-5":{"f":"운송인의 책임은 수하인이 운송물을 수령한 날로부터 1년을 경과하면 소멸시효가 완성한다.","w":"운송인의 책임은 수하인이 운송물을 수령한 날부터 1년이 지나면 소멸한다. 6개월이 아니다(상법 제121조, 제147조).","c":"상","v":1},"공인회2016_51-02-2":{"f":"가맹상이 그 영업을 양도하기 위하여 가맹업자에게 동의를 요구하는 경우 가맹업자는 특별한 사유가 없으면 동의를 거절할 수 없다.","w":"가맹업자는 특별한 사유가 없으면 가맹상의 영업양도 동의를 거절하지 못한다(상법 제168조의9).","c":"상","v":1},"공인회2016_51-06-3":{"f":"A의 경과실로 물건이 전부 멸실한 경우 A의 B에 대한 채무불이행책임에는 운송인의 정액배상책임규정이 준용되지 않는다.","w":"운송주선인의 손해배상책임은 상법 제115조에 따른다. 운송인 규정 중 운송주선업에 준용되는 것은 제136조·제140조·제141조뿐이어서 제137조의 정액배상 규정은 준용되지 않는다(제124조).","c":"상","v":1},"공인회2016_51-08-1":{"f":"대리상이 본인의 허락없이 자기의 계산으로 경업거래를 한 경우 본인이 개입권을 행사하면 그 거래를 본인의 계산으로 한 것으로 볼 수 있으나 대리상의 거래상대방에 대하여 직접 계약상의 권리를 취득하는 것은 아니다.","w":"개입권은 거래의 경제적 효과를 본인에게 돌리는 권리이고 본인이 상대방과 직접 계약관계를 갖게 되는 것은 아니다(상법 제89조 제2항).","c":"상","v":1},"공인회2016_51-08-3":{"f":"위탁매매인이 개입권을 행사한 경우에도 위탁매매인은 위탁자에게 보수를 청구할 수 있다.","w":"개입권을 행사해도 위탁매매인은 위탁자에게 보수를 청구할 수 있다(상법 제107조 제2항).","c":"상","v":1},"공인회2016_51-08-4":{"f":"운송주선인이 개입권을 행사하는 데에는 운임에 관한 거래소의 시세가 있을 필요가 없다.","w":"거래소 시세가 있는 물건이어야 개입할 수 있는 것은 위탁매매인이다. 운송주선인의 개입권에는 그런 제한이 없다(상법 제116조).","c":"상","v":1},"공인회2016_51-08-5":{"f":"중개인이 임의로 당사자 일방의 성명 또는 상호를 상대방에게 표시하지 않은 경우 중개인은 그 상대방에 대하여 이행할 책임이 있다.","w":"이 경우 중개인은 당사자가 되는 것이 아니라 상대방에 대하여 이행책임을 진다(상법 제99조).","c":"상","v":1},"공인회2017_52-04-1":{"f":"화물상환증이 발행된 때에는 운송인과 송하인 사이에 화물상환증에 적힌 대로 운송계약이 체결되고 운송물을 수령한 것으로 추정한다.","w":"송하인과 운송인 사이에서는 추정이다. 선의의 소지인에 대해서만 적힌 대로 수령한 것으로 본다(상법 제131조).","c":"상","v":1},"공인회2017_52-04-2":{"f":"화물상환증이 발행되지 않은 때에는 송하인이 운송인에 대하여 운송의 중지, 운송물의 반환 기타의 처분을 청구할 수 있다.","w":"처분청구권자는 송하인이다. 화물상환증이 발행되었으면 그 소지인이 행사한다(상법 제139조 제1항). 수하인은 해당하지 않는다.","c":"상","v":1},"공인회2017_52-04-4":{"f":"운송인이 화물상환증과 상환하지 않고 운송물을 인도한 때에는 정당한 화물상환증 소지인에 대하여 채무불이행으로 인한 손해배상책임을 부담한다.","w":"화물상환증을 받지 않고 인도하면 정당한 소지인에 대해 손해배상책임을 진다. 증권과 상환해야 운송물을 인도할 의무가 있기 때문이다(상법 제129조).","c":"상","v":1},"공인회2017_52-04-5":{"f":"화물상환증이 발행된 때에는 운송물에 관한 처분은 화물상환증으로써 하여야 하며 화물상환증이 기명식인 경우에도 배서에 의해 양도할 수 있다.","w":"화물상환증은 기명식이라도 배서금지 기재가 없으면 배서로 양도할 수 있다(상법 제130조).","c":"상","v":1},"공인회2017_52-07-2":{"f":"A가 운송물의 종류 및 가액을 명시한 때에는 운송물이 전부멸실된 경우 B의 손해배상액은 명시가액을 최고한도로 하여 인도할 날의 도착지 가격에 의한다.","w":"전부 멸실의 손해배상액은 인도할 날의 도착지 가격이 기준이다. 계약 체결일의 출발지 가격이 기준이 되는 것이 아니다(상법 제137조 제1항).","c":"상","v":1},"공인회2017_52-07-3":{"f":"판례에 의하면 A는 B의 하도급을 받아 물건을 운송하는 자에게까지 운송물의 종류 및 가액을 명시하지 않아도 B에게 운송물에 대한 손해배상책임을 물을 수 있다.","w":"고가물의 종류와 가액은 송하인이 계약 상대방인 운송인에게 명시하면 되고, 그 운송인이 다시 맡긴 하수급 운송인에게까지 명시할 필요는 없다는 것이 판례다.","c":"중","v":1},"공인회2017_52-07-4":{"f":"A가 운송물의 종류 및 가액을 명시하지 않은 때에는 운송물이 연착된 경우 B의 손해배상액은 운송물을 인도할 날의 도착지 가격에 의한다.","w":"연착의 손해배상액은 인도할 날의 도착지 가격을 기준으로 한다(상법 제137조 제1항). 인도한 날을 기준으로 하는 것은 일부 멸실·훼손의 경우다.","c":"상","v":1},"공인회2017_52-07-5":{"f":"판례에 의하면 A가 운송물의 종류 및 가액을 명시하지 않은 경우 B는 채무불이행으로 인한 손해배상책임은 지지 않지만 불법행위로 인한 손해배상책임은 질 수 있다.","w":"고가물을 명시하지 않으면 운송인은 운송계약상 책임을 면한다(상법 제136조). 이 면책이 불법행위책임에도 미치는지는 판례 근거를 확인하지 못했다.","c":"하","v":1},"공인회2018_53-03-4":{"f":"운송주선인이 송하인의 지정가액보다 염가로 운송계약을 체결한 경우 그 차액은 다른 약정이 없으면 위탁자의 이익으로 한다.","w":"지정가액보다 싸게 운송계약을 맺어 생긴 차액은 다른 약정이 없으면 위탁자의 이익으로 한다(상법 제123조에 따라 준용되는 제106조 제2항).","c":"상","v":1},"공인회2019_54-03-2":{"f":"위탁매매인이 거래소의 시세가 있는 물건의 매수를 위탁받은 경우에는 직접 그 매도인이 될 수 있으며 이 경우 매매대가는 위탁매매인이 매매의 통지를 발송한 때의 거래소의 시세에 따른다.","w":"개입권을 행사할 때의 매매대가는 위탁매매인이 매매의 통지를 발송한 때의 거래소 시세로 정한다(상법 제107조 제1항).","c":"상","v":1},"공인회2019_54-07-2":{"f":"금융리스물건이 공급계약에서 정한 시기와 내용에 따라 공급되지 아니한 경우 금융리스이용자는 직접 공급자에 대하여 공급계약의 내용에 적합한 금융리스물건의 인도를 청구할 수 있다.","w":"이용자는 공급자에게 직접 손해배상이나 적합한 물건의 인도를 청구할 수 있다(상법 제168조의4 제2항).","c":"상","v":1},"공인회2019_54-08-5":{"f":"계약의 존속기간에 대한 약정이 없는 경우 A와 B는 2개월 전에 예고한 후 계약을 해지할 수 있다.","w":"대리상계약은 존속기간의 약정이 없을 때 2개월 전 예고로 해지할 수 있다(상법 제92조 제1항). 기간을 약정했다면 부득이한 사정이 있을 때만 해지할 수 있다.","c":"상","v":1},"공인회2020_55-04-3":{"f":"중개인에 의해 당사자 간에 계약이 성립된 때에는 중개인은 지체없이 결약서를 작성하여 기명날인 또는 서명한 후 각 당사자에게 교부하여야 한다.","w":"결약서는 당사자가 아니라 중개인이 지체 없이 작성해 기명날인 또는 서명한 뒤 각 당사자에게 교부한다(상법 제96조 제1항).","c":"상","v":1},"공인회2020_55-07-4":{"f":"공중접객업자는 고객의 휴대물에 대하여 책임이 없음을 알린 경우에도 그 물건의 멸실이나 훼손으로 인한 손해에 대하여 배상책임을 면하지 못한다.","w":"책임이 없다고 게시했더라도 면책되지 않는다(상법 제152조 제3항).","c":"상","v":1},"공인회2021_56-03-5":{"f":"일정한 상인을 위해 상시 그 거래의 대리 또는 중개를 영업으로 하는 자가 상법상 대리상이며, 상인이 아닌 자를 위한 경우는 해당하지 않는다.","w":"대리상은 일정한 상인을 위하여 상업사용인이 아니면서 상시 거래의 대리 또는 중개를 하는 자다(상법 제87조). 본인이 상인이어야 한다.","c":"상","v":1},"공인회2021_56-04-2":{"f":"여객운송인은 여객으로부터 인도를 받은 수하물에 관하여는 그 수하물에 관한 운임을 받지 아니한 경우에도 물건운송인과 동일한 책임이 있다.","w":"인도받은 수하물에는 운임을 받았는지와 관계없이 물건운송인과 같은 책임을 진다(상법 제149조 제1항).","c":"상","v":1},"공인회2021_56-05-2":{"f":"선의의 운송주선인의 책임은 수하인이 운송물을 수령한 날로부터 1년을 경과하면 소멸시효가 완성한다.","w":"기산점은 운송인이 수령한 날이 아니라 수하인이 운송물을 수령한 날이다. 전부 멸실이면 운송물을 인도할 날부터 1년이다(상법 제121조).","c":"상","v":1},"공인회2021_56-06-4":{"f":"운송인과 송하인 사이에는 화물상환증에 적힌 대로 운송계약이 체결되고 운송물을 수령한 것으로 추정한다.","w":"송하인과 운송인 사이에서는 추정되는 데 그치고 반증이 가능하다(상법 제131조 제1항).","c":"상","v":1},"공인회2022_57-05-3":{"f":"중개인은 당사자가 즉시 이행을 해야 하는 경우에는 각 당사자로 하여금 결약서에 기명날인 또는 서명하게 한 후 그 상대방에게 교부하지 않아도 된다.","w":"당사자가 즉시 이행해야 하는 경우에는 각 당사자의 기명날인 또는 서명을 받아 상대방에게 교부하는 절차가 필요 없다(상법 제96조 제2항). 중개인이 결약서를 작성해 각 당사자에게 교부할 의무(제1항)는 그대로 있다.","c":"상","v":1},"공인회2022_57-06-2":{"f":"위탁매매인이 위탁자로부터 받은 물건은 위탁자와 위탁매매인의 채권자간의 관계에서는 이를 위탁자의 소유로 본다.","w":"위탁자의 소유로 보는 것은 위탁매매인의 채권자와의 관계에서다. 위탁자의 채권자와 위탁매매인 사이의 문제가 아니다(상법 제103조).","c":"상","v":1},"공인회2022_57-07-5":{"f":"창고증권이 발행된 경우, 당사자가 임치기간을 정하지 아니한 때에는 창고업자는 임치물을 받은 날로부터 6월을 경과한 후에는 언제든지 이를 반환할 수 있다.","w":"임치기간의 약정이 없으면 창고업자는 임치물을 받은 날부터 6개월이 지난 뒤 언제든지 반환할 수 있다(상법 제163조 제1항). 반환하려면 2주 전에 예고해야 한다(같은 조 제2항).","c":"상","v":1},"공인회2022_57-08-2":{"f":"금융리스물건수령증을 발급한 경우에는 금융리스계약 당사자 사이에 적합한 금융리스물건이 수령된 것으로 추정한다.","w":"수령증을 발급하면 적합한 물건이 수령된 것으로 추정되며, 반증이 가능하다(상법 제168조의3 제3항).","c":"상","v":1},"공인회2022_57-08-3":{"f":"금융리스이용자는 금융리스물건을 수령한 이후에는 선량한 관리자의 주의로 금융리스물건을 유지 및 관리하여야 한다.","w":"수령한 뒤 금융리스물건을 선량한 관리자의 주의로 유지·관리할 의무는 금융리스이용자가 진다(상법 제168조의3 제4항).","c":"상","v":1},"공인회2022_57-08-4":{"f":"금융리스이용자의 책임 있는 사유로 금융리스계약을 해지하는 경우에는 금융리스업자는 금융리스이용자에 대하여 잔존 금융리스료 상당액의 일시 지급 또는 금융리스물건의 반환을 청구할 수 있다.","w":"이용자의 책임 있는 사유로 해지하면 잔존 리스료의 일시 지급이나 물건 반환을 청구하는 사람은 금융리스업자다(상법 제168조의5 제1항).","c":"상","v":1},"공인회2022_57-08-5":{"f":"금융리스물건이 공급계약에서 정한 시기와 내용에 따라 공급되지 아니한 경우 금융리스이용자는 공급자에게 직접 손해배상을 청구할 수 있다.","w":"이용자는 공급자에게 직접 손해배상을 청구할 수 있다(상법 제168조의4 제2항).","c":"상","v":1},"공인회2023_58-07-1":{"f":"대리상이 거래의 대리 또는 중개를 한 때에는 본인의 청구 여부와 관계없이 지체없이 본인에게 그 통지를 발송하여야 한다.","w":"대리상의 통지의무는 본인의 청구와 무관하게 거래의 대리·중개를 한 때 곧바로 생긴다(상법 제88조).","c":"상","v":1},"공인회2023_58-07-2":{"f":"대리상은 본인의 허락없이 자기나 제3자의 계산으로 본인의 영업부류에 속한 거래를 하거나 동종영업을 목적으로 하는 회사의 무한책임사원 또는 이사가 되지 못한다.","w":"대리상의 겸업금지 범위는 동종영업을 목적으로 하는 회사의 무한책임사원·이사까지이고, 다른 상인의 사용인이 되는 것은 금지대상이 아니다(상법 제89조 제1항).","c":"상","v":1},"공인회2023_58-07-3":{"f":"위탁매매인이 거래소의 시세가 있는 물건의 매매를 위탁받은 경우 직접 그 매도인이나 매수인이 되는 때의 매매 대가는 위탁매매인이 매매의 통지를 발송한 때의 거래소의 시세에 따른다.","w":"기준 시점은 위탁자가 통지를 받은 때가 아니라 위탁매매인이 매매의 통지를 발송한 때다(상법 제107조 제1항).","c":"상","v":1},"공인회2023_58-07-5":{"f":"대리상계약의 존속기간 중에 본인이 사망하더라도 대리상계약은 종료되지 않는다.","w":"상행위의 위임에 의한 대리권은 본인의 사망으로 소멸하지 않으므로 대리상계약도 본인 사망으로 끝나지 않는다(상법 제50조).","c":"중","v":1},"공인회2023_58-08-1":{"f":"금융리스이용자는 중대한 사정변경으로 인하여 금융리스물건을 계속 사용할 수 없는 경우에는 3개월 전에 예고하고 금융리스계약을 해지할 수 있다.","w":"중대한 사정변경으로 해지하려면 3개월 전에 예고해야 하고, 해지로 금융리스업자에게 생긴 손해도 배상해야 한다(상법 제168조의5 제3항).","c":"상","v":1},"공인회2024_59-06-5":{"f":"운송주선인이 위탁자의 청구에 의하여 화물상환증을 작성한 때에는 직접운송하는 것으로 본다.","w":"운송주선인이 위탁자의 청구로 화물상환증을 작성하면 직접운송하는 것으로 본다(상법 제116조 제2항).","c":"상","v":1},"공인회2024_59-07-1":{"f":"운송인은 수하물이 도착지에 도착한 날로부터 10일 내에 여객이 그 인도를 청구하지 아니한 때에는 상당한 기간을 정하여 여객에게 최고한 후 수하물을 경매할 수 있다.","w":"수하물이 도착한 날부터 10일 내에 인도 청구가 없으면 운송인은 상당한 기간을 정해 최고한 뒤 경매할 수 있다. 최고와 통지 없이 경매할 수 있는 것은 주소나 거소를 알 수 없는 여객의 경우뿐이다(상법 제149조 제2항, 제67조).","c":"하","v":1},"공인회2024_59-08-4":{"f":"창고업자는 임치물의 보관기간 경과 후에는 임치물을 출고하는 때가 아니어도 보관료 기타의 비용과 체당금의 지급을 청구할 수 있다.","w":"원칙은 출고할 때 청구하지만 보관기간이 지난 뒤에는 출고 전에도 청구할 수 있다(상법 제162조).","c":"상","v":1},"공인회2025_60-09-3":{"f":"사원이 회사성립 후에 사원으로 가입한 경우 그 가입 전에 생긴 회사채무에 대하여도 책임이 있다.","w":"가입한 사원은 가입 전에 생긴 회사채무에 대해서도 다른 사원과 같은 책임을 진다(상법 제213조).","c":"상","v":1},"공인회2025_60-10-3":{"f":"유한책임사원은 다른 사원의 동의없이 자기 또는 제3자의 계산으로 회사의 영업부류에 속하는 거래를 할 수 있다.","w":"경업금지는 무한책임사원에게만 적용되고 유한책임사원에게는 적용되지 않는다(상법 제275조).","c":"상","v":1},"공인회2025_60-11-2":{"f":"사원은 그 지분의 전부 또는 일부를 다른 사원 또는 제3자에게 양도할 수 있으나 정관으로 지분양도를 제한할 수 있다.","w":"유한회사 지분은 원칙적으로 자유롭게 양도할 수 있고, 정관으로 제한하는 방식이다(상법 제556조). 사원총회 특별결의가 요건이 아니다.","c":"상","v":1},"공인회2026_61-09-5":{"f":"청산인이 회사의 영업의 전부 또는 일부를 양도함에는 총사원 과반수의 결의가 있어야 한다.","w":"합명회사 청산인이 영업 전부 또는 일부를 양도할 때는 총사원 과반수의 결의를 받는다(상법 제257조).","c":"상","v":1},"공인회2016_51-31-1":{"f":"합명회사의 원시정관은 공증인의 인증이 없어도 법적 효력이 발생한다.","w":"공증인의 인증을 받아야 효력이 생기는 것은 주식회사의 원시정관이다(상법 제292조). 합명회사의 정관은 사원 전원이 기명날인하거나 서명하면 된다.","c":"상","v":1},"공인회2016_51-31-2":{"f":"미성년자 또는 한정치산자가 법정대리인의 동의 없이 설립행위에 참가한 경우 이는 회사설립취소의 소의 원인이 된다.","w":"행위능력 제한을 이유로 한 설립행위 취소는 설립취소의 소로 주장할 수 있다(상법 제184조).","c":"상","v":1},"공인회2016_51-31-3":{"f":"업무집행에 관한 의사결정은 원칙적으로 총사원의 과반수로 정하고 따로 업무집행사원을 정한 때에는 업무집행사원의 과반수로 정한다.","w":"업무집행 결정은 총사원 과반수로 하고, 업무집행사원을 따로 정했으면 업무집행사원 과반수로 한다(상법 제195조, 민법 제706조 제2항).","c":"상","v":1},"공인회2016_51-31-5":{"f":"정관으로 회사의 존립기간을 정하지 아니하거나 어느 사원의 종신까지 존속할 것을 정한 경우에는 사원은 원칙적으로 6월 전에 예고하고 영업연도말에 퇴사할 수 있다.","w":"존립기간을 정하지 않은 경우 퇴사는 영업연도말에 하고, 6개월 전에 예고해야 한다. 부득이한 사유가 있을 때만 언제든 퇴사할 수 있다(상법 제217조).","c":"상","v":1},"공인회2016_51-32-1":{"f":"유한책임회사의 사원과 유한회사의 사원은 모두 노무나 신용의 출자가 허용되지 않는다.","w":"유한책임회사도 사원은 금전 그 밖의 재산만 출자할 수 있다(상법 제287조의4 제1항).","c":"상","v":1},"공인회2016_51-32-2":{"f":"유한책임회사의 사원과 유한회사의 사원은 모두 출자의 전액을 현실적으로 납입하여야 한다.","w":"유한책임회사 사원은 설립등기 때까지 출자를 전부 이행해야 하고(상법 제287조의4 제2항), 유한회사도 이사가 사원에게 출자 전액을 납입하게 해야 한다(제548조 제1항).","c":"상","v":1},"공인회2016_51-32-3":{"f":"사원이 사망한 경우 유한책임회사에서는 사망이 퇴사 원인이어서 원칙적으로 지분이 상속되지 않으나 유한회사의 경우에는 지분의 상속이 허용된다.","w":"유한책임회사에서는 사원의 사망이 퇴사원인이어서 정관에 승계 규정이 없으면 상속인이 사원이 되지 못한다(상법 제287조의25, 제287조의26). 유한회사의 지분은 상속할 수 있다(제556조).","c":"상","v":1},"공인회2016_51-32-4":{"f":"유한책임회사의 사원이 성년후견개시 심판을 받으면 퇴사사유가 되지만 유한회사의 사원에게는 퇴사제도가 없어 퇴사사유가 되지 않는다.","w":"유한책임회사는 합명회사의 퇴사원인 규정을 준용하므로 성년후견개시(옛 금치산)가 퇴사원인이다(상법 제287조의25, 제218조 제4호). 유한회사에는 퇴사 제도가 없다.","c":"상","v":1},"공인회2017_52-18-2":{"f":"합자회사의 유한책임사원이 사망한 경우 정관에 정함이 없어도 그 상속인은 그 지분을 승계하여 사원이 된다.","w":"합자회사의 유한책임사원은 사망해도 퇴사하지 않고 상속인이 지분을 승계한다(상법 제283조 제1항).","c":"상","v":1},"공인회2017_52-18-3":{"f":"유한책임회사의 사원은 업무를 집행하는 사원이 없는 경우에는 사원 전원의 동의를 받아야 그 지분의 전부 또는 일부를 타인에게 양도할 수 있다.","w":"업무를 집행하는 사원이 없으면 지분양도에 사원 전원의 동의가 필요하다(상법 제287조의8 제2항 단서).","c":"상","v":1},"공인회2017_52-18-4":{"f":"유한회사의 자본금 총액의 100분의 3 이상에 해당하는 출자좌수를 가진 사원은 이사가 법령 또는 정관에 위반한 행위를 하여 회사에 회복할 수 없는 손해가 생길 염려가 있는 경우에는 회사를 위하여 이사에 대하여 그 행위를 유지할 것을 청구할 수 있다.","w":"유지청구권은 소수사원권이다. 각 사원이 단독으로 행사하지 못하고 자본금 3% 이상 출자좌수가 필요하다(상법 제564조의2).","c":"상","v":1},"공인회2017_52-18-5":{"f":"상법상의 외국회사는 다른 법률의 적용에 있어서는 법률에 다른 규정이 있는 경우 외에는 대한민국에서 성립된 동종 또는 가장 유사한 회사로 본다.","w":"외국회사는 주식회사로 간주되는 것이 아니라 대한민국에서 성립된 동종 또는 가장 유사한 회사로 본다(상법 제621조).","c":"상","v":1},"공인회2017_52-22-1":{"f":"이사가 수인인 경우에 정관에 다른 정함이 없으면 사원총회에서 회사를 대표할 이사를 선정하여야 한다.","w":"유한회사에는 이사회가 없다. 대표이사는 정관 또는 사원총회가 정한다(상법 제562조).","c":"상","v":1},"공인회2017_52-22-2":{"f":"이사는 감사가 있는 경우에는 감사의 승인이 있는 때에 한하여 자기 또는 제3자의 계산으로 회사와 거래를 할 수 있다.","w":"감사가 있으면 감사의 승인, 감사가 없으면 사원총회의 승인을 받아야 한다(상법 제564조 제3항).","c":"상","v":1},"공인회2017_52-22-4":{"f":"유한회사는 사원총회의 특별결의에 의하여 자본금을 증가할 수 있으며 본점소재지에서 자본금증가의 등기를 한 때에 효력이 생긴다.","w":"유한회사의 자본금 증가는 결의 때가 아니라 본점소재지에서 증가 등기를 해야 효력이 생긴다(상법 제592조).","c":"상","v":1},"공인회2017_52-22-5":{"f":"자본금증가 후에 아직 인수되지 아니한 출자가 있는 때에는 이사와 감사가 인수되지 아니한 출자를 공동으로 인수한 것으로 본다.","w":"자본금 증가 후 인수되지 않은 출자는 이사와 감사가 공동으로 인수한 것으로 본다(상법 제594조 제1항). 결의에 동의한 사원이 지는 책임은 현물출자 등의 부족액 지급책임이다(제593조).","c":"상","v":1},"공인회2018_53-23-2":{"f":"합명회사 사원의 입사는 정관기재사항으로서 입사의 시점은 그 변경내용을 등기한 때가 아니라 총사원의 동의가 있는 때로 본다.","w":"입사는 총사원의 동의로 정관을 변경하는 때에 효력이 생긴다. 변경등기는 효력 요건이 아니다.","c":"상","v":1},"공인회2018_53-28-1":{"f":"무한책임사원은 다른 사원 전원의 동의가 있으면 그 지분의 전부 또는 일부를 타인에게 양도할 수 있다.","w":"합자회사 무한책임사원의 지분양도에는 다른 사원 전원의 동의가 필요하다(상법 제269조, 제197조). 일부 무한책임사원의 동의로는 부족하다.","c":"상","v":1},"공인회2018_53-28-2":{"f":"유한책임사원은 영업연도말에 영업시간 내에 한하여 회사의 회계장부와 대차대조표 및 기타의 서류를 열람할 수 있고 회사의 업무와 재산상태를 검사할 수 있다.","w":"평상시 검사권은 영업연도말에 영업시간 내에 한하고, 중요한 사유가 있으면 법원의 허가를 얻어 언제든지 검사할 수 있다(상법 제277조).","c":"상","v":1},"공인회2018_53-28-4":{"f":"무한책임사원은 다른 사원 과반수의 결의가 있는 때에 한하여 자기 또는 제3자의 계산으로 회사와 거래를 할 수 있다.","w":"자기거래의 승인은 다른 무한책임사원이 아니라 다른 사원 과반수의 결의다(상법 제199조).","c":"상","v":1},"공인회2018_53-28-5":{"f":"유한책임사원은 성년후견개시 심판을 받더라도 퇴사하지 않지만 파산선고를 받으면 퇴사한다.","w":"유한책임사원은 성년후견개시 심판을 받아도 퇴사하지 않지만(상법 제284조), 파산은 퇴사원인이다(제269조, 제218조 제5호).","c":"상","v":1},"공인회2019_54-09-1":{"f":"회사설립의 취소는 취소권 있는 사원과 사해설립을 이유로 하는 채권자가 회사성립의 날로부터 2년 내에 소만으로 이를 주장할 수 있다.","w":"설립취소의 소는 취소권 있는 자가 제기할 수 있고(상법 제184조 제1항), 사원이 채권자를 해할 것을 알고 회사를 설립한 때에는 채권자도 제기할 수 있다(제185조).","c":"상","v":1},"공인회2019_54-09-2":{"f":"사원의 일부가 업무집행사원인 경우에 각 업무집행사원의 업무집행행위에 대하여 다른 업무집행사원의 이의가 있는 때에는 곧 그 행위를 중지하고 업무집행사원 과반수의 결의에 의하여야 한다.","w":"결의는 사원 전원이 아니라 업무집행사원 과반수로 한다(상법 제201조 제2항).","c":"상","v":1},"공인회2019_54-09-3":{"f":"사원이 사망한 경우 그 사원은 퇴사하며 정관에 상속인이 사원이 된다는 규정이 없으면 상속인이 사원이 되지 못한다.","w":"합명회사 사원의 사망은 퇴사사유다(상법 제218조 제3호). 정관으로 승계를 정한 때에만 상속인이 사원이 된다.","c":"상","v":1},"공인회2019_54-09-5":{"f":"판례에 의하면 사원의 지위를 취득하는 시점은 정관의 기재가 실제로 변경된 때가 아니라 총사원의 동의가 있는 때로 본다.","w":"입사 시점은 정관 기재의 실제 변경이 아니라 총사원의 동의가 있는 때다.","c":"중","v":1},"공인회2019_54-10-1":{"f":"채권자는 퇴사하는 사원에게 환급하는 금액이 잉여금을 초과하는 경우 그 환급에 대하여 회사에 이의를 제기할 수 있다.","w":"환급액이 잉여금을 초과하면 채권자는 그 환급에 대하여 회사에 이의를 제기할 수 있다(상법 제287조의30 제1항).","c":"상","v":1},"공인회2019_54-10-2":{"f":"업무를 집행하지 않는 사원은 업무를 집행하는 사원 전원의 동의가 있으면 그 지분의 전부 또는 일부를 타인에게 양도할 수 있다.","w":"업무를 집행하지 않는 사원의 지분양도에는 업무집행사원 전원의 동의가 필요하고 과반수로는 부족하다(상법 제287조의8 제2항).","c":"상","v":1},"공인회2019_54-10-3":{"f":"회사는 그 지분의 전부 또는 일부를 양수할 수 없으며 회사가 지분을 취득하는 경우 그 지분은 취득한 때에 소멸한다.","w":"유한책임회사는 지분을 양수할 수 없고, 취득하게 되면 그 지분은 취득 시점에 소멸한다(상법 제287조의9).","c":"상","v":1},"공인회2019_54-10-4":{"f":"업무집행자는 다른 사원 전원의 동의가 있는 경우에만 자기 또는 제3자의 계산으로 회사의 영업부류에 속한 거래를 할 수 있다.","w":"경업 거래는 사원 전원의 동의가 있어야 하고 과반수로는 부족하다(상법 제287조의10). 과반수 동의로 하는 것은 회사와의 자기거래다.","c":"상","v":1},"공인회2020_55-06-2":{"f":"유한책임조합원이 업무를 집행하지 않는 경우에는 그 유한책임조합원의 성명 또는 상호, 주소 및 주민등록번호는 등기사항이 아니다.","w":"유한책임조합원의 성명 또는 상호, 주소, 주민등록번호는 그 조합원이 업무를 집행하는 경우에만 등기한다(상법 제86조의4 제1항 제1호).","c":"상","v":1},"공인회2020_55-25-2":{"f":"무한책임사원은 신용 또는 노무를 출자의 목적으로 할 수 있다.","w":"무한책임사원은 재산뿐 아니라 신용·노무로도 출자할 수 있다. 유한책임사원만 재산 출자로 한정된다(상법 제272조).","c":"상","v":1},"공인회2020_55-25-3":{"f":"유한책임사원은 무한책임사원 전원의 동의가 있으면 그 지분의 전부 또는 일부를 양도할 수 있다.","w":"합자회사의 유한책임사원 지분양도에는 무한책임사원 전원의 동의가 필요하다. 사원 전원의 동의까지는 요구되지 않는다(상법 제276조).","c":"상","v":1},"공인회2020_55-25-4":{"f":"지배인의 선임과 해임은 무한책임사원 과반수의 결의에 의한다.","w":"합자회사에서는 업무집행사원이 있어도 지배인의 선임·해임은 무한책임사원 과반수의 결의로 한다(상법 제274조).","c":"상","v":1},"공인회2020_55-25-5":{"f":"총사원의 동의가 있어야 합명회사로의 조직변경이 가능하다.","w":"합자회사를 합명회사로 바꾸려면 사원 전원의 동의가 필요하다(상법 제286조 제1항). 무한책임사원 전원의 동의만으로 할 수 있는 것은 유한책임사원이 모두 퇴사한 경우다(같은 조 제2항).","c":"상","v":1},"공인회2020_55-26-5":{"f":"감사가 없는 경우, 이사는 사원총회의 승인이 있는 때에 한하여 자기 또는 제3자의 계산으로 회사와 거래를 할 수 있다.","w":"유한회사에서 이사의 자기거래는 감사가 있으면 감사의 승인, 없으면 사원총회의 승인을 받는다. 이사 전원의 승인으로는 부족하다(상법 제564조 제3항).","c":"상","v":1},"공인회2021_56-25-1":{"f":"금전출자에 의한 자본금 증가의 경우에 출자의 인수를 한 자는 출자의 납입의 기일로부터 이익배당에 관하여 사원과 동일한 권리를 가진다.","w":"출자 인수인은 증가 등기일이 아니라 출자의 납입기일(현물출자는 재산 급여기일)부터 이익배당에 관하여 사원과 같은 권리를 가진다(상법 제590조).","c":"상","v":1},"공인회2021_56-25-2":{"f":"이사가 회사에 대하여 소를 제기하는 경우에는 사원총회가 그 소에 관하여 회사를 대표할 자를 선정하여야 한다.","w":"유한회사에서는 감사가 있더라도 이사와 회사 사이의 소에서 회사를 대표할 자를 사원총회가 선정한다(상법 제563조). 주식회사 감사의 회사대표 규정(제394조)은 유한회사 감사에 준용되지 않는다(제570조).","c":"상","v":1},"공인회2021_56-25-3":{"f":"이사가 수인인 경우 정관에 다른 정함이 없으면 사원총회에서 회사를 대표할 이사를 선정하여야 한다.","w":"이사가 여럿이어도 각 이사가 당연히 대표권을 갖는 것이 아니라, 정관이나 사원총회의 선정으로 정한다(상법 제562조).","c":"상","v":1},"공인회2021_56-25-5":{"f":"회사의 설립무효는 그 사원·이사·감사에 한하여 회사성립일로부터 2년 내에 소만으로 이를 주장할 수 있다.","w":"유한회사에서 사원·이사·감사가 2년 내 소로 주장할 수 있는 것은 설립무효다(상법 제552조). 설립취소와는 다르다.","c":"상","v":1},"공인회2021_56-26-1":{"f":"합명회사의 사원은 신용 또는 노무를 출자의 목적으로 할 수 있다.","w":"합명회사 사원은 재산 외에 신용과 노무도 출자할 수 있다(상법 제195조, 민법 제703조).","c":"상","v":1},"공인회2021_56-26-2":{"f":"합명회사의 사원이 회사채무에 관하여 변제의 청구를 받은 때에는 회사가 주장할 수 있는 항변으로 그 채권자에게 대항할 수 있다.","w":"사원은 회사가 주장할 수 있는 항변으로 채권자에게 대항할 수 있다(상법 제214조 제1항).","c":"상","v":1},"공인회2021_56-26-3":{"f":"합명회사 성립 후에 가입한 사원은 그 가입 전에 생긴 회사채무에 대해서도 다른 사원과 동일한 책임을 진다.","w":"가입 사원은 가입 전에 생긴 채무에도 책임을 진다(상법 제213조).","c":"상","v":1},"공인회2021_56-26-5":{"f":"합자회사의 유한책임사원은 무한책임사원 전원의 동의가 있으면 그 지분의 전부 또는 일부를 타인에게 양도할 수 있다.","w":"유한책임사원의 지분양도에 필요한 것은 무한책임사원 전원의 동의다. 사원 전원의 동의가 아니다(상법 제276조).","c":"상","v":1},"공인회2021_56-27-2":{"f":"유한책임회사는 그 지분의 전부 또는 일부를 양수할 수 없다.","w":"유한책임회사는 자기지분을 양수하지 못한다(상법 제287조의9).","c":"상","v":1},"공인회2021_56-27-3":{"f":"사원의 지분을 압류한 채권자는 영업연도 말에 그 사원을 퇴사시킬 수 있다.","w":"지분을 압류한 채권자는 회사와 그 사원에게 6개월 전에 예고하고 영업연도 말에 그 사원을 퇴사시킬 수 있다(상법 제287조의29, 제224조).","c":"상","v":1},"공인회2021_56-27-4":{"f":"유한책임회사는 총사원의 동의에 의하여 주식회사로 조직변경을 할 수 있다.","w":"유한책임회사는 주식회사로 조직변경할 수 있다(상법 제287조의43). 유한회사로의 조직변경 규정은 없다.","c":"상","v":1},"공인회2021_56-27-5":{"f":"사원이 아닌 자가 정관에 의해 업무집행자가 된 경우에도 유한책임회사를 대표할 수 있다.","w":"유한책임회사는 정관으로 사원이 아닌 사람을 업무집행자로 정할 수 있고 그 업무집행자가 회사를 대표한다(상법 제287조의12, 제287조의19).","c":"상","v":1},"공인회2022_57-10-2":{"f":"사원의 성명ㆍ주민등록번호 및 주소는 정관에 기재되어야 하지만 1인 사원만으로도 회사를 설립할 수 있다.","w":"유한책임회사는 사원 1인으로도 설립할 수 있다. 사원 수에 하한이 없다.","c":"중","v":1},"공인회2022_57-16-3":{"f":"회사의 지배인 선임과 해임은 업무집행사원이 있는 경우에도 무한책임사원 과반수의 결의가 있어야 한다.","w":"합자회사의 지배인 선임·해임은 무한책임사원 과반수의 결의로 한다. 전원 동의까지 요구하지 않는다(상법 제274조).","c":"상","v":1},"공인회2024_59-05-1":{"f":"합자조합의 설립을 위한 조합계약에는 법정 사항을 적고 총조합원이 기명날인하거나 서명하여야 한다.","w":"합자조합의 조합계약에는 총조합원이 기명날인하거나 서명한다(상법 제86조의3).","c":"상","v":1},"공인회2024_59-05-2":{"f":"조합계약에 다른 정함이 없으면 출자가액을 한도로 하여 유한책임을 지는 유한책임조합원은 성년후견개시 심판을 받은 경우에도 퇴사되지 않는다.","w":"조합계약에 다른 규정이 없으면 유한책임조합원은 성년후견개시 심판을 받아도 퇴사되지 않는다(상법 제86조의8 제3항, 제284조).","c":"상","v":1},"공인회2024_59-05-3":{"f":"유한책임조합원의 지분은 조합계약에서 정하는 바에 따라 타인에게 양도할 수 있다.","w":"유한책임조합원의 지분양도는 조합계약에서 정하는 바에 따른다(상법 제86조의7 제2항). 유한책임조합원 전원의 동의를 요건으로 하는 규정은 없다.","c":"중","v":1},"공인회2024_59-05-4":{"f":"유한책임조합원은 조합계약에서 정한 출자가액에서 이미 이행한 부분을 뺀 가액을 한도로 하여 조합채무를 변제할 책임이 있다.","w":"이미 이행한 출자는 책임 한도에서 공제된다. 출자 이행 여부와 상관없이 전액이 책임 한도가 되는 것은 아니다(상법 제86조의6).","c":"상","v":1},"공인회2024_59-09-1":{"f":"회사의 사원만 설립무효의 소를 제기할 수 있고 회사채권자는 설립무효의 소를 제기할 수 없다.","w":"합명회사의 설립무효의 소는 사원만 제기할 수 있다(상법 제184조). 채권자는 사해설립을 이유로 설립취소의 소를 제기할 수 있을 뿐이다.","c":"상","v":1},"공인회2024_59-09-3":{"f":"회사가 총사원의 동의로 해산하는 경우 해산등기가 이루어져도 청산이 종결되어야 회사가 소멸한다.","w":"해산은 청산 절차로 들어간다는 뜻이고, 회사는 청산이 종결되어야 소멸한다.","c":"상","v":1},"공인회2024_59-09-4":{"f":"노무를 출자의 목적으로 한 사원이 퇴사한 경우에도 정관에 다른 정함이 없으면 회사로부터 지분의 환급을 받을 수 있다.","w":"퇴사원은 노무나 신용을 출자한 경우에도 지분의 환급을 받을 수 있고, 정관에 다른 정함이 있으면 그에 따른다(상법 제222조).","c":"상","v":1},"공인회2024_59-09-5":{"f":"회사가 정관으로 존립기간을 정하고 있지 아니한 경우 사원은 6월 전에 예고하고 영업연도 말에 퇴사할 수 있고, 부득이한 사유가 있으면 언제든지 퇴사할 수 있다.","w":"존립기간 정함이 없을 때 사원은 영업연도 말에 6개월 전 예고로 퇴사한다. 부득이한 사유가 있을 때에만 언제든지 퇴사할 수 있다(상법 제217조).","c":"상","v":1},"공인회2024_59-26-3":{"f":"업무집행자는 사원 전원의 동의를 받지 아니하고는 같은 종류의 영업을 목적으로 하는 다른 회사의 업무집행자ㆍ이사 또는 집행임원이 되지 못한다.","w":"유한책임회사의 업무집행자 경업금지는 사원 전원의 동의로만 해제된다(상법 제287조의10).","c":"상","v":1},"공인회2024_59-32-3":{"f":"총사원의 동의가 있을 때에는 소집절차 없이 총회를 열 수 있으며 총회의 결의를 하여야 할 경우 서면에 의한 결의를 할 수 있다.","w":"소집절차를 생략하거나 서면결의를 하려면 총사원의 동의가 있어야 하고 의결권의 과반수로는 부족하다(상법 제573조, 제577조 제1항).","c":"상","v":1},"공인회2025_60-12-2":{"f":"모집설립에서 이사와 감사는 창립총회에서 선임하고 그 이사와 감사는 취임 후 지체없이 회사의 설립에 관한 모든 사항이 법령 또는 정관의 규정에 위반되지 아니하는지의 여부를 조사하여 창립총회에 보고하여야 한다.","w":"모집설립에서 조사 결과의 보고 대상은 발기인이 아니라 창립총회다(상법 제313조). 발기설립에서만 발기인에게 보고한다.","c":"상","v":1},"공인회2025_60-12-3":{"f":"모집설립에서 창립총회의 결의는 출석한 주식인수인의 의결권의 3분의 2 이상이며 인수된 주식의 총수의 과반수에 해당하는 다수로 하여야 한다.","w":"창립총회의 결의는 출석한 주식인수인 의결권의 3분의 2 이상이고 인수된 주식 총수의 과반수가 되어야 한다(상법 제309조).","c":"상","v":1},"공인회2025_60-12-4":{"f":"회사가 성립하지 못한 경우에는 발기인이 그 설립에 관한 행위에 대하여 연대하여 책임을 진다.","w":"회사가 성립하지 못하면 발기인이 연대하여 설립에 관한 행위의 책임을 지고, 설립에 쓴 비용도 부담한다(상법 제326조).","c":"상","v":1},"공인회2025_60-12-5":{"f":"회사성립 후에는 주식을 인수한 자는 주식청약서의 요건의 흠결을 이유로 하여 그 인수의 무효를 주장하거나 사기 또는 강박을 이유로 하여 그 인수를 취소할 수 없다.","w":"회사성립 후에는 주식청약서 요건 흠결을 이유로 한 무효 주장과 사기·강박을 이유로 한 취소 모두 허용되지 않는다(상법 제320조).","c":"상","v":1},"공인회2026_61-14-2":{"f":"창립총회에서 정관의 변경 또는 설립의 폐지를 결의할 수 있으며, 소집통지서에 그 뜻의 기재가 없어도 그러한 결의를 할 수 있다.","w":"창립총회는 정관 변경이나 설립 폐지를 결의할 수 있고, 소집통지서에 그 뜻의 기재가 없어도 결의할 수 있다(상법 제316조).","c":"상","v":1},"공인회2026_61-28-3":{"f":"정관의 변경은 주주총회의 특별결의가 있는 때 효력이 발생하며 등기는 효력요건이 아니다.","w":"정관변경은 총회 결의로 효력이 생기고, 변경으로 등기사항이 바뀐 경우의 변경등기는 대항요건일 뿐이다.","c":"상","v":1},"공인회2016_51-11-5":{"f":"발기인의 인수담보책임이나 납입담보책임은 총주주의 동의로도 면제할 수 없다.","w":"인수·납입담보책임은 자본충실을 위한 책임이어서 총주주의 동의로도 면제할 수 없다.","c":"중","v":1},"공인회2016_51-25-5":{"f":"정관의 변경은 주주총회의 특별결의가 있는 때 효력이 발생하며 등기는 효력요건이 아니다.","w":"정관변경은 주주총회의 특별결의로 효력이 생긴다. 등기사항이 바뀌었을 때의 변경등기는 대항요건일 뿐이다.","c":"상","v":1},"공인회2017_52-09-2":{"f":"회사는 다른 회사의 무한책임사원이 될 수 없고 청산중의 회사는 청산의 목적범위 내로 권리능력이 제한된다.","w":"회사가 될 수 없는 것은 무한책임사원이다. 유한책임사원, 주주, 유한책임회사의 사원은 될 수 있다(상법 제173조).","c":"상","v":1},"공인회2017_52-09-3":{"f":"판례에 의하면 회사는 정관에서 정한 목적범위 내로 그 권리능력이 제한된다.","w":"회사의 권리능력은 정관에 적힌 목적의 범위 안으로 제한되고, 목적 수행에 직접 또는 간접으로 필요한 행위까지 그 범위에 포함된다는 것이 판례다.","c":"상","v":1},"공인회2017_52-09-4":{"f":"대표이사가 그 업무집행으로 인하여 타인에게 손해를 가한 경우 그 타인에 대하여 회사가 배상할 책임이 있고 대표이사도 연대하여 책임을 진다.","w":"회사의 책임과 별도로 대표이사 개인도 연대하여 배상책임을 진다(상법 제389조 제3항, 제210조).","c":"상","v":1},"공인회2017_52-09-5":{"f":"회사는 친권, 상속권 등 자연인에게 인정되는 특유한 권리를 가질 수 없으나 유증을 받을 권리는 가질 수 있다.","w":"유증은 자연인 특유의 권리가 아니어서 법인도 받을 수 있다는 것이 통설이다.","c":"중","v":1},"공인회2017_52-12-4":{"f":"판례에 의하면 발기인이 제3자로부터 일시적으로 금전을 차입하여 주금을 납입하고 회사 성립 후 즉시 인출하여 차입금을 변제한 경우에도 주금납입으로서의 효력이 있다.","w":"가장납입이어도 금원의 이동에 따른 현실의 납입이 있으므로 주금납입의 효력이 인정된다는 것이 판례다. 별도로 납입가장죄가 문제될 수는 있다.","c":"상","v":1},"공인회2017_52-21-5":{"f":"모집설립에서 검사인은 현물출자와 그 이행을 조사하여 창립총회에 보고하여야 하고 창립총회는 현물출자가 부당하다고 인정하면 이를 변경할 수 있다.","w":"모집설립에서는 검사인의 보고를 창립총회가 받고 창립총회가 변경한다(상법 제310조, 제314조). 법원에 보고하고 법원이 변경하는 것은 발기설립이다.","c":"상","v":1},"공인회2018_53-13-2":{"f":"발기인은 납입금의 보관자 또는 납입장소를 변경한 때에는 법원의 허가를 얻어야 한다.","w":"납입금 보관자나 납입장소를 변경하려면 법원의 허가를 받아야 한다. 신고만으로는 부족하다(상법 제306조).","c":"상","v":1},"공인회2018_53-13-3":{"f":"발기인은 변태설립사항에 관한 조사를 하게 하기 위하여 검사인의 선임을 법원에 청구하여야 한다.","w":"모집설립에서 변태설립사항 조사를 위해 법원에 검사인 선임을 청구하는 사람은 이사가 아니라 발기인이다(상법 제310조 제1항). 이사가 청구하는 것은 발기설립의 경우다(제298조 제4항).","c":"상","v":1},"공인회2018_53-13-4":{"f":"창립총회의 결의는 출석한 주식인수인의 의결권의 3분의 2 이상의 수와 인수된 주식총수의 과반수에 해당하는 수로써 하여야 한다.","w":"창립총회 결의 요건은 출석 주식인수인 의결권의 3분의 2 이상과 인수된 주식 총수의 과반수다(상법 제309조). 과반수와 3분의 1 이상이 아니다.","c":"상","v":1},"공인회2018_53-13-5":{"f":"법원이 선임한 검사인이 악의 또는 중대한 과실로 인하여 그 임무를 해태한 때에는 회사 또는 제3자에 대하여 손해를 배상할 책임이 있다.","w":"검사인의 책임은 악의 또는 중대한 과실이 있을 때 생긴다. 경과실로는 책임지지 않는다(상법 제325조).","c":"상","v":1},"공인회2018_53-14-1":{"f":"민사회사는 상행위 이외의 행위를 영업으로 하는 회사로서 영리성이 있기 때문에 상법상 회사가 될 수 있다.","w":"회사는 상행위나 그 밖의 영리를 목적으로 설립한 법인이다(상법 제169조). 상행위 외의 영리 행위를 하는 민사회사도 상법상 회사다.","c":"상","v":1},"공인회2018_53-14-2":{"f":"회사가 아니면 상호에 회사임을 표시하는 문구를 사용하지 못하며 회사의 영업을 양수한 경우에도 마찬가지이다.","w":"회사가 아닌 자는 상호에 회사임을 나타내는 문자를 쓰지 못하고, 회사의 영업을 양수해도 마찬가지다(상법 제20조).","c":"상","v":1},"공인회2018_53-14-3":{"f":"유한책임회사의 내부관계에 관하여는 정관이나 상법에 다른 규정이 없으면 합명회사에 관한 규정을 준용한다.","w":"합명회사 규정이 준용되는 것은 유한책임회사의 내부관계다(상법 제287조의18).","c":"상","v":1},"공인회2018_53-14-4":{"f":"합자회사의 유한책임사원은 신용 또는 노무를 출자의 목적으로 할 수 없다.","w":"유한책임사원은 금전 그 밖의 재산으로만 출자할 수 있다(상법 제272조).","c":"상","v":1},"공인회2018_53-29-5":{"f":"감사를 선임하지 아니한 회사가 이사에 대하여 소를 제기하는 경우에 회사, 이사 또는 이해관계인은 법원에 회사를 대표할 자를 선임하여 줄 것을 신청하여야 한다.","w":"감사를 두지 않은 자본금 10억원 미만 회사에서 회사와 이사 사이의 소가 제기되면 회사, 이사 또는 이해관계인이 법원에 회사를 대표할 자의 선임을 신청한다(상법 제409조 제5항).","c":"상","v":1},"공인회2019_54-13-4":{"f":"1인주식회사에서 1인주주인 대표이사가 임무위반행위로써 회사에 재산상의 손해를 발생케 하였다면 배임죄가 성립한다.","w":"1인회사라도 회사와 주주는 별개의 법인격이므로 1인주주의 임무위반으로 회사에 손해가 생기면 배임죄가 성립한다는 것이 판례다. 횡령죄와 같은 논리다.","c":"중","v":1},"공인회2019_54-23-3":{"f":"A가 납입한 돈을 나중에 인출하여 차입금을 변제한 것은 업무상횡령죄가 성립하지 않는다.","w":"가장납입으로 인출한 돈은 회사가 자본금으로 확보한 돈이 아니므로 횡령이 되지 않는다. 대신 납입가장죄가 성립한다.","c":"중","v":1},"공인회2020_55-09-2":{"f":"회사설립 시에 발행하는 주식에 관하여 그 주식의 종류와 수에 관한 사항은 정관으로 달리 정하지 아니하면 발기인 전원의 동의로 이를 정한다.","w":"설립 시 발행하는 주식의 종류·수는 발기인 전원의 동의로 정한다. 과반수가 아니다(상법 제291조).","c":"상","v":1},"공인회2020_55-09-3":{"f":"회사설립의 무효는 주주·이사 또는 감사에 한하여 회사성립의 날로부터 2년 내에 소만으로 이를 주장할 수 있다.","w":"설립무효의 소를 제기할 수 있는 사람은 주주·이사·감사이고 채권자는 포함되지 않는다(상법 제328조).","c":"상","v":1},"공인회2020_55-09-4":{"f":"상법은 회사의 설립시에 발행하는 주식의 총수가 회사가 발행할 주식의 총수의 4분의 1 이상이어야 한다는 규정을 두고 있지 않다.","w":"발행예정주식총수의 4분의 1 이상을 설립 때 발행해야 한다는 규정은 삭제되었다.","c":"상","v":1},"공인회2020_55-09-5":{"f":"회사성립 후에는 주식을 인수한 자는 사기·강박 또는 착오를 이유로 하여 그 인수를 취소할 수 없다.","w":"회사가 성립한 뒤에는 주식청약서 요건 흠결을 이유로 인수의 무효를 주장하거나 사기·강박·착오를 이유로 인수를 취소하지 못한다(상법 제320조 제1항).","c":"상","v":1},"공인회2020_55-11-5":{"f":"해산 후의 회사는 존립 중의 회사를 존속하는 회사로 하는 경우에 한하여 합병할 수 있다.","w":"해산한 회사도 존립 중인 회사를 존속회사로 삼는 경우에는 합병할 수 있다(상법 제174조 제3항).","c":"상","v":1},"공인회2020_55-14-1":{"f":"정관으로 회사가 부담할 설립비용과 발기인이 받을 보수액을 정한 때에는, 발기인은 이에 관한 조사를 하게 하기 위하여 검사인의 선임을 법원에 청구하여야 한다.","w":"모집설립에서 변태설립사항을 조사할 검사인의 선임을 법원에 청구하는 사람은 발기인이다(상법 제310조 제1항). 이사가 청구하는 것은 발기설립의 경우다(제298조 제4항).","c":"상","v":1},"공인회2020_55-14-3":{"f":"자본금 총액이 10억원 미만인 회사를 발기설립하는 경우에는, 은행의 납입금 보관금액에 관한 증명서를 그 잔고증명서로 대체할 수 있다.","w":"잔고증명서 대체는 자본금 10억원 미만 회사의 발기설립에만 인정된다. 모집설립에는 적용되지 않는다(상법 제318조 제3항).","c":"상","v":1},"공인회2020_55-14-4":{"f":"모집설립에서는 이사와 감사를 창립총회에서 선임한다.","w":"납입과 현물출자가 끝난 뒤 발기인이 의결권 과반수로 이사·감사를 선임하는 것은 발기설립이다(상법 제296조). 모집설립에서는 창립총회가 선임한다(제312조).","c":"상","v":1},"공인회2020_55-14-5":{"f":"창립총회는 변태설립사항이 부당하다고 인정한 때에는 이를 변경할 수 있다.","w":"모집설립에서는 법원이 아니라 창립총회가 변태설립사항을 변경한다(상법 제314조). 법원이 변경하여 발기인에게 통고하는 것은 발기설립이다.","c":"상","v":1},"공인회2021_56-10-3":{"f":"모집설립시 납입장소를 변경할 때에는 법원의 허가를 얻어야 하며 창립총회의 결의만으로는 변경할 수 없다.","w":"납입장소 변경은 법원의 허가 사항이다(상법 제306조). 창립총회 결의로 대신할 수 없다.","c":"상","v":1},"공인회2022_57-11-1":{"f":"발기설립의 경우 납입과 현물출자의 이행이 완료된 때 발기인은 지체없이 의결권의 과반수로 이사와 감사를 선임하여야 하는데, 발기인의 의결권은 인수주식 1주에 대하여 1개로 한다.","w":"발기인의 의결권은 사람 수가 아니라 인수한 주식 1주마다 1개다(상법 제296조 제2항).","c":"상","v":1},"공인회2022_57-11-3":{"f":"회사의 설립 당시 주식발행사항의 결정에 관하여 정관에 달리 정하고 있지 않은 경우, 발기인 전원이 동의하면 전환주식을 발행할 수 있다.","w":"설립 때 발행하는 주식의 종류와 수는 발기인 전원의 동의로 정한다(상법 제291조). 전환주식을 발행하려면 정관에 근거 규정이 있어야 한다.","c":"중","v":1},"공인회2022_57-11-4":{"f":"회사 설립무효는 소만으로 주장할 수 있고, 원고가 승소한 경우 소급효가 인정되지 않는다.","w":"설립무효 판결은 장래를 향해서만 효력이 있고 소급하지 않는다(상법 제328조 제2항, 제190조 단서 준용).","c":"상","v":1},"공인회2022_57-11-5":{"f":"회사가 성립하지 못한 경우에 발기인은 회사의 설립에 관하여 지급한 비용을 부담한다.","w":"회사가 성립하지 못하면 발기인이 연대하여 설립행위의 책임을 지고 설립에 쓴 비용도 부담한다(상법 제326조).","c":"상","v":1},"공인회2022_57-13-5":{"f":"합명회사의 사원이 회사 채무에 관하여 변제의 청구를 받은 때에는 회사가 그 채권자에 대하여 상계할 권리가 있는 경우 그 사원은 변제를 거부할 수 있다.","w":"회사가 상계권, 취소권, 해제권을 가지는 경우 사원은 변제를 거부할 수 있다(상법 제214조 제2항).","c":"상","v":1},"공인회2023_58-09-1":{"f":"기본적 상행위가 아닌 그 밖의 행위를 영리 목적으로 하여 설립한 법인도 회사가 될 수 있다.","w":"영리를 목적으로 설립한 법인이면 상행위 여부와 관계없이 회사다(상법 제169조). 이것이 민사회사다.","c":"상","v":1},"공인회2023_58-09-2":{"f":"합명회사는 다른 회사의 무한책임사원이 될 수 없다.","w":"회사는 다른 회사의 무한책임사원이 되지 못한다(상법 제173조). 합명회사도 마찬가지다.","c":"상","v":1},"공인회2023_58-09-3":{"f":"자본금 총액의 100분의 10 이상에 해당하는 출자좌수를 가진 사원은 부득이한 사유가 있는 때에는 유한회사의 해산판결을 법원에 청구할 수 있다.","w":"유한회사의 해산판결은 자본금 총액의 100분의 10 이상 출자좌수를 가진 사원만 청구할 수 있다. 이해관계인이나 검사에게는 청구권이 없다(상법 제613조 제1항, 제520조).","c":"상","v":1},"공인회2023_58-09-5":{"f":"합자회사와 주식회사의 합병으로 인하여 신회사를 설립하는 경우에는 정관의 작성 기타 설립에 관한 행위는 각 회사에서 선임한 설립위원이 공동으로 하여야 한다.","w":"신설합병의 정관 작성과 설립 행위는 각 회사가 선임한 설립위원이 공동으로 한다(상법 제175조). 한 회사의 설립위원 단독으로 할 수 없다.","c":"상","v":1},"공인회2023_58-11-1":{"f":"회사설립 시에 발행하는 주식의 종류와 수는 정관으로 달리 정하지 아니하면 발기인 전원의 동의로 이를 정한다.","w":"발기인 과반수가 아니라 발기인 전원의 동의가 필요하다(상법 제291조).","c":"상","v":1},"공인회2023_58-11-2":{"f":"정관은 발기인이 작성하며 발기인은 1인으로도 족하다.","w":"주식회사의 발기인은 1인 이상이면 되므로 2인 이상일 필요가 없다(상법 제288조).","c":"상","v":1},"공인회2023_58-11-4":{"f":"정관은 공증인의 인증을 받음으로써 효력이 생기지만 자본금 총액이 10억원 미만인 회사를 발기설립하는 경우에는 각 발기인이 기명날인 또는 서명함으로써 효력이 생긴다.","w":"정관은 원칙적으로 공증인의 인증을 받아야 효력이 있고, 자본금 10억원 미만 회사의 발기설립에서는 인증이 필요 없다(상법 제292조). 설립등기로 효력이 생기는 것이 아니다.","c":"상","v":1},"공인회2023_58-11-5":{"f":"회사가 성립되었으나 인수된 주식의 납입을 완료하지 아니한 때에는 발기인이 연대하여 납입할 책임이 있다.","w":"납입이 안 된 주식에 대해 발기인은 연대하여 납입할 책임을 진다(상법 제321조 제2항). 인수한 것으로 보는 규정은 인수되지 않은 주식에 관한 것이다.","c":"중","v":1},"공인회2024_59-10-4":{"f":"주식인수인이 인수가액을 납입하지 않은 때에는 실권절차를 거쳐야 그 권리를 잃는다.","w":"납입을 하지 않은 주식인수인의 실권은 발기인이 2주 이상의 기간을 정해 최고하고 통지한 뒤에 생긴다(상법 제307조). 최고 없이 곧바로 권리를 잃지 않는다.","c":"상","v":1},"공인회2025_60-13-4":{"f":"무액면주식을 발행하는 회사는 액면주식을 발행할 수 없다.","w":"회사는 액면주식과 무액면주식 가운데 하나만 골라 발행한다. 둘을 함께 발행할 수 없다(상법 제329조 제1항).","c":"상","v":1},"공인회2025_60-14-5":{"f":"회사가 주식의 상환에 관한 종류주식을 발행한 경우 회사는 상환의 대가로 현금 외에 유가증권이나 그 밖의 자산도 교부할 수 있다.","w":"상환 대가는 현금에 한정되지 않는다. 다만 해당 회사 발행의 다른 종류주식은 교부할 수 없다(상법 제345조 제4항).","c":"상","v":1},"공인회2025_60-16-2":{"f":"의결권 없는 주식을 제외한 발행주식총수의 100분의 10 이상의 주식을 가진 주주와 그 직계비속에게는 주식매수선택권을 부여할 수 없다.","w":"10% 이상 주주뿐 아니라 그 배우자와 직계존비속에게도 부여하지 못한다(상법 제340조의2 제2항).","c":"상","v":1},"공인회2025_60-16-3":{"f":"자기주식양도방식의 주식매수선택권의 경우 주식매수선택권의 행사가액은 주식매수선택권의 부여일을 기준으로 한 주식의 실질가액 이상이어야 한다.","w":"자기주식을 양도하는 방식에서는 부여일 기준 실질가액 이상이어야 하고, 권면액 이상이라는 기준은 신주 발행 방식에 관한 요건의 일부다(상법 제340조의2 제4항).","c":"상","v":1},"공인회2025_60-16-4":{"f":"주식매수선택권은 이를 양도할 수 없지만, 주식매수선택권을 행사할 수 있는 자가 사망한 경우 그 상속인이 주식매수선택권을 행사할 수 있다.","w":"양도는 금지되나 상속은 허용된다(상법 제340조의4 제2항).","c":"상","v":1},"공인회2025_60-16-5":{"f":"주식매수선택권은 정관에 근거를 두고 주주총회의 특별결의로 부여한다.","w":"주식매수선택권은 주주총회 특별결의로 부여하며 이사회 결의만으로는 부여할 수 없다(상법 제340조의2 제1항).","c":"상","v":1},"공인회2025_60-18-1":{"f":"상법 제341조의2에 따라 특정 목적에 의한 자기주식의 취득이 허용되는 경우에는 다른 회사의 영업 전부의 양수로 인하여 자기주식을 취득하는 경우가 포함된다.","w":"허용되는 것은 다른 회사의 영업 전부를 양수하는 경우다. 영업의 일부 양수는 포함되지 않는다(상법 제341조의2 제1호).","c":"상","v":1},"공인회2026_61-13-5":{"f":"회사가 정관으로 정하는 바에 따라 회사의 이익으로써 소각할 수 있는 종류주식을 발행한 경우 회사는 그 주식 취득의 대가로 해당 회사 발행의 의결권 제한 종류주식을 교부할 수 없다.","w":"상환의 대가로 현금 외의 유가증권이나 자산을 줄 수는 있지만 해당 회사가 발행한 다른 종류주식은 줄 수 없다(상법 제345조 제4항).","c":"상","v":1},"공인회2026_61-17-2":{"f":"지배주주가 소수주주에게 상법 제360조의24 제1항의 매도청구를 할 때에는 미리 주주총회의 승인을 받아야 한다.","w":"지배주주의 매도청구에는 사전에 주주총회의 승인이 필요하다. 이사회 승인으로는 부족하다(상법 제360조의24 제3항).","c":"상","v":1},"공인회2026_61-18-3":{"f":"회사가 주식매수선택권 부여를 위해 신주를 발행하는 경우 주식매수선택권의 행사가액은 주식매수선택권의 부여일을 기준으로 한 주식의 실질가액과 주식의 권면액 중 높은 금액 이상이어야 한다.","w":"행사가액의 기준 시점은 행사일이 아니라 부여일이다(상법 제340조의2 제4항 제1호).","c":"상","v":1},"공인회2016_51-09-1":{"f":"회사가 의결권이 제한되는 종류주식을 발행하면서 그 주주에게 당해 주식의 상환을 청구할 수 있는 권리를 부여할 수 있다.","w":"상환에 관한 종류주식은 상환·전환 외의 다른 종류주식에 붙여서 발행하므로, 의결권 제한 종류주식에 상환청구권을 붙일 수 있다(상법 제345조 제3항·제5항).","c":"상","v":1},"공인회2016_51-09-2":{"f":"회사가 상환권을 가진 상환에 관한 종류주식을 발행한 회사가 그 종류주식을 상환하면 회사의 자본금은 감소하지 않는다.","w":"상환주식은 회사의 이익으로 소각하므로 자본금 감소 절차를 밟지 않고 자본금도 줄지 않는다(상법 제345조 제1항).","c":"상","v":1},"공인회2016_51-09-4":{"f":"주주명부 폐쇄기간 중에 전환에 관한 종류주식을 가진 주주가 의결권 있는 주식으로 전환을 청구하면 그 폐쇄기간 중의 주주총회 결의에서 전환으로 발행된 신주의 의결권을 행사할 수 없다.","w":"폐쇄기간 중에 전환된 주식의 주주는 그 기간 중의 총회 결의에서 의결권을 행사하지 못한다(상법 제350조 제2항).","c":"상","v":1},"공인회2016_51-09-5":{"f":"전환에 관한 종류주식의 경우 전환으로 인해 발행되는 신주 1주의 액면가와 전환으로 인해 소멸하는 전환주식 1주의 액면가는 같아야 한다.","w":"액면주식의 금액은 균일해야 하므로 전환으로 발행되는 신주와 소멸하는 전환주식의 1주 액면가는 같다(상법 제329조 제2항).","c":"상","v":1},"공인회2016_51-10-5":{"f":"회사의 이익을 주주들에게 분배할 목적으로 액면주식을 병합하는 방법으로 행하는 자본금 감소는 채권자이의절차가 종료하지 않으면 주권제출기간이 종료하더라도 그 효력이 생기지 않는다.","w":"주식병합의 효력은 채권자 보호절차가 끝난 뒤에야 생긴다(상법 제441조). 주권제출기간 종료만으로는 효력이 없다.","c":"상","v":1},"공인회2016_51-13-5":{"f":"","w":"丙이 乙의 주식을 추가로 취득해도 丙이 가진 甲 주식의 비율은 달라지지 않으므로, 甲이 가진 丙의 주식에 대한 의결권 제한이 새로 생기지 않는다(상법 제369조 제3항).","c":"하","v":1},"공인회2016_51-14-2":{"f":"상법은 甲회사가 취득할 수 있는 자기주식의 종류와 수 등을 결정하는 기관을 원칙적으로 주주총회로 하되, 이사회 결의로 이익배당을 결정할 수 있는 회사는 이사회가 결정하도록 정한다.","w":"자기주식 취득 사항은 원칙적으로 주주총회 결의로 정하지만, 정관으로 이사회가 이익배당을 결정하도록 한 회사는 이사회 결의로 정한다(상법 제341조 제2항).","c":"중","v":1},"공인회2016_51-14-3":{"f":"甲회사가 자기주식을 취득한 영업연도의 결산기에 결손이 발생한 경우 이사가 과실 없이 결손을 예견하지 못했음을 증명하지 못하면 이사는 회사에 배상책임을 진다.","w":"증명책임은 이사에게 있다. 이사가 결손 우려가 없다고 판단할 때 주의를 게을리하지 않았음을 증명해야 책임을 면한다(상법 제341조 제4항).","c":"상","v":1},"공인회2016_51-14-5":{"f":"甲회사가 자기주식을 처분하는 경우 상법은 주주들에게 자신의 주식 소유비율에 따라 우선적으로 자기주식을 양수할 수 있는 권리를 명문으로 인정하지 않는다.","w":"처분 방법은 정관에 없으면 이사회가 정하고(상법 제342조), 주주의 우선 양수권을 정한 규정은 없다.","c":"상","v":1},"공인회2017_52-19-1":{"f":"판례에 의하면 주식의 양도에 관하여 이사회의 승인을 받도록 규정한 정관에도 불구하고 이사회의 승인 없이 주식을 양도한 경우 주주 사이의 주식양도계약 자체는 유효하다.","w":"승인 없는 양도는 회사에 대해서는 효력이 없지만 당사자 사이의 양도계약은 유효하다는 것이 판례다.","c":"상","v":1},"공인회2017_52-25-1":{"f":"소수주주의 보유주식에 대한 지배주주의 매도청구는 상장회사의 경우에도 인정된다.","w":"지배주주의 매도청구는 상장 여부와 관계없이 지배주주가 95% 이상을 보유한 회사에서 인정된다(상법 제360조의24).","c":"상","v":1},"공인회2017_52-25-3":{"f":"소수주주가 지배주주에 대하여 그 보유주식의 매수를 청구하기 위해서는 주주총회의 사전승인이 필요하지 않다.","w":"소수주주는 언제든지 매수를 청구할 수 있다. 사전승인이 필요한 것은 지배주주가 매도청구를 할 때다(상법 제360조의25).","c":"상","v":1},"공인회2017_52-25-4":{"f":"소수주주가 지배주주에 대하여 그 보유주식의 매수를 청구한 경우 지배주주는 매수청구한 날을 기준으로 2개월 내에 그 주식을 매수하여야 한다.","w":"지배주주는 청구를 거절할 수 없고 2개월 내에 매수해야 한다(상법 제360조의25 제2항).","c":"상","v":1},"공인회2017_52-25-5":{"f":"지배주주인지 여부를 판단하기 위한 보유주식수를 산정할 때에는 지배주주의 명의로써 타인의 계산으로 보유한 주식을 산입하지 않는다.","w":"자기의 계산으로 보유한 주식만 산입한다(상법 제360조의24 제1항).","c":"상","v":1},"공인회2017_52-26-5":{"f":"액면주식을 무액면주식으로 전환하는 경우 자본금은 동일하게 유지되어야 하지만 전환에 의해 발행되는 무액면주식의 수는 기존의 주식 수와 동일하지 않아도 된다.","w":"전환으로 자본금은 바뀌지 않지만(상법 제451조 제3항) 전환 뒤 주식 수가 전과 같아야 하는 것은 아니다(제329조 제4항·제5항).","c":"중","v":1},"공인회2017_52-27-1":{"f":"등록질권자가 회사에 대하여 질권자로서의 권리를 행사하기 위하여는 주권을 제시할 필요가 없다.","w":"등록질권자는 질권자의 성명과 주소가 주주명부에 기재되어 있으므로 주권 제시 없이 권리를 행사할 수 있다(상법 제340조).","c":"중","v":1},"공인회2018_53-09-1":{"f":"회사가 잔여재산의 분배에 관하여 내용이 다른 종류주식을 발행하는 경우에는 정관에 잔여재산의 종류, 잔여재산의 가액의 결정방법, 그 밖에 잔여재산분배에 관한 내용을 정하여야 한다.","w":"잔여재산 분배에 관한 종류주식의 내용은 정관에 정해야 하고 이사회가 정할 수 없다(상법 제344조의2 제2항).","c":"상","v":1},"공인회2018_53-09-2":{"f":"회사가 종류주식을 발행하는 경우 정관에 다른 정함이 없는 경우에도 그 종류에 따라 회사의 합병·분할로 인한 주식의 배정에 관하여 특수하게 정할 수 있다.","w":"주식의 소각과 합병·분할로 인한 주식 배정에 관한 특수한 정함은 정관에 따로 규정이 없어도 가능하다(상법 제344조 제3항).","c":"상","v":1},"공인회2018_53-09-3":{"f":"회사가 의결권의 배제·제한에 관한 종류주식을 발행주식총수의 4분의 1을 초과하여 발행한 경우 회사는 지체 없이 그 제한을 초과하지 아니하도록 하기 위하여 필요한 조치를 하여야 한다.","w":"초과 발행 때는 지체 없이 필요한 조치를 해야 한다(상법 제344조의3 제2항). 6개월 내 소각 의무는 없다.","c":"상","v":1},"공인회2018_53-09-4":{"f":"회사가 주식의 상환에 관한 종류주식을 발행하는 경우 주식의 취득의 대가로 현금 외에 해당 회사의 다른 종류주식을 제외한 유가증권 또는 그 밖의 자산을 교부할 수 있다.","w":"현금 외의 자산은 줄 수 있으나 해당 회사가 발행한 다른 종류주식은 줄 수 없다(상법 제345조 제4항).","c":"상","v":1},"공인회2018_53-11-1":{"f":"주식매수선택권의 부여는 정관이 정하는 바에 따라 주주총회 특별결의로 정한다.","w":"주식매수선택권은 주주총회 특별결의로 부여한다. 이사회 결의로 정하는 것이 아니다(상법 제340조의2 제1항).","c":"상","v":1},"공인회2018_53-11-3":{"f":"주식매수선택권의 행사가액은 신주를 발행하는 경우에는 주식매수선택권의 부여일을 기준으로 한 주식의 실질가액과 주식의 권면액 중 높은 금액 이상이어야 한다.","w":"기준일은 행사일이 아니라 부여일이다(상법 제340조의2 제4항).","c":"상","v":1},"공인회2018_53-11-4":{"f":"주식매수선택권의 행사가액이 주식의 실질가액보다 낮은 경우에 회사는 그 차액을 금전으로 지급할 수 있으며 이 경우 주식의 실질가액은 주식매수선택권의 행사일을 기준으로 평가한다.","w":"차액을 금전으로 지급할 때 실질가액은 행사일을 기준으로 평가한다(상법 제340조의2 제1항 단서).","c":"상","v":1},"공인회2018_53-11-5":{"f":"주식매수선택권은 그 부여를 정한 주주총회 결의일부터 2년 이상 재임 또는 재직하여야 행사할 수 있으며 이를 양도할 수 없다.","w":"주식매수선택권은 부여를 정한 주주총회 결의일부터 2년 이상 재임하거나 재직해야 행사할 수 있다(상법 제340조의4 제1항). 양도는 금지된다(같은 조 제2항).","c":"상","v":1},"공인회2018_53-16-1":{"f":"주식의 양도에 있어서는 주권을 교부하여야 하며 주권의 점유자는 이를 적법한 소지인으로 추정한다.","w":"주권 점유자는 적법한 소지인으로 추정될 뿐이며 의제되지는 않는다(상법 제336조 제2항).","c":"상","v":1},"공인회2018_53-16-2":{"f":"판례에 의하면 A가 주식양도에 관하여 이사회의 승인을 받지 않은 경우에도 그 주식양도는 당사자인 A와 B 사이에서는 효력이 있다.","w":"이사회의 승인이 없으면 회사에 대해서만 효력이 없고 당사자 사이의 양도는 유효하다는 것이 판례다.","c":"상","v":1},"공인회2018_53-16-3":{"f":"甲회사가 주식양도시까지 주권을 발행하지 않은 경우라도 회사성립 후 6월이 경과하였고 A가 이사회의 승인을 받았다면 A와 B 사이의 주식양도는 甲회사에 대하여 그 효력이 있다.","w":"주권 발행 전 양도는 회사성립 후 또는 신주 납입기일 후 6개월이 지나면 회사에 대하여 효력이 있다(상법 제335조 제3항 단서).","c":"중","v":1},"공인회2018_53-16-4":{"f":"A가 甲회사에 대하여 주식양도의 승인을 청구하였으나 甲회사가 1개월 내에 이를 거절한 때에는 A는 그 거절의 통지를 받은 날로부터 20일 내에 甲회사에 대하여 주식양도의 상대방의 지정을 청구할 수 있다.","w":"회사는 승인 청구를 받은 날부터 1개월 내에 승인 여부를 통지해야 하고, 거부 통지를 받은 주주는 그날부터 20일 내에 상대방 지정이나 주식 매수를 청구할 수 있다(상법 제335조의2 제2항·제4항).","c":"상","v":1},"공인회2019_54-11-1":{"f":"주권이 발행되지 않고 전자등록부에 등록된 주식을 취득하여 등록한 경우에도 주식의 선의취득이 인정된다.","w":"전자등록부를 선의로, 중대한 과실 없이 믿고 등록에 따라 주식을 취득한 자는 그 권리를 적법하게 취득한다(상법 제356조의2 제3항).","c":"상","v":1},"공인회2019_54-12-2":{"f":"회사는 주주명부상 주주 외에 실제 주식을 인수한 자가 따로 존재하는 사실을 안 경우에도 주주명부상 주주의 주주권 행사를 부인할 수 없다.","w":"회사는 주주명부에 기재된 주주만을 주주로 대우해야 하고, 실제 인수인이 따로 있음을 알더라도 명부상 주주의 권리행사를 부인하지 못한다는 것이 판례다.","c":"상","v":1},"공인회2019_54-14-4":{"f":"甲회사의 주식에 대한 양도통지가 확정일자 없는 증서에 의하여 이루어진 경우 나중에 그 증서에 확정일자를 얻었더라도 소급하지 않고 확정일자를 얻은 때부터 제3자에 대한 대항력을 취득한다.","w":"확정일자 없는 통지에 나중에 확정일자를 받아도 원래 통지일로 소급하여 대항력이 생기지 않는다는 것이 판례다.","c":"상","v":1},"공인회2019_54-18-5":{"f":"판례에 의하면 정관변경에 필요한 종류주주총회의 결의가 아직 이루어지지 않았더라도 그 정관변경을 결의한 주주총회결의의 하자를 이유로 그 결의의 무효확인을 구할 수는 없다.","w":"종류주주총회 결의가 없으면 주주총회의 정관변경 결의는 효력이 발생하지 않은 상태일 뿐 결의 자체에 무효의 하자가 있는 것이 아니라는 것이 판례다.","c":"상","v":1},"공인회2019_54-19-3":{"f":"회사가 정관으로 주주명부의 폐쇄기간을 정하지 않은 때에는 그 기간의 2주간 전에 이를 공고하여야 한다.","w":"정관으로 기간을 정해 두었다면 따로 공고하지 않아도 된다. 정관에 없을 때에만 2주 전 공고가 필요하다(상법 제354조 제4항).","c":"상","v":1},"공인회2020_55-10-2":{"f":"이미 발행된 주권이 주주의 주권불소지 신고에 의하여 회사에 제출된 경우, 회사는 그 제출된 주권을 무효로 하거나 임치할 수 있다.","w":"불소지 신고로 제출된 주권은 회사가 무효로 하거나 명의개서대리인에게 임치한다(상법 제358조의2 제3항).","c":"상","v":1},"공인회2020_55-13-4":{"f":"회사가 종류주식을 발행하는 경우에는, 정관에 정함이 있어야 주주는 인수한 주식을 다른 종류주식으로 전환할 것을 청구할 수 있다.","w":"전환주식은 정관에 전환의 조건, 청구기간 등을 정한 경우에만 발행할 수 있다(상법 제346조).","c":"상","v":1},"공인회2021_56-11-1":{"f":"회사의 자본금은 액면주식을 무액면주식으로 전환함으로써 변경할 수 없고, 무액면주식을 액면주식으로 전환함으로써도 변경할 수 없다.","w":"액면과 무액면 상호 간 전환 모두 자본금을 변경시키지 못한다(상법 제451조 제3항).","c":"상","v":1},"공인회2021_56-11-2":{"f":"회사는 분할 후의 액면주식 1주의 금액을 100원 미만으로 하는 주식분할을 할 수 없다.","w":"분할 후 1주의 금액은 100원 이상이어야 한다(상법 제329조의2 제2항).","c":"상","v":1},"공인회2021_56-11-3":{"f":"회사설립시 무액면주식을 발행하는 경우에는 주식의 발행가액 중 자본금으로 계상하는 금액에 관한 사항은 정관으로 달리 정하지 아니하면 발기인 전원의 동의로 이를 정한다.","w":"발기인 과반수가 아니라 발기인 전원의 동의가 필요하다(상법 제291조 제3호).","c":"상","v":1},"공인회2021_56-11-5":{"f":"주식이 수인의 공유에 속하는 때 공유자는 주주의 권리를 행사할 자 1인을 정하여야 하고, 주주의 권리를 행사할 자가 없는 때에는 공유자에 대한 통지는 그 중 1인에 대하여 하면 된다.","w":"권리행사자가 정해지지 않았으면 공유자 중 1인에게 통지하면 충분하다(상법 제333조 제3항).","c":"상","v":1},"공인회2021_56-12-2":{"f":"회사는 주식 취득의 대가로 현금 외에 해당 회사 발행의 다른 종류주식은 교부할 수 없다.","w":"상환주식의 대가로 해당 회사의 다른 종류주식을 줄 수 없다(상법 제345조 제4항).","c":"상","v":1},"공인회2021_56-14-5":{"f":"상법은 주식의 약식질권이 신주인수권에 대하여 우선변제적 효력을 미친다는 규정을 두고 있지 않다.","w":"상법은 주식의 소각·병합·분할·전환으로 받는 금전이나 주식(제339조)과 등록질의 이익배당·잔여재산분배(제340조 제1항)에 질권의 효력을 정할 뿐, 신주인수권에 관한 규정은 약식질에도 등록질에도 없다.","c":"상","v":1},"공인회2021_56-15-2":{"f":"주권발행 전 주식을 양수한 자는 특별한 사정이 없는 한 양도인의 협력 없이 단독으로 회사에 대하여 그 명의개서를 청구할 수 있다.","w":"양수인은 자신이 주식을 양수한 사실을 증명하여 양도인의 협력 없이 단독으로 명의개서를 청구할 수 있다.","c":"상","v":1},"공인회2021_56-16-5":{"f":"주식을 양수하려는 자가 타인의 명의를 빌려 회사의 주식을 양수하고 타인의 명의로 주주명부에의 기재까지 마치는 경우, 회사에 대한 관계에서는 그 타인의 명의를 차용한 자가 아니라 주주명부상 주주만이 주주로서 의결권 등 주주권을 적법하게 행사할 수 있다.","w":"회사는 명의를 빌려준 주주명부상 주주를 주주로 대우하며, 실제 출자자인 명의차용인이 주주권을 행사하는 것이 아니다.","c":"상","v":1},"공인회2022_57-09-5":{"f":"A회사가 E회사와 주식의 포괄적 교환을 하여 E회사의 모회사가 되었다면, 주식의 교환 전에 E회사가 보유하고 있던 A회사의 주식은 소멸하지 않고 E회사가 6개월 이내에 처분하여야 한다.","w":"완전자회사가 된 E가 이미 갖고 있던 A 주식은 교환으로 소멸하지 않는다. 주식교환으로 자회사가 모회사 주식을 갖게 된 경우이므로 6개월 이내에 처분해야 한다(상법 제342조의2 제1항 제1호·제2항).","c":"중","v":1},"공인회2022_57-12-1":{"f":"정관이나 상환주식인수계약 등에서 특별한 정함이 없는 경우, 상환주식의 상환권자인 주주가 상환권을 행사하였더라도 회사로부터 상환금을 지급받지 않았다면 그 행사시점에 주주의 지위를 상실하지 않는다.","w":"상환권 행사만으로 주주 지위가 곧바로 사라지지 않는다. 상환금 지급과 주식 소각이 이루어져야 주주 지위가 소멸한다.","c":"중","v":1},"공인회2022_57-15-5":{"f":"주식양수인이 명의개서를 청구한 경우 회사는 그 청구자가 진정한 주주인가에 대하여 실질적인 자격 여부까지 심사할 의무를 부담하지 않는다.","w":"회사의 심사 의무는 형식적 자격에 그친다. 청구자가 진정한 주주인지 실질까지 가릴 의무는 없다.","c":"상","v":1},"공인회2023_58-12-1":{"f":"액면주식을 발행하는 회사는 주식의 일부를 무액면주식으로 발행할 수 없다.","w":"회사는 정관으로 액면주식과 무액면주식 중 하나를 택해 발행하며 함께 발행할 수 없다(상법 제329조 제1항).","c":"상","v":1},"공인회2023_58-12-2":{"f":"회사는 발행된 액면주식의 전부를 무액면주식으로 전환할 수 있다.","w":"무액면주식을 발행하면 액면주식을 함께 발행할 수 없으므로 전환은 발행된 주식 전부에 대해서만 할 수 있다(상법 제329조 제1항 단서·제4항).","c":"상","v":1},"공인회2023_58-12-4":{"f":"무액면주식을 발행한 회사의 자본금은 주식 발행가의 2분의 1 이상의 금액으로서 이사회에서 자본금으로 계상하기로 한 금액의 총액으로 한다.","w":"발행가 전액이 자본금이 되는 것이 아니다. 발행가의 2분의 1 이상 범위에서 이사회(정관에 정하면 주주총회)가 자본금으로 정한 금액이 자본금이다(상법 제451조 제2항).","c":"상","v":1},"공인회2023_58-12-5":{"f":"회사는 주주총회의 특별결의와 법원의 인가를 얻어 액면미달의 가액으로 신주를 발행할 수 있다.","w":"액면미달 발행은 주주총회 특별결의와 법원의 인가가 필요하다(상법 제417조). 보통결의로는 할 수 없다.","c":"상","v":1},"공인회2023_58-13-4":{"f":"주권이 발행된 경우 정관에 다른 정함이 없으면 주주는 그 주식에 대하여 주권의 소지를 하지 아니하겠다는 뜻을 회사에 신고할 수 있다.","w":"정관에 불소지를 금지하는 규정이 없으면 주주는 불소지 신고를 할 수 있다(상법 제358조의2 제1항).","c":"상","v":1},"공인회2023_58-15-2":{"f":"회사는 명의개서를 마치지 않은 주식양수인에게 의결권 행사를 허락할 수 없다.","w":"주주명부에 이름이 오르지 않은 양수인의 주주권 행사를 회사가 임의로 인정할 수 없다는 것이 판례다.","c":"상","v":1},"공인회2023_58-16-1":{"f":"주식의 인수로 인한 권리의 양도는 회사의 승인 여부와 관계없이 회사에 대하여 효력이 없다.","w":"주식인수인의 권리(권리주)의 양도는 회사에 대하여 효력이 없다(상법 제319조).","c":"상","v":1},"공인회2024_59-11-1":{"f":"회사가 상환주식을 이익으로써 소각한 경우 회사의 자본금은 감소하지 않는다.","w":"상환주식은 회사의 이익으로 소각하므로 자본금 감소 절차를 거치지 않고 자본금도 줄지 않는다(상법 제345조 제1항).","c":"상","v":1},"공인회2024_59-11-3":{"f":"전환주식을 소유한 주주가 전환을 청구한 경우 청구를 한 때에 전환의 효력이 발생한다.","w":"전환청구권은 형성권이다. 회사의 승낙 없이 청구한 때 효력이 생긴다(상법 제350조 제1항).","c":"상","v":1},"공인회2024_59-11-4":{"f":"상환주식과 전환주식의 종류와 내용은 회사가 발행하는 주권에 기재하여야 한다.","w":"종류주식의 종류와 내용은 주권의 절대적 기재사항이다(상법 제356조 제6호).","c":"상","v":1},"공인회2024_59-11-5":{"f":"주주명부 폐쇄기간 중에 전환된 주식의 주주는 그 기간 중의 주주총회 결의에 관하여 의결권을 행사할 수 없다.","w":"폐쇄기간 중 전환된 주식의 주주는 그 기간 중 결의에서 의결권을 행사할 수 없다(상법 제350조 제2항).","c":"상","v":1},"공인회2024_59-13-1":{"f":"주식을 양도할 경우 이사회 승인이 요구된다는 사정은 설립등기시 등기해야 할 사항에 포함된다.","w":"주식양도에 이사회 승인을 받도록 정관에 정한 경우 그 규정은 등기사항이다(상법 제317조 제2항 제3호의2).","c":"상","v":1},"공인회2024_59-13-2":{"f":"양도인이 회사에 대해 주식양도에 대한 승인을 청구하지 않은 경우에도 양수인은 회사에 대해 주식 취득의 승인을 청구할 수 있다.","w":"주식을 취득한 양수인도 회사에 취득의 승인을 청구할 수 있다(상법 제335조의7 제1항).","c":"상","v":1},"공인회2024_59-13-4":{"f":"양도인이 회사에 대해 주식양도에 대한 승인을 청구할 때에는 서면으로 하여야 하며 구두로는 할 수 없다.","w":"승인 청구는 주식의 종류와 수, 상대방의 성명을 적은 서면으로 한다(상법 제335조의2 제1항).","c":"상","v":1},"공인회2024_59-13-5":{"f":"만약 회사의 자본금 총액이 10억원 미만이고 이사 1인만 재직 중이라면 주식양도에 대한 승인 여부는 주주총회가 결정한다.","w":"이사가 1인이거나 2인인 소규모 회사에서는 이사회 기능을 주주총회가 한다(상법 제383조 제4항). 그 이사 혼자 결정하지 못한다.","c":"상","v":1},"공인회2024_59-14-2":{"f":"회사가 공고한 주권제출기간이 끝난 때 주식분할의 효력이 발생한다.","w":"주식분할의 효력은 주주가 주권을 제출한 때가 아니라 주권제출기간이 끝난 때 생긴다(상법 제329조의2 제3항, 제441조).","c":"상","v":1},"공인회2024_59-14-3":{"f":"주식분할이 이루어지면 발행주식총수가 증가한다.","w":"주식분할로 주식 수는 늘어난다(상법 제329조의2).","c":"상","v":1},"공인회2024_59-14-4":{"f":"주식분할이 이루어지면 1주의 액면금액은 감소한다.","w":"주식분할로 액면가는 나뉜 비율만큼 줄어든다. 다만 1주의 금액은 100원 이상이어야 한다.","c":"상","v":1},"공인회2024_59-14-5":{"f":"주식분할이 이루어져도 회사의 자본금은 증가하지 않는다.","w":"주식 수가 늘고 액면가가 줄어드는 것이어서 자본금은 변하지 않는다.","c":"상","v":1},"공인회2024_59-16-5":{"f":"A회사가 C회사의 소수주주에게 매매가액을 지급한 경우 C회사의 소수주주가 가진 주식은 매매가액을 지급한 때에 A회사에게 이전된다.","w":"지배주주가 매매가액을 소수주주에게 지급한 때 주식이 이전된 것으로 본다. 주권 교부 시점이 아니다(상법 제360조의26).","c":"상","v":1},"공인회2025_60-20-1":{"f":"주주가 이사선임결의에 대하여 결의취소소송을 제기하기 위해서는 회사를 피고로 하여야 한다.","w":"결의취소의 소의 피고는 회사이고, 그 결의로 선임된 이사는 피고가 될 수 없다는 것이 판례다.","c":"상","v":1},"공인회2025_60-20-2":{"f":"결의취소소송에서 패소한 원고가 악의 또는 중대한 과실이 있는 경우에는 회사에 대해 손해를 배상할 책임이 있다.","w":"패소한 원고에게 악의 또는 중대한 과실이 있으면 회사에 대해 연대하여 손해배상책임을 진다(상법 제376조 제2항, 제191조).","c":"상","v":1},"공인회2025_60-20-4":{"f":"결의부존재확인소송은 결의취소소송과 달리 제소기간의 제한이 없다.","w":"2개월 제소기간은 결의취소의 소에만 있다. 부존재·무효확인의 소는 기간 제한이 없다(상법 제376조, 제380조).","c":"상","v":1},"공인회2025_60-20-5":{"f":"부당결의취소·변경의 소가 제기된 경우 법원은 그 청구를 재량으로 기각할 수 없다.","w":"재량기각 규정은 결의취소의 소(상법 제379조)에만 있고 부당결의의 취소·변경의 소에는 준용되지 않는다(제381조 제2항).","c":"중","v":1},"공인회2026_61-19-3":{"f":"회사는 이사회의 결의로 주주가 총회에 출석하지 아니하고 전자적 방법으로 의결권을 행사할 수 있음을 정할 수 있다.","w":"전자투표는 정관 규정이 없어도 이사회 결의로 도입할 수 있다(상법 제368조의4 제1항).","c":"상","v":1},"공인회2026_61-20-4":{"f":"이사인 주주가 결의취소의 소를 제기한 때에는 법원은 회사의 청구가 있어도 담보를 제공할 것을 명하지 못한다.","w":"담보제공 명령은 주주가 제기한 소에 대한 것이고 제소 주주가 이사 또는 감사이면 적용되지 않는다(상법 제377조 제1항 단서).","c":"상","v":1},"공인회2016_51-16-2":{"f":"주주이자 이사인 B는 자신의 이사직 수행에 대한 보수액을 결정하기 위한 주주총회결의에서 의결권을 행사할 수 없다.","w":"보수 결정은 B 개인에게 특별한 이해관계가 있는 사항이어서 의결권을 행사하지 못한다(상법 제368조 제3항). 선임·해임 결의에서는 주주 지위에서 의결권을 행사한다.","c":"중","v":1},"공인회2016_51-17-3":{"f":"甲회사의 주주총회결의와 관련하여 특별이해관계 있는 주주가 가진 의결권의 수는 출석한 주주의 의결권 수에 산입되지 않는다.","w":"의결권을 행사할 수 없는 주식의 의결권 수는 출석한 주주의 의결권 수에 넣지 않는다(상법 제371조 제2항).","c":"상","v":1},"공인회2016_51-17-4":{"f":"甲회사의 감사 선임결의에서 의결권 없는 주식을 제외한 발행주식총수의 5%를 소유한 주주의 의결권 수 중 3%를 초과하는 부분은 출석한 주주의 의결권 수에 산입되지 않는다.","w":"감사 선임에서는 3%를 넘는 주식은 의결권을 행사하지 못하고, 그 부분은 출석 의결권 수에도 들어가지 않는다(상법 제409조 제2항, 제371조 제2항).","c":"상","v":1},"공인회2016_51-18-4":{"f":"상법은 주주총회결의취소의 소에서는 명문으로 법원의 재량에 의한 청구기각 제도를 인정하지만 주주총회결의무효확인의 소에서는 인정하지 않는다.","w":"재량기각은 결의취소의 소에만 규정되어 있다(상법 제379조).","c":"상","v":1},"공인회2017_52-16-3":{"f":"주주총회에서 회의의 속행 또는 연기의 결의를 한 경우에는 총회소집절차를 따로 거치지 않아도 된다.","w":"속행·연기된 총회에는 소집통지 규정이 적용되지 않는다(상법 제372조 제2항).","c":"상","v":1},"공인회2017_52-20-1":{"f":"판례에 의하면 위 주주총회에 참석하여 의결권을 행사한 주주 B도 다른 주주가 소집통지를 받지 못하였음을 이유로 하여 결의취소의 소를 제기할 수 있다.","w":"소집절차 하자는 모든 주주에게 문제이므로 총회에 참석한 주주도 다른 주주의 통지 누락을 이유로 취소의 소를 제기할 수 있다는 것이 판례다.","c":"상","v":1},"공인회2019_54-15-3":{"f":"판례에 의하면 주주가 타인에게 의결권 행사를 위임하는 경우 포괄적으로 위임할 수 있다.","w":"의결권 대리행사의 위임은 개별 사항을 특정하지 않고 포괄적으로 해도 유효하다는 것이 판례다.","c":"상","v":1},"공인회2019_54-21-1":{"f":"주주총회에서 회의를 연기할 것을 결의한 경우 연기하는 주주총회일을 정하여 소집통지를 다시 하지 않아도 된다.","w":"연기된 총회는 별도의 소집통지나 공고 없이 열 수 있다(상법 제372조 제2항).","c":"상","v":1},"공인회2020_55-18-5":{"f":"자본금 총액이 10억원 미만인 회사의 경우 주주 전원이 서면으로 동의한 때에 한하여 서면에 의한 결의로써 주주총회의 결의를 갈음할 수 있다.","w":"자본금 10억원 미만 회사가 서면결의로 총회 결의를 갈음하려면 주주 전원의 동의가 있어야 한다(상법 제363조 제4항).","c":"상","v":1},"공인회2020_55-22-2":{"f":"결의취소의 소에는 법원의 재량에 의한 청구 기각이 인정되지만 결의부존재확인의 소에는 인정되지 않는다.","w":"재량기각은 결의취소의 소에서만 인정된다(상법 제379조).","c":"상","v":1},"공인회2021_56-17-1":{"f":"주주총회의 목적사항에 합병계약서 승인사항이 포함된 경우, 의결권 없는 주주에게도 총회소집을 통지하여야 한다.","w":"합병계약서 승인 같은 주식매수청구권이 생기는 사항이 안건이면 의결권 없는 주주에게도 소집을 통지해야 한다(상법 제363조 제7항).","c":"상","v":1},"공인회2021_56-18-5":{"f":"회사는 이사회의 결의로 주주가 총회에 출석하지 아니하고 전자적 방법으로 의결권을 행사하도록 할 수 있다.","w":"전자투표는 정관 규정 없이 이사회 결의로 정할 수 있다(상법 제368조의4 제1항).","c":"상","v":1},"공인회2021_56-19-2":{"f":"주주가 아닌 감사가 결의취소의 소를 제기한 경우, 법원은 회사의 청구가 있어도 담보를 제공할 것을 명할 수 없다.","w":"담보제공 명령 대상은 주주가 제기한 소이고, 이사나 감사가 제기하면 명할 수 없다(상법 제377조).","c":"상","v":1},"공인회2022_57-17-2":{"f":"보통결의 사항에 반대하는 주주에게는 주식매수청구권이 인정되지 않는다.","w":"주식매수청구권은 영업양도·합병 등 상법이 정한 특별결의 사항에서만 생긴다.","c":"상","v":1},"공인회2022_57-18-4":{"f":"감사를 전자투표로 선임하는 경우, 전자투표된 주식의 의결권수를 총회에 출석한 주주의 의결권수에 산입하고, 출석주주 의결권의 과반수로써 선임을 결의할 수 있다.","w":"전자투표를 채택한 회사는 발행주식총수 4분의 1 요건 없이 출석한 주주 의결권의 과반수로 감사를 선임할 수 있다(상법 제409조 제3항).","c":"상","v":1},"공인회2023_58-19-1":{"f":"주주가 주식의 신탁을 인수한 경우 회사는 그 주주의 의결권의 불통일행사를 거부할 수 없다.","w":"주식의 신탁을 인수했거나 타인을 위해 주식을 가진 주주의 불통일행사는 회사가 거부하지 못한다(상법 제368조의2 제2항).","c":"상","v":1},"공인회2023_58-21-4":{"f":"이사인 주주가 부당결의취소의 소를 제기한 때에는 법원은 회사의 청구가 있어도 제소주주로 하여금 담보를 제공하게 할 수 없다.","w":"주주가 이사나 감사이면 담보제공을 명할 수 없고, 이 규정은 부당결의취소의 소에도 준용된다(상법 제381조 제2항, 제377조 제1항 단서).","c":"상","v":1},"공인회2023_58-24-4":{"f":"이사회는 주주제안의 내용이 법령 또는 정관을 위반하는 경우와 그 밖에 대통령령으로 정하는 경우를 제외하고는 이를 주주총회의 목적사항으로 하여야 한다.","w":"법령 위반뿐 아니라 정관 위반과 시행령이 정한 사유도 거부 사유다(상법 제363조의2 제3항).","c":"상","v":1},"공인회2024_59-17-5":{"f":"자본금 총액이 10억원 미만인 회사는 주주총회 결의의 목적사항에 대하여 주주 전원이 서면으로 동의를 한 때에는 서면에 의한 결의가 있는 것으로 본다.","w":"과반수가 아니라 주주 전원이 서면으로 동의해야 서면결의가 있는 것으로 본다(상법 제363조 제4항).","c":"상","v":1},"공인회2024_59-18-4":{"f":"전자적 방법에 의한 의결권 행사는 이사회의 결의로 정할 수 있으며 정관의 근거가 필요하지 않다.","w":"전자투표는 이사회 결의로 도입한다(상법 제368조의4 제1항).","c":"상","v":1},"공인회2024_59-20-1":{"f":"주주총회의 결의의 내용이 법령에 위반한 때에는 결의무효확인의 소의 원인이 된다.","w":"내용이 법령에 위반한 결의는 무효확인의 소의 대상이고, 취소의 소는 소집절차나 결의방법의 하자 또는 정관 위반에 대한 것이다(상법 제376조, 제380조).","c":"상","v":1},"공인회2025_60-23-1":{"f":"이사회는 각 이사가 소집할 수 있으나, 이사회 결의로 소집할 이사를 지정할 수 있다.","w":"이사회 결의로 소집권자를 정할 수 있고, 그 경우 지정된 이사가 소집한다(상법 제390조 제1항).","c":"상","v":1},"공인회2025_60-23-2":{"f":"이사회의 소집통지를 해야 하는 때에는 각 이사와 감사에게 통지를 발송해야 한다.","w":"소집통지는 이사뿐 아니라 감사에게도 해야 한다(상법 제390조 제3항).","c":"상","v":1},"공인회2025_60-23-3":{"f":"이사회에서는 회의의 속행 또는 연기의 결의를 할 수 있다.","w":"이사회도 속행·연기 결의를 할 수 있고, 그 경우 별도의 소집절차가 필요 없다(상법 제392조, 제372조).","c":"상","v":1},"공인회2025_60-23-5":{"f":"이사회 소집통지가 일부 이사에게 누락되었음에도 이사회 결의가 이루어진 경우 그 결의는 원칙적으로 무효이며 상법에는 이사회결의취소소송이 없다.","w":"상법이 이사회 결의에 대해 정하는 것은 주주총회와 달리 취소의 소가 아니다. 소집통지 누락은 무효사유가 되어 무효확인의 소로 다툰다.","c":"중","v":1},"공인회2025_60-25-5":{"f":"회사의 채권자가 회사의 채무를 면제하는 의사표시를 회사에 하려면 공동대표이사 중 1인에 대해서만 하면 된다.","w":"공동대표이사가 있어도 회사에 대한 의사표시는 그중 1인에게 하면 효력이 있다(상법 제389조 제3항, 제208조 제2항).","c":"상","v":1},"공인회2026_61-21-2":{"f":"이사가 고의 또는 중대한 과실로 그 임무를 게을리 한 경우에 성립한 제3자에 대한 손해배상책임은 주주 전원의 동의로도 면제할 수 없다.","w":"주주 전원의 동의로 면제되는 것은 회사에 대한 책임이다(상법 제400조). 제3자에 대한 책임(제401조)은 해당하지 않는다.","c":"상","v":1},"공인회2026_61-22-4":{"f":"이사의 배우자가 자기 또는 제3자의 계산으로 회사와 거래를 하기 위하여는 미리 이사회에서 해당 거래에 관한 중요사실을 밝히고 이사 3분의 2 이상의 수로써 이사회의 승인을 받아야 한다.","w":"자기거래 승인은 이사 3분의 2 이상의 찬성이 필요하고 과반수로는 부족하다(상법 제398조).","c":"상","v":1},"공인회2026_61-25-1":{"f":"대표이사가 정관상 이사회 결의를 거쳐야 할 대외적 거래행위에 관해 이를 거치지 않은 경우 거래상대방이 이사회 결의가 없었음을 경과실로 알지 못하였다면 그 거래행위는 유효하다.","w":"이사회 결의가 필요한 거래라도 상대방이 결의 없음을 알았거나 중대한 과실로 몰랐을 때에만 무효가 된다.","c":"중","v":1},"공인회2016_51-19-3":{"f":"법률 또는 정관에 정한 이사의 원수를 결한 경우 법원은 이사·감사 그 밖의 이해관계인의 청구에 의하여 일시 이사의 직무를 행할 자를 선임할 수 있다.","w":"일시이사는 청구가 있어야 선임하며 법원이 직권으로 선임하지 못한다(상법 제386조 제2항).","c":"상","v":1},"공인회2016_51-20-5":{"f":"주주가 이사를 상대로 적법하게 대표소송을 제기한 후 그 주주가 주식을 전혀 보유하지 않게 된 경우에는 원고적격을 잃는다.","w":"제소 후 지분이 1% 미만으로 줄어도 소는 유지되지만(상법 제403조 제5항), 주식을 전혀 보유하지 않게 되면 원고적격을 상실한다는 것이 판례다.","c":"상","v":1},"공인회2016_51-21-4":{"f":"판례에 의하면 대표이사가 회사의 재산을 횡령하여 기존의 주주가 간접적인 손해를 입은 경우 주주는 그 대표이사를 상대로 자신에게 직접 그 손해를 배상할 것을 청구할 수 없다.","w":"회사가 입은 손해로 인한 주주의 간접손해는 제401조의 직접손해가 아니어서 이사에게 직접 배상을 청구할 수 없다는 것이 판례다.","c":"상","v":1},"공인회2016_51-22-3":{"f":"판례에 의하면 B를 직무대행자로 선임한 가처분은 제3자에게도 효력이 미친다.","w":"이사 직무집행정지와 직무대행자 선임 가처분은 당사자뿐 아니라 제3자에게도 효력이 미친다는 것이 판례다. 이 가처분은 본점 소재지에서 등기해야 한다(상법 제407조 제3항).","c":"상","v":1},"공인회2016_51-23-3":{"f":"주주총회에서 분식결산된 재무제표를 승인한 후 2년 내에 다른 결의가 없더라도 대표이사의 부정행위에 대해서는 책임을 해제한 것으로 보지 않는다.","w":"책임 해제 간주는 이사의 부정행위가 있는 경우에는 적용되지 않는다(상법 제450조). 분식결산은 부정행위에 해당한다.","c":"중","v":1},"공인회2017_52-11-5":{"f":"회사는 정관의 규정으로 사외이사의 회사에 대한 책임에 관하여 그 행위를 한 날 이전 최근 1년간의 보수액의 3배를 초과하는 금액에 대하여 면제할 수 있다.","w":"정관으로 감경할 수 있는 것은 이사의 회사에 대한 책임이다(상법 제400조 제2항). 제3자에 대한 책임(제401조)은 정관으로 면제할 수 없다.","c":"상","v":1},"공인회2017_52-13-1":{"f":"이사가 이사회의 승인 없이 제3자의 계산으로 회사의 영업부류에 속한 거래를 한 경우 회사는 이사회의 결의로 그 이사에 대하여 이로 인한 이득의 양도를 청구할 수 있다.","w":"제3자의 계산으로 한 거래는 회사의 계산으로 한 것으로 볼 수 없고, 이득의 양도를 청구한다. 회사의 계산으로 본다는 개입권은 자기의 계산으로 한 거래에 대한 것이다(상법 제397조 제2항).","c":"상","v":1},"공인회2017_52-13-2":{"f":"이사가 직무를 수행하는 과정에서 알게 된 회사의 이익이 될 수 있는 사업기회를 자기의 이익을 위하여 이용하기 위해서는 이사 3분의 2 이상의 수에 의한 이사회의 승인을 받아야 한다.","w":"사업기회 이용의 승인은 이사 3분의 2 이상의 수로 한다. 과반수로는 부족하다(상법 제397조의2 제1항).","c":"상","v":1},"공인회2017_52-13-4":{"f":"판례에 의하면 이사가 이사회의 승인 없이 한 자기거래는 이사와 회사 사이에서는 무효이지만, 제3자에 대하여는 그 제3자가 승인 없음을 알았거나 중대한 과실로 알지 못한 경우에 한하여 무효를 주장할 수 있다.","w":"회사가 제3자에게 무효를 주장하려면 제3자가 이사회 승인이 없음을 알았거나 중대한 과실로 몰랐다는 점을 증명해야 한다는 것이 판례다.","c":"상","v":1},"공인회2017_52-13-5":{"f":"판례에 의하면 이사가 이사회의 승인 없이 자기거래를 한 경우 회사만이 그 거래의 무효를 주장할 수 있고 거래의 상대방이나 제3자는 무효를 주장할 수 없다.","w":"승인 규정은 회사의 이익을 보호하려는 것이어서 무효 주장은 회사만 할 수 있다.","c":"상","v":1},"공인회2017_52-15-2":{"f":"최대주주가 아니면서 비상장회사의 발행주식총수의 10% 이상의 주식을 소유하는 주요주주와 그 배우자 및 직계 존속ㆍ비속도 그 회사의 사외이사로 선임될 수 있다.","w":"비상장회사 사외이사의 결격사유에는 최대주주와 그 배우자·직계존비속이 들어 있고 10% 이상 주요주주는 없다(상법 제382조 제3항). 주요주주와 그 배우자·직계존비속의 결격은 상장회사 독립이사에 관한 특례다(제542조의8 제2항 제6호).","c":"상","v":1},"공인회2018_53-22-1":{"f":"최근 사업연도 말 현재의 자산총액이 3천억원인 상장회사는 이사 총수의 3분의 1 이상을 독립이사로 하여야 한다.","w":"자산총액 2조원 미만 상장회사는 이사 총수의 3분의 1 이상을 독립이사로 두면 되고, 3명 이상이면서 이사 총수의 과반수여야 하는 요건은 2조원 이상 상장회사에만 적용된다(상법 제542조의8 제1항, 시행령 제34조 제2항). 2025년 개정 전에는 사외이사 4분의 1 이상이었다.","c":"상","v":1},"공인회2018_53-22-3":{"f":"사외이사의 사임으로 인하여 사외이사의 수가 상법상의 이사회의 구성요건에 미달하게 되면 그 사유가 발생한 후 처음 소집되는 주주총회에서 그 요건에 합치되도록 사외이사를 선임하여야 한다.","w":"요건에 미달하게 된 사유가 생긴 뒤 처음 소집되는 주주총회에서 선임해야 한다(상법 제542조의8 제3항). 2025년 개정으로 상장회사의 사외이사는 독립이사로 이름이 바뀌었다.","c":"상","v":1},"공인회2018_53-22-4":{"f":"최근 사업연도 말 현재의 자산총액이 2조원 이상인 상장회사가 주주총회에서 사외이사를 선임하려는 때에는 사외이사 후보추천위원회의 추천을 받은 자 중에서 선임하여야 한다.","w":"후보추천위원회를 설치하고 그 추천을 받은 사람 중에서 선임해야 하는 회사는 자산총액 2조원 이상 상장회사다(상법 제542조의8 제4항·제5항, 시행령 제34조 제2항). 7천억원 회사는 해당하지 않는다.","c":"상","v":1},"공인회2018_53-22-5":{"f":"사외이사 후보추천위원회 설치의무가 있는 회사가 설치하는 사외이사 후보추천위원회는 사외이사가 총위원의 과반수가 되도록 구성하여야 한다.","w":"후보추천위원회는 독립이사(2025년 개정 전 사외이사)가 총위원의 과반수가 되도록 구성한다(상법 제542조의8 제4항).","c":"상","v":1},"공인회2018_53-25-1":{"f":"집행임원은 이사회에서 선임되며 회사의 업무집행을 담당한다.","w":"집행임원의 선임·해임은 이사회 권한이다(상법 제408조의2 제3항 제1호).","c":"상","v":1},"공인회2018_53-25-3":{"f":"집행임원 설치회사는 이사회의 회의를 주관하기 위하여 이사회 의장을 두어야 하고 정관에 정함이 없으면 이사회 결의로 선임한다.","w":"이사회 의장을 반드시 사외이사 중에서 뽑아야 하는 것은 아니다. 정관에 정하지 않으면 이사회 결의로 선임한다(상법 제408조의2 제4항).","c":"중","v":1},"공인회2018_53-25-4":{"f":"집행임원의 임기는 정관에 다른 규정이 없으면 2년을 초과하지 못한다.","w":"집행임원의 임기는 정관에 달리 정하지 않으면 2년을 초과할 수 없다(상법 제408조의3 제1항). 이사의 3년과 다르다.","c":"상","v":1},"공인회2018_53-25-5":{"f":"이사회는 집행임원의 업무집행을 감독할 권한을 가지지만 이사를 집행임원으로 선임할 수 있다.","w":"이사가 집행임원을 겸하는 것은 허용된다.","c":"중","v":1},"공인회2018_53-32-4":{"f":"회사의 진정한 대표이사가 아닌 지배주주가 표현대표이사의 명칭 사용을 허용한 경우에는 회사의 귀책사유가 인정되지 않는다.","w":"표현대표이사 책임은 회사 대표기관이 명칭 사용을 허용했을 때 성립한다. 진정한 대표이사가 아닌 지배주주의 허용은 회사의 귀책으로 보지 않는다는 것이 판례다.","c":"상","v":1},"공인회2019_54-24-2":{"f":"회사가 집중투표제에 의해 이사를 선임하기 위해서는 정관에 집중투표를 배제하는 규정이 없어야 하며, 정관에 집중투표제를 채택하는 규정을 둘 필요는 없다.","w":"집중투표는 정관으로 배제하지 않는 한 소수주주의 청구로 할 수 있다(상법 제382조의2 제1항).","c":"상","v":1},"공인회2019_54-26-1":{"f":"이사가 경업금지의무를 위반한 경우 회사는 그 거래가 있은 날로부터 1년 내에 개입권을 행사할 수 있다.","w":"이사의 경업에 대한 개입권은 거래가 있은 날부터 1년이 지나면 소멸한다(상법 제397조 제3항). 안 날을 기준으로 하는 기간은 없다.","c":"상","v":1},"공인회2019_54-26-2":{"f":"자본금 총액이 10억원 미만으로서 2인의 이사를 둔 회사에는 이사회가 없으므로 이사의 3개월마다 이사회에 대한 업무집행상황 보고 규정이 적용되지 않는다.","w":"이사가 1명 또는 2명인 자본금 10억원 미만 회사에는 이사회가 없어 3개월마다 이사회에 업무집행상황을 보고하는 규정이 적용되지 않고(상법 제383조 제5항, 제393조 제4항), 이를 주주총회 보고로 바꾸는 규정도 없다.","c":"상","v":1},"공인회2019_54-26-4":{"f":"이사는 이사회의 승인을 얻은 때에 한하여 동종영업을 목적으로 하는 다른 회사의 이사의 직을 겸할 수 있다.","w":"경업 승인에는 3분의 2 이상 요건이 없고 이사회의 승인으로 충분하다(상법 제397조 제1항). 3분의 2 이상은 사업기회 이용(제397조의2)과 자기거래(제398조)에 요구된다.","c":"중","v":1},"공인회2019_54-26-5":{"f":"이사는 직무상 알게 된 회사의 영업상 비밀을 재임 중은 물론 퇴임 후에도 누설하여서는 아니 된다.","w":"영업비밀 누설 금지는 퇴임 후에도 계속된다(상법 제382조의4).","c":"상","v":1},"공인회2019_54-29-1":{"f":"이사가 회사에 대하여 소를 제기한 경우 감사가 그 소에 관하여 회사를 대표한다.","w":"이사와 회사 사이의 소에서는 감사가 회사를 대표한다(상법 제394조 제1항).","c":"상","v":1},"공인회2019_54-29-2":{"f":"집행임원 설치회사의 경우 집행임원의 선임 및 해임의 권한은 이사회에 있다.","w":"집행임원은 이사회가 선임·해임한다(상법 제408조의2 제3항).","c":"상","v":1},"공인회2019_54-29-3":{"f":"집행임원의 임기는 정관에 다른 규정이 없으면 2년을 초과하지 못한다.","w":"집행임원의 임기는 2년을 넘지 못한다(상법 제408조의3 제1항). 3년이 아니다.","c":"상","v":1},"공인회2019_54-29-5":{"f":"회사는 대표이사의 대표권의 제한을 이유로 선의의 제3자에게 대항할 수 없다.","w":"대표권의 제한은 선의의 제3자에게 대항하지 못한다(상법 제389조 제3항, 제209조 제2항).","c":"상","v":1},"공인회2020_55-20-2":{"f":"판례에 의하면, 이사가 그 의사에 반하여 해임될 경우 일정한 해직보상금을 지급받기로 약정한 때에는 이는 보수에 포함되므로, 정관에 그 액을 정하는 규정이나 주주총회의 결의가 없으면 이사는 회사에 대하여 이를 청구할 수 없다.","w":"해직보상금도 이사의 보수에 해당하여 정관이나 주주총회 결의로 정해야 한다(상법 제388조).","c":"상","v":1},"공인회2020_55-21-4":{"f":"판례에 의하면, 이사가 회사에 손해를 발생시킨 경우 법원은 손해의 공평한 분담이라는 견지에서 이사의 책임을 재량으로 제한할 수 있다.","w":"이사의 책임은 정관·주주총회에 의한 감경 외에도, 법원이 신의칙과 손해의 공평한 분담 원칙에 따라 제한할 수 있다는 것이 판례다.","c":"상","v":1},"공인회2020_55-24-3":{"f":"이사회의 결의는 이사 과반수의 출석과 출석이사의 과반수로 하여야 하지만, 정관으로 그 비율을 높게 정할 수 있다.","w":"이사회 결의 요건은 정관으로 높일 수 있고 낮출 수는 없다(상법 제391조 제1항).","c":"상","v":1},"공인회2021_56-20-3":{"f":"주주총회에서 이사를 선임하는 경우, 주주총회 선임결의와 피선임자의 승낙이 있으면 별도의 임용계약 없이 이사의 지위를 취득한다.","w":"이사 지위는 주주총회의 선임결의와 피선임자의 승낙으로 생기고, 대표이사와의 임용계약은 필요 없다는 것이 판례다.","c":"상","v":1},"공인회2021_56-21-4":{"f":"주주총회의 결의로 이사의 퇴직위로금액이 결정된 경우, 퇴임한 특정이사에 대하여 새로운 주주총회에서 그 퇴직위로금을 박탈하는 결의를 하더라도 그 박탈하는 결의는 효력이 없다.","w":"이미 확정된 퇴직위로금 청구권은 사후의 총회 결의로 박탈할 수 없다는 것이 판례다.","c":"상","v":1},"공인회2021_56-22-5":{"f":"이사 자신이 직접 출석하여 이사회의 결의에 참가할 수 없는 경우라도 대리인에 의한 출석은 인정되지 않는다.","w":"이사는 개인적 신임에 기초한 지위이므로 이사회에는 본인이 직접 출석해야 하고 대리 출석은 허용되지 않는다.","c":"상","v":1},"공인회2021_56-23-3":{"f":"이사와 회사 사이의 거래라도 양자 사이의 이해가 상반되지 않고 회사에 불이익을 초래할 우려가 없는 때에는 이사회의 승인을 받을 필요가 없다.","w":"자기거래 규제는 이사와 회사 사이의 이해 충돌을 막으려는 취지여서 불이익 우려가 없는 거래에는 적용되지 않는다는 것이 판례다.","c":"상","v":1},"공인회2021_56-24-3":{"f":"대표이사가 회사재산을 횡령하여 회사가 손해를 입고 결과적으로 주주의 경제적 이익이 침해되는 간접적인 손해는 이사의 제3자에 대한 책임에서의 손해의 개념에 포함되지 않는다.","w":"상법 제401조의 손해는 직접손해만을 뜻하고 회사의 손해로 인한 주주의 간접손해는 포함되지 않는다는 것이 판례다.","c":"상","v":1},"공인회2022_57-19-5":{"f":"판례에 의하면, 대표이사가 중요한 자산의 처분에 관하여 이사회의 결의를 거치지 않고 거래한 경우, 그 거래상대방이 이사회 결의 부존재 사실을 경과실로 인식하지 못한 때에는 그 거래행위는 유효하다.","w":"이사회 결의가 필요한 거래라도 상대방이 결의 없음을 알았거나 중대한 과실로 몰랐을 때에만 무효가 된다.","c":"중","v":1},"공인회2022_57-22-1":{"f":"이사가 경과실로 그 임무를 게을리한 경우에도 이사는 회사에 대하여 손해배상책임을 부담한다.","w":"이사는 선량한 관리자의 주의의무를 지므로 경과실로도 임무를 게을리하면 회사에 대한 책임이 생긴다(상법 제399조 제1항).","c":"상","v":1},"공인회2022_57-22-2":{"f":"이사의 회사에 대한 손해배상책임은 주주 전원의 동의가 있으면 면제할 수 있다.","w":"주주 전원이 동의하면 이사의 회사에 대한 책임을 면제할 수 있다(상법 제400조 제1항).","c":"상","v":1},"공인회2022_57-22-3":{"f":"회사의 손해를 발생시킨 이사의 행위가 이사회의 결의에 의한 경우, 그 결의에 반대한 것으로 의사록에 기재된 이사는 회사에 대하여 손해배상책임을 부담하지 않는다.","w":"이사회 결의에 의한 책임은 결의에 찬성한 이사가 진다. 반대 기재가 있으면 책임이 없다(상법 제399조 제2항·제3항).","c":"상","v":1},"공인회2022_57-22-4":{"f":"이사회 결의에 참가한 이사로서 이의를 한 기재가 의사록에 없는 이사는 결의에 찬성한 것으로 추정되므로 회사가 찬성 사실을 따로 증명할 필요가 없다.","w":"이의 기재가 없으면 찬성으로 추정하고(상법 제399조 제3항), 반증책임은 이사에게 있다.","c":"상","v":1},"공인회2023_58-20-2":{"f":"이사의 임기가 임기 중의 최종 결산기에 관한 정기주주총회가 종결하기 전에 만료할 때에는 정관으로 정기주주총회의 종결에 이르기까지 임기를 연장할 수 있다.","w":"임기 연장은 이사회 결의로는 할 수 없고 정관 규정이 있어야 한다(상법 제383조 제3항).","c":"상","v":1},"공인회2023_58-22-1":{"f":"감사위원회를 설치한 경우 감사위원회 위원은 이사회의 구성원이다.","w":"감사위원회는 이사회 내 위원회이고 위원은 이사다(상법 제415조의2 제2항).","c":"상","v":1},"공인회2023_58-28-4":{"f":"집행임원 설치회사는 대표이사를 둘 수 없다.","w":"집행임원을 두는 회사는 대표이사 대신 대표집행임원을 두며 대표이사를 두지 못한다(상법 제408조의2 제1항).","c":"상","v":1},"공인회2024_59-21-3":{"f":"이사가 그 직무에 관하여 부정행위가 있음에도 불구하고 주주총회에서 이사의 해임을 부결한 때에는 발행주식총수의 100분의 3 이상의 주식을 가진 주주가 주주총회의 결의가 있은 날부터 1월 내에 그 이사의 해임을 법원에 청구할 수 있다.","w":"해임청구권자는 회사채권자가 아니라 발행주식총수 3% 이상의 주주다(상법 제385조 제2항).","c":"상","v":1},"공인회2025_60-27-1":{"f":"감사를 선임하지 아니한 자본금 10억원 미만의 회사가 이사에게 소를 제기하는 경우 회사, 이사 또는 이해관계인은 법원에 회사를 대표할 자를 선임하여 줄 것을 신청하여야 한다.","w":"감사를 두지 않은 소규모 회사와 이사 사이에 소가 제기되면 회사·이사·이해관계인의 신청에 따라 법원이 회사를 대표할 사람을 선임한다(상법 제409조 제4항·제5항).","c":"상","v":1},"공인회2025_60-27-3":{"f":"회사는 감사위원회를 설치한 경우 감사를 둘 수 없다.","w":"감사위원회를 설치하면 감사를 둘 수 없다. 감사위원회와 감사는 양자택일이다(상법 제415조의2 제1항).","c":"상","v":1},"공인회2025_60-27-4":{"f":"감사위원회 위원은 이사이므로 이사회에 참석하여 모든 결의안에 대하여 의결권을 행사할 수 있다.","w":"감사위원회 위원은 이사회의 구성원이므로 이사회 결의에서 의결권이 있다.","c":"상","v":1},"공인회2025_60-27-5":{"f":"감사위원회는 그 결의로 위원회를 대표할 자를 선정하여야 하며 수인의 위원이 공동으로 위원회를 대표할 것을 정할 수도 있다.","w":"감사위원회는 결의로 대표를 선정해야 하고, 여러 위원이 공동으로 대표하도록 정할 수도 있다(상법 제415조의2 제4항).","c":"상","v":1},"공인회2025_60-31-5":{"f":"주주의 열람·등사청구의 대상이 회계서류인 경우에는 그 작성명의인이 반드시 회사에 국한되지 않고, 원본에 국한되는 것도 아니다.","w":"회사가 보관하는 회계 관련 서류는 작성명의인이 회사가 아니어도 열람·등사 대상에 해당하고, 사본도 포함된다는 것이 판례다.","c":"중","v":1},"공인회2025_60-35-1":{"f":"회사의 재무제표의 작성책임은 대표이사와 회계담당 임원에게 있으며, 회계담당 임원이 없는 경우에는 회계업무를 집행하는 직원에게 있다.","w":"회계담당 임원이 없으면 회계업무를 집행하는 직원이 대표이사와 함께 재무제표 작성책임을 진다(외부감사법 제6조 제1항).","c":"상","v":1},"공인회2025_60-35-2":{"f":"주권상장법인 등 대통령령으로 정하는 회사는 해당 사업연도의 재무제표를 작성하여 감사인의 감사를 받기 전에 이를 증권선물위원회에 제출하여야 한다.","w":"감사인에게 낸 재무제표를 증권선물위원회에도 제출해야 하는 회사는 주권상장법인과 대통령령으로 정하는 회사뿐이다(외부감사법 제6조 제4항).","c":"상","v":1},"공인회2025_60-35-4":{"f":"주권상장법인의 감사인이 되려는 회계법인은 등록요건을 모두 갖추어 금융위원회에 등록하여야 하며, 등록한 감사인이 등록요건을 갖추지 못하게 되는 경우 금융위원회는 해당 감사인의 주권상장법인 감사인 등록을 취소할 수 있다.","w":"주권상장법인 감사인 등록의 취소 권한은 금융위원회에 있다(외부감사법 제9조의2 제5항).","c":"상","v":1},"공인회2025_60-35-5":{"f":"지배회사는 연결재무제표 작성을 위하여 필요한 범위에서 종속회사의 회계에 관한 장부와 서류를 열람하거나 복사할 수 있다.","w":"지배회사는 연결재무제표 작성에 필요한 범위에서 종속회사의 회계 장부와 서류를 열람하거나 복사할 수 있다(외부감사법 제7조 제1항).","c":"상","v":1},"공인회2025_60-36-2":{"f":"회사는 증권선물위원회로부터 지정받은 감사인을 지정 사업연도 이후 최초로 도래하는 사업연도의 감사인으로 선임할 수 없다.","w":"지정받은 감사인은 지정 사업연도가 끝난 뒤 처음 오는 사업연도의 감사인으로 선임할 수 없다(외부감사법 제11조 제6항).","c":"상","v":1},"공인회2025_60-38-1":{"f":"증권선물위원회는 회계처리기준과 회계감사기준의 준수 여부에 대한 감리업무뿐 아니라 감사인의 업무설계와 운영에 관한 기준인 품질관리기준의 준수 여부에 대한 감리업무도 할 수 있다.","w":"증권선물위원회의 감리 업무에는 감사인의 품질관리기준 준수 여부에 대한 감리와 품질관리수준 평가도 들어 있다(외부감사법 제26조 제1항 제3호).","c":"상","v":1},"공인회2025_60-38-2":{"f":"증권선물위원회는 감리업무 수행을 위해 회사 또는 관계회사와 감사인에게 자료의 제출을 요구할 수 있고, 감사인 지정업무를 수행하기 위하여 필요한 경우 세무관서의 장에게 자료 제출을 요청할 수 있다.","w":"증권선물위원회는 감사인 지정 업무에 필요하면 세무관서의 장에게 대통령령으로 정하는 자료의 제출을 요청할 수 있다(외부감사법 제27조 제3항).","c":"상","v":1},"공인회2025_60-38-3":{"f":"보험업법에 따른 보험회사가 감사인 또는 감사에 참여한 공인회계사에 대하여 손해배상 청구의 소를 제기하는 경우, 보험회사가 감사인 또는 감사에 참여한 공인회계사가 임무를 게을리하였음을 증명하여야 한다.","w":"감사인은 원칙적으로 임무를 게을리하지 않았음을 스스로 증명해야 면책되지만, 보험회사가 소를 제기하면 보험회사가 감사인의 임무 해태를 증명해야 한다(외부감사법 제31조 제7항 단서 제4호).","c":"상","v":1},"공인회2025_60-38-5":{"f":"금융위원회는 감사인이 고의 또는 중대한 과실로 회계감사기준을 위반하여 감사보고서를 작성한 경우 과징금을 부과할 수 있다.","w":"감사인에 대한 과징금은 고의 또는 중대한 과실로 회계감사기준을 위반해 감사보고서를 작성한 경우에 부과하고, 한도는 그 감사로 받은 보수의 5배다(외부감사법 제35조 제2항).","c":"상","v":1},"공인회2025_60-39-1":{"f":"회계법인은 감사업무를 할 때 그 업무를 총괄하고 책임지는 이사를 지정하여야 하며, 지정된 이사는 지정된 업무를 수행할 때 각자 회계법인을 대표한다.","w":"감사업무를 총괄하도록 지정된 이사는 그 업무를 수행할 때 각자 회계법인을 대표하고, 대표이사와 공동으로 대표하지 않는다(공인회계사법 제34조 제2항·제3항).","c":"상","v":1},"공인회2025_60-39-2":{"f":"회계법인은 이사가 아닌 소속공인회계사로 하여금 회계에 관한 감사 또는 증명에 관한 업무를 행하게 할 수 있다.","w":"회계법인이 감사·증명 업무를 맡길 수 없는 사람은 이사도 소속공인회계사도 아닌 자이므로, 소속공인회계사도 이 업무를 할 수 있다(공인회계사법 제34조 제1항).","c":"상","v":1},"공인회2025_60-39-3":{"f":"미국의 공인회계사가 한국공인회계사회에 입회하는 경우 한국에서 국제적으로 통용되는 국제회계기준에 관한 자문업무를 수행할 수 있으나 한국의 법인세 세무대리업무는 수행할 수 없다.","w":"외국공인회계사의 직무는 원자격국의 회계법·회계기준에 관한 자문과 국제회계법·국제회계기준에 관한 자문뿐이고, 국내 세무대리는 들어 있지 않다(공인회계사법 제40조의3).","c":"상","v":1},"공인회2025_60-39-4":{"f":"A회계법인이 분할을 결정하여 B회계법인을 새로이 설립한 경우 A회계법인이 분할 전 체결한 기존 감사계약은 B회계법인이 승계할 수 있다.","w":"분할로 새로 설립되는 회계법인은 분할계획서가 정하는 바에 따라 분할 전 회계법인의 감사계약을 승계할 수 있다(공인회계사법 제37조의2 제4항).","c":"상","v":1},"공인회2025_60-40-1":{"f":"공인회계사는 서울 사무소와 지방 사무소를 동시에 둘 수 없다.","w":"공인회계사는 어떤 명목으로도 사무소를 둘 이상 둘 수 없다(공인회계사법 제12조 제2항).","c":"상","v":1},"공인회2025_60-40-2":{"f":"A회계법인에 고용된 외국공인회계사는 A회계법인의 사원은 될 수 있지만 이사는 될 수 없다.","w":"회계법인에 고용된 외국공인회계사는 사원이 될 수 있으나 이사는 될 수 없다(공인회계사법 제26조 제1항 제4호·제5항).","c":"상","v":1},"공인회2025_60-40-4":{"f":"C공인회계사의 배우자가 乙회사의 재무에 관한 사무의 책임이 있는 팀장으로 근무하고 있는 경우, C공인회계사는 乙회사의 감사위원회의 동의가 있더라도 乙회사의 감사업무를 수행할 수 없다.","w":"배우자가 재무 사무의 책임 있는 담당자로 있는 회사의 재무제표는 감사위원회 동의와 관계없이 감사할 수 없다(공인회계사법 제21조 제1항 제1호).","c":"상","v":1},"공인회2025_60-40-5":{"f":"공인회계사는 다른 사람에게 그 등록증을 대여할 수 없다.","w":"공인회계사는 업무 범위와 관계없이 등록증을 다른 사람에게 빌려주지 못한다(공인회계사법 제22조 제1항).","c":"상","v":1},"공인회2026_61-23-5":{"f":"대표소송의 소를 제기한 주주는 제소시에 발행주식총수의 100분의 1 이상의 주식을 보유하면 족하고, 제소 후 100분의 1 미만으로 감소하더라도 원고적격이 유지된다.","w":"보유 요건은 제소 시에만 필요하고 제소 후 지분이 1% 미만으로 줄어도 소는 유지된다(상법 제403조 제5항). 주식을 전혀 보유하지 않게 되면 원고적격을 잃는다.","c":"상","v":1},"공인회2026_61-24-3":{"f":"이사회는 감사위원회가 결의한 사항에 대하여 다시 결의할 수 없다.","w":"이사회는 다른 위원회의 결의는 다시 결의할 수 있지만 감사위원회의 결의는 다시 결의할 수 없다(상법 제415조의2 제6항, 제393조의2 제4항).","c":"상","v":1},"공인회2026_61-34-5":{"f":"준법지원인은 준법통제기준의 준수여부를 점검하여 그 결과를 이사회에 보고하여야 한다.","w":"준법지원인은 점검 결과를 주주총회가 아니라 이사회에 보고한다(상법 제542조의13 제3항).","c":"상","v":1},"공인회2026_61-35-2":{"f":"수산업협동조합법에 따른 수협은행의 재무제표에 대한 감사는 회계법인인 감사인이 한다.","w":"수협은행은 외부감사법상 금융회사여서 회계법인인 감사인만 감사할 수 있다(외부감사법 제9조 제1항 제3호).","c":"상","v":1},"공인회2026_61-36-1":{"f":"외부감사의 대상이 되는 회사 중 직전 사업연도 말의 자산총액이 1천억원 미만인 주권상장법인의 감사인은 회계감사를 실시할 때 내부회계관리제도의 운영실태에 관한 보고내용을 검토하여야 한다.","w":"자산총액 1천억원 미만 주권상장법인의 감사인은 내부회계관리제도 운영실태 보고내용을 감사하지 않고 검토한다(외부감사법 제8조 제6항).","c":"상","v":1},"공인회2026_61-38-1":{"f":"감사위원회가 설치된 대형비상장주식회사는 감사위원회가 선정한 회계법인을 감사인으로 선임하여야 한다.","w":"감사위원회가 설치된 대형비상장주식회사는 감사위원회가 선정한 감사인을 선임한다. 감사인선임위원회의 승인은 감사위원회가 없는 회사의 감사가 감사인을 선정할 때 받는다(외부감사법 제10조 제4항 제1호).","c":"상","v":1},"공인회2026_61-38-2":{"f":"회사는 감사인을 선임 또는 변경선임하는 경우 원칙적으로 감사 또는 감사위원회가 선정한 회계법인 또는 감사반을 선임하며, 주주총회의 승인을 미리 얻을 필요는 없다.","w":"감사인은 감사나 감사위원회가 선정하고 주주총회의 사전 승인은 요건이 아니다. 사원총회 승인은 감사가 없는 일정 규모 이상 유한회사에만 해당하고, 선임 사실은 선임 뒤 정기총회에 보고하거나 주주에게 통지·공고한다(외부감사법 제10조 제4항, 제12조 제1항).","c":"상","v":1},"공인회2026_61-38-3":{"f":"회계법인인 감사인은 동일한 소속공인회계사에게 주권상장법인인 회사의 연속하는 3개 사업연도에 대한 감사업무를 수행하게 한 경우, 그 다음 사업연도에는 그 소속공인회계사의 3분의 2 이상을 교체하여야 한다.","w":"교체해야 하는 비율은 그 소속공인회계사의 3분의 2 이상이다(외부감사법 제9조 제6항).","c":"상","v":1},"공인회2026_61-38-4":{"f":"주권상장법인은 재무제표를 작성하여 회사로부터 독립된 외부의 감사인에 의한 회계감사를 받아야 하며 이 경우 재무제표 및 연결재무제표의 감사인은 동일하여야 한다.","w":"외부감사 대상 회사의 재무제표와 연결재무제표의 감사인은 같아야 한다(외부감사법 제4조 제1항).","c":"상","v":1},"공인회2026_61-39-1":{"f":"금고이상의 형의 선고유예를 받고 그 유예기간 중에 있는 자는 공인회계사가 될 수 없다.","w":"선고유예는 그 유예기간 중에만 결격사유이고, 기간이 끝난 뒤 2년을 기다려야 하는 것은 집행유예다(공인회계사법 제4조 제3호·제4호).","c":"상","v":1},"공인회2026_61-40-3":{"f":"회계법인의 자본금은 5억원 이상이어야 한다.","w":"회계법인의 자본금은 5억원 이상이어야 한다(공인회계사법 제27조 제1항).","c":"상","v":1},"공인회2016_51-24-2":{"f":"최근 사업연도 말 현재의 자산총액이 1천억원 이상인 상장회사는 감사위원회를 둘 수 있고, 감사위원회를 두는 경우에는 상근감사를 두지 않아도 된다.","w":"상장회사는 상근감사를 두어야 하지만 감사위원회를 설치하면 이를 면한다(상법 제542조의10). 감사위원회 설치는 허용된다.","c":"상","v":1},"공인회2016_51-24-3":{"f":"최근 사업연도 말 현재의 자산총액이 2조원 이상인 상장회사의 감사위원회 위원을 선임하거나 해임하는 권한은 주주총회에 있다.","w":"대규모 상장회사의 감사위원 선임·해임은 주주총회가 한다(상법 제542조의12). 이사회는 해임권이 없다.","c":"상","v":1},"공인회2016_51-24-4":{"f":"회사가 감사의 임기 내에 정당한 이유 없이 감사를 해임하는 경우 그 감사는 회사에 대하여 해임으로 인한 손해배상을 청구할 수 있다.","w":"임기 중 정당한 이유 없는 해임은 손해배상 사유다(상법 제415조, 제385조 제1항).","c":"상","v":1},"공인회2016_51-24-5":{"f":"상장회사는 주주총회에서 감사의 보수와 이사의 보수를 별도 안건으로 상정하여 각각 의결하여야 한다.","w":"감사의 보수는 이사의 보수와 구분하여 의결한다(상법 제542조의12 제5항).","c":"중","v":1},"공인회2017_52-17-4":{"f":"비상장회사의 감사를 해임하는 경우에는 3%를 초과하는 주식에 대한 의결권 제한이 적용되지 않는다.","w":"3% 초과 의결권 제한은 감사를 선임할 때 적용되고 해임에는 적용되지 않는다(상법 제409조 제2항). 해임은 주주총회 특별결의로 한다.","c":"상","v":1},"공인회2018_53-12-1":{"f":"판례에 의하면 타인의 승낙을 얻어 그 타인의 명의로 주식을 취득한 명의차용인은 주주명부에 명의개서를 하지 않으면 대표소송을 제기할 수 없다.","w":"회사에 대하여 주주로 인정되는 사람은 주주명부상 주주이므로 명의개서 없는 명의차용인은 대표소송의 원고가 될 수 없다는 것이 판례다.","c":"상","v":1},"공인회2018_53-27-3":{"f":"신주발행유지청구를 할 수 있는 주주는 지분율에 제한이 없고 주주이면 누구나 할 수 있다.","w":"신주발행유지청구는 소수주주권이 아니라 단독주주권이다(상법 제424조).","c":"상","v":1},"공인회2019_54-27-1":{"f":"모회사의 감사는 당해회사 이사의 직을 겸할 수 없고 자회사의 이사의 직도 겸할 수 없다.","w":"감사는 회사 및 자회사의 이사 또는 지배인 기타 사용인을 겸하지 못한다(상법 제411조).","c":"상","v":1},"공인회2019_54-27-2":{"f":"감사위원회위원은 이사로서 경업금지의무와 회사의 사업기회유용금지의무를 부담한다.","w":"감사위원은 이사이므로 이사에게 적용되는 경업금지와 사업기회유용금지 의무가 모두 적용된다.","c":"상","v":1},"공인회2019_54-27-3":{"f":"감사는 신주발행유지청구권은 행사할 수 없으나 이사에 대한 위법행위유지청구권은 행사할 수 있다.","w":"이사의 위법행위 유지청구는 감사도 할 수 있지만(상법 제402조), 신주발행 유지청구는 불이익을 받을 염려가 있는 주주만 할 수 있다(상법 제424조).","c":"중","v":1},"공인회2019_54-27-4":{"f":"최근 사업연도 말 현재의 자산총액이 2조원 이상인 상장회사는 주주총회에서 감사위원회위원이 되는 이사를 선임하여야 하며 이사회 결의로는 감사위원회위원을 선임할 수 없다.","w":"대규모 상장회사에서는 감사위원 선임을 주주총회가 한다(상법 제542조의12).","c":"상","v":1},"공인회2020_55-19-2":{"f":"대표소송을 제기한 주주는 제소시에 발행주식총수의 100분의 1 이상의 주식을 보유하면 되고, 제소 후 1% 미만으로 감소하더라도 원고적격이 유지된다.","w":"보유요건은 제소 시에만 요구되며 제소 후 1% 미만이 되어도 소는 유지된다(상법 제403조 제5항).","c":"상","v":1},"공인회2020_55-27-3":{"f":"판례에 의하면, 해임된 이사에 대하여 회사가 소를 제기하는 경우에는 감사가 아니라 대표이사가 그 소에 관하여 회사를 대표한다.","w":"감사의 회사 대표는 현재 이사인 사람에 대한 소를 전제로 한다. 소 제기 시점에 이사가 아니면 대표이사가 대표한다는 것이 판례다.","c":"중","v":1},"공인회2022_57-23-4":{"f":"청산인의 회사에 대한 손해배상책임을 추궁하기 위한 대표소송도 허용된다.","w":"이사의 책임을 묻는 대표소송 규정은 청산인에게 준용된다(상법 제542조 제2항).","c":"상","v":1},"공인회2022_57-24-2":{"f":"감사록에는 감사의 실시요령과 그 결과를 기재해야 하고, 감사를 실시한 감사는 기명날인 또는 서명하여야 한다.","w":"서명 의무는 감사를 실시한 감사에게 있다. 감사를 하지 않은 감사까지 서명하는 것이 아니다(상법 제413조의2 제2항).","c":"상","v":1},"공인회2023_58-26-1":{"f":"감사를 여러 명 선임한 경우에도 각 감사는 독립하여 감사업무를 수행하며 회의체를 구성하지 않는다.","w":"감사는 독임제 기관이어서 각자 단독으로 직무를 수행한다.","c":"상","v":1},"공인회2023_58-26-3":{"f":"자회사의 감사는 모회사의 사내이사를 겸직할 수 있다.","w":"상법 제411조가 금지하는 겸직은 회사의 감사가 그 회사 및 자회사의 이사 등을 겸하는 경우다. 자회사 감사가 모회사의 이사를 겸하는 경우는 금지 대상이 아니다.","c":"중","v":1},"공인회2023_58-26-4":{"f":"이사회는 감사위원회가 결의한 사항에 대하여 다시 결의할 수 없다.","w":"이사회는 감사위원회가 결의한 사항을 다시 결의할 수 없다. 이사회 재결의를 허용하는 제393조의2 제4항 후단은 감사위원회에 적용되지 않는다(상법 제415조의2 제6항).","c":"상","v":1},"공인회2023_58-26-5":{"f":"회사가 감사위원회 위원에게 소를 제기하는 경우 감사위원회는 법원에 회사를 대표할 자를 선임해 줄 것을 신청하여야 한다.","w":"감사위원회 위원과 회사 사이의 소에서는 감사위원회나 이사가 법원에 대표자 선임을 신청한다(상법 제394조 제2항).","c":"상","v":1},"공인회2024_59-19-4":{"f":"회계장부 열람등사청구권의 행사가 회사에 지나치게 불리한 시기를 택하여 이루어지는 경우에는 청구의 목적이 정당하지 않다.","w":"회사에 지나치게 불리한 시기를 택한 청구는 정당한 목적을 결한 부당한 청구다(상법 제466조).","c":"상","v":1},"공인회2024_59-23-2":{"f":"업무집행지시자의 회사에 대한 손해배상책임을 추궁하기 위한 대표소송도 허용된다.","w":"업무집행지시자 등은 그가 지시하거나 집행한 업무에 관하여 제399조·제403조 등을 적용할 때 이사로 보므로, 그 책임을 묻는 대표소송을 제기할 수 있다(상법 제401조의2 제1항).","c":"상","v":1},"공인회2024_59-24-2":{"f":"비상장주식회사의 감사위원회 위원의 해임에 관한 이사회의 결의는 이사 총수의 3분의 2 이상의 결의로 하여야 한다.","w":"이사 총수의 3분의 2 이상이라는 가중 요건은 해임 결의에만 있다. 선임은 일반 이사회 결의로 한다(상법 제415조의2 제3항).","c":"상","v":1},"공인회2024_59-31-1":{"f":"상장회사는 발행주식총수의 100분의 20의 범위에서 주식매수선택권을 부여할 수 있고 관계 회사의 이사, 집행임원, 감사 또는 피용자에게도 부여할 수 있다.","w":"상장회사의 한도는 20%이고, 상장회사 특례에서는 관계 회사의 임직원에게도 부여할 수 있다(상법 제542조의3).","c":"상","v":1},"공인회2024_59-31-3":{"f":"상장회사가 이사ㆍ감사의 선임에 관한 사항을 목적으로 하는 주주총회를 소집할 경우 이사ㆍ감사 후보자의 약력이나 추천인 등 후보자에 관한 사항을 통지할 의무가 있다.","w":"후보자의 성명, 약력, 추천인 등을 소집통지·공고에 포함해야 한다(상법 제542조의4 제2항).","c":"상","v":1},"공인회2024_59-31-4":{"f":"상장회사는 정관에서 소수주주권에 관한 상장회사 특례보다 단기의 주식 보유기간을 정하거나 낮은 주식 보유비율을 정할 수 있다.","w":"상장회사는 정관으로 소수주주권 특례보다 짧은 보유기간이나 낮은 보유비율을 정할 수 있을 뿐, 높은 보유비율을 정할 수는 없다(상법 제542조의6 제8항).","c":"상","v":1},"공인회2024_59-31-5":{"f":"상장회사는 주요주주를 상대방으로 하거나 그를 위하여 신용공여를 하여서는 아니 되며 이사회의 승인이 있더라도 마찬가지이다.","w":"상장회사의 주요주주에 대한 신용공여는 예외 사유가 없는 한 금지되고, 이사 3분의 2 이상의 이사회 승인으로 허용되는 것이 아니다(상법 제542조의9).","c":"상","v":1},"공인회2025_60-28-1":{"f":"현물출자를 하는 자가 있는 경우에는 원칙적으로 검사인의 선임을 법원에 청구하거나 공인된 감정인의 감정으로 검사인의 조사에 갈음하게 하여야 하나, 일정한 경우에는 이를 생략할 수 있다.","w":"현물출자 재산의 가액이 자본금의 5분의 1과 5천만원을 넘지 않는 경우, 거래소 시세 있는 유가증권으로 시세를 넘지 않게 평가한 경우, 변제기가 된 회사에 대한 금전채권을 장부가액 이하로 출자하는 경우 등에는 검사를 하지 않는다(상법 제422조 제2항, 상법 시행령 제14조).","c":"상","v":1},"공인회2025_60-29-3":{"f":"결손의 보전을 위한 자본금 감소의 경우 채권자 이의절차를 거치지 않아도 된다.","w":"결손보전을 위한 자본금 감소는 회사 재산이 밖으로 나가지 않으므로 채권자보호절차를 거치지 않는다(상법 제439조 제2항 단서).","c":"상","v":1},"공인회2025_60-32-3":{"f":"이권(利券)있는 무기명식의 사채를 상환하는 경우에 이권이 흠결되었다면 그 이권에 상당한 금액을 상환액으로부터 공제한다.","w":"이권이 빠진 무기명식 사채를 상환하면 그 이권 금액을 상환액에서 공제하고, 이권소지인은 언제든지 이권과 맞바꾸어 공제액의 지급을 청구할 수 있다(상법 제486조).","c":"상","v":1},"공인회2026_61-26-4":{"f":"회사는 신주인수권증서를 발행하는 대신 정관으로 정하는 바에 따라 전자등록기관의 전자등록부에 신주인수권을 등록할 수 있다.","w":"전자등록으로 갈음하려면 정관의 근거가 있어야 한다(상법 제420조의4).","c":"상","v":1},"공인회2026_61-31-5":{"f":"결손의 보전을 위해 자본금을 감소하는 경우에는 채권자보호절차를 거치지 않아도 된다.","w":"결손보전을 위한 자본금 감소는 채권자보호절차를 거치지 않아도 된다(상법 제439조 제2항 단서).","c":"상","v":1},"공인회2026_61-32-1":{"f":"신주인수권부사채를 발행함에 있어 신주인수권만을 양도할 수 있는 것에 관한 사항은 정관에 규정이 없으면 이사회가 이를 결정한다.","w":"정관에 정함이 없으면 이사회가 결정한다. 주주총회 결의사항이 아니다(상법 제516조의2 제2항).","c":"상","v":1},"공인회2016_51-12-2":{"f":"甲회사는 주주들이 신주인수의 청약을 하지 않아 실권된 주식을 다시 제3자에게 배정할 수 있다.","w":"실권주의 처리는 이사회가 정하고 제3자에게 배정할 수 있다.","c":"상","v":1},"공인회2016_51-12-3":{"f":"이사회 결의에서 신주인수권 양도에 관한 사항을 정한 경우에도 주주는 신주인수권증서를 발행받는지와 관계없이 신주인수권을 취득한다.","w":"신주인수권은 주주 지위에서 생기는 권리다. 신주인수권증서는 양도의 방법과 관련된 것이다(상법 제416조, 제420조의2).","c":"중","v":1},"공인회2016_51-12-4":{"f":"주주가 신주를 인수한 후 납입기일까지 납입을 하지 않으면 별도의 해제 의사표시나 실권절차 없이 곧바로 신주인수인의 권리를 잃는다.","w":"신주 인수인은 납입기일에 납입하지 않으면 그 권리를 잃는다(상법 제423조 제2항). 설립 때의 실권절차와 다르다.","c":"상","v":1},"공인회2016_51-12-5":{"f":"신주를 인수한 주주가 납입기일에 이행기가 도래한 甲회사에 대한 금전채권을 가지고 있더라도 회사의 동의 없이 주주의 일방적 의사표시만으로 주식대금 납입의무와 상계할 수 없다.","w":"자본충실을 위해 신주 인수인은 회사의 동의 없이 상계하지 못한다(상법 제421조 제2항).","c":"상","v":1},"공인회2016_51-26-1":{"f":"결손의 보전을 위하여 자본금을 감소하기 위해서는 주주총회의 보통결의가 있어야 한다.","w":"결손보전 감자는 보통결의로 한다. 일반 감자의 특별결의 요건과 다르다(상법 제438조 제2항).","c":"상","v":1},"공인회2016_51-26-2":{"f":"회사는 결손의 보전을 위한 자본금의 감소 시에는 회사채권자에 대한 이의제출 공고 등 채권자 보호절차를 거치지 않아도 된다.","w":"결손보전을 위한 자본금 감소에는 채권자 이의 공고 등 채권자보호절차가 필요 없다(상법 제439조 제2항 단서).","c":"상","v":1},"공인회2016_51-26-3":{"f":"주주총회는 자본금의 감소를 결의하면서 감소의 방법을 정하여야 한다.","w":"자본금 감소 결의에서 감소의 방법을 반드시 정해야 하며 이사회에 위임할 수 없다(상법 제439조 제1항).","c":"상","v":1},"공인회2016_51-26-5":{"f":"자본금 감소의 무효를 인정하는 판결이 확정되면 그 판결은 제3자에 대하여도 효력이 있고 소급효도 있다.","w":"감자무효의 판결은 대세효와 소급효가 모두 있다. 불소급을 정한 제190조 단서는 감자무효에 준용되지 않는다(상법 제446조).","c":"상","v":1},"공인회2016_51-28-2":{"f":"사채를 발행하는 회사는 사채관리회사를 정하여 사채의 관리를 위탁할 수 있고 이는 의무가 아니다.","w":"사채관리회사를 두는 것은 임의다. 두지 않을 수도 있다(상법 제480조의2).","c":"상","v":1},"공인회2016_51-28-3":{"f":"사채의 인수인은 은행이라도 그 사채의 사채관리회사가 될 수 없다.","w":"사채의 인수인은 그 사채의 사채관리회사가 될 수 없고, 은행이라도 마찬가지다(상법 제480조의3 제2항).","c":"상","v":1},"공인회2016_51-28-4":{"f":"사채관리회사는 사채권자를 위하여 사채에 관한 채권을 변제받기 위하여 필요한 재판상의 행위를 할 수 있다.","w":"사채관리회사는 사채권자를 위해 채권 변제에 필요한 재판상·재판외의 모든 행위를 할 수 있다(상법 제484조 제1항).","c":"상","v":1},"공인회2016_51-28-5":{"f":"사채권자집회의 결의는 법원의 인가를 받아야 효력이 발생하지만 그 종류의 사채권자 전원이 동의한 결의는 법원의 인가가 필요하지 않다.","w":"전원이 동의한 결의는 인가가 필요하지 않다(상법 제498조 제1항 단서).","c":"상","v":1},"공인회2017_52-23-4":{"f":"신주의 인수인은 회사의 동의를 얻으면 납입채무와 회사에 대한 채권을 상계할 수 있다.","w":"회사의 동의가 있으면 상계가 가능하다. 동의 없는 상계만 금지된다(상법 제421조 제2항).","c":"상","v":1},"공인회2017_52-28-1":{"f":"사채를 발행하기 위하여는 이사회의 결의가 필요하다.","w":"사채는 이사회 결의로 발행하며 주주총회 결의는 필요 없다(상법 제469조 제1항).","c":"상","v":1},"공인회2017_52-28-2":{"f":"사채의 납입에는 분할납입이 가능하고 사채의 상환에도 분할상환이 인정된다.","w":"사채는 분할납입도 분할상환도 가능하다.","c":"상","v":1},"공인회2017_52-28-3":{"f":"사채의 상환청구권은 10년간 행사하지 아니하면 소멸시효가 완성된다.","w":"사채 원금의 상환청구권은 10년이고 이자 청구권은 5년이다(상법 제487조).","c":"상","v":1},"공인회2017_52-28-5":{"f":"사채권자는 회사가 기명식에 한할 것을 정하지 않은 경우 기명식의 채권을 무기명식으로 할 것을 회사에 청구할 수 있다.","w":"전환 청구에 이사회의 승인이 필요하지 않다. 회사가 채권을 기명식으로만 하기로 정한 때에는 청구할 수 없다(상법 제480조).","c":"상","v":1},"공인회2017_52-32-4":{"f":"신주발행무효의 판결이 확정된 경우 신주는 장래에 대해서만 효력을 잃으므로 확정판결 전에 이루어진 신주의 양도는 유효하다.","w":"신주발행무효의 판결은 소급하지 않는다(상법 제431조 제1항).","c":"상","v":1},"공인회2018_53-21-4":{"f":"판례에 의하면 신주인수권부사채 발행의 경우에도 신주발행 무효의 소에 관한 상법 제429조가 유추적용된다.","w":"신주인수권부사채 발행의 무효도 신주발행무효의 소에 관한 규정을 유추적용하여 다툰다는 것이 판례다. 제소기간은 6개월이다.","c":"상","v":1},"공인회2018_53-26-1":{"f":"결손의 보전을 위하여 자본금을 감소하는 경우에도 주주총회의 결의가 필요하다.","w":"결손보전 감자는 보통결의로 하며 총회 결의가 필요하다(상법 제438조 제2항).","c":"상","v":1},"공인회2018_53-31-1":{"f":"","w":"액면미달 발행은 회사 성립일부터 2년이 지난 뒤에만 할 수 있는데, 2014년 12월 12일 설립된 회사에게 2016년 11월 15일은 아직 2년이 지나지 않은 때다(상법 제417조 제1항).","c":"상","v":1},"공인회2019_54-30-2":{"f":"회사성립 후 주식을 발행하는 경우 신주의 인수방법에 관한 사항에 대하여 정관에 정함이 없으면 이사회가 이를 정한다.","w":"신주 발행사항은 정관에 달리 정함이 없으면 이사회가 결정한다(상법 제416조).","c":"상","v":1},"공인회2019_54-31-2":{"f":"사채권자는 사채권자집회의 결의가 있어야 자본금 감소에 대한 이의를 제기할 수 있다.","w":"사채권자가 자본금 감소에 이의를 제기하려면 사채권자집회의 결의가 있어야 한다(상법 제439조 제3항).","c":"상","v":1},"공인회2019_54-31-3":{"f":"주식병합으로 감자하는 경우 단주가 있는 때에는 그 부분에 대하여 발행한 신주를 경매하여 그 대금을 종전의 주주에게 그 주식의 비율에 따라 지급하여야 한다.","w":"단주의 경매 대금은 자본금에 전입하지 않고 종전 주주에게 비율대로 지급한다(상법 제443조 제1항).","c":"상","v":1},"공인회2019_54-31-4":{"f":"주식병합으로 감자하는 경우 단주가 있는 때에는 거래소의 시세없는 주식은 법원의 허가를 받아 경매 외의 방법으로 매각할 수 있다.","w":"거래소 시세 없는 주식을 경매 외의 방법으로 매각하려면 법원의 허가가 필요하다(상법 제443조 제1항 단서).","c":"상","v":1},"공인회2019_54-31-5":{"f":"감자무효는 주주·이사·감사·청산인·파산관재인 또는 자본금 감소를 승인하지 않은 채권자만이 감자로 인한 변경등기가 된 날부터 6개월 내에 소만으로 주장할 수 있다.","w":"제소권자에는 주주·이사·감사 외에 청산인, 파산관재인, 감자에 승인하지 않은 채권자도 포함된다(상법 제445조).","c":"상","v":1},"공인회2019_54-32-2":{"f":"주주 외의 자에 대하여 전환사채를 발행하는 경우에도 주주명부폐쇄기간 중에 전환청구를 할 수 있고, 다만 그 기간 중의 총회 결의에서는 의결권을 행사할 수 없다.","w":"폐쇄기간 중에도 전환 청구는 가능하다. 제한되는 것은 그 기간 중 총회에서의 의결권 행사다(상법 제516조 제2항, 제350조 제2항).","c":"상","v":1},"공인회2019_54-32-3":{"f":"주주 외의 자에 대하여 전환사채를 발행하는 경우 회사가 전환으로 인하여 발행할 주식의 종류와 수를 주주에게 통지하여야 하는 것은 아니다.","w":"전환 내용은 정관 또는 주주총회(특별결의)로 정할 뿐이며, 개별 주주에게 통지하는 규정은 없다(상법 제513조).","c":"중","v":1},"공인회2019_54-32-4":{"f":"회사가 법령 또는 정관에 위반하거나 현저하게 불공정한 방법에 의하여 전환사채를 발행하는 경우 주주의 전환사채발행유지청구권이 인정된다.","w":"신주발행 유지청구 규정이 전환사채에 준용된다(상법 제516조 제1항, 제424조).","c":"상","v":1},"공인회2019_54-32-5":{"f":"회사가 전환사채를 발행한 때에는 그 납입이 완료된 날로부터 2주간 내에 본점의 소재지에서 전환사채의 등기를 하여야 한다.","w":"등기는 본점 소재지에서 2주 내에 한다. 지점 소재지의 3주 내 등기 규정은 현행법에 없다(상법 제514조의2).","c":"상","v":1},"공인회2020_55-28-1":{"f":"신주발행 유지청구의 상대방은 현저하게 불공정한 방법으로 주식을 발행하는 회사이다.","w":"신주발행 유지청구는 이사가 아니라 회사를 상대로 한다(상법 제424조).","c":"상","v":1},"공인회2020_55-28-2":{"f":"신주인수권증서를 상실한 자는 신주인수권증서를 재발급 받지 않더라도 주식청약서에 의하여 주식의 청약을 할 수 있다.","w":"신주인수권증서를 잃어버린 자는 주식청약서로 청약할 수 있고, 그 청약은 신주인수권증서에 의한 청약이 있으면 효력을 잃는다(상법 제420조의5 제2항).","c":"상","v":1},"공인회2020_55-28-3":{"f":"회사가 성립한 날로부터 2년을 경과한 후에 주식을 발행하는 경우, 회사는 주주총회의 특별결의와 법원의 인가를 얻어서 주식을 액면미달의 가액으로 발행할 수 있다.","w":"요건은 성립 후 2년 경과, 주주총회 특별결의, 법원 인가다. 이사회 결의와 법원의 허가로는 부족하다(상법 제417조).","c":"상","v":1},"공인회2020_55-28-4":{"f":"판례에 의하면, 회사가 정관이나 이사회의 결의로 신주인수권을 양도할 수 있음을 정하지 않았더라도 회사의 승낙이 있으면 신주인수권의 양도는 회사에 대하여 효력이 있다.","w":"정함이 없어 회사에 대해 효력이 없던 양도도 회사가 승낙하면 회사에 대해 효력이 생긴다는 것이 판례다.","c":"상","v":1},"공인회2020_55-29-2":{"f":"사채의 인수인은 그 사채의 사채관리회사가 될 수 없다.","w":"사채의 인수인은 그 사채의 사채관리회사가 될 수 없다(상법 제480조의3 제2항).","c":"상","v":1},"공인회2020_55-29-3":{"f":"기명사채의 이전은 취득자의 성명과 주소를 사채원부에 기재하고 그 성명을 채권에 기재하지 아니하면, 회사 기타의 제3자에게 대항하지 못한다.","w":"기명사채 이전의 대항요건은 회사뿐 아니라 제3자에 대해서도 적용된다(상법 제479조 제1항).","c":"상","v":1},"공인회2020_55-29-4":{"f":"사채의 모집이 완료된 때에는 사채인수인은 사채의 전액 또는 제1회의 납입을 하여야 하며, 분할납입도 허용된다.","w":"사채는 분할납입이 가능하다(상법 제476조 제1항).","c":"상","v":1},"공인회2020_55-29-5":{"f":"판례에 의하면, 전환사채발행무효의 소에는 신주발행무효의 소에 관한 6월 내의 제소기간 규정이 유추적용된다.","w":"전환사채 발행무효의 소는 신주발행무효의 소 규정을 유추적용하여 발행일부터 6개월 내에 제기해야 한다는 것이 판례다.","c":"상","v":1},"공인회2021_56-28-3":{"f":"신주인수권증서를 상실한 자는 신주인수권증서를 재발급 받지 않더라도 주식청약서에 의하여 주식의 청약을 할 수 있다.","w":"신주인수권증서를 잃어버린 자는 재발급 없이 주식청약서로 청약할 수 있다(상법 제420조의5 제2항).","c":"상","v":1},"공인회2021_56-30-4":{"f":"신주발행무효의 판결이 확정되면 신주는 장래에 대하여 그 효력을 잃는다.","w":"신주발행무효 판결은 소급효가 없고 장래에 대해서만 효력을 잃는다(상법 제431조 제1항).","c":"상","v":1},"공인회2021_56-32-1":{"f":"전환사채의 전환으로 회사의 자본금은 증가한다.","w":"전환사채를 전환하면 사채가 소멸하고 신주가 발행되므로 그만큼 자본금이 늘어난다(상법 제516조 제2항, 제348조).","c":"상","v":1},"공인회2022_57-25-2":{"f":"신주의 인수인이 현물출자의 이행을 한 때에는 납입기일의 다음 날로부터 주주의 권리의무가 있다.","w":"주주의 권리의무는 이행한 날이 아니라 납입기일의 다음 날부터 생긴다(상법 제423조 제1항).","c":"상","v":1},"공인회2022_57-30-3":{"f":"회사가 채권을 기명식에 한할 것을 정한 때에는 사채권자가 기명식의 채권을 무기명식으로 할 것을 청구하더라도 회사는 이에 응할 의무가 없다.","w":"기명식에 한한다는 정함이 있으면 전환 청구가 제한된다(상법 제480조 단서).","c":"상","v":1},"공인회2022_57-32-4":{"f":"감자무효의 판결은 대세적 효력과 소급효가 있다.","w":"감자무효 판결은 제3자에게도 효력이 있고, 신주발행무효와 달리 소급효가 있다(상법 제446조, 제190조).","c":"상","v":1},"공인회2023_58-27-4":{"f":"신주인수권증서를 점유하는 소지인은 신주인수권증서에 의하여 주식의 청약을 하여야 한다.","w":"증서를 가진 사람은 증서로 청약한다. 주식청약서로 청약할 수 있는 사람은 증서를 상실한 자다(상법 제420조의5).","c":"상","v":1},"공인회2024_59-25-5":{"f":"현물출자의 목적인 재산의 가액이 자본금의 5분의 1을 초과하지 않더라도 그 재산의 가액이 5천만원을 초과하면 법원이 선임한 검사인의 조사 및 공인된 감정인의 감정이 필요하다.","w":"조사 면제는 현물출자 가액이 5천만원 이하이면서 자본금의 5분의 1 이하일 때다(상법 제422조 제2항).","c":"상","v":1},"공인회2024_59-29-1":{"f":"발행할 수 있는 전환사채의 액, 전환의 조건, 전환으로 인하여 발행할 주식의 내용과 전환을 청구할 수 있는 기간에 관하여 정관에 규정이 없으면 주주총회의 특별결의로써 이를 정하여야 한다.","w":"주주 외의 자에게 전환사채를 발행할 때 이 사항들이 정관에 없으면 주주총회 특별결의(제434조의 결의)로 정한다(상법 제513조 제3항).","c":"상","v":1},"공인회2025_60-30-2":{"f":"정기총회에서 재무제표의 승인을 한 후 2년 내에 다른 결의가 없으면, 회사는 이사 또는 감사의 부정행위를 제외하고 이사와 감사의 책임을 해제한 것으로 본다.","w":"책임 해제 간주는 이사·감사의 부정행위에는 적용되지 않는다(상법 제450조).","c":"상","v":1},"공인회2026_61-27-3":{"f":"이사는 정기총회회일의 6주간전에 상법 제447조(재무제표의 작성) 및 제447조의2(영업보고서의 작성)에 따른 서류를 감사에게 제출하여야 한다.","w":"감사에게 서류를 내는 시한은 정기총회일 6주 전이다(상법 제447조의3).","c":"상","v":1},"공인회2026_61-33-4":{"f":"회사는 주식배당의 경우를 제외하고는 그 자본금의 2분의 1이 될 때까지 매 결산기 이익배당액의 10분의 1 이상을 이익준비금으로 적립하여야 한다.","w":"주식배당에는 이익준비금 적립 의무가 없다(상법 제458조 단서).","c":"상","v":1},"공인회2017_52-24-3":{"f":"이사는 매 결산기에 영업보고서를 작성하여 이사회의 승인을 받은 후 정기총회에 제출하여 그 내용을 보고하여야 한다.","w":"영업보고서는 주주총회 승인 사항이 아니라 보고 사항이다(상법 제449조 제2항).","c":"상","v":1},"공인회2017_52-29-5":{"f":"회사가 정관으로 금전 외의 재산으로 배당할 것을 정한 경우 일정 수 미만의 주식을 보유한 주주에게 금전 외의 재산 대신 금전을 지급하기로 정할 수 있다.","w":"현물배당에서 일정 수 미만 보유 주주에게는 금전을 지급하는 것으로 정할 수 있다(상법 제462조의4 제2항).","c":"상","v":1},"공인회2018_53-30-4":{"f":"발행주식총수의 100분의 3 이상의 주식을 가진 주주는 이유를 붙인 서면으로 회계의 장부와 서류의 열람을 청구할 수 있으며 회사채권자에게는 이 권리가 없다.","w":"회계장부 열람청구권자는 3% 이상 주주이고 회사채권자는 재무제표 열람만 할 수 있다(상법 제466조, 제448조).","c":"상","v":1},"공인회2020_55-32-1":{"f":"이익준비금과 자본준비금은 순서와 관계없이 자본금의 결손 보전에 충당할 수 있다.","w":"이익준비금과 자본준비금은 순서와 관계없이 결손 보전에 쓸 수 있다. 이익준비금을 먼저 써야 한다는 순서 제한은 2011년 개정으로 없어졌다(상법 제460조).","c":"상","v":1},"공인회2022_57-28-5":{"f":"발행주식총수의 100분의 3 이상의 주식을 보유한 주주가 회계장부의 열람을 재판상 청구한 경우, 소송이 계속되는 동안 그 주식보유 요건이 계속 구비되어야 한다.","w":"열람·등사 청구의 소는 소송이 끝날 때까지 3% 보유 요건을 유지해야 한다.","c":"중","v":1},"공인회2022_57-29-3":{"f":"회사는 적립된 자본준비금 및 이익준비금의 총액이 자본금의 1.5배를 초과하는 경우에는 주주총회의 결의에 따라 그 초과한 금액의 범위에서 자본준비금과 이익준비금을 감액할 수 있다.","w":"준비금 감액은 주주총회 결의 사항이다(상법 제461조의2).","c":"상","v":1},"공인회2023_58-25-2":{"f":"법정준비금을 자본금으로 전입한 경우에도 회사의 순자산은 증가하지 않는다.","w":"준비금 전입은 순자산 내부의 항목 간 이동이어서 순자산에 변동이 없다.","c":"상","v":1},"공인회2023_58-25-3":{"f":"액면주식을 발행한 회사가 법정준비금을 자본금으로 전입하려면 신주의 발행을 수반한다.","w":"액면주식을 발행한 회사가 준비금을 자본금에 전입하면 주주에게 그가 가진 주식 수에 따라 신주를 발행해야 한다(상법 제461조 제2항).","c":"상","v":1},"공인회2023_58-25-4":{"f":"법정준비금을 자본금으로 전입하는 경우 줄어드는 법정준비금과 늘어나는 자본금은 같은 금액이다.","w":"준비금에서 빠져나간 금액이 그대로 자본금으로 들어가므로 두 금액은 같다.","c":"상","v":1},"공인회2023_58-25-5":{"f":"법정준비금을 자본금의 결손 보전에 충당하는 경우 회사의 순자산은 회사 밖으로 유출되지 않는다.","w":"결손 보전은 장부상 항목 간 정리일 뿐이어서 회사 외부로 재산이 나가지 않는다.","c":"상","v":1},"공인회2023_58-29-1":{"f":"재무제표를 이사회 결의로 승인할 수 있도록 정관 규정을 둔 회사라도 주식배당은 주주총회 결의로 하여야 한다.","w":"이사회가 정할 수 있는 것은 금전배당이다. 주식배당은 주주총회 결의로 한다(상법 제462조의2 제1항).","c":"상","v":1},"공인회2023_58-29-2":{"f":"주식배당은 회사가 새로 발행하는 주식으로 하며 자기주식을 교부함으로써 행할 수 없다.","w":"주식배당은 신주 발행으로 한다(상법 제462조의2).","c":"상","v":1},"공인회2023_58-29-3":{"f":"주식배당을 통해 자본금이 증가하면, 그 금액만큼 이익잉여금(배당가능이익)이 감소한다.","w":"주식배당은 이익잉여금을 자본금으로 옮기는 것이며 법정준비금은 줄지 않는다.","c":"상","v":1},"공인회2023_58-29-4":{"f":"주식배당이 완료된 후에는 자본금 증가에 따른 변경등기가 필요하다.","w":"주식배당으로 발행주식 수와 자본금이 바뀌므로 변경등기를 해야 한다(상법 제317조).","c":"상","v":1},"공인회2024_59-27-3":{"f":"주식배당의 경우 회사는 주주총회의 결의에 의하여 이익의 배당을 새로 발행하는 주식으로 할 수 있다.","w":"주식배당은 신주 발행으로 하며 자기주식으로 할 수 없다(상법 제462조의2 제1항).","c":"상","v":1},"공인회2026_61-10-4":{"f":"유한회사의 주식회사로의 조직변경은 총사원의 일치에 의한 총회의 결의로 하며, 정관으로 정한 경우에는 사원총회의 특별결의로도 가능하다.","w":"유한회사의 주식회사 조직변경은 총사원 일치에 의한 총회 결의로 하는 것이 원칙이지만, 정관으로 정하면 제585조의 사원총회 특별결의로 할 수 있다(상법 제607조 제1항).","c":"상","v":1},"공인회2026_61-15-1":{"f":"주식이전의 효력은 완전모회사의 설립등기를 한 때에 발생한다.","w":"주식이전은 설립한 완전모회사가 본점 소재지에서 등기를 함으로써 효력이 생긴다(상법 제360조의21).","c":"상","v":1},"공인회2026_61-15-2":{"f":"주식이전을 무효로 하는 판결이 확정되면 완전모회사가 된 회사는 주식이전을 위하여 발행한 주식의 주주에 대하여 그가 소유하였던 완전자회사가 된 회사의 주식을 이전하여야 한다.","w":"무효 판결 후에는 원래 상태로 돌리기 위해 완전자회사 주식을 주주에게 이전해야 한다(상법 제360조의23).","c":"상","v":1},"공인회2026_61-15-4":{"f":"주식의 포괄적 이전에 따라 설립하는 완전모회사는 완전자회사가 되는 회사의 주주에게 주식이전의 대가로 금전을 제공할 수 있다.","w":"주식이전계획서에 완전자회사가 되는 회사의 주주에게 주식 대신 금전이나 그 밖의 재산을 제공하는 내용을 정할 수 있다(상법 제360조의16 제1항 제4호).","c":"상","v":1},"공인회2026_61-15-5":{"f":"주식이전무효의 소는 완전모회사가 되는 회사의 본점소재지의 지방법원의 관할에 전속한다.","w":"주식이전무효의 소는 완전모회사가 되는 회사의 본점 소재지 지방법원의 전속관할이다(상법 제360조의23 제2항).","c":"상","v":1},"공인회2026_61-16-4":{"f":"주식교환의 무효는 각 회사의 주주·이사·감사·감사위원회의 위원 또는 청산인에 한하여 주식교환의 날부터 6월내에 소만으로 이를 주장할 수 있다.","w":"주식교환무효의 소는 각 회사의 주주·이사·감사·감사위원회 위원·청산인만 제기할 수 있고, 채권자는 제소권자가 아니다(상법 제360조의14 제1항).","c":"상","v":1},"공인회2026_61-30-1":{"f":"회사분할에 관한 주주총회 승인 결의에서 의결권이 없는 종류주식의 주주도 의결권을 행사할 수 있다.","w":"분할 승인 결의에서는 의결권이 배제되는 주주도 의결권이 있다(상법 제530조의3 제3항).","c":"상","v":1},"공인회2026_61-30-3":{"f":"단순분할신설회사는 분할 전의 분할회사 채무에 관하여 분할회사와 연대하여 변제할 책임이 있으나, 주주총회 특별결의로 신설회사가 승계한 채무에 대해서만 책임지기로 정한 경우에는 이 연대책임이 배제된다.","w":"연대책임은 분할회사가 주주총회 특별결의로 승계 채무만 책임지기로 정하면 배제할 수 있다(상법 제530조의9 제1항·제2항).","c":"상","v":1},"공인회2026_61-30-4":{"f":"해산후의 회사는 존립중의 회사를 존속하는 회사로 하거나 새로 회사를 설립하는 경우에 한하여 분할 또는 분할합병할 수 있다.","w":"해산 후의 회사는 존립 중의 회사를 존속회사로 하는 경우뿐 아니라 새로 회사를 설립하는 경우에도 분할 또는 분할합병을 할 수 있다(상법 제530조의2 제4항).","c":"상","v":1},"공인회2026_61-30-5":{"f":"분할합병 무효판결이 확정된 경우 분할승계회사가 분할합병 후에 취득한 재산은 분할회사와 분할승계회사의 공유로 한다.","w":"분할합병 무효판결이 확정되면 분할승계회사가 분할합병 후 취득한 재산은 분할회사와 분할승계회사의 공유가 된다(상법 제530조의11 제1항, 제239조 제2항).","c":"상","v":1},"공인회2016_51-29-2":{"f":"간이합병의 경우 소멸회사의 주주총회는 이사회승인으로 갈음하지만 소멸회사의 주주는 주식매수청구권을 행사할 수 있다.","w":"간이합병 반대주주에게도 주식매수청구권이 인정된다. 인정되지 않는 것은 소규모합병의 존속회사 주주다(상법 제527조의2, 제522조의3).","c":"상","v":1},"공인회2017_52-30-2":{"f":"간이합병에 반대하는 소멸회사의 주주로서 의결권이 없거나 제한되는 주주도 주식매수청구권을 행사할 수 있다.","w":"합병 반대주주의 매수청구는 의결권 유무와 무관하게 인정된다(상법 제522조의3 제1항).","c":"상","v":1},"공인회2017_52-31-3":{"f":"회사의 분할은 분할등기를 한 때에 그 효력이 발생한다.","w":"분할은 계획서에 적은 분할을 할 날이 아니라 분할등기를 한 때 효력이 생긴다(상법 제530조의11 제1항, 제234조).","c":"상","v":1},"공인회2018_53-19-4":{"f":"존속회사가 합병으로 인하여 발행하는 신주 및 이전하는 자기주식의 총수가 그 회사의 발행주식총수의 100분의 10을 초과하지 아니하는 경우에도 채권자보호절차는 거쳐야 한다.","w":"소규모합병이라도 존속회사의 주주총회 승인이 생략될 뿐이고 채권자 보호절차는 생략되지 않는다(상법 제527조의3, 제527조의5).","c":"상","v":1},"공인회2018_53-20-1":{"f":"인적분할에 의하여 1개 또는 수개의 회사를 설립하는 단순분할의 경우 이에 반대하는 주주는 주식매수청구를 할 수 없다.","w":"단순분할의 반대주주에게는 주식매수청구권이 없다. 분할합병의 반대주주에게만 인정된다(상법 제530조의11, 제522조의3).","c":"상","v":1},"공인회2018_53-20-2":{"f":"물적분할에 의하여 설립되는 회사의 주식의 총수를 분할회사가 취득하는 단순분할의 경우에도 이에 반대하는 주주는 주식매수청구를 할 수 없다.","w":"단순분할이면 인적·물적을 가리지 않고 반대주주 매수청구권이 없다.","c":"상","v":1},"공인회2018_53-20-3":{"f":"분할계획서를 승인하는 주주총회의 결의에 있어 의결권이 배제되는 주주도 의결권을 행사할 수 있다.","w":"분할 승인 결의에서는 의결권이 배제·제한되는 주주도 의결권이 있다(상법 제530조의3 제3항).","c":"상","v":1},"공인회2018_53-20-4":{"f":"인적분할의 경우에도 단순분할신설회사의 이사는 분할에 관한 사항을 기재한 서면을 일정기간 본점에 비치하여야 한다.","w":"분할로 설립되는 회사의 이사도 분할에 관한 사항을 적은 서면을 분할한 날부터 6개월간 본점에 비치해야 한다(상법 제530조의11 제1항, 제527조의6).","c":"상","v":1},"공인회2018_53-24-1":{"f":"유한회사가 주식회사와 합병하여 합병후 존속하는 회사가 주식회사인 경우에는 법원의 인가를 얻어야 한다.","w":"법원의 인가 없이는 합병의 효력이 없다. 신고로는 부족하다(상법 제600조 제1항).","c":"상","v":1},"공인회2018_53-24-3":{"f":"주식회사가 유한회사로 변경하는 경우에는 사채의 상환을 완료한 때에 한하여 총주주의 일치에 의한 총회의 결의로 그 조직을 변경할 수 있다.","w":"주식회사의 유한회사 조직변경은 총주주의 일치 결의가 필요하다. 특별결의 요건으로는 부족하다(상법 제604조 제1항).","c":"상","v":1},"공인회2018_53-24-4":{"f":"유한회사가 주식회사로 그 조직을 변경하는 경우 회사에 현존하는 순재산액이 조직변경으로 발행하는 주식의 발행가액 총액에 부족할 때에는 조직변경 결의 당시의 이사, 감사 및 사원은 연대하여 회사에 그 부족액을 지급할 책임이 있다.","w":"순재산액이 발행가액 총액에 못 미치면 조직변경 결의 당시의 이사·감사와 사원이 연대하여 그 부족액을 회사에 지급한다(상법 제607조 제4항).","c":"상","v":1},"공인회2018_53-24-5":{"f":"유한회사 또는 유한책임회사가 주식회사로 조직변경하는 경우에는 합병에서와 같은 채권자보호절차를 거쳐야 한다.","w":"유한회사나 유한책임회사가 주식회사로 조직변경할 때에도 합병의 채권자보호절차(제232조)를 거쳐야 한다(상법 제608조, 제287조의44).","c":"상","v":1},"공인회2020_55-16-3":{"f":"주식의 포괄적 교환 및 이전을 위해서는 채권자 보호절차가 필요하지 않다.","w":"주식교환·이전은 회사 재산에 변동이 없어서 채권자 보호절차를 두지 않는다.","c":"상","v":1},"공인회2020_55-30-1":{"f":"간이합병에 반대하는 소멸회사의 주주에게도 주식매수청구권이 인정된다.","w":"간이합병에서도 소멸회사의 반대주주는 매수청구권을 가진다(상법 제522조의3).","c":"상","v":1},"공인회2020_55-30-2":{"f":"존속회사가 소멸회사의 주주에게 제공하기 위하여 취득한 존속회사의 모회사주식 중 합병 후 남아 있는 주식은 합병의 효력이 생긴 날부터 6개월 내에 처분하여야 한다.","w":"즉시 처분이 아니라 6개월 안에 처분하면 된다(상법 제523조의2 제2항).","c":"상","v":1},"공인회2020_55-30-4":{"f":"소규모합병의 경우에도 존속회사는 채권자보호절차를 거쳐야 한다.","w":"소규모합병은 존속회사 주주총회 승인을 이사회 승인으로 대체할 뿐이고 채권자 보호절차는 그대로 필요하다(상법 제527조의3).","c":"상","v":1},"공인회2020_55-30-5":{"f":"존속회사는 소멸회사의 주주에게 합병대가의 전부 또는 일부로서 금전이나 그 밖의 재산을 제공할 수 있다.","w":"합병대가의 전부를 금전 그 밖의 재산으로 줄 수 있다(상법 제523조 제4호).","c":"상","v":1},"공인회2020_55-31-4":{"f":"단순분할신설회사가 분할회사의 분할 전 채무에 대해 연대책임을 지지 않는 경우, 분할회사는 이의를 제기하는 채권자에 대해서 변제 또는 상당한 담보를 제공하거나 이를 목적으로 하여 상당한 재산을 신탁회사에 신탁하여야 한다.","w":"채권자보호절차가 필요한 것은 단순분할신설회사가 승계한 채무만 책임지기로 하여 연대책임을 배제한 경우다. 연대책임을 지는 단순분할에서는 이 절차가 필요 없다(상법 제530조의9 제4항, 제527조의5).","c":"상","v":1},"공인회2021_56-29-2":{"f":"주식의 포괄적 교환을 하는 회사는 채권자보호절차가 필요하지 않다.","w":"주식교환은 채권자 보호절차를 요구하지 않는다.","c":"상","v":1},"공인회2021_56-31-2":{"f":"유한회사가 주식회사와 합병하는 경우에 합병 후 존속하는 회사가 주식회사인 때에는 법원의 인가를 얻지 아니하면 합병의 효력이 없다.","w":"법원의 인가가 필요한 경우는 존속회사가 주식회사일 때이고, 존속회사가 유한회사이면 인가가 필요 없다(상법 제600조 제1항).","c":"상","v":1},"공인회2022_57-26-3":{"f":"의결권 없는 주식을 가진 주주도 주식교환계약서를 승인하는 주주총회의 결의에 반대하는 경우, 상법상 다른 요건을 갖추면 반대주주의 주식매수청구권을 행사할 수 있다.","w":"반대주주 주식매수청구는 의결권 유무와 관계없이 인정된다(상법 제360조의5).","c":"상","v":1},"공인회2022_57-27-1":{"f":"소규모합병의 경우 존속회사의 주주에게는 합병반대주주의 주식매수청구권이 인정되지 않지만 소멸회사의 주주에게는 인정된다.","w":"소규모합병에서 매수청구권이 배제되는 사람은 존속회사 주주다. 소멸회사 주주는 그대로 청구할 수 있다(상법 제527조의3 제5항).","c":"상","v":1},"공인회2023_58-30-2":{"f":"분할회사의 주주는 분할등기가 이루어진 때에 단순분할신설회사의 주주가 된다.","w":"분할의 효력은 분할계획서의 분할을 할 날이 아니라 분할등기 시에 생긴다(상법 제530조의11 제1항, 제234조).","c":"상","v":1},"공인회2023_58-30-3":{"f":"분할합병에서 분할승계회사는 분할회사의 주주에게 신주를 발행하거나 자기주식을 이전하지 않고 그 대가의 전부를 금전이나 그 밖의 재산으로 지급할 수 있다.","w":"분할합병에서도 합병대가의 전부를 금전이나 재산으로 지급할 수 있다(상법 제530조의6, 제523조).","c":"상","v":1},"공인회2023_58-30-4":{"f":"분할회사가 주주총회 특별결의에 의하여 단순분할신설회사가 분할계획서에서 승계하기로 정한 채무에 대한 책임만을 부담하는 것으로 정한 경우에도 분할회사는 채권자보호절차를 거쳐야 한다.","w":"단순분할신설회사가 승계하기로 정한 채무만 책임지도록 정하여 연대책임을 배제하면 분할회사는 채권자보호절차를 거쳐야 한다(상법 제530조의9 제2항·제4항, 제527조의5).","c":"상","v":1},"공인회2023_58-30-5":{"f":"분할합병 무효판결이 확정된 경우 분할승계회사가 분할합병 후에 취득한 재산은 분할회사와 분할승계회사의 공유로 한다.","w":"분할합병 무효판결이 확정되면 분할승계회사가 분할합병 후 취득한 재산은 분할회사와 분할승계회사의 공유가 된다(상법 제530조의11 제1항, 제239조 제2항).","c":"상","v":1},"공인회2024_59-22-4":{"f":"소규모합병의 경우 그 합병에 반대하는 소멸회사의 주주에게는 주식매수청구권이 인정된다.","w":"소규모합병에서 매수청구권이 없는 쪽은 존속회사의 주주이고 소멸회사 주주에게는 인정된다.","c":"상","v":1},"공인회2025_60-34-2":{"f":"휴면회사의 해산은 주식회사에 대해서만 인정되며, 유한책임회사, 유한회사, 합명회사와 합자회사에 대해서는 인정되지 않는다.","w":"휴면회사의 해산 간주는 주식회사에만 있는 제도다(상법 제520조의2).","c":"상","v":1},"공인회2017_52-10-4":{"f":"법원은 이해관계인이 회사의 해산을 청구한 때에는 회사의 청구에 의하여 상당한 담보를 제공할 것을 명할 수 있다.","w":"담보제공 명령은 직권이 아니라 회사의 청구가 있어야 가능하다(상법 제176조 제3항).","c":"상","v":1},"공인회2021_56-09-1":{"f":"회사의 합병은 합자회사의 해산사유이다.","w":"합병은 합자회사의 해산사유이지만 분할은 해산사유가 아니다(상법 제269조, 제227조).","c":"상","v":1},"공인회2021_56-09-2":{"f":"사원이 1인으로 된 때는 유한책임회사의 해산사유가 아니다.","w":"유한책임회사는 사원이 1인이어도 존속하고, 사원이 없게 된 때에 해산한다(상법 제287조의38).","c":"상","v":1},"공인회2021_56-09-3":{"f":"휴면회사의 해산의제는 주식회사의 해산사유이다.","w":"휴면회사 해산의제는 주식회사에만 적용되고 유한회사에는 적용되지 않는다(상법 제520조의2).","c":"상","v":1},"공인회2021_56-09-4":{"f":"유한책임사원 전원이 퇴사한 때는 합자회사의 해산사유이다.","w":"합자회사는 무한책임사원과 유한책임사원이 모두 있어야 하므로 한쪽이 전원 퇴사하면 해산한다(상법 제285조).","c":"상","v":1},"공인회2022_57-31-4":{"f":"청산사무가 종료한 때에는 청산인은 지체없이 결산보고서를 작성하고 이를 주주총회에 제출하여 승인을 얻어야 한다.","w":"결산보고서 승인은 주주총회 보통결의 사항이고 특별결의가 필요하지 않다(상법 제540조).","c":"상","v":1},"공인회2016_51-33-4":{"f":"어음에는 반드시 지급받을 자 또는 지급받을 자를 지시할 자의 명칭의 기재가 있어야 하지만 수표는 소지인출급식으로 발행할 수 있어 반드시 기재해야 하는 것은 아니다.","w":"환어음과 약속어음은 수취인 기재가 필수이고 수표는 소지인출급식도 허용된다(수표법 제5조).","c":"상","v":1},"공인회2016_51-34-1":{"f":"기명은 반드시 어음행위자의 본명과 일치할 필요가 없다.","w":"어음행위자를 특정할 수 있으면 아호나 예명, 상호로도 기명할 수 있다.","c":"상","v":1},"공인회2016_51-34-3":{"f":"어음상 기명의 명의와 날인의 명의는 반드시 일치하여야 하는 것은 아니다.","w":"기명과 날인 명의가 달라도 어음행위자가 누구인지 알 수 있으면 유효하다는 것이 판례다.","c":"상","v":1},"공인회2016_51-34-4":{"f":"무인(拇印) 또는 지장(指章)은 날인으로서의 효력을 가지지 않는다.","w":"어음행위의 날인은 인장 날인을 뜻하고 무인으로는 갈음할 수 없다는 것이 판례다.","c":"상","v":1},"공인회2016_51-34-5":{"f":"성명의 일부 또는 전부를 도형화하여 표시하는 속칭 사인(signature)은 이를 통해 서명자의 성명을 식별할 수 없다면 자필로 기재한 경우에도 서명으로 인정되지 않는다.","w":"서명은 성명을 식별할 수 있는 자필 기재여야 한다.","c":"상","v":1},"공인회2016_51-36-4":{"f":"약속어음에 만기가 적혀 있지 아니한 경우 일람출급의 약속어음으로 본다.","w":"만기가 적혀 있지 않은 약속어음은 일람출급의 약속어음으로 본다(어음법 제76조 제1호).","c":"상","v":1},"공인회2016_51-37-3":{"f":"발행일자 후 정기출급의 환어음에 발행인이 어음금액에 이자가 붙는다는 약정 내용을 적은 경우 이러한 기재는 적지 아니한 것으로 본다.","w":"이자 약정은 일람출급과 일람 후 정기출급 환어음에서만 유효하다(어음법 제5조 제1항).","c":"상","v":1},"공인회2017_52-37-3":{"f":"배서인은 이전의 다른 배서인을 피보증인으로 하여 어음보증을 할 수 있다.","w":"보증인은 어음채무자를 포함해 누구든 될 수 있다(어음법 제30조 제2항).","c":"상","v":1},"공인회2017_52-38-1":{"f":"만기 이후 지급거절이 되지 않고 지급거절증서의 작성기간도 경과하기 전에 한 배서는 기한후배서가 아니다.","w":"기한후배서는 지급거절증서 작성 후 또는 작성기간 경과 후의 배서다(어음법 제20조).","c":"상","v":1},"공인회2017_52-38-2":{"f":"기한후배서는 지명채권양도의 효력만 있으나 어음채무자에 대한 통지·승낙 등 대항요건을 갖출 필요는 없다.","w":"기한후배서에는 지명채권양도의 효력이 있다는 뜻이고 민법상의 통지·승낙까지 요구되는 것은 아니다.","c":"상","v":1},"공인회2017_52-38-3":{"f":"기한후배서 여부를 결정하는 자료가 되는 것은 배서란에 기재된 일자가 아니라 실제 배서한 일자이다.","w":"배서란의 날짜가 아니라 실제로 배서한 때를 기준으로 판단한다.","c":"상","v":1},"공인회2017_52-38-4":{"f":"날짜를 적지 아니한 배서는 지급거절증서의 작성기간이 지나기 전에 한 것으로 추정한다.","w":"날짜 없는 배서는 기한후배서가 아닌 것으로 추정된다(어음법 제20조 제2항).","c":"상","v":1},"공인회2018_53-33-2":{"f":"말소한 배서는 배서의 연속에 관하여 배서를 하지 아니한 것으로 보며, 어음을 절취한 자가 배서를 말소한 경우에도 마찬가지이다.","w":"말소한 배서는 말소할 권한이 있는 자가 한 것인지를 묻지 않고 배서의 연속에서 배서가 없는 것으로 본다는 것이 판례다(어음법 제16조 제1항).","c":"상","v":1},"공인회2018_53-35-1":{"f":"","w":"수취인이 백지인 채로는 어음 요건을 갖추지 못해 지급청구를 할 수 없다.","c":"중","v":1},"공인회2018_53-35-2":{"f":"","w":"미리 합의한 보충권의 범위를 넘어 보충된 어음을 그 사정을 알고 취득한 소지인에게 발행인은 합의된 범위를 넘는 부분은 책임지지 않지만 합의된 범위 안에서는 책임을 진다(어음법 제77조 제2항, 제10조).","c":"중","v":1},"공인회2018_53-35-4":{"f":"","w":"상환청구권을 행사하려면 지급제시기간 내에 제시해야 하는데 그 기간이 지난 뒤의 보충으로는 상환청구가 불가능하다.","c":"중","v":1},"공인회2018_53-35-5":{"f":"","w":"백지 보충은 보충권자의 서명 없이 한다.","c":"상","v":1},"공인회2018_53-36-1":{"f":"A가 B에게 물품대금채무의 지급을 위하여 환어음을 발행한 경우 그 어음발행의 원인인 물품대금채무를 원인관계라 한다.","w":"자금관계는 발행인과 지급인 사이의 관계이고, 발행인과 수취인 사이의 어음 발행 원인을 원인관계라 한다.","c":"상","v":1},"공인회2018_53-36-2":{"f":"A가 B에게 물품대금채무의 지급을 위하여 약속어음을 발행한 경우 물품대금채무는 원칙적으로 소멸하지 않는다.","w":"어음은 지급을 위하여 발행한 것으로 추정되고 원인채무가 소멸하지 않으며, 어음채무와 병존한다.","c":"상","v":1},"공인회2018_53-36-4":{"f":"A가 B에게 발행한 약속어음이 기존채무의 지급을 위하여 발행한 것인지 지급에 갈음하여 발행한 것인지 명시된 합의가 없다면 지급을 위하여 발행된 것으로 본다.","w":"당사자의 명시가 없으면 지급에 갈음하여가 아니라 지급을 위하여 발행한 것으로 추정한다.","c":"상","v":1},"공인회2018_53-36-5":{"f":"A가 B에게 기존채무의 지급을 담보하기 위하여 약속어음을 발행한 경우 B는 기존채권과 어음채권 중에서 어느 것을 먼저 행사하여도 된다.","w":"담보를 위한 어음의 경우 채권자는 두 채권을 임의로 선택해 행사할 수 있다.","c":"상","v":1},"공인회2018_53-37-1":{"f":"어음의 단순한 점유자도 인수제시를 할 수 있다.","w":"인수 제시는 소지인뿐 아니라 단순한 점유자도 할 수 있다(어음법 제21조).","c":"상","v":1},"공인회2018_53-37-2":{"f":"배서인이 인수를 위한 어음의 제시를 금지한다는 내용을 어음에 적더라도 그 기재는 효력이 없다.","w":"인수제시 금지는 발행인만 적을 수 있고, 배서인은 인수를 위하여 제시해야 한다는 내용만 적을 수 있다(어음법 제22조 제2항·제4항).","c":"상","v":1},"공인회2018_53-37-4":{"f":"어음의 소지인은 인수를 위하여 제시한 어음을 지급인에게 교부할 필요가 없다.","w":"소지인은 인수를 위하여 제시한 어음을 지급인에게 넘겨줄 필요가 없다(어음법 제24조 제2항).","c":"상","v":1},"공인회2018_53-37-5":{"f":"어음에 지급담당자가 기재되어 있는 경우에도 인수제시는 지급인에게 한다.","w":"인수제시의 상대방은 지급인이다. 지급담당자는 지급제시 때의 상대방이다.","c":"상","v":1},"공인회2018_53-38-2":{"f":"환어음의 인수인은 주채무자이지만 수표의 지급보증인은 제시기간 내에 제시된 경우에만 책임을 지는 점에서 같지 않다.","w":"수표의 지급보증인은 제시기간 내 제시된 경우에 한해 책임을 지고, 환어음의 인수인과는 의무의 성격이 다르다(수표법 제55조).","c":"중","v":1},"공인회2018_53-38-3":{"f":"약속어음의 발행인은 주채무자이고 수표의 발행인은 상환의무자로서 지급담보책임을 진다.","w":"약속어음 발행인은 주채무자다. 수표 발행인은 상환의무를 지는 사람이다.","c":"상","v":1},"공인회2018_53-38-4":{"f":"환어음에서는 지급인에 대한 배서도 유효하고 지급인이 하는 배서도 유효하지만, 수표에서는 지급인에 대한 배서는 영수증의 효력만 있고 지급인의 배서는 무효이다.","w":"수표에서는 지급인이 한 배서는 무효이고 지급인에 대한 배서는 영수증의 효력만 있다(수표법 제15조 제3항·제5항).","c":"상","v":1},"공인회2018_53-38-5":{"f":"환어음의 지급인 자격에는 제한이 없지만 수표의 지급인은 은행에 한하며 지급담당자는 제한이 없다.","w":"수표의 지급인은 은행이어야 한다(수표법 제3조). 환어음의 지급담당자에는 제한이 없다.","c":"상","v":1},"공인회2018_53-39-2":{"f":"지시금지어음의 경우 배서가 연속되더라도 그 배서에는 자격수여적 효력이 없고 선의취득도 인정되지 않는다.","w":"지시금지어음은 지명채권 양도방식으로만 양도되므로 배서의 자격수여적 효력과 선의취득이 인정되지 않는다.","c":"상","v":1},"공인회2018_53-39-3":{"f":"판례에 의하면 백지어음의 선의취득도 인정된다.","w":"백지어음도 어음이어서 선의취득의 대상이 된다는 것이 판례다.","c":"상","v":1},"공인회2018_53-39-4":{"f":"입질배서의 경우 피배서인은 질권을 선의취득할 수 있다.","w":"입질배서의 피배서인도 선의취득의 요건을 갖추면 질권을 취득한다.","c":"상","v":1},"공인회2018_53-39-5":{"f":"기한후배서의 경우 지명채권양도의 효력만 있으므로 자격수여적 효력이 인정되지 않고 선의취득도 인정되지 않는다.","w":"기한후배서는 지명채권양도의 효력만 있어 선의취득의 대상이 아니다(어음법 제20조).","c":"상","v":1},"공인회2019_54-33-2":{"f":"약속어음의 발행인은 주채무자이지만 환어음의 발행인은 상환의무자이다.","w":"약속어음 발행인은 주채무자로 환어음의 발행인과 다르다. 환어음에서는 인수인이 주채무자다.","c":"상","v":1},"공인회2019_54-33-3":{"f":"환어음의 소지인은 인수가 거절되면 만기가 도래하기 전이라도 상환의무자에게 상환청구권을 행사할 수 있지만 약속어음에는 인수 제도가 없어 그러하지 아니하다.","w":"인수는 환어음에만 있는 제도여서 약속어음에는 인수거절에 의한 만기 전 상환청구가 없다.","c":"상","v":1},"공인회2019_54-33-4":{"f":"환어음을 발행하는 때에는 발행인, 수취인, 지급인이 기재되지만 약속어음을 발행하는 때에는 발행인, 수취인만 기재된다.","w":"환어음은 지급인이 있고 약속어음은 발행인이 직접 지급을 약속하므로 지급인이 없다.","c":"상","v":1},"공인회2019_54-33-5":{"f":"약속어음과 환어음은 모두 설권증권이다.","w":"어음의 권리는 어음 작성으로 비로소 생기는 설권증권이다.","c":"상","v":1},"공인회2019_54-35-3":{"f":"발행인이 인수를 위한 어음의 제시를 금지한 환어음을 소지한 자는 그 어음을 배서하여 교부할 때 인수를 위하여 어음을 제시해야 한다는 내용을 적을 수 없다.","w":"발행인이 인수제시를 금지한 경우에는 배서인도 제시를 요구하는 문구를 적을 수 없다(어음법 제22조 제4항).","c":"상","v":1},"공인회2019_54-37-2":{"f":"","w":"추심위임배서의 피배서인 C에 대해서는 배서인 B에게 대항할 수 있는 항변으로 대항할 수 있다(어음법 제18조 제2항).","c":"상","v":1},"공인회2020_55-33-1":{"f":"수표의 발행인이 만기를 기재하면 그 만기는 적지 아니한 것으로 본다.","w":"수표는 일람출급이어서 만기를 적어도 그 기재가 없는 것으로 될 뿐 수표가 무효가 되지 않는다(수표법 제28조 제1항).","c":"상","v":1},"공인회2020_55-33-2":{"f":"환어음의 발행인이 지급지를 기재하지 않았다면 지급인의 명칭에 부기한 지를 지급지로 본다.","w":"지급지가 적혀 있지 않은 환어음은 지급인의 명칭에 부기한 곳을 지급지로 본다. 발행지를 지급지로 보는 것은 약속어음이다(어음법 제2조 제2호, 제76조 제2호).","c":"상","v":1},"공인회2020_55-33-3":{"f":"일람출급 환어음의 발행인이 이자가 붙는다는 약정을 기재하면서 이율을 기재하지 않으면 그 이자 약정은 적지 아니한 것으로 본다.","w":"이율이 없으면 이자 기재가 없는 것으로 볼 뿐 환어음이 무효가 되지 않는다(어음법 제5조 제2항).","c":"상","v":1},"공인회2020_55-33-5":{"f":"수표의 발행인이 지급인에게 수표자금을 예치하고 이를 수표에 의해 처분할 수 있는 계약을 체결하지 않은 채 발행한 수표도 유효하다.","w":"수표자금이나 수표계약 없이 발행한 수표도 수표로서의 효력에는 영향이 없다(수표법 제3조 단서).","c":"상","v":1},"공인회2020_55-34-5":{"f":"","w":"본인(甲)을 위한 것임을 표시하지 않으면 대리 방식을 갖추지 못해 乙이 직접 어음상 책임을 진다.","c":"상","v":1},"공인회2020_55-38-1":{"f":"약속어음의 소지인이 지급제시기간 경과 후에 타인에게 어음을 배서·교부한 경우, 그 배서에는 지명채권양도의 효력이 있다.","w":"기한후배서는 권리이전적 효력이 없는 것이 아니라 지명채권양도의 효력을 가진다(어음법 제20조).","c":"상","v":1},"공인회2020_55-38-2":{"f":"약속어음의 발행인이 자신이 발행하였던 약속어음을 배서·교부의 방식으로 취득한 경우, 만기가 남아 있으면 다시 어음에 배서할 수 있다.","w":"환수한 어음은 어음채무자도 다시 배서해 유통시킬 수 있다(어음법 제11조 제3항, 제77조).","c":"상","v":1},"공인회2020_55-38-3":{"f":"채권자가 공연한 입질배서를 받아 소지하고 있던 환어음을 타인에게 양도할 생각으로 다시 배서·교부한 경우, 어음금 지급청구권은 양수인에게 이전되지 않는다.","w":"입질배서의 피배서인은 질권자일 뿐이어서, 그가 다시 한 배서는 대리를 위한 배서의 효력만 있고 어음상 권리가 양수인에게 넘어가지 않는다(어음법 제19조 제1항 단서).","c":"상","v":1},"공인회2020_55-38-5":{"f":"배서인이 환어음에 날짜를 적지 아니한 채 행한 배서는 지급거절증서 작성기간이 지나기 전에 한 것으로 추정한다.","w":"날짜 없는 배서는 기한후배서가 아닌 것으로 추정한다(어음법 제20조 제2항).","c":"상","v":1},"공인회2021_56-33-5":{"f":"수표는 일람출급으로만 발행될 수 있으며, 기재된 발행일이 도래하기 전에 지급을 받기 위하여 제시된 수표는 제시된 날에 이를 지급하여야 한다.","w":"선일자수표라도 제시된 날에 지급해야 한다(수표법 제28조 제2항).","c":"상","v":1},"공인회2021_56-36-1":{"f":"어음의 선의취득에 의해 인적 항변은 소멸하지만 물적 항변은 소멸하지 않는다.","w":"선의취득은 전자의 인적 항변을 끊을 뿐이고 증권 자체에서 생기는 물적 항변은 그대로 남는다.","c":"상","v":1},"공인회2021_56-37-3":{"f":"발행인이 인수를 담보하지 아니한다는 뜻의 문구는 유효하며, 지급을 담보하지 아니한다는 문구는 적지 아니한 것으로 본다.","w":"발행인은 인수담보책임을 면할 수 있지만 지급담보책임은 면할 수 없다(어음법 제9조).","c":"상","v":1},"공인회2021_56-38-3":{"f":"일람출급의 환어음은 발행일부터 1년 내에 지급을 받기 위한 제시를 하여야 하고, 발행인은 이 기간을 단축하거나 연장할 수 있으며 배서인은 단축할 수 있을 뿐이다.","w":"배서인은 제시기간을 단축할 수만 있고 연장할 수 없다(어음법 제34조).","c":"상","v":1},"공인회2021_56-39-2":{"f":"날짜를 적지 아니한 배서는 지급거절증서 작성기간이 지나기 전에 한 것으로 추정한다.","w":"날짜 없는 배서는 기한 내의 배서로 추정한다(어음법 제20조 제2항).","c":"상","v":1},"공인회2022_57-33-2":{"f":"기명무인(記名拇印)은 유효한 배서가 되지 못한다.","w":"무인은 날인이나 서명으로 인정되지 않아 기명무인에 의한 배서는 효력이 없다는 것이 판례다.","c":"상","v":1},"공인회2022_57-33-3":{"f":"약속어음의 발행에 있어 발행인의 기명은 아호나 예명으로도 가능하다.","w":"어음행위자를 특정할 수 있는 기명이면 아호나 예명도 유효하다.","c":"상","v":1},"공인회2022_57-33-4":{"f":"대표이사 직인의 날인만 있고 회사를 위하여 발행하였다는 뜻이 표시되어 있지 않다면 회사는 어음상의 책임을 부담하지 않는다.","w":"대리 또는 대표 방식으로 어음행위를 하려면 본인(회사)을 위한 것임을 표시해야 한다.","c":"중","v":1},"공인회2022_57-33-5":{"f":"조합의 대표조합원이 조합원 전원을 대리하여 그 대표자격을 밝히고 서명하여 발행한 어음은 유효하다.","w":"조합 대리의 방식을 갖추어 발행한 어음은 유효하다.","c":"상","v":1},"공인회2022_57-34-3":{"f":"지급지가 제주도 서귀포시인데 지급장소는 국민은행 서울시 영등포구 여의도 지점으로 된 약속어음은 지급장소 기재가 효력이 없을 뿐 어음 자체가 무효는 아니다.","w":"지급지 밖의 지급장소 기재는 효력이 없을 뿐이고, 약속어음은 지급지가 유효하게 적혀 있으면 유효하다.","c":"중","v":1},"공인회2022_57-35-5":{"f":"발행인이 인수를 위한 어음의 제시를 금지한 경우, 배서인은 인수를 위하여 어음을 제시하여야 한다는 내용을 적을 수 없다.","w":"발행인이 금지한 경우에는 배서인의 제시 요구 문구도 허용되지 않는다(어음법 제22조 제4항).","c":"상","v":1},"공인회2022_57-39-1":{"f":"단순히 어음을 반환하는 것으로도 지급거절의 통지를 할 수 있다.","w":"지급거절의 통지는 어떤 방법으로도 할 수 있고, 어음을 돌려주는 것만으로도 할 수 있다(어음법 제45조 제4항).","c":"상","v":1},"공인회2023_58-33-3":{"f":"배서인이 자기의 배서 이후에 새로 하는 배서를 금지할 경우, 그 배서인은 자기 배서의 피배서인에 대하여는 담보의 책임을 지고 그 이후의 취득자에 대하여만 담보책임을 지지 아니한다.","w":"배서금지배서는 직접 피배서인에 대한 책임은 유지하고 그 이후 취득자에 대해서만 책임을 면한다(어음법 제15조 제2항).","c":"상","v":1},"공인회2023_58-34-2":{"f":"환어음의 만기를 변경하여 인수하였을 경우 인수를 거절한 것으로 보지만, 인수인은 그 인수 문구에 따른 책임을 진다.","w":"만기를 변경해 인수하면 인수 거절로 보되 인수인은 인수 문구에 따라 책임진다(어음법 제26조 제2항).","c":"상","v":1},"공인회2023_58-35-5":{"f":"환어음의 소지인과 수표의 소지인은 모두 일부지급을 거절하지 못한다.","w":"소지인은 어음과 수표 모두 일부지급을 거절할 수 없다(어음법 제39조 제2항, 수표법 제34조 제2항).","c":"상","v":1},"공인회2023_58-40-3":{"f":"환어음의 만기에 지급하는 지급인은 사기 또는 중대한 과실이 없으면 그 책임을 면한다.","w":"지급인이 책임을 면하는 요건은 사기 또는 중대한 과실이 없을 것이다(어음법 제40조 제3항).","c":"상","v":1},"공인회2024_59-33-3":{"f":"지급지가 적혀 있지 아니한 경우 지급인의 명칭에 부기한 지를 지급지 및 지급인의 주소지로 본다.","w":"지급지가 적혀 있지 않은 환어음은 지급인의 명칭에 부기한 곳을 지급지 및 지급인의 주소지로 본다. 발행지를 지급지로 보는 것은 약속어음이다(어음법 제2조 제2호, 제76조 제2호).","c":"상","v":1},"공인회2024_59-34-2":{"f":"특정한 날짜가 적혀 있지 아니한 경우에는 환어음을 발행한 날부터 이자를 계산한다.","w":"이자는 특정한 날짜를 정하지 않으면 발행일부터 계산한다(어음법 제5조 제3항).","c":"상","v":1},"공인회2024_59-35-3":{"f":"환어음의 발행인이 인수를 담보하지 아니한다는 뜻의 문구는 유효하다.","w":"발행인은 인수담보책임을 면할 수 있고, 면할 수 없는 것은 지급담보책임이다(어음법 제9조).","c":"상","v":1},"공인회2024_59-36-1":{"f":"환어음의 지급인에 대한 배서도 유효한 배서이다.","w":"환어음은 지급인에게도 배서할 수 있고 그 배서는 유효하다. 지급인에 대한 배서가 영수증의 효력만 갖는 것은 수표다(어음법 제11조 제3항, 수표법 제15조 제5항).","c":"상","v":1},"공인회2024_59-36-2":{"f":"소지인에게 지급하라는 소지인출급의 배서는 환어음과 수표 모두 백지식 배서와 같은 효력이 있다.","w":"수표에서도 소지인출급의 배서는 백지식 배서와 같은 효력이 있다(어음법 제12조 제3항, 수표법 제15조 제4항).","c":"상","v":1},"공인회2024_59-36-4":{"f":"일부의 배서는 환어음과 수표 모두 무효로 한다.","w":"일부의 배서는 환어음과 수표 모두 무효다(어음법 제12조 제2항, 수표법 제15조 제2항).","c":"상","v":1},"공인회2024_59-36-5":{"f":"환어음의 배서에는 조건을 붙여서는 아니 되고, 수표의 배서에 붙인 조건도 적지 아니한 것으로 본다.","w":"배서에 붙인 조건은 환어음과 수표 모두 적지 아니한 것으로 본다(어음법 제12조 제1항, 수표법 제15조 제1항).","c":"상","v":1},"공인회2024_59-37-1":{"f":"기한 후 배서 여부에 관하여서는 어음의 문면이 아니라 실제 배서를 한 날짜에 의하여 결정한다.","w":"실제 배서일을 기준으로 판단한다.","c":"상","v":1},"공인회2024_59-38-2":{"f":"일람 후 정기출급의 환어음은 그 발행한 날부터 1년 내에 인수를 위한 제시를 하여야 하고, 발행인은 그 기간을 단축하거나 연장할 수 있다.","w":"발행인은 이 기간을 단축하거나 연장할 수 있다(어음법 제23조).","c":"상","v":1},"공인회2024_59-39-1":{"f":"발행일자 후 정기출급 환어음의 소지인은 지급을 할 날 또는 그날 이후의 2거래일 내에 지급을 받기 위한 제시를 하여야 한다.","w":"지급제시는 소지인이 지급할 날 또는 그 후 2거래일 안에 한다. 단순한 점유자도 할 수 있는 것은 인수제시다(어음법 제38조 제1항, 제21조).","c":"상","v":1},"공인회2016_51-35-1":{"f":"위조어음에 배서한 자는 선의·무중과실이라도 자신의 배서에 대한 어음상 책임을 진다.","w":"어음행위독립의 원칙에 따라 위조된 어음에 한 배서도 독립하여 효력이 있다(어음법 제7조).","c":"상","v":1},"공인회2016_51-39-1":{"f":"인수인에 대한 환어음상의 청구권은 만기일부터 3년간 행사하지 아니하면 소멸시효가 완성된다.","w":"인수인에 대한 청구권은 만기일부터 3년이다(어음법 제70조 제1항). 1년은 소지인의 배서인·발행인에 대한 상환청구권이다.","c":"상","v":1},"공인회2016_51-40-5":{"f":"발행인, 배서인 또는 보증인이 환어음상에 거절증서 작성 면제의 문구를 적고 기명날인 또는 서명한 경우에도 소지인은 법정기간 내 어음의 제시 및 통지 의무가 면제되지 않는다.","w":"거절증서 작성만 면제되고 제시·통지 의무는 그대로다. 면제 문구는 의무를 이행하지 않았다는 증명책임을 상대방에게 돌릴 뿐이다(어음법 제46조 제2항).","c":"상","v":1},"공인회2017_52-34-4":{"f":"상속에 의하여 어음이 이전된 경우 어음채무자는 피상속인에 대한 인적 항변사유로써 상속인에게 대항할 수 있다.","w":"상속은 포괄승계여서 인적 항변이 절단되지 않는다.","c":"상","v":1},"공인회2017_52-36-2":{"f":"어음상의 권리가 소멸할 당시에 원인채권이 존재하였다면 이후 원인채권이 소멸하더라도 이득상환청구권은 발생하지 않는다.","w":"이득상환청구권은 어음상 권리 소멸 시점에 이득이 있어야 생긴다. 원인채권이 있던 시점에는 이득이 없었다.","c":"상","v":1},"공인회2017_52-39-1":{"f":"어음의 소멸시효를 계산할 때에는 만기가 공휴일이더라도 그에 이은 제1거래일이 아니라 만기일의 다음 날부터 기산한다.","w":"어음의 소멸시효에는 만기가 휴일이라도 제1거래일로 미루는 규정이 적용되지 않고, 초일불산입에 따라 만기일 다음 날부터 기산한다(어음법 제70조 제1항, 제73조).","c":"중","v":1},"공인회2021_56-34-5":{"f":"어음상에 발행인으로 기명날인하여 외관을 갖춘 어음을 작성한 자는 그 어음이 도난으로 인하여 그의 의사에 의하지 아니하고 유통되었더라도 선의의 취득자에게는 대항할 수 없다.","w":"서명자의 의사에 반해 유통된 경우에도 선의·무중과실의 취득자에게는 책임을 진다는 것이 판례다.","c":"중","v":1},"공인회2021_56-35-1":{"f":"어음소지인이 약속어음 발행인의 보증인에 대하여 갖는 어음상 청구권은 만기일로부터 3년간 행사하지 아니하면 소멸시효가 완성된다.","w":"보증인은 피보증인과 같은 책임을 지고 시효도 같다. 약속어음 발행인에 대한 청구권은 만기일부터 3년이다.","c":"상","v":1},"공인회2023_58-36-4":{"f":"발행인이 소지인의 상환청구권 행사를 위한 지급거절증서의 작성을 면제한 경우에도 소지인은 법정기간 내 환어음의 지급제시 및 통지 의무를 이행하여야 한다.","w":"거절증서 작성 면제는 제시·통지 의무를 면제하지 않는다(어음법 제46조 제2항).","c":"상","v":1},"공인회2024_59-40-5":{"f":"무비용상환의 문구가 적혀 있는 경우에 지급을 받기 위한 제시기간이 지나면 소지인은 배서인, 발행인, 그 밖의 어음채무자에 대하여 그 권리를 잃으며 인수인에 대하여는 권리를 잃지 않는다.","w":"무비용상환 문구가 있는 어음의 지급제시기간이 지나면 소지인은 배서인·발행인 등에 대한 권리를 잃지만 주채무자인 인수인에 대한 권리는 잃지 않는다(어음법 제53조 제1항 제3호·단서).","c":"상","v":1},"공인회2017_52-35-2":{"f":"발행지의 기재가 없는 경우에는 발행인의 명칭에 부기한 지를 발행지로 본다.","w":"발행지가 적혀 있지 않으면 발행인의 명칭에 부기한 곳을 발행지로 본다. 지급지에서 발행한 것으로 보는 규정은 없다(수표법 제2조 제3호).","c":"중","v":1},"공인회2017_52-40-1":{"f":"수표의 지급제시기간 중의 휴일은 지급제시기간에 산입한다.","w":"수표의 지급제시기간 중의 휴일은 그 기간에 산입하고, 기간의 말일이 휴일이면 그다음 첫 거래일까지 기간이 늘어난다(수표법 제60조 제2항).","c":"상","v":1},"공인회2017_52-40-2":{"f":"선일자수표의 지급제시기간과 소멸시효는 모두 수표에 기재된 발행일자를 기준으로 계산한다.","w":"선일자수표의 제시기간은 수표에 적힌 발행일부터 기산하고, 상환청구권의 시효도 그 제시기간이 지난 후 6개월이므로 실제 발행일은 기준이 되지 않는다(수표법 제29조 제4항, 제51조 제1항).","c":"상","v":1},"공인회2017_52-40-3":{"f":"지급보증은 수표의 앞면에 지급보증 또는 그 밖에 지급을 하겠다는 뜻을 적고 날짜를 부기하여 지급인이 기명날인하거나 서명하여야 한다.","w":"지급보증은 수표의 뒷면이 아니라 앞면에 한다(수표법 제53조 제2항).","c":"상","v":1},"공인회2017_52-40-4":{"f":"지급위탁의 취소는 수표행위가 아니어서 수표면에 할 필요가 없고 방식의 제한이 없어 구두로도 할 수 있다.","w":"지급위탁의 취소는 발행인이 지급인에게 하는 의사표시여서 방식에 제한이 없고 구두로도 할 수 있으며, 제시기간이 지난 후에만 효력이 생긴다(수표법 제32조 제1항).","c":"중","v":1},"공인회2018_53-34-2":{"f":"지급인이 지급보증을 거절하더라도 수표소지인은 그 거절을 이유로 배서인에 대하여 상환청구권을 행사할 수 없다.","w":"지급보증은 지급인의 임의 행위이고, 수표에는 인수제도가 없어 지급보증 거절은 상환청구 사유가 아니다.","c":"상","v":1},"공인회2019_54-39-5":{"f":"수표의 소지인도 그 수표에 횡선을 그을 수 있다.","w":"횡선은 발행인뿐 아니라 소지인도 그을 수 있다(수표법 제37조 제1항).","c":"상","v":1},"공인회2019_54-40-1":{"f":"자기앞수표의 발행인은 A은행이다.","w":"자기앞수표는 은행이 자기를 지급인으로 하여 발행하는 수표이고, 발행 의뢰자 B는 발행인이 아니다.","c":"상","v":1},"공인회2019_54-40-2":{"f":"자기앞수표를 분실한 B가 수표금의 지급중지를 A은행에 청구하는 행위는 수표법상의 지급위탁의 취소행위에 해당하지 않는다.","w":"자기앞수표는 발행인과 지급인이 같은 은행이어서 지급위탁이 있을 수 없으므로 사고신고는 지급위탁의 취소가 아니다.","c":"상","v":1},"공인회2019_54-40-3":{"f":"","w":"국내 수표의 지급제시기간은 10일이어서 1개월 뒤에 제시하면 B는 수표상 권리를 행사할 수 없고 A은행에게 수표법상 지급의무는 없다. 지급위탁의 취소가 없으면 은행이 지급할 수는 있다(수표법 제29조 제1항, 제32조 제2항).","c":"중","v":1},"공인회2019_54-40-5":{"f":"","w":"B와 C가 외상대금의 지급을 위하여 수표를 교부하기로 합의했으므로 외상대금채무는 교부만으로 소멸하지 않고 수표금이 지급된 때 소멸한다.","c":"중","v":1},"공인회2020_55-39-2":{"f":"A가 B에게 지급하여 달라고 기재한 경우에도 B는 배서·교부의 방식으로 수표를 양도할 수 있다.","w":"기명식 수표도 지시금지 문구가 없으면 배서·교부로 양도할 수 있다(수표법 제14조 제1항).","c":"상","v":1},"공인회2021_56-40-4":{"f":"수표의 소지인은 일부지급을 거절할 수 없다.","w":"수표 소지인은 일부지급을 거절하지 못한다(수표법 제34조 제2항).","c":"상","v":1},"공인회2022_57-37-1":{"f":"수표에 적은 인수의 문구는 적지 아니한 것으로 본다.","w":"수표는 인수할 수 없다(수표법 제4조).","c":"상","v":1},"공인회2022_57-37-2":{"f":"수표는 제3자의 계산으로 발행할 수 있다.","w":"수표는 제3자의 계산으로 발행할 수 있다(수표법 제6조 제2항).","c":"상","v":1},"공인회2022_57-37-3":{"f":"수표의 금액을 글자 또는 숫자로 중복하여 적은 경우에 그 금액에 차이가 있으면 최소금액을 수표금액으로 한다.","w":"같은 방식으로 중복 기재해 차이가 나면 최소금액이 기준이다. 글자와 숫자 사이의 차이는 글자가 우선한다(수표법 제9조).","c":"상","v":1},"공인회2022_57-37-5":{"f":"일반횡선은 특정횡선으로 변경할 수 있으나, 특정횡선은 일반횡선으로 변경하지 못한다.","w":"변경은 일반횡선에서 특정횡선으로만 가능하다(수표법 제37조 제4항).","c":"상","v":1},"공인회2022_57-40-4":{"f":"발행인에 대하여 배서한 경우 그 발행인은 다시 수표에 배서할 수 있다.","w":"발행인에 대한 배서도 유효하고 그 발행인은 다시 배서할 수 있다(수표법 제14조 제3항).","c":"상","v":1},"공인회2023_58-37-2":{"f":"수표의 보증인은 일부의 지급을 담보할 수 있으나 수표의 지급보증인은 지급보증에 의하여 그 금액의 일부의 지급을 담보할 수 없다.","w":"수표의 보증은 금액의 일부에 대해서도 할 수 있지만, 지급보증은 조건 없이 하여야 하고 일부에 대한 지급보증은 인정되지 않는다(수표법 제25조 제1항, 제54조 제1항).","c":"중","v":1},"공인회2025_60-21-5":{"f":"자회사가 모회사의 주식을 소유하고 있는 경우 자회사는 모회사의 주주총회에서 의결권을 행사할 수 없다.","w":"모회사의 주식은 자회사가 가지고 있더라도 의결권이 없다(상법 제369조 제3항).","c":"상","v":1},"공인회2025_60-24-1":{"f":"신주인수로 인한 주식배정에 관하여 정관에 다른 정함이 없음에도 주식의 종류에 따라 특수하게 정한 경우 이로 인해 손해를 보는 종류주식의 주주의 총회의 결의가 필요하다.","w":"신주 배정으로 어느 종류의 주주에게 손해를 미치게 되면 그 종류주주총회의 결의가 있어야 한다(상법 제436조, 제435조).","c":"상","v":1},"공인회2016_51-14-4":{"f":"甲회사는 취득한 자기주식을 상당한 기간 내에 처분해야 할 의무를 부담하지 않는다.","w":"배당가능이익으로 취득한 자기주식은 계속 보유할 수 있다. 처분할 때 처분 주식의 종류·수, 가액, 상대방 등은 정관에 정함이 없으면 이사회가 정한다(상법 제342조).","c":"상","v":1},"공인회2016_51-17-2":{"f":"甲회사가 가진 자기주식의 수는 발행주식총수에 산입되지 않는다.","w":"회사가 가진 자기주식은 의결권이 없고(상법 제369조 제2항), 총회 결의에 관하여 발행주식총수에 산입하지 않는다(제371조 제1항).","c":"상","v":1},"공인회2016_51-17-5":{"f":"甲회사가 발행한 의결권이 없는 종류주식은 甲회사의 발행주식총수에 산입되지 않는다.","w":"제344조의3 제1항의 의결권 없는 종류주식은 총회 결의에 관하여 발행주식총수에 산입하지 않는다(상법 제371조 제1항).","c":"상","v":1},"공인회2016_51-30-2":{"f":"甲회사가 분할을 하는 경우 언제나 채권자보호절차를 거쳐야 하는 것은 아니다.","w":"단순분할신설회사는 원칙적으로 분할회사 채무에 연대책임을 지므로(상법 제530조의9 제1항) 채권자보호절차가 필요 없다. 분할계획서로 승계 채무만 책임지기로 정한 경우에만 제527조의5의 채권자보호절차를 거친다(같은 조 제2항·제4항).","c":"상","v":1},"공인회2016_51-15":{"w":"정관으로 이사회 권한을 주주총회로 돌릴 수 있다고 상법이 명문으로 정한 사항: 대표이사 선정(제389조 제1항 단서), 정관에 정함이 없는 신주발행사항의 결정(제416조 단서), 법정준비금의 자본금 전입(제461조 제1항 단서), 전환사채 발행사항의 결정(제513조 제2항 단서).\n이사의 자기거래 승인은 이사회 승인(제398조)이며 정관으로 주주총회 권한으로 정할 수 있다는 명문 규정이 없다(자본금 10억원 미만 회사는 주주총회가 승인하나 제외 조건). 3번이 해당하지 않는다.","c":"상","v":1},"공인회2016_51-27":{"w":"주주의 열람·등사 청구를 회사가 거절할 수 있다고 상법이 명문으로 정한 것은 이사회의사록(제391조의3 제4항: 이유를 붙여 거절)과 회계의 장부와 서류(제466조 제2항: 청구가 부당함을 증명하면 거부)이다. 2번이다.\n주주명부(제396조), 재무제표(제448조), 주주총회의사록(제396조)은 이런 거절 규정이 없다.","c":"상","v":1},"공인회2016_51-38":{"w":"5) 날짜를 적지 않은 배서는 거절증서 작성기간이 지나기 전에 한 것으로 추정한다(어음법 제20조 제2항). 지난 후라고 한 5번이 틀렸다.\n1) 발행인이 지시금지 문구를 적으면 배서로 양도할 수 없다(제11조 제2항). 2) 배서는 환어음이나 보충지에 적으면 되고 앞면도 가능하지만 백지식 배서는 뒷면이나 보충지에 하지 않으면 효력이 없다(제13조). 3) 배서에 붙인 조건은 적지 않은 것으로 본다(제12조 제1항). 4) 일부 배서는 무효다(제12조 제2항).","c":"상","v":1},"공인회2017_52-14":{"w":"2) 회사가 정당한 사유 없이 명의개서를 거절하면 양수인은 명의개서 없이도 주주로서 권리를 행사할 수 있다(판례). 2번이다.\n1) 명의개서가 이루어지기 전의 양수인은 회사에 대항하지 못한다(제337조 제1항). 3) 등록질권자라도 의결권은 주주에게 있다. 4) 자회사가 다른 회사 발행주식총수의 10분의 1을 넘게 가지면 그 다른 회사가 가진 모회사 주식은 의결권이 없다(제369조 제3항). 5) 이사의 책임을 추궁하는 결의에서 그 이사인 주주는 특별이해관계인이어서 의결권을 행사하지 못한다(제368조 제3항).","c":"상","v":1},"공인회2018_53-01":{"w":"㉠ 대표이사 개인이 개인 명의로 회사원에게 빌린 돈은 상행위로 인한 채무가 아니라 민사 5%.\n㉡ 부동산중개업자가 영업과 관련해 한 금전 대여는 영업을 위한 보조적 상행위로 추정되어 6%.\n㉢ 교통사고 손해배상채무는 상행위로 인한 채무가 아니라 불법행위로 민사 5%.\n㉣ 판매점을 운영하며 포도를 파는 것은 상행위(매매)여서 대금채권에 6% 적용.\n해당 2개(㉡, ㉣).","c":"중","v":1},"공인회2018_53-04":{"w":"5) 매수인이 목적물의 수령을 거부하는 경우 매도인은 목적물을 공탁하거나 상당한 기간을 정해 최고한 후 경매할 수 있다. 이 경우 법원의 허가가 필요하다고 한 설명이 틀리다(상법 제67조는 법원 허가 없이 경매 가능).\n1) 검사·통지의무(제69조 제1항). O  2) 6개월 내 하자 발견 시 즉시 통지. O  3), 4) 해제 후 보관·공탁 의무와 법원 허가 경매(제70조). O","c":"상","v":1},"공인회2018_53-10":{"w":"㉠ 주식이전은 주주총회 특별결의가 필요하다(제360조의16, 제434조). O\n㉡ 주식이전으로 주주의 부담이 가중되는 경우에는 특별결의 외에 그 주주 전원의 동의가 필요하다. X\n㉢ 완전모회사의 자본금은 주식이전의 날에 완전자회사가 되는 회사에 현존하는 순자산액에서 주주에게 제공할 금전 등을 뺀 액을 초과하지 못한다(제360조의18). O\n㉣ 주식이전 결의 시 주권 제출을 1개월 이상 공고하고 주주명부상 주주와 질권자에게 각각 통지해야 한다(공고 및 통지). '통지 또는 공고'라는 표현이 틀리다. X\n㉤ 주식이전 무효의 소는 주식이전의 날부터 6개월 내에 제기. O","c":"중","v":1},"공인회2018_53-15":{"w":"상법 제289조 제1항의 정관 절대적 기재사항: 목적, 상호, 회사가 발행할 주식의 총수, 액면주식 1주의 금액, 회사 설립시 발행하는 주식의 총수, 본점 소재지, 공고방법, 발기인의 성명·주민등록번호·주소.\n자본금의 액은 정관의 절대적 기재사항은 아니지만 설립등기 사항이다(제317조 제2항).","c":"상","v":1},"공인회2018_53-17":{"w":"㉠ O: 의결권 없는 주식을 제외한 발행주식총수의 3% 이상 주주는 주주총회일 6주 전(10월 10일)까지 서면·전자문서로 주주제안을 할 수 있다(제363조의2 제1항). 10월 2일은 가능하다.\n㉡ X: 집중투표 청구는 주주총회일 7일 전(11월 14일)까지 해야 한다(제382조의2 제2항). 11월 17일은 늦다.\n㉢ X: 주주가 청구하면 이사는 의안의 요령을 소집통지에 적어야 한다(제363조의2 제2항). 적을 수 있다가 아니다.\n㉣ X: 영업에 중대한 영향을 미치는 영업 일부의 양수는 특별결의로 출석 의결권의 3분의 2 이상과 발행주식총수의 3분의 1 이상이 필요하다(제374조, 제434조).\n㉤ X: 의결권을 불통일 행사하려면 총회일 3일 전까지 회사에 통지해야 한다(제368조의2 제1항).\n옳은 것은 1개다.","c":"상","v":1},"공인회2018_53-18":{"w":"양도승인 거부 통지를 받은 주주(20일), 영업양도 반대주주(주주총회 결의일부터 20일 이내 매수청구), 영업양수 반대주주(20일), 합병 반대주주(20일)는 모두 20일 이내에 청구한다.\n지배주주가 있는 회사의 소수주주의 매수청구권은 지배주주가 매도청구 통지를 한 경우 등 기간 제한이 다르다(소수주주는 언제든지 청구할 수 있다). 2번이 다르다.","c":"상","v":1},"공인회2018_53-40":{"w":"5) 만기 전에는 소지인이 지급을 받을 의무가 없다(어음법 제77조, 제40조 제1항). 수령을 거절해도 수령지체가 아니므로 5번이 틀렸다.\n1) 판례는 2월 30일 같은 날을 그 달 말일로 보아 만기 기재를 유효로 본다. 2) 지급할 날은 2월 28일(수)이다. 3) 3월 2일은 지급할 날 이후 2거래일(3월 2일, 3월 5일) 안이어서 거절증서 작성기간이 지나기 전의 배서이므로 만기 전 배서와 같은 효력이 있다(제20조 제1항). 4) 지급제시기간 안에 어음교환소에서 한 제시는 지급을 받기 위한 제시의 효력이 있다(제38조 제2항).","c":"상","v":1},"공인회2019_54-06":{"w":"ㄱ: 회사는 수개의 영업을 영위해도 단일상호를 써야 한다. X\nㄴ: 등기한 상호를 정당한 사유 없이 2년간 사용하지 않으면 폐지한 것으로 본다. O\nㄷ: 상호의 가등기는 설립 시뿐 아니라 상호·목적 변경 때도 가능하다. X\nㄹ: 명의대여자는 거래 상대방이 악의 또는 중과실이면 면책된다. O\nㅁ: 부정한 목적으로 타인의 영업으로 오인할 상호를 쓰는 자에 대해서는 등기 여부와 관계없이 폐지를 청구할 수 있다. X","c":"중","v":1},"공인회2019_54-17":{"w":"1) 회계장부·서류 열람청구권은 발행주식총수의 3% 이상 소수주주권이다(제466조).\n2)~5) 영업보고서, 대차대조표, 손익계산서, 감사보고서의 열람은 단독주주권이다(제448조).","c":"상","v":1},"공인회2019_54-20":{"w":"5) 포괄적 주식이전으로 발행하는 완전모회사의 주식은 완전모회사의 설립등기일에 효력이 생긴다(제360조의20). 주식이전의 날이 아니다.\n1) 회사가 전환권을 가진 전환주식: 주권제출기간 만료 시. O  2) 주주의 전환 청구: 청구한 때. O  3) 신주인수권부사채: 납입 시. O  4) 포괄적 주식교환의 신주: 주식교환을 할 날. O","c":"상","v":1},"공인회2019_54-22":{"w":"상근감사 결격사유(제542조의10 제2항): 미성년자·피성년후견인·피한정후견인, 파산선고를 받고 복권되지 않은 자, 금고 이상의 형 집행이 끝나거나 면제된 후 2년이 지나지 않은 자, 해당 회사의 상무에 종사하는 이사·피용자의 배우자와 직계존비속 등.\n감사위원회 위원으로 재임하였던 자는 결격이 아니므로 상근감사로 선임할 수 있다.","c":"상","v":1},"공인회2019_54-25":{"w":"이사 자기거래 승인 대상(제398조): 이사·주요주주, 그들의 배우자 및 직계존비속, 이사·주요주주의 배우자의 직계존비속, 이들이 단독 또는 공동으로 의결권 있는 발행주식총수의 50% 이상을 가진 회사 및 그 자회사.\n이사의 직계비속의 배우자는 해당하지 않는다.","c":"상","v":1},"공인회2019_54-28":{"w":"합병, 파산, 분할(분할합병 포함)로 해산하는 경우는 청산절차에 들어가지 않는다. 해산판결, 해산명령, 주주총회 특별결의로 해산하면 청산절차를 밟는다.\nㄱ, ㄷ, ㅁ.","c":"상","v":1},"공인회2019_54-34":{"w":"4) 분할출급 환어음은 만기 요건에 어긋나 무효다(어음법 제33조 제2항).\n1) 수표의 이자약정은 기재하지 않은 것으로 본다. 2) 수표 지급담보 면제 문구는 기재하지 않은 것으로 본다. 3) 일람출급 어음의 이자약정은 유효. 5) 인수 담보 면제 문구는 유효.","c":"상","v":1},"공인회2019_54-36":{"w":"백지식 배서(피배서인란 공란)를 받은 C는 ① 공란에 D 명의를 기재하고 교부하거나 ② 공란을 보충하지 않고 교부하거나 ③ 다시 배서하여 교부할 수 있다.\n3) C가 공란에 자기 자신의 명의를 기재하면 C가 피배서인이 되어 배서의 연속상 다시 양도하려면 C의 배서가 필요하다. 배서 없이 교부만으로 양도할 수 있다는 설명이 틀리다.","c":"상","v":1},"공인회2019_54-38":{"w":"2) 만기 후 제시기간(2.19~2.21) 안의 지급은 선의·무과실이면 면책된다. 면하지 못한다는 설명이 틀리다.\n1) 만기 전 지급은 지급인이 위험을 부담한다. O  3) 제시기간 경과 후 지급도 선의·무과실이면 면책. O  4) 지급제시기간이 지난 뒤 공탁 가능. O  5) 만기 전에는 소지인이 수령할 의무가 없다. O","c":"상","v":1},"공인회2020_55-03":{"w":"익명조합의 종료사유는 영업의 폐지 또는 양도, 영업자의 사망 또는 성년후견개시, 영업자 또는 익명조합원의 파산이다(제84조).\n익명조합원의 사망(ㄴ)은 종료사유가 아니다. ㄱ, ㄷ, ㄹ로 4번이다.","c":"상","v":1},"공인회2020_55-12":{"w":"ㄱ: 합명회사도 주식회사의 주주가 될 수 있다. X\nㄴ: 1인회사에서 실제 총회가 없었어도 총회 의사록이 작성되었다면 결의가 있었던 것으로 볼 수 있다(판례). O\nㄷ: 회사의 권리능력 목적 범위에는 목적 수행에 직접·간접으로 필요한 행위가 포함된다(판례). O\nㄹ: 액면주식을 무액면주식으로 전환하려면 정관 변경이 필요하다. 이사회 결의만으로는 안 된다. X","c":"상","v":1},"공인회2020_55-15":{"w":"ㄱ O: 주식은 자본금 감소 규정에 따라서만 소각하고 이사회 결의로 자기주식을 소각하는 경우는 예외다(제343조 제1항).\nㄴ X: 다른 회사 발행주식총수의 10분의 1을 넘게 취득하면 지체 없이 통지해야 한다(제342조의3). 6개월이 아니다.\nㄷ X: 정관에 정함이 없으면 자기주식 처분 사항은 이사회가 정한다(제342조).\nㄹ X: 이사회 승인 없이 주식을 취득한 자도 회사에 취득 승인을 청구할 수 있다(제335조의7).\n1번이다.","c":"상","v":1},"공인회2020_55-17":{"w":"정관의 절대적 기재사항(제289조 제1항)은 발기인의 성명·주민등록번호·주소이다. 이사의 성명 등은 정관의 절대적 기재사항이 아니다.","c":"상","v":1},"공인회2020_55-23":{"w":"재무제표의 승인은 주주총회 보통결의사항이다(제449조). 경영위임, 회사의 계속, 영업 손익 전부를 같이하는 계약, 영업에 중대한 영향을 미치는 영업양수는 특별결의사항이다.","c":"상","v":1},"공인회2020_55-35":{"w":"1) 발행인이 지급 담보 면제 문구를 적어도 그 문구는 기재하지 않은 것으로 보아 발행인은 인수와 지급을 담보한다(어음법 제9조). 담보책임이 인정된다.\n2) 소지인출급식 배서 후 교부만으로 양도한 자는 배서인이 아니라 담보책임이 없다. 3) 무담보 문구는 유효. 4) 의사무능력자의 행위는 무효. 5) 발행인 서명이 없는 어음은 무효로, 그 후 배서의 책임이 생기지 않는다.","c":"중","v":1},"공인회2020_55-36":{"w":"추심위임배서의 피배서인은 어음상 권리를 취득하지 못하고 대리권만 갖는다. 따라서 선의취득이 성립하지 않는다.\n배서금지·무담보·입질배서(공연한 질권 설정)나 교부만 한 경우는 선의취득이 가능하다.","c":"상","v":1},"공인회2020_55-37":{"w":"3) '지급을 위하여' 교부한 경우 채권자는 먼저 어음상 권리를 행사해야 하고, 어음금을 받지 못했을 때 원인채권을 행사할 수 있다. 어음상 권리를 행사하지 않고 원인채권을 선택해 행사할 수 있다는 설명이 틀리다.\n1) 지급을 위한 교부는 원인채권을 소멸시키지 않는다. O  2) 변제기가 어음 만기까지 유예. O  4) 어음금을 받으면 원인채권이 소멸. O  5) 어음과 원인채무 이행은 동시이행 관계. O","c":"상","v":1},"공인회2020_55-40":{"w":"5) 수표는 인수가 금지되어 있어 수표의 인수 제도가 없다. 지급인이 인수를 거절했다는 이유의 상환청구는 성립하지 않는다.\n1)~4)는 환어음에서 만기 전 상환청구가 인정되는 사유(일부 인수, 인수인 파산, 인수제시금지어음 발행인의 파산, 인수 거절 후 지급인 재산에 대한 강제집행 부주효 등)다.","c":"상","v":1},"공인회2021_56-13":{"w":"해산판결청구권은 발행주식총수의 10% 이상 소수주주권이다(제520조).\n주주제안권(제363조의2), 청산인해임청구권(제539조), 감사해임청구권(제415조, 제385조), 회계장부열람청구권(제466조)은 3% 이상 주주가 행사한다.","c":"상","v":1},"공인회2022_57-14":{"w":"ㄱ: 발행주식총수의 95% 이상을 보유한 지배주주는 경영상 목적상 필요하면 소수주주에게 주식 전부의 매도를 청구할 수 있다(제360조의24). O\nㄴ: 주권 상실자는 제권판결을 얻어야 재발행을 청구할 수 있다(공시최고 진행만으로는 불가). X\nㄷ: 의결권 없는 주식을 제외한 발행주식총수의 10% 이상을 가진 주주에게는 주식매수선택권을 부여할 수 없다(제340조의2 제2항). O\nㄹ: 주식을 질권의 목적으로 할 때에도 주권을 교부해야 질권이 성립한다(제338조). X","c":"중","v":1},"공인회2022_57-20":{"w":"ㄱ: 최근 2년 이내에 회사의 상무에 종사한 이사는 사외이사가 될 수 없다(제382조 제3항). X\nㄴ: 모회사의 이사는 자회사의 사외이사가 될 수 없다. O\nㄷ: 최대주주가 자연인이면 본인과 그 배우자·직계존비속은 사외이사가 될 수 없다. X\nㄹ: 금고 이상의 형 집행이 끝난 후 2년이 지났으면 결격이 아니다(제542조의8 제2항). O\nㅁ: 의결권 없는 주식을 제외한 발행주식총수의 10% 이상 소유한 주요주주는 상장회사 사외이사가 될 수 없다. O","c":"상","v":1},"공인회2022_57-21":{"w":"이사가 회사에 이자 약정이나 담보 없이 금전을 대여하는 것은 회사에 이익만 되고 불이익이 없는 거래여서 이사회 승인이 필요하지 않다고 본다.\n2) 이사의 직계비속, 3) 이사의 배우자의 직계존속, 4) 이사 개인 채무에 대한 회사의 보증, 5) 이사가 50% 이상 가진 회사와의 거래는 승인 대상이다.","c":"중","v":1},"공인회2022_57-36":{"w":"ㄱ: 어음행위의 대리에는 대리관계를 표시하는 현명주의가 엄격하게 적용된다. O\nㄴ: 대리권을 내부적으로 제한할 수 있다. O\nㄷ: 대리권 없이 대리인으로 어음에 서명한 자는 본인으로서 어음상 책임을 진다(어음법 제8조). O\nㄹ: 무권대리의 항변은 누구에게나 주장할 수 있는 물적 항변이다. X","c":"상","v":1},"공인회2022_57-38":{"w":"2) 배서에 조건을 붙이면 조건만 기재하지 않은 것으로 보며 배서 자체는 유효하다(어음법 제12조 제1항). 배서 자체가 무효라는 설명이 틀리다.\n1) 말소한 배서는 배서를 하지 않은 것으로 본다. O  3) 일부 배서는 무효. O  4) 배서금지 배서. O  5) 소지인출급 배서는 백지식 배서와 같다. O","c":"상","v":1},"공인회2023_58-01":{"w":"ㄱ: 출판에 관한 행위는 기본적 상행위(제46조 제8호)를 영업으로 하는 당연상인이다. 의제상인이 아니다. X\nㄴ: 미성년자가 영업의 허락을 받아 상인이 되는 것이고, 법정대리인이 상인이 되는 것은 아니다. X\nㄷ: 자기 이름으로 타인의 계산으로 물건 매매를 영업으로 하는 위탁매매인은 당연상인이다. X\nㄹ: 영업 중 피한정후견인이 되어도 상인 자격을 상실하지 않는다. X\n옳은 것은 0개.","c":"상","v":1},"공인회2023_58-04":{"w":"위탁매매인은 위탁자를 위해 한 매매에 관해 상대방이 채무를 이행하지 않으면 위탁자에게 직접 이행할 책임을 진다(제105조). 이행담보책임을 부담한다.","c":"상","v":1},"공인회2023_58-06":{"w":"ㄱ X: 익명조합은 상대방의 영업을 위해 출자하고 상대방은 그 영업으로 인한 이익을 분배할 것을 약정하는 계약이다(제78조). 이익 여부와 관계없이 일정액을 주는 약정이 아니다.\nㄴ O: 제86조가 준용하는 제272조에 따라 익명조합원은 신용이나 노무를 출자하지 못한다.\nㄷ O: 출자한 재산은 영업자의 재산으로 보므로(제79조) 영업자가 유용해도 횡령죄가 성립하지 않는다(판례).\nㄹ O: 익명조합원이 자기 성명을 영업자의 상호에 쓰게 하면 그 뒤의 채무에 대해 영업자와 연대책임을 진다(제81조).\nㅁ X: 익명조합원의 사망은 종료사유가 아니다(제84조).\n옳은 것은 3개다.","c":"상","v":1},"공인회2023_58-10":{"w":"ㄱ: 유한회사의 이사가 수인이면 지점의 설치·이전·폐지는 이사 과반수 결의로 한다(제564조). O\nㄴ: 유한책임회사는 정관으로 사원이 아닌 자를 업무집행자로 정할 수 있다. X\nㄷ: 합자회사의 무한책임사원은 정관에 다른 정함이 없으면 각자가 업무를 집행할 권리와 의무가 있다. O\nㄹ: 유한책임사원은 업무집행권과 대표권이 없다. X\nㅁ: 합명회사에서 수인의 업무집행사원을 정한 경우 정관이나 총사원 동의로 회사 대표자를 정할 수 있다. O","c":"중","v":1},"공인회2023_58-14":{"w":"ㄱ: 정관에 정한 바에 따라 이익배당, 잔여재산분배, 의결권, 상환, 전환 등에 관해 내용이 다른 종류주식을 발행할 수 있다(제344조 제1항). O\nㄴ: 종류주식을 발행하는 경우 정관에 다른 정함이 없는 경우에도 합병·분할로 인한 주식의 배정에 관해 특수하게 정할 수 있다(제344조 제3항). 정관에 정함이 없으면 정할 수 없다는 설명이 틀리다. X\nㄷ: 의결권 없는 주식과 제한되는 주식의 수는 발행주식총수의 4분의 1을 초과하지 못한다. O\nㄹ: 상환주식의 상환 대가로 현금 외에 유가증권(다른 종류주식 제외)이나 그 밖의 자산을 교부할 수 있다. 다른 종류주식을 교부할 수 있다는 설명이 틀리다. X\nㅁ: 전환으로 신주식을 발행하는 경우 전환 전의 발행가액을 신주식의 발행가액으로 한다(제348조). O","c":"중","v":1},"공인회2023_58-17":{"w":"법정준비금의 감소는 주주총회 보통결의사항이다(제461조의2). 액면주식의 분할(제329조의2), 사후설립(제375조), 회사의 계속(제519조), 감사의 해임(제415조, 제385조)은 특별결의사항이다.","c":"상","v":1},"공인회2023_58-23":{"w":"5) 집중투표에서 각 주주는 1주마다 선임할 이사의 수와 같은 수의 의결권을 가진다(제382조의2 제3항). 이사 후보자의 수와 같다는 설명이 틀리다.\n1) 발기설립: 발기인 의결권의 과반수(제296조). O  2) 모집설립: 창립총회에서 출석한 주식인수인 의결권의 2/3 이상, 인수된 주식 총수의 과반수(제309조). O  3) 설립 후: 출석 의결권의 과반수와 발행주식총수의 1/4 이상. O  4) 3% 이상 주주의 집중투표 청구. O","c":"상","v":1},"공인회2023_58-31":{"w":"합병대가를 존속회사의 자기주식과 금전으로만 지급하면 신주를 발행하지 않으므로 존속회사의 증가할 자본금과 준비금에 관한 사항(제523조 제2호)은 합병계약서에 기재할 내용이 아니다.\n1)~4) 주주총회 기일(제523조 제6호), 합병을 할 날, 정관변경 규정, 합병으로 인한 이익배당 한도액은 기재사항이다.","c":"상","v":1},"공인회2023_58-32":{"w":"5) 주식교환 무효판결이 확정되면 완전모회사는 교환으로 신주를 받았거나 자기주식을 이전받은 완전자회사 주주에게 완전자회사의 주식을 이전해야 한다(제360조의14 제3항).\n1) 완전모회사가 되는 A회사도 주주총회 특별결의가 원칙이다. 2) 완전자회사가 가진 모회사 주식은 이전되지 않는다. 3) 교환 대가로 금전을 줄 수 있다(제360조의3 제3항 제4호). 4) 주권은 주식교환의 날에 무효가 된다.","c":"상","v":1},"공인회2023_58-38":{"w":"수표에는 등본 제도가 없다. 3번이다.\n자기지시수표와 위탁수표(수표법 제6조), 제3자방 지급 기재(제8조), 복본은 수표법이 인정한다.","c":"상","v":1},"공인회2023_58-39":{"w":"어음 수수의 목적에 관한 명시적 합의가 없으면 원인채무의 지급을 위해 교부한 것으로 추정된다. 이 경우 어음금을 지급받으면 원인채권이 소멸한다.\n1) 담보 목적이 아니라 지급 목적 추정. X  2) 지급을 위한 교부면 먼저 어음상 권리를 행사해야 한다. X  3) 원인관계가 소멸해도 어음관계는 소멸하지 않는다(무인성). X  4) 어음금을 지급받으면 매매대금 채무도 소멸. O  5) 어음 반환과 원인채무 이행은 동시이행 관계라 A는 어음의 반환을 요구하며 이행을 거절할 수 있다. X","c":"상","v":1},"공인회2024_59-12":{"w":"2) 불소지 신고를 한 주식은 회사가 주권을 발행하지 않으므로, 이를 양도하려면 주주가 회사에 주권의 발행을 청구해 그 주권을 교부해야 한다. 다른 주주들에게 주권이 발행되었다고 해서 불소지 신고 주주가 주권 교부 없이 양도할 수 있게 되는 것은 아니다. 틀리다.\n1) 신고 후 발행된 주권은 선의취득의 대상이 될 수 없다. O  3) 주권을 발행받은 주주는 주권을 회사에 제출해야 한다. O  4) 회사는 제출된 주권을 무효로 하거나 명의개서대리인에게 임치. O  5) 언제든지 주권의 발행·반환을 청구할 수 있다. O","c":"중","v":1},"공인회2024_59-15":{"w":"주권의 기재사항(제356조): 회사의 상호, 회사 성립 연월일, 회사가 발행할 주식의 총수, 액면주식을 발행하는 경우 1주의 금액, 회사 성립 후 발행된 주식은 발행 연월일, 종류주식의 내용·수, 양도 제한 규정, 번호, 대표이사의 기명날인.\n무액면주식의 1주 발행가액은 기재사항이 아니다.","c":"상","v":1},"공인회2024_59-28":{"w":"해산사유(제517조): 존립기간의 만료 기타 정관으로 정한 사유의 발생(ㄱ), 합병(ㄴ), 파산(ㄹ), 법원의 해산명령 또는 해산판결(ㅂ), 주주총회의 특별결의(보통결의가 아니다).\n주주가 1인으로 된 때는 해산사유가 아니다(1인회사 허용). 해당하는 것은 ㄱ, ㄴ, ㄹ, ㅂ 4개.","c":"상","v":1},"공인회2024_59-30":{"w":"ㄱ: 액면미달 발행은 주주총회 특별결의로 최저발행가액을 정하고 법원의 인가를 받아야 한다(제417조). O\nㄴ: 이사는 발행조건과 미상각액을 주식청약서에 기재해야 한다(제420조). O\nㄷ: 액면미달 발행에 따른 변경등기에는 미상각액을 등기해야 한다. O\nㄹ: 액면미달 발행은 채권자보호절차를 요구하지 않는다. X\n옳은 것은 3개.","c":"중","v":1},"공인회2025_60-03":{"w":"5) 상호를 계속 쓰는 영업양수인이 책임지는 양도인의 영업으로 인한 채무에는 영업활동과 관련된 불법행위로 인한 손해배상채무도 들어간다(판례). 책임이 없다고 한 5번이 틀렸다.\n1) 속용 상호가 양도인 상호와 완전히 같지 않아도 주요 부분이 공통되면 상호속용이 인정된다(판례). 2) 양수인이 지체 없이 책임 없음을 등기하면 책임이 없다(제42조 제2항). 3) 양도인과 양수인이 지체 없이 제3자에게 그 뜻을 통지하면 통지받은 제3자에게 책임이 없다(제42조 제2항). 4) 양도인의 책임은 영업양도 후 2년이 지나면 소멸한다(제45조).","c":"상","v":1},"공인회2025_60-08":{"w":"ㄱ X: 대리상의 보상청구권은 계약이 종료한 날부터 6개월이 지나면 행사하지 못한다(제92조의2 제3항). 1년 소멸시효가 아니다.\nㄴ O: 운송인의 송하인·수하인에 대한 채권은 1년이다(제147조가 준용하는 제122조).\nㄷ O: 운송주선인의 위탁자·수하인에 대한 채권은 1년이다(제122조).\nㄹ O: 창고업자의 임치인·창고증권소지인에 대한 채권은 출고한 날부터 1년이다(제167조).\n5번이다.","c":"상","v":1},"공인회2025_60-15":{"w":"2) 주권의 불소지 신고는 정관에 이를 금지하는 정함이 없는 한 할 수 있다(제358조의2 제1항). 정관에 가능하다는 정함이 있는 경우에 한한다는 설명이 틀리다.\n1) 회사성립 전 발행 주권은 무효(제355조 제3항). O  3) 제권판결을 얻어야 재발행 청구. O  4) 이사회 승인 규정은 주권에 기재(제356조). O  5) 무효인 주권은 선의취득 불가. O","c":"상","v":1},"공인회2025_60-17":{"w":"4) 양도승인거부 통지를 받은 주주는 통지를 받은 날부터 20일 내에 회사에 양도 상대방의 지정 또는 그 주식의 매수를 청구할 수 있다(제335조의2 제4항). 상대방의 지정만 청구할 수 있다는 설명이 틀리다.\n1) 판례: 회사성립 후 6개월이 지나도록 주권을 발행하지 않으면 주권발행 전 양도도 회사에 효력. O  2) 주권발행 후 양도는 교부가 필요. O  3) 1개월 내 거부 통지가 없으면 승인 간주. O  5) 승인 없는 양도는 회사에 효력 없다. O","c":"상","v":1},"공인회2025_60-19":{"w":"2) 주주총회 소집통지는 2주 전에 각 주주에게 서면 또는 동의를 받은 전자문서로 '통지를 발송'하면 된다(제363조 제1항). '도달하여야 한다'는 설명이 틀리다.\n1) 이사회가 소집을 결정. O  3) 소집통지서에 회의의 목적사항 기재. O  4) 연 2회 이상 결산기를 정한 회사는 매기 소집. O  5) 주주명부에 기재된 주소로 통지. O","c":"상","v":1},"공인회2025_60-22":{"w":"주주총회결의취소소송에서는 법원이 결의의 내용, 회사 현황과 제반 사정을 참작해 청구를 기각할 수 있다고만 정하고(제379조) 하자 보완을 요건으로 명시하지 않는다.\n자본금감소무효, 신주발행무효, 합병무효, 분할무효의 소는 하자가 보완되고 회사의 현황·제반 사정을 고려해 무효 청구가 부당하다고 인정할 때 기각할 수 있다고 정한다(제446조, 제430조, 제240조, 제530조의11 등이 제189조를 준용).","c":"중","v":1},"공인회2025_60-26":{"w":"1) 이사의 제3자에 대한 손해배상책임(제401조)은 제3자가 입은 직접 손해에 대한 책임이어서 대표소송의 대상이 아니다.\n2) 발기인의 책임(제324조), 3) 이사 이름으로 업무를 집행한 자(제401조의2), 4) 통모인수인의 차액 지급의무(제424조의2), 5) 청산인의 책임(제542조 제2항)은 대표소송 대상이다.","c":"상","v":1},"공인회2025_60-33":{"w":"4) 합병무효 판결은 장래에 대해서만 효력이 있다(제240조, 제190조 단서). 판결 확정 전에 존속회사 또는 신설회사와 사원, 제3자 사이에 생긴 권리의무에는 영향을 미치지 않는다. 소급효가 있어 영향을 미친다는 설명이 틀리다.\n1) 합병계약서의 특별결의 승인. O  2) 모회사 주식은 합병 효력 발생 후 6개월 내 처분. O  3) 의결권 없는 주주도 매수청구권 행사 가능. O  5) 합병비율의 현저한 불공정은 무효 원인이 될 수 있다. O","c":"상","v":1},"공인회2025_60-37":{"w":"ㄱ O: 감사위원회가 없는 대형비상장주식회사는 감사인선임위원회의 승인을 받아 감사가 선정한 회계법인 또는 감사반을 감사인으로 선임한다(외부감사법 제10조 제4항 제1호 나목).\nㄴ X: 이런 사유가 있으면 연속하는 3개 사업연도 중이라도 매 사업연도 종료 후 3개월 이내에 해임요청된 감사인을 해임해야 한다(제13조 제2항). 즉시 해지하는 것이 아니다.\nㄷ X: 대형비상장주식회사는 동일한 이사에게 연속하는 4개 사업연도에 대한 감사업무를 하게 할 수 없다(제9조 제5항). 6개 사업연도는 그 밖의 회사 기준이다.\nㄹ O: 감사계약을 해지하거나 감사인을 해임하면 지체 없이 증권선물위원회에 보고해야 한다(제13조 제3항).\nㄱ, ㄹ로 2번이다.","c":"상","v":1},"공인회2026_61-03":{"w":"4) 주식회사의 영업 전부 양도는 주주총회 특별결의로 하며, 출석한 주주 의결권의 3분의 2 이상과 발행주식총수의 3분의 1 이상의 찬성이 필요하다(제374조, 제434조). O\n1) 영업양도인의 경업금지기간은 10년이다. X  2) 상호는 영업과 함께 양도하거나 영업을 폐지하는 경우에도 양도할 수 있다. X  3) 양수인이 단독 통지가 아니라 양도인과 양수인이 공동으로 통지해야 면책된다. X  5) 양도인의 책임은 영업양도 후 2년이 지나면 소멸한다. X","c":"상","v":1},"공인회2026_61-04":{"w":"2) 매수인의 수령 거부로 경매한 경우 그 대금을 공탁해야 하지만 그 전부나 일부를 매매대금에 충당할 수 있다(상법 제67조 제1항). 대금 전액을 공탁해야 한다는 설명이 틀리다.\n1) 멸실·훼손 염려가 있으면 최고 없이 경매 가능. O  3) 정기행위는 즉시 이행청구가 없으면 해제 간주(제68조). O  4), 5) 해제 후 보관·공탁 및 법원 허가 경매(제70조). O","c":"상","v":1},"공인회2026_61-11":{"w":"3) 액면주식의 분할은 정관의 1주 금액이 바뀌므로 정관 변경(주주총회 특별결의)이 필요하다. O\n1) 액면주식과 무액면주식은 서로 전환할 수 있다. X  2) 액면주식 1주의 금액은 분할할 때에도 100원 이상이어야 한다. X  4) 불소지 신고한 주식을 양도하려면 주권의 발행을 청구해 교부해야 한다. X  5) 액면·무액면 전환 시 공고·통지 기간은 1개월 이상이다. X","c":"상","v":1},"공인회2026_61-12":{"w":"3) 양도승인 거부 통지를 받은 주주는 통지를 받은 날부터 20일 내에 양도 상대방의 지정 또는 주식의 매수를 청구할 수 있다(제335조의2 제4항). 2주 내라는 설명이 틀리다.\n1) 정관에 따라 이사회 승인을 요구할 수 있다. O  2) 청구일부터 1개월 내 서면 통지. O  4) 이사회는 청구일부터 2주 내에 양도 상대방을 지정·통지(제335조의3). O  5) 주식 취득자의 승인 청구. O","c":"상","v":1},"공인회2026_61-29":{"w":"ㄱ: 회사가 특정 주주에게 무상으로 재산상 이익을 공여하면 주주의 권리행사와 관련하여 공여한 것으로 추정한다(제467조의2 제2항). O\nㄴ: 공여받은 자는 이익을 반환해야 하고, 대가를 지급한 것이 있으면 반환받을 수 있다(제3항). O\nㄷ: 주주의 권리에는 공익권뿐 아니라 이익배당청구권·신주인수권 같은 자익권도 포함된다. X\nㄹ: 유상 공여라도 회사가 얻은 이익이 공여한 이익에 비해 현저하게 적으면 추정한다(제2항). O","c":"상","v":1},"공인회2026_61-37":{"w":"ㄱ O: 외부감사법 제22조 제1항.\nㄴ O: 같은 조 제2항.\nㄷ O: 같은 조 제6항.\nㄹ X: 감사 또는 감사위원회는 외부전문가의 조사결과와 회사의 시정조치 결과 등을 즉시 증권선물위원회와 감사인에게 제출해야 한다(같은 조 제4항). 한국공인회계사회가 아니다.\nㄱ, ㄴ, ㄷ으로 3번이다.","c":"상","v":1},"공인회2017_52-02-5":{"w":"외관을 믿고 거래한 상대방을 보호하는 책임에서는 상대방의 악의나 중대한 과실을 책임을 면하려는 쪽이 증명해야 한다는 것이 판례다. 상대방이 자기의 선의·무중과실을 증명할 필요는 없다.","c":"중","v":1},"공인회2022_57-04-2":{"w":"판례는 농약판매업 등록명의를 빌려준 자에게도 상법 제24조의 명의대여자 책임을 인정했다. 행정법규상 명의대여가 금지되어 있어도 외관을 믿은 거래상대방 보호에는 영향이 없다.","c":"중","v":1},"공인회2022_57-04-3":{"w":"명의대여자 책임은 명의대여자를 영업주로 오인한 제3자를 보호하는 제도다(상법 제24조). 판례는 상대방이 명의대여 사실을 알았거나 모른 데 중대한 과실이 있으면 명의대여자가 책임을 지지 않는다고 본다.","c":"상","v":1},"공인회2022_57-04-5":{"w":"상법 제24조는 영업주로 오인하고 거래한 제3자를 보호하는 규정이므로 거래와 관계없는 명의차용자의 불법행위에는 적용되지 않는다는 것이 판례다.","c":"상","v":1},"공인회2025_60-02-4":{"w":"판례는 법인등기부에 이사로 등기되어 있으면 특별한 사정이 없는 한 정당한 절차로 선임된 적법한 이사로 추정한다. 등기의 추정력이 미치는 것이다.","c":"상","v":1},"공인회2022_57-04-1":{"w":"상법 제24조가 명의대여자에게 명의차용자와 연대하여 변제할 책임을 지운다. 보호받는 상대방은 명의대여자를 영업주로 오인하고 거래한 제3자다.","c":"상","v":1},"공인회2016_51-03-1":{"w":"상호 등기 자체는 개인 상인의 선택이지만 일단 등기한 사항이 변경되거나 소멸하면 당사자는 지체 없이 변경·소멸 등기를 해야 한다(상법 제40조).","c":"상","v":1},"공인회2023_58-03-1":{"w":"상법 제34조가 등기는 당사자 신청으로 영업소 소재지 관할 법원의 상업등기부에 한다고 정한다. 2024년 개정으로 회사의 영업소는 본점을 가리키는 것으로 정리되었다.","c":"상","v":1},"공인회2023_58-03-2":{"w":"상호는 영업을 폐지하거나 영업과 함께 하는 경우에만 양도할 수 있다(상법 제25조 제1항). 그 양도는 등기하지 않으면 제3자에게 대항하지 못한다(같은 조 제2항).","c":"상","v":1},"공인회2016_51-01-2":{"w":"구매부장은 영업의 특정 종류나 사항을 위임받은 부분적 포괄대리권을 가진 사용인이다. 그 대리권 제한은 상법 제15조 제2항이 준용하는 제11조 제3항에 따라 선의의 제3자에게 대항하지 못한다.","c":"상","v":1},"공인회2018_53-08-2":{"w":"지배인의 대리권은 영업주의 선임행위로 생기고 선임등기는 대항요건일 뿐 효력요건이 아니다(상법 제10조·제13조·제37조). 등기 전이라도 지배인이 한 영업상 거래는 영업주에게 효력이 있다.","c":"상","v":1},"공인회2020_55-01-1":{"w":"상법 제17조 제1항이 상업사용인에게 영업주 허락 없이 자기 또는 제3자의 계산으로 영업주의 영업부류에 속한 거래를 하지 못하도록 한다(경업금지).","c":"상","v":1},"공인회2020_55-01-2":{"w":"공동지배인을 정한 사항과 그 변경도 지배인 등기와 마찬가지로 등기해야 한다(상법 제12조 제1항, 제13조 후단).","c":"상","v":1},"공인회2020_55-01-4":{"w":"부분적 포괄대리권을 가진 사용인의 권한은 위임받은 사항에 관한 재판 외의 모든 행위다(상법 제15조 제1항). 재판상 행위는 지배인만 할 수 있다(제11조 제1항).","c":"상","v":1},"공인회2020_55-01-5":{"w":"상법 제15조 제2항이 지배인 대리권 제한에 관한 제11조 제3항을 준용하므로 부분적 포괄대리권의 제한도 선의의 제3자에게 대항하지 못한다.","c":"상","v":1},"공인회2023_58-02-5":{"w":"경업금지를 위반한 거래가 제3자의 계산으로 한 것이면 영업주는 사용인에게 그 이득의 양도를 청구할 수 있다(상법 제17조 제2항). 자기의 계산이면 영업주의 계산으로 한 것으로 볼 수 있다.","c":"상","v":1},"공인회2026_61-01-1":{"w":"표현지배인은 본점·지점의 지배인과 동일한 권한이 있는 것으로 보되 재판상 행위는 제외된다(상법 제14조 제1항). 상대방이 악의이면 적용되지 않는다(같은 조 제2항).","c":"상","v":1},"공인회2026_61-01-3":{"w":"상법 제17조 제1항은 거래 제한과 함께 영업주 허락 없이 회사의 무한책임사원, 이사, 다른 상인의 사용인이 되는 것도 금지한다(겸직금지).","c":"상","v":1},"공인회2026_61-01-4":{"w":"경업금지 위반은 사용인과 영업주 사이의 내부 의무 위반이어서 제3자와의 거래 자체는 유효하다. 영업주는 개입권, 계약 해지, 손해배상청구로 대응한다(상법 제17조 제2항·제3항).","c":"상","v":1},"공인회2026_61-01-5":{"w":"상법 제15조 제1항이 정한 부분적 포괄대리권의 범위다. 재판상 행위는 포함되지 않아 지배인 권한(제11조 제1항)보다 좁다.","c":"상","v":1},"공인회2024_59-02-1":{"w":"상법 제17조 제1항의 경업금지의무다. 영업주의 허락이 있으면 거래할 수 있다.","c":"상","v":1},"공인회2024_59-02-2":{"w":"자기의 계산으로 한 위반 거래에 대해 영업주가 행사하는 개입권이다(상법 제17조 제2항 전단). 거래 상대방과의 관계에서 거래 당사자가 바뀌는 것은 아니고 경제적 효과를 영업주에게 돌리는 것이다.","c":"상","v":1},"공인회2024_59-02-3":{"w":"제3자의 계산으로 한 위반 거래에서는 영업주가 사용인에게 이득의 양도를 청구한다(상법 제17조 제2항 후단).","c":"상","v":1},"공인회2024_59-02-5":{"w":"상법 제17조 제4항이 개입권(이득양도청구권 포함)의 제척기간을 안 날부터 2주, 거래가 있은 날부터 1년으로 정한다.","c":"상","v":1},"공인회2022_57-01-1":{"w":"상법 제9조가 지배인, 상호, 상업장부, 상업등기에 관한 규정을 소상인에게 적용하지 않는다고 정한다.","c":"상","v":1},"공인회2022_57-01-2":{"w":"상법 제30조 제1항이 회계장부의 기재사항을 이렇게 정한다. 대차대조표는 회계장부에 의하여 작성한다(같은 조 제2항).","c":"상","v":1},"공인회2022_57-01-4":{"w":"상법 제32조에 따라 법원은 신청 또는 직권으로 소송당사자에게 상업장부나 그 일부의 제출을 명할 수 있다.","c":"상","v":1},"공인회2022_57-01-5":{"w":"상법 제33조 제1항 단서가 전표 등은 5년간 보존하도록 정한다. 상업장부와 영업에 관한 중요서류는 10년이다.","c":"상","v":1},"공인회2026_61-05-3":{"w":"상법 제8조 제1항이 법정대리인이 미성년자, 피한정후견인 또는 피성년후견인을 위하여 영업을 하는 때에는 등기하도록 정한다.","c":"상","v":1},"공인회2025_60-01-5":{"w":"판례는 새마을금고가 회원에게 자금을 대출하는 것을 상호 유대를 가진 회원의 경제적 지위 향상을 위한 사업으로 보아 새마을금고를 상인으로 보지 않는다.","c":"상","v":1},"공인회2019_54-02-1":{"w":"자기 명의로 상행위를 하는 자가 상인이고(상법 제4조), 여기의 상행위는 영업으로 하는 제46조의 기본적 상행위다. 이런 상인을 당연상인이라 한다.","c":"상","v":1},"공인회2019_54-02-2":{"w":"상법 제5조 제2항이 회사는 상행위를 하지 않더라도 상인으로 본다고 정한다(의제상인).","c":"상","v":1},"공인회2019_54-02-3":{"w":"소상인은 자본금액 1천만원 미만의 상인으로서 회사가 아닌 자이고(상법 시행령 제2조), 소상인에게는 지배인·상호·상업장부·상업등기 규정을 적용하지 않는다(상법 제9조).","c":"상","v":1},"공인회2019_54-02-5":{"w":"상법 제17조 제2항이 개입권을, 같은 조 제3항이 개입권 행사가 계약 해지나 손해배상청구에 영향을 미치지 않는다고 정한다. 두 구제를 함께 쓸 수 있다.","c":"상","v":1},"공인회2017_52-05-4":{"w":"판례는 농업협동조합이 조합원의 생산물자 판매사업을 하더라도 조합원의 이익을 위한 것이고 영리를 목적으로 하지 않으므로 상인이 아니라고 본다.","c":"상","v":1},"공인회2018_53-05-3":{"w":"상법 제21조 제1항이 상호단일의 원칙을, 제2항이 지점 상호에 본점과의 종속관계를 표시하도록 정한다.","c":"상","v":1},"공인회2020_55-02-1":{"w":"상법 제18조의 상호선정 자유다. 다만 회사는 종류에 따른 문자를 써야 하고(제19조) 회사 아닌 자는 회사 문자를 쓰지 못한다(제20조).","c":"상","v":1},"공인회2020_55-02-3":{"w":"상법 제23조 제1항이 부정한 목적의 오인 상호 사용을 금지한다. 위반하면 손해를 받을 염려가 있는 자나 상호 등기자가 폐지를 청구할 수 있다(같은 조 제2항).","c":"상","v":1},"공인회2020_55-02-4":{"w":"상법 제25조 제2항이 상호의 양도는 등기하지 않으면 제3자에게 대항하지 못한다고 정한다.","c":"상","v":1},"공인회2020_55-02-5":{"w":"상법 제27조가 상호를 변경·폐지한 뒤 2주 안에 등기한 자가 변경·폐지 등기를 하지 않으면 이해관계인이 말소를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-02-1":{"w":"상법 제23조 제1항의 부정한 목적의 오인 상호 사용 금지다. 동일 시·군에서 동종영업으로 타인의 등기 상호를 쓰면 부정한 목적이 추정된다(같은 조 제4항).","c":"상","v":1},"공인회2026_61-02-3":{"w":"상법 제22조의2 제2항은 모든 회사가 상호·목적 변경 때 본점 소재지 관할 등기소에 상호 가등기를 신청할 수 있게 한다.","c":"상","v":1},"공인회2026_61-02-4":{"w":"상법 제22조의2 제3항에 따라 회사는 본점을 이전하려 할 때 이전할 곳의 관할 등기소에 상호 가등기를 신청할 수 있다.","c":"상","v":1},"공인회2026_61-02-5":{"w":"상법 제27조의 상호등기 말소청구다. 변경·폐지 후 2주 안에 등기가 없으면 이해관계인이 청구한다.","c":"상","v":1},"공인회2018_53-06-2":{"w":"상호·목적 변경 때의 가등기는 회사 종류를 가리지 않고 할 수 있다(상법 제22조의2 제2항). 설립 때의 가등기만 유한책임회사·주식회사·유한회사로 한정된다(제1항).","c":"상","v":1},"공인회2018_53-06-3":{"w":"상법 제22조의2 제3항에 따라 회사는 본점 이전 예정지의 관할 등기소에 상호 가등기를 신청할 수 있다.","c":"상","v":1},"공인회2018_53-06-4":{"w":"상법 제22조의2는 가등기 신청 주체를 설립 중이거나 기존의 회사로 한정하므로 개인 상인은 상호를 가등기할 수 없다.","c":"상","v":1},"공인회2018_53-06-5":{"w":"상호 가등기는 제22조의 적용에서 상호 등기로 보므로(상법 제22조의2 제4항) 가등기한 상호도 동일 시·군에서 동종영업의 상호로 등기하지 못한다(제22조).","c":"상","v":1},"공인회2017_52-06-1":{"w":"상법 제11조 제1항이 정한 지배인의 포괄적 대리권이다. 재판상 행위까지 포함하는 점에서 부분적 포괄대리권 사용인과 다르다.","c":"상","v":1},"공인회2017_52-06-3":{"w":"상법 제11조 제3항이 지배인 대리권에 대한 제한은 선의의 제3자에게 대항하지 못한다고 정한다.","c":"상","v":1},"공인회2017_52-06-4":{"w":"판례는 어음행위에서 대리권 제한에 대항할 수 있는지 문제 되는 제3자에 지배인과 직접 어음행위를 한 상대방뿐 아니라 그로부터 어음을 다시 배서·양도받은 제3취득자도 포함된다고 본다.","c":"상","v":1},"공인회2017_52-06-5":{"w":"상법 제17조 제1항의 경업금지와 겸직금지는 지배인을 포함한 상업사용인 모두에게 적용된다.","c":"상","v":1},"공인회2021_56-01-1":{"w":"지배인은 지배인이 아닌 점원 기타 사용인을 선임·해임할 수 있고(상법 제11조 제2항), 부분적 포괄대리권을 가진 사용인도 여기에 포함된다. 지배인을 선임·해임할 권한은 없다.","c":"상","v":1},"공인회2021_56-01-2":{"w":"상법 제17조 제1항이 상업사용인의 겸직을 금지하므로 지배인은 영업주 허락 없이 다른 상인의 사용인이 되지 못한다.","c":"상","v":1},"공인회2021_56-01-3":{"w":"상법 제9조가 지배인에 관한 규정을 소상인에게 적용하지 않는다고 정한다.","c":"상","v":1},"공인회2024_59-01-1":{"w":"상법 제11조 제2항에 따른 권한이다. 지배인이 다른 지배인을 선임·해임할 수는 없다.","c":"상","v":1},"공인회2024_59-01-2":{"w":"판례는 지배인의 행위가 영업에 관한 것인지를 행위 당시 지배인의 주관적 의사와 관계없이 행위의 객관적 성질에 따라 추상적으로 판단한다. 지배인이 개인적 목적으로 한 행위도 객관적으로 영업에 관한 것이면 대리권 범위에 든다.","c":"상","v":1},"공인회2024_59-01-3":{"w":"상법 제11조 제3항이 정한 내용이다. 악의의 제3자에게는 대항할 수 있다.","c":"상","v":1},"공인회2024_59-01-4":{"w":"상법 제14조 제1항 본문이 표현지배인을 지배인과 동일한 권한이 있는 것으로 보고 단서가 재판상 행위를 제외한다.","c":"상","v":1},"공인회2019_54-01-2":{"w":"상사 이자, 보수청구권, 상사 법정이율 같은 영리성 보장 제도는 기업이 수익을 내어 존속하고 커질 수 있게 하는 장치다.","c":"중","v":1},"공인회2019_54-01-3":{"w":"상업등기·공고 같은 공시제도와 표현지배인·명의대여자 책임·부실등기 책임 같은 외관주의 규정(상법 제14조·제24조·제39조)은 거래 상대방의 신뢰를 보호해 거래안전에 기여한다.","c":"중","v":1},"공인회2019_54-01-4":{"w":"자본시장법과 채무자회생법은 상사에 관한 특별법이어서 같은 사항에 대해 일반법인 상법보다 먼저 적용된다.","c":"중","v":1},"공인회2019_54-01-5":{"w":"영업양도는 영업을 해체하지 않고 통째로 넘기게 하고 합병·분할은 청산 없이 회사를 결합·재편하게 한다. 모두 기업 유지 이념에서 나온 제도다.","c":"중","v":1},"공인회2017_52-01-4":{"w":"판례는 새마을금고가 상인이 아니라도 상인인 회원이 영업자금으로 빌린 대출은 회원에게 보조적 상행위(상법 제47조)가 된다고 본다. 일방적 상행위에도 상법이 적용되므로(제3조) 대출금채권에는 5년의 상사시효(제64조)가 적용된다.","c":"상","v":1},"공인회2017_52-03-1":{"w":"영업양수인이 양도인의 상호를 계속 사용하면 양도인의 영업으로 인한 제3자의 채권에 대해 양수인도 변제할 책임이 있다(상법 제42조 제1항).","c":"상","v":1},"공인회2017_52-03-2":{"w":"양도인과 양수인이 지체 없이 제3자에게 양수인이 책임지지 않는다는 뜻을 통지하면 그 통지를 받은 제3자에게는 양수인의 책임이 생기지 않는다(상법 제42조 제2항 후단).","c":"상","v":1},"공인회2017_52-03-3":{"w":"양수인이 영업양도를 받은 뒤 지체 없이 양도인의 채무에 대한 책임이 없음을 등기하면 제42조 제1항의 책임을 지지 않는다(상법 제42조 제2항 전단).","c":"상","v":1},"공인회2017_52-03-4":{"w":"판례는 상호속용 양수인이 책임지는 양도인의 영업으로 인한 채무에 거래상 채무뿐 아니라 영업활동과 관련된 불법행위로 인한 손해배상채무도 포함된다고 본다(상법 제42조 제1항).","c":"상","v":1},"공인회2023_58-18-1":{"w":"상법 제374조의2 제1항은 반대주주에 의결권이 없거나 제한되는 주주를 포함한다고 명시한다.","c":"상","v":1},"공인회2023_58-18-2":{"w":"판례는 주식매수청구권을 형성권으로 보아 주주가 행사하면 회사의 승낙 없이 회사와 주주 사이에 주식 매매계약이 성립한다고 본다. 회사가 매수기간(2개월) 안에 지급할 의무는 그 매매대금 지급의무다(상법 제374조의2 제2항).","c":"상","v":1},"공인회2023_58-18-4":{"w":"매수가액은 먼저 주주와 회사의 협의로 정한다. 매수청구기간 종료일부터 30일 안에 협의가 안 되면 회사나 매수청구 주주가 법원에 결정을 청구한다(상법 제374조의2 제3항·제4항).","c":"상","v":1},"공인회2023_58-18-5":{"w":"매수청구로 회사가 취득한 주식은 자기주식이다. 자기주식 처분에 관한 사항 중 정관에 규정이 없는 것은 이사회가 결정한다(상법 제342조).","c":"상","v":1},"공인회2018_53-07-1":{"w":"영업양도는 영업의 동일성을 유지하며 영업재산을 이전하는 계약이다. 양수인은 양수로 상인이 되면 충분하고 양수 전부터 상인일 필요는 없다.","c":"중","v":1},"공인회2018_53-07-2":{"w":"영업양도로 영업에 관한 채무가 당연히 넘어가지는 않고 채무인수 절차가 따로 있어야 한다. 그래서 상법은 상호속용(제42조)이나 채무인수 광고(제44조)가 있을 때만 양수인에게 변제책임을 지운다.","c":"상","v":1},"공인회2018_53-07-4":{"w":"상법 제43조가 상호속용 양수인에게 선의·무중과실로 변제한 채무자의 변제를 유효로 한다.","c":"상","v":1},"공인회2018_53-07-5":{"w":"판례는 영업양도로 영업의 동일성이 유지되면 반대 특약이 없는 한 근로관계도 원칙적으로 포괄 승계된다고 본다. 근로자가 승계를 거부하면 양도인과의 근로관계가 유지될 수 있다.","c":"상","v":1},"공인회2021_56-02-3":{"w":"상호를 속용하지 않는 양수인도 양도인의 영업상 채무를 인수한다고 광고하면 변제책임이 있다(상법 제44조).","c":"상","v":1},"공인회2024_59-03-2":{"w":"상법 제44조의 채무인수 광고 책임이다. 양수인의 책임이 생기면 양도인의 채무는 광고 후 2년이 지나면 소멸한다(제45조).","c":"상","v":1},"공인회2024_59-03-3":{"w":"상법 제43조가 상호속용 양수인에게 한 선의·무중과실 변제를 유효로 정한다. 채권 자체는 양도되지 않았더라도 외관을 믿은 채무자를 보호하는 것이다.","c":"상","v":1},"공인회2024_59-03-4":{"w":"상법 제45조가 양수인이 제42조 제1항이나 제44조로 책임지는 경우 양도인의 제3자에 대한 채무는 영업양도 또는 광고 후 2년이 지나면 소멸한다고 정한다.","c":"상","v":1},"공인회2024_59-03-5":{"w":"상법 제41조 제2항이 경업금지 약정의 효력을 동일·인접 특별시·광역시·시·군에서 20년 이내로 제한한다. 약정이 없으면 같은 지역에서 10년이다(제1항).","c":"상","v":1},"공인회2019_54-16-5":{"w":"상대방이 발행주식총수의 90% 이상을 가져 주주총회 승인을 생략하는 간이영업양도에서도 공고·통지 후 2주 안에 반대 의사를 통지한 주주는 주식매수를 청구할 수 있다(상법 제374조의3 제1항·제3항).","c":"상","v":1},"공인회2016_51-04-1":{"w":"당구장은 공중이 이용하는 시설에 의한 거래를 하는 영업이어서 공중접객업에 해당한다(상법 제46조 제9호, 제151조).","c":"상","v":1},"공인회2016_51-04-2":{"w":"판례는 영업을 위한 준비행위를 한 때 상인 자격을 취득하고 그 준비행위가 보조적 상행위가 된다고 본다. 개업을 위한 점포 임대차는 영업 목적이 객관적으로 드러나는 준비행위다(상법 제47조).","c":"상","v":1},"공인회2016_51-04-3":{"w":"영업을 위하여 하는 행위는 상행위로 보므로(상법 제47조 제1항) 영업에 쓸 점포를 넓히는 공사계약도 보조적 상행위다.","c":"상","v":1},"공인회2016_51-04-5":{"w":"자본금 500만원의 개인 상인은 소상인이고(상법 시행령 제2조, 1천만원 미만), 소상인에게는 지배인 규정이 적용되지 않는다(상법 제9조).","c":"상","v":1},"공인회2016_51-07-1":{"w":"상법 제69조 제1항은 상인간의 매매에 적용된다고 규정하므로 한쪽만 상인인 매매에는 적용되지 않는다.","c":"상","v":1},"공인회2016_51-07-2":{"w":"판례는 특정 주문자의 수요에 맞춰 대체할 수 없는 물건을 제작·공급하는 계약은 도급의 성질이 강해 상법 제69조가 적용되지 않는다고 본다.","c":"상","v":1},"공인회2016_51-07-4":{"w":"검사·통지의무는 위반해도 손해배상 같은 책임이 생기지 않는 간접의무다. 위반하면 계약해제, 대금감액, 손해배상 같은 하자담보 권리를 잃을 뿐이고(상법 제69조 제1항), 매도인이 악의이면 그마저도 잃지 않는다(제2항).","c":"상","v":1},"공인회2016_51-07-5":{"w":"판례는 상법 제69조 제1항이 매도인 보호를 위한 임의규정이어서 당사자가 특약으로 적용을 배제할 수 있다고 본다.","c":"상","v":1},"공인회2022_57-03-1":{"w":"상법 제58조 단서가 당사자 사이에 다른 약정이 있으면 일반상사유치권이 생기지 않는다고 정한다.","c":"상","v":1},"공인회2022_57-03-2":{"w":"상법 제58조는 유치 대상을 채무자 소유의 물건 또는 유가증권으로 정한다. 대리상·운송주선인 등의 특별상사유치권은 채무자 소유를 요구하지 않는다.","c":"상","v":1},"공인회2022_57-03-4":{"w":"상법 제120조가 운송주선인의 유치권을 그 운송물에 관한 보수, 운임, 체당금, 선대금 채권으로 한정한다. 채권과 유치물 사이의 개별적 견련성이 필요하다.","c":"상","v":1},"공인회2022_57-03-5":{"w":"상법 제91조가 대리상의 유치권을 정한다. 거래의 대리 또는 중개로 인한 채권이면 되고 본인을 위하여 점유하는 물건이면 본인 소유가 아니어도 된다.","c":"상","v":1},"공인회2023_58-05-1":{"w":"상법 제48조 본문이 민법의 현명주의(민법 제115조)에 대한 특칙으로 비현명 상사대리도 본인에게 효력이 있다고 정한다. 단서는 본인을 위한 것임을 모른 상대방이 대리인에게도 이행을 청구할 수 있게 한다.","c":"상","v":1},"공인회2023_58-05-3":{"w":"상법 제53조가 상시 거래관계에 있는 자로부터 영업부류에 속한 청약을 받은 상인에게 낙부통지의무를 지운다. 통지를 게을리하면 승낙한 것으로 본다.","c":"상","v":1},"공인회2023_58-05-4":{"w":"상법 제57조 제2항에 따라 보증이 상행위이거나 주채무가 상행위로 인한 것이면 주채무자와 보증인은 연대책임을 진다. 보증인에게 최고·검색의 항변권이 없다.","c":"상","v":1},"공인회2023_58-05-5":{"w":"상법 제62조가 무상임치라도 영업범위 내에서 임치를 받은 상인에게 선관주의의무를 지운다. 민법상 무상수치인은 자기 재산과 동일한 주의만 하면 된다(민법 제695조).","c":"상","v":1},"공인회2020_55-05-1":{"w":"상법 제67조 제1항이 상인간 매매에서 매수인이 수령을 거부하거나 수령할 수 없을 때 매도인에게 공탁권과 최고 후 경매권을 준다.","c":"상","v":1},"공인회2020_55-05-2":{"w":"상법 제67조 제1항 후단이 공탁하거나 경매한 매도인은 지체 없이 매수인에게 그 통지를 발송하도록 정한다.","c":"상","v":1},"공인회2020_55-05-4":{"w":"상법 제68조가 상인간 확정기매매에서 상대방이 이행기 경과 후 즉시 이행을 청구하지 않으면 계약을 해제한 것으로 본다고 정한다. 해제의 의사표시가 필요 없다.","c":"상","v":1},"공인회2020_55-05-5":{"w":"상법 제67조 제2항이 매수인에게 최고할 수 없거나 목적물이 멸실·훼손될 염려가 있으면 최고 없이 경매할 수 있게 한다.","c":"상","v":1},"공인회2024_59-04-1":{"w":"상법 제68조가 상인간 확정기매매에서 이행시기가 지나면 상대방이 즉시 이행을 청구하지 않는 한 계약을 해제한 것으로 본다고 정한다. 곧바로 이행을 청구하면 해제 의제가 생기지 않는다.","c":"상","v":1},"공인회2024_59-04-2":{"w":"상법 제67조 제1항 후단에 따라 공탁 또는 경매를 한 매도인은 지체 없이 매수인에게 통지를 발송해야 한다.","c":"상","v":1},"공인회2024_59-04-3":{"w":"판례는 부대체물 제작공급계약은 도급의 성질을 가져 상법 제69조의 검사·하자통지의무가 적용되지 않는다고 본다.","c":"상","v":1},"공인회2024_59-04-4":{"w":"상법 제69조 제1항 후단이 즉시 발견할 수 없는 하자도 수령 후 6월 내에 발견해 즉시 통지를 발송하지 않으면 이로 인한 계약해제, 대금감액, 손해배상을 청구하지 못한다고 정한다.","c":"상","v":1},"공인회2018_53-02-1":{"w":"상법 제48조 본문에 따라 비현명 상사대리도 본인에게 효력이 있다. 단서에 따라 본인을 위한 것임을 모른 상대방은 대리인에게도 이행을 청구할 수 있다.","c":"상","v":1},"공인회2018_53-02-2":{"w":"판례는 차주인 회원이 상인이면 영업자금 대출이 차주에게 보조적 상행위가 되어 대출금채권이 상사채권이 되고 5년의 상사시효가 적용된다고 본다(상법 제3조·제47조·제64조).","c":"상","v":1},"공인회2018_53-02-3":{"w":"상법 제56조가 채권자의 지점 거래로 인한 채무는 이행장소가 특정되지 않으면 특정물 인도 외에는 그 지점을 이행장소로 본다고 정한다.","c":"상","v":1},"공인회2018_53-02-5":{"w":"상법 제68조의 확정기매매 해제 의제다. 상대방이 즉시 이행을 청구하지 않으면 계약을 해제한 것으로 본다.","c":"상","v":1},"공인회2020_55-08-1":{"w":"상법 제49조가 상행위의 위임을 받은 자에게 위임의 본지에 반하지 않는 범위에서 위임받지 않은 행위도 할 수 있게 한다.","c":"상","v":1},"공인회2020_55-08-2":{"w":"상법 제58조의 일반상사유치권이다. 피담보채권과 유치물 사이의 개별적 견련성은 필요 없고 다른 약정이 있으면 배제된다.","c":"상","v":1},"공인회2020_55-08-3":{"w":"상법 제57조 제1항이 수인이 그 1인 또는 전원에게 상행위가 되는 행위로 채무를 부담하면 연대책임을 지운다. 민법의 분할채무 원칙(민법 제408조)에 대한 특칙이다.","c":"상","v":1},"공인회2020_55-08-4":{"w":"상법 제61조가 상인이 영업범위 내에서 타인을 위하여 한 행위에 대해 약정이 없어도 상당한 보수를 청구할 수 있게 한다.","c":"상","v":1},"공인회2021_56-07-5":{"w":"상호부금 기타 이와 유사한 행위는 영업으로 하면 기본적 상행위다(상법 제46조 제16호). 임금을 받을 목적의 제조·노무는 제46조 단서로 제외된다.","c":"상","v":1},"공인회2022_57-02-1":{"w":"상법 제51조가 대화자 간 계약의 청약은 상대방이 즉시 승낙하지 않으면 효력을 잃는다고 정한다.","c":"상","v":1},"공인회2022_57-02-2":{"w":"상법 제53조가 상시 거래관계에 있는 자의 영업부류 청약을 받은 상인에게 지체 없는 낙부통지 발송의무를 지우고 이를 게을리하면 승낙한 것으로 본다. 민법상 청약에 대한 침묵은 승낙이 아니라는 원칙의 특칙이다.","c":"상","v":1},"공인회2022_57-02-3":{"w":"상법 제55조 제1항에 따라 상인이 영업에 관해 금전을 대여하면 약정이 없어도 법정이자를 청구할 수 있다. 상사 법정이율은 연 6%다(제54조).","c":"상","v":1},"공인회2022_57-02-5":{"w":"상법 제57조 제2항은 주채무가 상행위로 인한 것이거나 보증이 상행위인 경우 주채무자와 보증인의 연대책임을 정한다.","c":"상","v":1},"공인회2019_54-05-1":{"w":"상법 제48조 본문이 민법의 현명주의에 대한 특칙으로 비현명 상사대리의 효력을 본인에게 미치게 한다.","c":"상","v":1},"공인회2019_54-05-2":{"w":"상법 제64조가 상행위로 인한 채권의 소멸시효를 5년으로 정한다. 다른 법령에 더 짧은 시효가 있으면 그에 따른다(같은 조 단서).","c":"상","v":1},"공인회2019_54-05-4":{"w":"상인의 영업상 금전 대여에는 법정이자 청구권이 있고(상법 제55조 제1항), 상행위로 인한 채무의 법정이율은 연 6분이다(제54조).","c":"상","v":1},"공인회2019_54-05-5":{"w":"상법 제62조가 영업범위 내 무상임치를 받은 상인에게도 선량한 관리자의 주의의무를 지운다.","c":"상","v":1},"공인회2016_51-05-1":{"w":"상법 제72조가 상호계산을 상인 간 또는 상인과 비상인 간의 상시 거래관계에서 할 수 있다고 정한다. 한쪽은 상인이어야 한다.","c":"상","v":1},"공인회2016_51-05-2":{"w":"상법 제77조가 각 당사자의 언제든 해지권과 해지 시 즉시 계산 폐쇄 및 잔액 지급청구를 정한다.","c":"상","v":1},"공인회2016_51-05-3":{"w":"상법 제76조 제1항이 잔액채권에 대해 계산폐쇄일 이후의 법정이자를 청구할 수 있게 한다. 이자에 이자가 붙는 결과가 되어 민법상 중리 제한의 예외다.","c":"상","v":1},"공인회2016_51-05-4":{"w":"계산서를 승인하면 각 항목에 이의를 하지 못하지만 착오나 탈루가 있으면 예외다(상법 제75조).","c":"상","v":1},"공인회2019_54-04-5":{"w":"상법 제75조 본문이 계산서 승인 후 각 항목에 대한 이의를 막는다. 착오나 탈루가 있으면 단서에 따라 이의할 수 있다.","c":"상","v":1},"공인회2025_60-04-1":{"w":"상법 제72조가 상호계산은 상인 간 또는 상인과 비상인 간 상시 거래관계에서 일정 기간 채권채무 총액을 상계하고 잔액을 지급하기로 약정함으로써 효력이 생긴다고 정한다. 한쪽은 상인이어야 한다.","c":"상","v":1},"공인회2025_60-04-2":{"w":"상법 제74조가 상계 기간을 정하지 않으면 6월로 한다고 정한다.","c":"상","v":1},"공인회2025_60-04-3":{"w":"상법 제73조가 어음 등 상업증권상 채권채무를 계입했는데 증권채무자가 변제하지 않으면 그 항목을 상호계산에서 제거할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-04-5":{"w":"상법 제76조 제1항이 계산폐쇄일 이후 잔액에 대한 법정이자를, 제2항이 계입일부터 이자를 붙이는 약정을 허용한다.","c":"상","v":1},"공인회2017_52-08-1":{"w":"상법 제58조 본문의 일반상사유치권이다. 유치물은 채무자 소유의 물건 또는 유가증권이어야 하고 채권자의 점유는 채무자에 대한 상행위로 취득한 것이어야 한다.","c":"상","v":1},"공인회2017_52-08-3":{"w":"상법 제91조의 대리상 유치권이다. 본인을 위하여 점유하는 물건이면 본인 소유일 필요가 없다.","c":"상","v":1},"공인회2017_52-08-4":{"w":"상법 제120조가 운송주선인의 유치권을 해당 운송물에 관한 보수·운임·체당금·선대금 채권으로 한정한다.","c":"상","v":1},"공인회2017_52-08-5":{"w":"상법 제147조가 운송주선인의 유치권에 관한 제120조를 운송인에 준용하므로 운송인도 그 운송물에 관한 채권에 대해서만 유치할 수 있다.","c":"상","v":1},"공인회2021_56-08-2":{"w":"상법 제81조가 익명조합원이 자기 성명이나 상호를 영업자의 상호로 사용하도록 허락하면 그 사용 이후의 채무에 대해 영업자와 연대책임을 지운다.","c":"상","v":1},"공인회2021_56-08-3":{"w":"상법 제85조가 계약 종료 시 출자가액 반환을 원칙으로 하되 손실로 출자가 감소했으면 그 잔액만 반환하면 된다고 정한다.","c":"상","v":1},"공인회2021_56-08-4":{"w":"상법 제83조 제2항이 존속기간 약정과 관계없이 부득이한 사정이 있으면 언제든지 해지할 수 있게 한다.","c":"상","v":1},"공인회2021_56-08-5":{"w":"상법 제84조 제3호가 영업자 또는 익명조합원의 파산을 계약 종료 사유로 정한다.","c":"상","v":1},"공인회2026_61-08-4":{"w":"상법 제82조 제1항이 손실로 감소한 출자를 전보하기 전에는 이익배당을 청구하지 못한다고 정한다. 다른 약정이 있으면 따르지 않을 수 있다(제3항).","c":"상","v":1},"공인회2017_52-07-1":{"w":"고가물은 종류와 가액을 명시해야 운송인이 책임지고(상법 제136조), 일부 멸실의 배상액은 인도한 날의 도착지 가격으로 정한다(제137조 제2항). 명시가액은 배상의 상한으로 작용한다는 것이 통설이다.","c":"중","v":1},"공인회2019_54-08-1":{"w":"상법 제91조의 대리상 유치권은 거래의 대리 또는 중개로 인한 채권을 담보한다. 유치물은 본인을 위하여 점유하는 물건이면 되고 본인 소유일 필요가 없다. 다른 약정이 있으면 배제된다(같은 조 단서).","c":"상","v":1},"공인회2019_54-08-2":{"w":"상법 제90조가 물건 판매나 그 중개의 위탁을 받은 대리상에게 하자, 수량부족, 기타 매매 이행에 관한 통지를 받을 권한을 준다. 중개대리상도 포함된다.","c":"상","v":1},"공인회2019_54-08-3":{"w":"상법 제92조의2 제2항이 보상금액 상한을 계약 종료 전 5년간의 평균연보수액으로 정한다. 계약기간이 5년 미만이면 그 기간의 평균연보수액이 기준이다.","c":"상","v":1},"공인회2019_54-08-4":{"w":"상법 제89조 제1항이 대리상의 경업금지를 정한다. 겸직 제한은 동종영업을 목적으로 하는 회사의 무한책임사원·이사로 한정되어 상업사용인(제17조)보다 좁다.","c":"상","v":1},"공인회2016_51-02-1":{"w":"상법 제168조의7 제1항이 가맹업자의 지원의무를 정한다.","c":"상","v":1},"공인회2016_51-02-3":{"w":"상법 제168조의8 제2항이 가맹상의 계약 종료 후 영업비밀 준수의무를 정한다.","c":"상","v":1},"공인회2016_51-02-4":{"w":"상법 제168조의7 제2항이 다른 약정이 없으면 가맹업자가 가맹상의 영업지역에서 동일·유사 업종의 영업이나 가맹계약을 하지 못하게 한다.","c":"상","v":1},"공인회2016_51-02-5":{"w":"상법 제168조의10이 존속기간 약정 유무와 관계없이 부득이한 사정이 있으면 상당한 기간을 정해 예고한 후 해지할 수 있게 한다.","c":"상","v":1},"공인회2023_58-08-2":{"w":"상법 제168조의8 제2항에 따라 가맹상은 계약 종료 후에도 가맹업자의 영업비밀을 지켜야 한다.","c":"상","v":1},"공인회2023_58-08-3":{"w":"상법 제168조의3 제3항이 금융리스물건수령증을 발급하면 적합한 물건이 수령된 것으로 추정한다고 정한다. 반증으로 뒤집을 수 있다.","c":"상","v":1},"공인회2023_58-08-4":{"w":"상법 제168조의9 제1항이 가맹업자의 동의를 받아 영업을 양도할 수 있게 한다. 가맹업자는 특별한 사유가 없으면 동의해야 한다(같은 조 제2항).","c":"상","v":1},"공인회2023_58-08-5":{"w":"상법 제168조의12 본문이 채권매입업자의 상환청구권을 정한다. 채권매입계약에서 다르게 정하면 상환청구를 할 수 없다(같은 조 단서).","c":"상","v":1},"공인회2016_51-08-2":{"w":"상법 제397조 제3항이 이사 경업에 대한 회사의 개입권은 거래가 있은 날부터 1년이 지나면 소멸한다고 정한다. 상업사용인과 달리 안 날부터 2주의 기간은 없다.","c":"상","v":1},"공인회2020_55-07-1":{"w":"상법 제151조가 공중접객업자를 이렇게 정의한다.","c":"상","v":1},"공인회2020_55-07-2":{"w":"상법 제152조 제1항이 임치받은 물건에 대해 공중접객업자에게 무과실 증명책임을 지운다.","c":"상","v":1},"공인회2020_55-07-3":{"w":"상법 제152조 제2항이 임치받지 않은 휴대물도 공중접객업자나 사용인의 과실로 멸실·훼손되면 배상책임을 지운다. 이때 과실은 고객이 증명한다.","c":"상","v":1},"공인회2020_55-07-5":{"w":"상법 제153조가 화폐, 유가증권, 그 밖의 고가물은 고객이 종류와 가액을 명시하여 임치하지 않으면 공중접객업자가 책임지지 않는다고 정한다.","c":"상","v":1},"공인회2025_60-07-1":{"w":"상법 제152조 제1항의 임치물 책임이다. 주의를 게을리하지 않았다는 증명책임이 공중접객업자에게 있다.","c":"상","v":1},"공인회2025_60-07-2":{"w":"상법 제152조 제2항의 휴대물 책임이다. 책임이 없음을 알려도 면책되지 않는다(같은 조 제3항).","c":"상","v":1},"공인회2025_60-07-4":{"w":"상법 제153조가 화폐, 유가증권, 그 밖의 고가물은 고객이 종류와 가액을 명시하여 임치하지 않으면 공중접객업자가 멸실·훼손 손해를 배상하지 않는다고 정한다.","c":"상","v":1},"공인회2025_60-07-5":{"w":"공중접객업자 책임의 시효는 6개월이고(상법 제154조 제1항), 물건이 전부 멸실되면 고객이 시설에서 퇴거한 날부터 기산한다(같은 조 제2항).","c":"상","v":1},"공인회2022_57-08-1":{"w":"상법 제168조의3 제1항이 금융리스업자에게 적합한 물건을 약정 시기에 수령할 수 있도록 할 의무를 지운다.","c":"상","v":1},"공인회2026_61-06-2":{"w":"상법 제168조의3 제4항이 수령 이후 금융리스이용자에게 선관주의에 따른 유지·관리의무를 지운다.","c":"상","v":1},"공인회2026_61-06-3":{"w":"상법 제168조의4 제2항이 금융리스이용자에게 공급자에 대한 직접 손해배상청구권과 적합물 인도청구권을 준다. 금융리스업자는 그 권리 행사에 협력해야 한다(제3항).","c":"상","v":1},"공인회2026_61-06-4":{"w":"상법 제168조의5 제1항이 이용자의 귀책사유로 해지하면 잔존 리스료 상당액의 일시 지급이나 물건 반환을 청구할 수 있게 한다. 손해배상청구는 따로 할 수 있다(제2항).","c":"상","v":1},"공인회2026_61-06-5":{"w":"상법 제168조의5 제3항이 중대한 사정변경으로 물건을 계속 쓸 수 없으면 3개월 전 예고로 해지할 수 있게 한다. 이용자는 해지로 생긴 손해를 배상해야 한다.","c":"상","v":1},"공인회2021_56-03-1":{"w":"상법 제88조가 대리상의 통지의무를 정한다. 본인의 청구가 없어도 지체 없이 발송해야 한다.","c":"상","v":1},"공인회2021_56-03-2":{"w":"상법 제89조 제1항이 대리상의 경업금지를 정한다. 위반하면 제17조 제2항~제4항이 준용되어 개입권 등이 생긴다(제89조 제2항).","c":"상","v":1},"공인회2021_56-03-3":{"w":"상법 제90조가 물건 판매나 그 중개의 위탁을 받은 대리상에게 하자·수량부족 통지의 수령권한을 준다.","c":"상","v":1},"공인회2021_56-03-4":{"w":"상법 제92조의2 제3항이 보상청구권의 행사기간을 계약 종료일부터 6월로 정한다.","c":"상","v":1},"공인회2023_58-07-4":{"w":"상법 제109조가 매수위탁에서 위탁자가 수령을 거부하거나 수령할 수 없으면 제67조의 공탁·경매권을 준용한다. 위탁자가 상인이 아니어도 적용된다.","c":"상","v":1},"공인회2025_60-06-2":{"w":"상법 제138조 제1항이 순차운송인의 연대책임을 정한다. 배상한 운송인은 원인 제공 운송인에게 구상할 수 있다(제2항).","c":"상","v":1},"공인회2025_60-06-3":{"w":"상법 제139조 제1항 후단이 처분청구 시 운송인이 이미 운송한 비율의 운임, 체당금, 처분 비용을 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-06-4":{"w":"상법 제144조 제1항이 송하인, 화물상환증소지인, 수하인을 모두 알 수 없으면 6월 이상의 기간을 정해 권리 주장을 공고하도록 정한다. 공고는 관보나 일간신문에 2회 이상 한다(제2항).","c":"하","v":1},"공인회2025_60-06-5":{"w":"상법 제134조 제1항이 송하인의 책임 없는 사유로 운송물이 멸실하면 운송인은 운임을 청구하지 못한다고 정한다. 운송물의 성질·하자나 송하인 과실로 멸실하면 운임 전액을 청구할 수 있다(제2항).","c":"상","v":1},"공인회2019_54-07-1":{"w":"상법 제168조의3 제3항이 금융리스물건수령증을 발급하면 리스계약 당사자 사이에 적합한 물건이 수령된 것으로 추정한다고 정한다. 간주가 아니라 추정이므로 반증으로 뒤집을 수 있다.","c":"상","v":1},"공인회2019_54-07-3":{"w":"상법 제168조의5 제3항이 중대한 사정변경으로 리스물건을 계속 쓸 수 없으면 금융리스이용자가 3개월 전 예고로 해지할 수 있게 한다. 이용자는 해지로 생긴 손해를 배상해야 한다.","c":"상","v":1},"공인회2019_54-07-4":{"w":"상법 제168조의10의 가맹계약 해지다. 존속기간 약정이 있어도 부득이한 사정이 있으면 예고 후 해지할 수 있다.","c":"상","v":1},"공인회2019_54-07-5":{"w":"상법 제168조의12 본문이 영업채권의 채무자가 이행하지 않으면 채권매입업자가 채권매입계약의 채무자에게 상환을 청구할 수 있다고 정한다. 계약에서 다르게 정하면 단서에 따라 청구할 수 없다.","c":"상","v":1},"공인회2024_59-07-2":{"w":"상법 제148조 제2항이 여객 손해의 배상액을 정할 때 피해자와 그 가족의 정상을 참작하도록 한다. 물건운송의 정액배상(제137조)과 다르다.","c":"상","v":1},"공인회2024_59-07-3":{"w":"상법 제149조 제1항이 인도받은 수하물에 대해 운임을 받지 않았어도 물건운송인과 동일한 책임을 지운다.","c":"상","v":1},"공인회2024_59-07-4":{"w":"상법 제148조 제1항이 여객 손해에 대해 운송인에게 무과실 증명책임을 지운다.","c":"상","v":1},"공인회2024_59-07-5":{"w":"상법 제150조가 인도받지 않은 휴대 수하물은 운송인이나 사용인의 과실이 있어야 배상하도록 정한다. 과실 증명은 여객이 한다.","c":"상","v":1},"공인회2021_56-04-1":{"w":"상법 제126조 제1항이 송하인은 운송인의 청구에 의하여 화물명세서를 교부하도록 정한다.","c":"상","v":1},"공인회2021_56-04-3":{"w":"상법 제148조 제2항이 여객 손해의 배상액을 정할 때 법원이 피해자와 그 가족의 정상을 참작하도록 정한다. 물건운송처럼 도착지 가격으로 정액화하지 않는다.","c":"상","v":1},"공인회2021_56-04-4":{"w":"상법 제136조가 고가물은 송하인이 위탁 때 종류와 가액을 명시한 경우에만 운송인이 배상책임을 진다고 정한다.","c":"상","v":1},"공인회2021_56-04-5":{"w":"상법 제139조 제1항이 송하인 또는 화물상환증 발행 시 그 소지인에게 운송물 처분청구권을 준다.","c":"상","v":1},"공인회2018_53-03-1":{"w":"상법 제122조가 운송주선인의 위탁자 또는 수하인에 대한 채권의 시효를 1년으로 정한다.","c":"상","v":1},"공인회2018_53-03-2":{"w":"상법 제114조가 운송주선인을 자기 명의로 물건운송의 주선을 영업으로 하는 자로 정의한다. 여객운송 주선은 준위탁매매(제113조)로 다룬다.","c":"상","v":1},"공인회2018_53-03-3":{"w":"상법 제116조 제2항이 위탁자의 청구로 화물상환증을 작성하면 직접운송하는 것으로 본다고 정한다.","c":"상","v":1},"공인회2018_53-03-5":{"w":"상법 제120조의 운송주선인 유치권이다. 그 운송물에 관한 채권으로 한정된다.","c":"상","v":1},"공인회2016_51-06-1":{"w":"상법 제119조 제2항이 운송주선계약으로 운임의 액을 정하면 다른 약정이 없는 한 따로 보수를 청구하지 못한다고 정한다.","c":"상","v":1},"공인회2016_51-06-2":{"w":"상법 제116조 제2항이 운송주선인이 위탁자의 청구로 화물상환증을 작성하면 직접운송하는 것으로 본다고 정한다. 그러면 운송인과 같은 권리의무를 가진다(같은 조 제1항).","c":"상","v":1},"공인회2016_51-06-4":{"w":"상법 제120조가 운송주선인의 유치권 범위를 그 운송물에 관한 보수, 운임, 체당금, 선대금으로 한정한다.","c":"상","v":1},"공인회2016_51-06-5":{"w":"상법 제122조가 운송주선인의 위탁자 또는 수하인에 대한 채권은 1년간 행사하지 않으면 시효로 소멸한다고 정한다.","c":"상","v":1},"공인회2021_56-05-1":{"w":"상법 제114조가 운송주선인을 자기 명의로 물건운송의 주선을 영업으로 하는 자로 정의한다. 타인 계산으로 자기 명의 거래를 한다는 점에서 위탁매매인과 구조가 같다.","c":"상","v":1},"공인회2021_56-05-3":{"w":"상법 제116조 제1항이 다른 약정이 없으면 운송주선인의 직접운송(개입권)을 허용하고 운송인과 동일한 권리의무를 부여한다.","c":"상","v":1},"공인회2021_56-05-4":{"w":"상법 제120조가 운송주선인은 그 운송물에 관한 보수, 운임, 체당금, 선대금에 관해서만 그 운송물을 유치할 수 있다고 정한다.","c":"상","v":1},"공인회2021_56-05-5":{"w":"상법 제117조 제1항이 순차운송주선에서 후자가 전자에 갈음하여 권리를 행사할 의무를 지운다.","c":"상","v":1},"공인회2024_59-06-1":{"w":"상법 제116조 제1항이 운송주선인은 다른 약정이 없으면 직접운송할 수 있고 이 경우 운송인과 동일한 권리의무가 있다고 정한다.","c":"상","v":1},"공인회2024_59-06-2":{"w":"상법 제119조 제1항이 운송물을 운송인에게 인도하면 즉시 보수를 청구할 수 있게 한다. 운임액을 정한 경우에는 제2항이 별도 보수청구를 막는다.","c":"상","v":1},"공인회2024_59-06-3":{"w":"상법 제117조 제1항이 후자의 권리행사 의무를, 제2항이 후자가 전자에게 변제하면 전자의 권리를 취득한다고 정한다.","c":"상","v":1},"공인회2024_59-06-4":{"w":"상법 제120조의 유치권이다. 일반상사유치권과 달리 그 운송물에 관한 채권으로 한정된다.","c":"상","v":1},"공인회2026_61-07-2":{"w":"상법 제122조의 1년 시효다. 운송인의 채권에도 준용된다(제147조).","c":"상","v":1},"공인회2019_54-03-1":{"w":"상법 제104조가 위탁매매인의 통지의무와 계산서 제출의무를 정한다.","c":"상","v":1},"공인회2019_54-03-3":{"w":"상법 제109조가 매수위탁의 위탁자가 수령을 거부하면 제67조를 준용하는데 위탁자가 상인일 것을 요구하지 않는다.","c":"상","v":1},"공인회2019_54-03-4":{"w":"상법 제110조가 상인인 위탁자가 영업에 관해 매수를 위탁하면 위탁자와 위탁매매인 사이에 제68조~제71조를 준용한다. 그래서 제69조의 검사·통지의무가 위탁자에게 적용된다.","c":"상","v":1},"공인회2019_54-03-5":{"w":"상법 제110조가 상인인 매수위탁자와 위탁매매인 사이에 제68조의 확정기매매 해제 의제를 준용한다.","c":"상","v":1},"공인회2022_57-06-1":{"w":"상법 제102조가 위탁매매인이 위탁자를 위한 매매로 상대방에 대하여 직접 권리를 취득하고 의무를 부담한다고 정한다. 위탁매매인이 자기 명의로 거래하기 때문이다(제101조).","c":"상","v":1},"공인회2022_57-06-3":{"w":"상법 제105조가 위탁매매인의 이행담보책임을 정한다. 다른 약정이나 관습이 있으면 예외다.","c":"상","v":1},"공인회2022_57-06-4":{"w":"상법 제106조 제1항이 지정가액보다 염가 매도나 고가 매수를 했어도 위탁매매인이 차액을 부담하면 그 매매가 위탁자에게 효력이 있다고 정한다.","c":"상","v":1},"공인회2022_57-06-5":{"w":"상법 제107조 제2항이 개입권을 행사한 위탁매매인도 위탁자에게 보수를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2020_55-04-1":{"w":"상법 제95조가 중개인의 견품 보관의무를 정한다. 보관 기간은 그 행위가 완료될 때까지다.","c":"상","v":1},"공인회2020_55-04-2":{"w":"상법 제99조가 중개인이 임의로 또는 묵비 요구에 따라 당사자 일방의 성명·상호를 표시하지 않으면 상대방이 중개인에게 이행을 청구할 수 있게 한다(개입의무).","c":"상","v":1},"공인회2020_55-04-4":{"w":"상법 제94조 본문이 중개인에게 급여수령권한이 없다고 정한다. 다른 약정이나 관습이 있으면 단서에 따라 예외가 된다.","c":"상","v":1},"공인회2020_55-04-5":{"w":"상법 제97조 제2항이 당사자가 언제든지 장부 등본의 교부를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-05-1":{"w":"상법 제100조 제2항이 중개인 보수를 당사자 쌍방이 균분 부담한다고 정한다.","c":"상","v":1},"공인회2022_57-05-2":{"w":"상법 제96조 제3항이 당사자 일방이 결약서 수령을 거부하거나 기명날인·서명을 하지 않으면 중개인이 지체 없이 상대방에게 통지를 발송하도록 정한다.","c":"상","v":1},"공인회2022_57-05-4":{"w":"상법 제100조 제1항이 제96조의 결약서 절차를 마치지 않으면 보수를 청구하지 못한다고 정한다.","c":"상","v":1},"공인회2022_57-05-5":{"w":"상법 제98조가 당사자의 묵비 요구가 있으면 상대방에게 교부할 결약서와 장부 등본에 그 성명·상호를 적지 못하게 한다.","c":"상","v":1},"공인회2022_57-07-1":{"w":"상법 제156조 제1항이 창고업자에게 임치인의 청구에 따른 창고증권 교부의무를 지운다.","c":"상","v":1},"공인회2022_57-07-2":{"w":"상법 제161조가 임치인 또는 창고증권소지인에게 영업시간 내 임치물 검사, 견품 적취, 보존처분을 요구할 권리를 준다.","c":"상","v":1},"공인회2022_57-07-3":{"w":"상법 제158조 제1항이 증권을 반환하고 분할 부분별 창고증권을 청구할 권리를 정한다. 비용은 증권소지인이 부담한다(제2항).","c":"상","v":1},"공인회2022_57-07-4":{"w":"상법 제160조가 창고업자에게 무과실 증명책임을 지운다.","c":"상","v":1},"공인회2024_59-08-1":{"w":"상법 제158조 제1항이 창고증권소지인은 증권을 반환하고 임치물을 분할해 각 부분의 창고증권을 청구할 수 있다고 정한다. 비용은 소지인이 부담한다(제2항).","c":"상","v":1},"공인회2024_59-08-2":{"w":"영업범위 내 무상임치를 받은 상인은 선관주의의무를 지므로(상법 제62조) 창고업자도 무상 임치물을 선량한 관리자의 주의로 보관해야 한다.","c":"상","v":1},"공인회2024_59-08-3":{"w":"상법 제162조 제2항이 일부출고 시 그 비율에 따른 보관료, 비용, 체당금을 청구할 수 있게 한다. 보관료는 원칙적으로 출고 때 청구한다(제1항).","c":"상","v":1},"공인회2024_59-08-5":{"w":"상법 제167조가 창고업자의 채권 시효를 출고한 날부터 1년으로 정한다.","c":"상","v":1},"공인회2017_52-04-3":{"w":"상법 제133조의 화물상환증 교부의 물권적 효력이다. 증권 교부가 운송물 인도와 같은 효력을 가진다.","c":"상","v":1},"공인회2025_60-05-4":{"w":"상법 제133조가 화물상환증 교부에 운송물 인도와 같은 효력을 준다(물권적 효력).","c":"상","v":1},"공인회2021_56-06-1":{"w":"상법 제132조가 화물상환증을 작성하면 운송물 처분은 화물상환증으로 해야 한다고 정한다(처분증권성).","c":"상","v":1},"공인회2021_56-06-2":{"w":"상법 제129조가 화물상환증과 상환하지 않으면 운송물 인도를 청구할 수 없다고 정한다(상환증권성).","c":"상","v":1},"공인회2021_56-06-3":{"w":"상법 제130조가 화물상환증은 기명식이어도 배서로 양도할 수 있고 배서금지 기재가 있으면 예외라고 정한다(법률상 당연한 지시증권).","c":"상","v":1},"공인회2021_56-06-5":{"w":"상법 제133조가 화물상환증으로 운송물을 받을 수 있는 자에게 증권을 교부하면 운송물 위의 권리 취득에 관하여 운송물을 인도한 것과 같은 효력이 있다고 정한다.","c":"상","v":1},"공인회2019_54-23-1":{"w":"판례는 일시 차입금으로 납입하고 설립 직후 인출해 갚는 가장납입이라도 금원의 이동에 따른 현실의 납입이 있었으므로 주금납입의 효력이 있다고 본다. 납입 의사가 없었다는 주관적 사정은 효력에 영향이 없다.","c":"상","v":1},"공인회2019_54-23-2":{"w":"판례가 가장납입도 주금납입으로 유효하다고 보므로 납입절차는 완료된다. 설립절차에 다른 하자가 없으면 회사는 유효하게 성립하고 A는 주주가 된다.","c":"상","v":1},"공인회2019_54-23-4":{"w":"판례는 가장납입 후 회사가 납입금을 인출해 주식인수인의 차입금을 갚은 경우 회사가 그 주주에게 체당한 주금 상당액의 상환을 청구할 수 있다고 본다.","c":"상","v":1},"공인회2019_54-23-5":{"w":"판례는 납입금을 회사를 위하여 쓰지 않고 곧바로 인출해 차입금을 갚으면 실질적으로 자본이 늘지 않아 상법 제628조 제1항의 납입가장죄가 성립한다고 본다. 민사상 납입의 효력과 별개로 판단한다.","c":"상","v":1},"공인회2019_54-13-1":{"w":"합명회사는 2인 이상의 사원이 정관을 작성해야 하고(상법 제178조) 합자회사는 무한책임사원과 유한책임사원이 각 1인 이상 있어야 하므로(제268조) 1인회사가 될 수 없다. 주식회사(제288조), 유한책임회사(제287조의2), 유한회사(제543조 제1항)는 1인으로 설립할 수 있다.","c":"상","v":1},"공인회2019_54-13-2":{"w":"판례는 1인회사에서 1인주주가 참석해 이의 없이 결의했다면 소집절차 하자가 있어도 결의가 유효하다고 본다. 소집절차는 주주의 출석 기회를 보장하려는 것이고 1인주주의 의사가 곧 총회 의사이기 때문이다.","c":"상","v":1},"공인회2019_54-13-3":{"w":"판례는 자기거래 승인 규정이 회사와 주주를 보호하려는 것이므로 1인주주가 사전에 동의했으면 회사가 이사회 승인이 없었다는 이유로 책임을 회피할 수 없다고 본다.","c":"상","v":1},"공인회2019_54-13-5":{"w":"판례는 1인회사와 1인주주는 별개의 인격이므로 1인주주가 회사 돈을 임의로 쓰면 횡령죄가 성립한다고 본다.","c":"상","v":1},"공인회2018_53-29-1":{"w":"원시정관은 공증인의 인증을 받아야 효력이 생긴다. 자본금 10억원 미만 회사가 발기설립할 때만 발기인의 기명날인·서명으로 효력이 생기므로(상법 제292조) 모집설립은 이 예외에 해당하지 않는다.","c":"상","v":1},"공인회2018_53-29-2":{"w":"상법 제318조 제3항이 자본금 10억원 미만 회사가 발기설립하면 납입금 보관증명서를 금융기관 잔고증명서로 대체할 수 있게 한다.","c":"상","v":1},"공인회2018_53-29-3":{"w":"상법 제363조 제4항 후단이 자본금 10억원 미만 회사에서 결의 목적사항에 주주 전원이 서면으로 동의하면 서면 결의가 있은 것으로 본다고 정한다.","c":"상","v":1},"공인회2018_53-29-4":{"w":"자본금 10억원 미만 회사는 이사를 1명 또는 2명으로 할 수 있고(상법 제383조 제1항 단서), 이 경우 자기거래 승인 등 이사회 권한 중 제398조의 승인은 주주총회가 한다(같은 조 제4항).","c":"상","v":1},"공인회2016_51-11-1":{"w":"회사 성립 후 주식인수 청약이 취소된 주식은 발기인이 공동으로 인수한 것으로 본다(상법 제321조 제1항, 인수담보책임). 별도의 의사표시가 필요 없다.","c":"상","v":1},"공인회2016_51-11-2":{"w":"상법 제321조 제2항이 회사 성립 후 납입을 완료하지 않은 주식에 대해 발기인에게 연대 납입담보책임을 지운다.","c":"상","v":1},"공인회2016_51-11-3":{"w":"납입담보책임은 인수인의 납입의무를 발기인이 대신 이행하는 것이다. 그래서 주식은 인수인이 그대로 취득하고 발기인은 인수인에게 구상할 수 있다.","c":"중","v":1},"공인회2016_51-11-4":{"w":"인수담보책임에서는 발기인이 그 주식을 인수한 것으로 보므로(상법 제321조 제1항) 발기인이 주주가 된다.","c":"상","v":1},"공인회2018_53-13-1":{"w":"주식청약서는 발기인이 작성하고 납입을 맡을 은행 기타 금융기관과 납입장소를 적어야 한다(상법 제302조 제2항 제9호).","c":"상","v":1},"공인회2020_55-14-2":{"w":"상법 제313조 제1항이 모집설립에서 이사와 감사가 설립 경과를 조사해 창립총회에 보고하도록 정한다. 발기설립에서는 발기인에게 보고한다(제298조 제1항).","c":"상","v":1},"공인회2024_59-10-1":{"w":"발기인은 정관에 발기인으로 기명날인 또는 서명한 사람을 말하는 형식적 개념이다(상법 제289조 제1항). 설립을 사실상 주관해도 정관에 서명하지 않으면 발기인이 아니어서 주식인수의무(제293조)가 없다. 다만 유사발기인 책임(제327조)은 질 수 있다.","c":"상","v":1},"공인회2024_59-10-2":{"w":"주식청약서에는 제290조의 변태설립사항을 적어야 하고(상법 제302조 제2항 제2호), 현물출자자의 성명과 재산의 종류·수량·가격, 부여할 주식의 종류와 수는 제290조 제2호의 사항이다.","c":"상","v":1},"공인회2024_59-10-3":{"w":"상법 제304조 제2항이 주식청약서에 적힌 주소로 한 통지·최고는 보통 도달할 시기에 도달한 것으로 본다고 정한다.","c":"상","v":1},"공인회2024_59-10-5":{"w":"상법 제314조 제1항이 창립총회가 변태설립사항을 부당하다고 인정하면 변경할 수 있게 한다. 발기인 보수액은 제290조 제4호의 변태설립사항이다.","c":"상","v":1},"공인회2017_52-21-1":{"w":"판례는 정관이 작성되고 발기인이 적어도 1주 이상의 주식을 인수한 때 설립중의 회사가 성립한다고 본다.","c":"상","v":1},"공인회2017_52-21-2":{"w":"판례는 설립중의 회사를 성립 후 회사와 동일한 실체로 보아 발기인이 그 권한 범위에서 설립중의 회사 명의로 한 행위의 효과가 별도 이전행위 없이 성립 후 회사에 귀속된다고 본다.","c":"상","v":1},"공인회2017_52-21-3":{"w":"발기인 보수액은 정관에 적어야 효력이 있는 변태설립사항이고(상법 제290조 제4호), 법원 선임 검사인의 조사를 받되(제298조 제4항, 제310조) 공증인의 조사·보고로 대신할 수 있다(제299조의2).","c":"상","v":1},"공인회2017_52-21-4":{"w":"상법 제298조 제1항이 발기설립에서 이사·감사가 설립 경과를 조사해 발기인에게 보고하도록 정한다.","c":"상","v":1},"공인회2020_55-09-1":{"w":"상법 제322조 제2항이 발기인이 악의 또는 중대한 과실로 임무를 게을리하면 제3자에게도 연대 배상책임을 지운다.","c":"상","v":1},"공인회2021_56-10-1":{"w":"상법 제289조 제1항 제6호가 본점 소재지를 정관의 절대적 기재사항으로 정한다.","c":"상","v":1},"공인회2021_56-10-2":{"w":"상법 제290조 제4호가 회사가 부담할 설립비용과 발기인 보수액을 정관에 적어야 효력이 있는 변태설립사항으로 정한다.","c":"상","v":1},"공인회2021_56-10-4":{"w":"상법 제309조가 창립총회 결의 요건을 출석 주식인수인 의결권의 3분의 2 이상이면서 인수 주식 총수의 과반수로 정한다.","c":"상","v":1},"공인회2021_56-10-5":{"w":"상법 제325조가 법원이 선임한 검사인이 악의 또는 중과실로 임무를 게을리하면 회사 또는 제3자에게 배상책임을 지운다.","c":"상","v":1},"공인회2022_57-11-2":{"w":"판례는 일시 차입금으로 납입하고 설립 직후 인출하는 가장납입도 현실의 금원 이동이 있으므로 주금납입의 효력을 인정한다.","c":"상","v":1},"공인회2023_58-11-3":{"w":"판례는 설립중의 회사 성립 시기를 정관 작성과 발기인의 1주 이상 주식인수가 있은 때로 본다.","c":"상","v":1},"공인회2025_60-12-1":{"w":"상법 제296조 제1항이 발기설립에서 납입과 현물출자 이행이 끝나면 발기인이 지체 없이 의결권 과반수로 이사·감사를 선임하도록 정한다. 의결권은 인수주식 1주에 1개다(제2항).","c":"상","v":1},"공인회2026_61-14-1":{"w":"상법 제306조가 모집설립에서 납입금 보관자나 납입장소를 변경하려면 법원의 허가를 얻도록 정한다.","c":"상","v":1},"공인회2026_61-14-3":{"w":"상법 제302조 제2항 제4호가 주식청약서 기재사항으로 각 발기인이 인수한 주식의 종류와 수를 정한다.","c":"상","v":1},"공인회2026_61-14-4":{"w":"판례가 설립중의 회사는 정관 작성과 발기인의 1주 이상 인수로 성립한다고 본다.","c":"상","v":1},"공인회2026_61-14-5":{"w":"상법 제298조 제1항이 발기설립의 이사·감사에게 설립 경과 조사와 발기인 보고 의무를 지운다.","c":"상","v":1},"공인회2017_52-12-1":{"w":"상법 제306조가 납입금 보관자 또는 납입장소 변경에 법원 허가를 요구한다.","c":"상","v":1},"공인회2017_52-12-2":{"w":"상법 제318조 제2항이 보관금액을 증명한 금융기관은 납입이 부실하거나 반환에 제한이 있다는 이유로 회사에 대항하지 못한다고 정한다.","c":"상","v":1},"공인회2017_52-12-3":{"w":"상법 제318조 제3항이 자본금 10억원 미만 회사의 발기설립에서 잔고증명서로 보관금액 증명서를 대체할 수 있게 한다.","c":"상","v":1},"공인회2017_52-12-5":{"w":"상법 제332조 제2항이 타인의 승낙을 얻어 그 명의로 주식을 인수한 자는 그 타인과 연대하여 납입할 책임이 있다고 정한다.","c":"상","v":1},"공인회2026_61-28-1":{"w":"정관변경은 주주총회 결의로 하고(상법 제433조 제1항), 그 결의는 제434조의 특별결의(출석 의결권 3분의 2 이상, 발행주식총수 3분의 1 이상)로 한다.","c":"상","v":1},"공인회2026_61-28-2":{"w":"상법 제433조 제2항이 정관변경 총회의 소집통지와 공고에 의안의 요령을 적도록 정한다.","c":"상","v":1},"공인회2026_61-28-4":{"w":"공증인 인증은 원시정관의 효력요건이고(상법 제292조), 정관변경은 주주총회 결의로 효력이 생긴다는 것이 통설·실무다.","c":"중","v":1},"공인회2026_61-28-5":{"w":"상법 제435조 제1항이 정관변경이 어느 종류주식 주주에게 손해를 미치면 주주총회 결의 외에 종류주주총회 결의를 요구한다. 결의 요건은 그 종류 출석 주식의 3분의 2 이상, 그 종류 발행주식총수의 3분의 1 이상이다(제2항).","c":"상","v":1},"공인회2018_53-14-5":{"w":"합명회사 사원은 무한책임을 지므로 재산 외에 신용이나 노무도 출자할 수 있고(유한책임사원의 신용·노무 출자를 막는 상법 제272조의 반대해석), 채권 출자도 가능하며 채무자가 변제하지 않으면 사원이 변제책임을 진다(제196조).","c":"상","v":1},"공인회2020_55-11-1":{"w":"상법 제169조가 회사를 상행위나 그 밖의 영리를 목적으로 하여 설립한 법인으로 정의한다.","c":"상","v":1},"공인회2020_55-11-2":{"w":"상법 제172조가 회사는 본점 소재지에서 설립등기를 함으로써 성립한다고 정한다.","c":"상","v":1},"공인회2020_55-11-3":{"w":"상법 제171조가 회사의 주소를 본점 소재지로 정한다.","c":"상","v":1},"공인회2020_55-11-4":{"w":"상법 제176조 제1항 제3호가 이사나 업무집행사원이 법령·정관에 위반하여 회사 존속을 허용할 수 없는 행위를 하면 법원이 이해관계인·검사의 청구 또는 직권으로 해산을 명할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-13-1":{"w":"상법 제173조가 회사는 다른 회사의 무한책임사원이 되지 못한다고 정한다. 합명회사 사원은 모두 무한책임사원이다.","c":"상","v":1},"공인회2022_57-13-2":{"w":"상법 제171조가 회사 종류를 가리지 않고 주소를 본점 소재지로 정한다.","c":"상","v":1},"공인회2022_57-13-3":{"w":"상법 제176조 제1항 제2호가 정당한 사유 없이 설립 후 1년 내에 영업을 개시하지 않으면 법원이 직권으로도 해산을 명할 수 있게 한다.","c":"상","v":1},"공인회2022_57-13-4":{"w":"합병 당사회사 일방이 유한회사이면 존속회사는 주식회사, 유한회사 또는 유한책임회사여야 한다(상법 제174조 제2항). 흡수합병의 존속회사는 당사회사 중 하나이므로 유한회사와 합명회사의 합병에서는 유한회사가 존속해야 한다.","c":"상","v":1},"공인회2023_58-09-4":{"w":"상법 제174조 제3항이 해산 후의 회사는 존립 중의 회사를 존속회사로 하는 경우에만 합병할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-09-1":{"w":"판례는 법인은 범죄능력이 없고 양벌규정이 있을 때만 처벌된다고 본다. 법인의 업무에 관한 범죄는 행위자인 자연인이 처벌받는다.","c":"상","v":1},"공인회2016_51-25-1":{"w":"상법 제435조 제1항이 정관변경으로 손해를 입는 종류주주의 총회 결의를 추가로 요구한다. 상장회사에도 같이 적용된다.","c":"상","v":1},"공인회2016_51-25-2":{"w":"상법 제433조 제2항이 정관변경을 위한 총회 소집통지에 의안의 요령을 적도록 정한다.","c":"상","v":1},"공인회2016_51-13-1":{"w":"상호주 의결권 제한은 회사(모회사·자회사 보유분 포함)가 다른 회사 발행주식총수의 10분의 1을 초과하여 가질 때 생긴다(상법 제369조 제3항). 지금 상태에서는 그 비율을 넘지 않으므로 丙이 가진 甲 주식 7%의 의결권은 그대로 있다.","c":"중","v":1},"공인회2016_51-13-2":{"w":"자회사가 가진 주식도 합산하므로 乙의 추가 취득으로 甲 측의 丙 주식이 10분의 1을 넘으면 丙이 가진 甲 주식은 의결권이 없어진다(상법 제369조 제3항).","c":"중","v":1},"공인회2016_51-13-3":{"w":"丙이 甲 주식을 추가 취득해 甲 발행주식총수의 10분의 1을 넘게 가지면 상법 제369조 제3항이 반대 방향으로도 적용되어 甲이 가진 丙 주식 10%의 의결권이 없어진다.","c":"중","v":1},"공인회2016_51-13-4":{"w":"甲이 丙 주식을 더 취득해 甲(자회사 보유분 포함)의 丙 주식이 10분의 1을 넘으면 丙이 가진 甲 주식은 의결권이 없다(상법 제369조 제3항).","c":"중","v":1},"공인회2016_51-14-1":{"w":"상법 제341조 제1항이 배당가능이익 범위에서 회사의 명의와 계산으로 자기주식을 취득할 수 있게 한다. 거래소 매수나 균등 조건 공개매수 등 정해진 방법과 주주총회(정관이 정하면 이사회) 결의가 필요하다.","c":"상","v":1},"공인회2018_53-16-5":{"w":"상법 제335조의3 제1항이 주주가 상대방 지정을 청구하면 이사회가 청구일부터 2주 내에 상대방을 지정하고 주주와 그 상대방에게 서면으로 통지하도록 정한다.","c":"상","v":1},"공인회2019_54-14-1":{"w":"회사 성립 후 6월이 지나면 주권 발행 전 주식양도도 회사에 효력이 있고(상법 제335조 제3항 단서), 판례는 이때의 양도를 지명채권 양도의 일반원칙에 따라 당사자 의사표시만으로 효력이 생긴다고 본다.","c":"상","v":1},"공인회2019_54-14-2":{"w":"판례는 주권 발행 전 주식의 양수인은 특별한 사정이 없으면 양도인의 협력 없이 단독으로 양수 사실을 증명해 회사에 명의개서를 청구할 수 있다고 본다.","c":"상","v":1},"공인회2019_54-14-3":{"w":"판례는 주권 발행 전 주식의 이중양도에서 양수인 사이의 우열을 확정일자 있는 양도통지가 회사에 도달한 일시나 확정일자 있는 승낙의 일시 선후로 정한다. 지명채권 이중양도 법리(민법 제450조)를 따른 것이다.","c":"상","v":1},"공인회2019_54-14-5":{"w":"주식 이전은 명의개서를 하지 않으면 회사에 대항하지 못하므로(상법 제337조 제1항) 양수인이 회사에 의결권을 행사하려면 명의개서를 해야 한다.","c":"상","v":1},"공인회2024_59-13-3":{"w":"상법 제335조의2 제2항이 회사는 양도승인 청구일부터 1월 내에 승인 여부를 서면으로 통지하도록 정한다. 그 기간 내에 거부 통지가 없으면 승인한 것으로 본다(같은 조 제3항).","c":"상","v":1},"공인회2024_59-16-1":{"w":"상법 제360조의24 제2항이 지배주주의 보유주식 수를 산정할 때 모회사와 자회사의 보유주식을 합산하도록 정한다.","c":"상","v":1},"공인회2024_59-16-2":{"w":"상법 제360조의24 제3항이 매도청구를 하려면 미리 대상회사 주주총회의 승인을 받도록 정한다.","c":"상","v":1},"공인회2024_59-16-3":{"w":"상법 제360조의24 제6항이 매도청구를 받은 소수주주는 청구일부터 2개월 내에 지배주주에게 주식을 매도하도록 정한다.","c":"상","v":1},"공인회2024_59-16-4":{"w":"매매가액은 지배주주와 소수주주의 협의로 정한다. 매도청구일부터 30일 내에 협의가 안 되면 어느 쪽이든 법원에 결정을 청구할 수 있다(상법 제360조의24 제7항·제8항).","c":"상","v":1},"공인회2022_57-09-1":{"w":"상법 제369조 제2항이 회사가 가진 자기주식은 의결권이 없다고 정한다.","c":"상","v":1},"공인회2022_57-09-2":{"w":"상법 제342조가 자기주식 처분 시 정관에 규정이 없는 사항(주식의 종류와 수, 처분가액과 납입기일, 상대방과 처분방법)을 이사회가 결정하도록 정한다.","c":"상","v":1},"공인회2022_57-09-3":{"w":"상법 제342조의3이 다른 회사 발행주식총수의 10분의 1을 초과하여 취득한 회사에 지체 없는 통지의무를 지운다.","c":"상","v":1},"공인회2022_57-09-4":{"w":"상법 제342조의2 제3항이 자회사가 다른 회사 주식의 50%를 초과하여 가지면 그 다른 회사(손회사)도 모회사의 자회사로 본다고 정한다.","c":"상","v":1},"공인회2025_60-18-2":{"w":"상법 제342조 제2호가 처분할 주식의 상대방과 처분방법을 정관에 규정이 없으면 이사회가 결정할 사항으로 정한다.","c":"상","v":1},"공인회2025_60-18-3":{"w":"상법 제342조의2 제1항 제1호가 주식의 포괄적 교환, 포괄적 이전, 흡수합병, 신설합병 또는 다른 회사의 영업전부 양수로 인한 때 자회사의 모회사 주식 취득을 허용한다.","c":"상","v":1},"공인회2025_60-18-4":{"w":"상법 제342조의2 제3항이 모회사와 자회사가 합하여 또는 자회사가 다른 회사 주식의 50%를 초과하여 가지면 그 다른 회사를 모회사의 자회사로 본다고 정한다.","c":"상","v":1},"공인회2025_60-18-5":{"w":"상법 제342조의2 제2항이 예외적으로 취득한 모회사 주식은 취득한 날부터 6월 내에 처분하도록 정한다.","c":"상","v":1},"공인회2023_58-13-1":{"w":"상법 제360조 제1항이 주권은 공시최고 절차로 무효로 할 수 있다고 정한다.","c":"상","v":1},"공인회2023_58-13-2":{"w":"상법 제358조의2 제2항이 주권불소지 신고가 있으면 회사가 지체 없이 주권을 발행하지 않는다는 뜻을 주주명부와 복본에 적고 주주에게 통지하도록 정한다.","c":"상","v":1},"공인회2023_58-13-3":{"w":"상법 제355조 제2항이 주권은 회사 성립 후 또는 신주 납입기일 후가 아니면 발행하지 못한다고 정한다. 위반한 주권은 무효다(제3항).","c":"상","v":1},"공인회2023_58-13-5":{"w":"상법 제360조 제2항이 주권 상실자는 제권판결을 얻지 않으면 재발행을 청구하지 못한다고 정한다.","c":"상","v":1},"공인회2023_58-12-3":{"w":"액면·무액면 전환에는 상법 제329조 제5항이 제440조를 준용하므로 1월 이상의 기간을 정해 주권 제출을 공고하고 주주명부상 주주와 질권자에게 각별로 통지해야 한다.","c":"상","v":1},"공인회2025_60-16-1":{"w":"판례는 회사가 주식매수선택권자의 권리를 부당하게 제한하지 않고 정관의 기본 취지나 핵심 내용을 해치지 않는 범위에서 주주총회 결의와 개별 계약으로 행사기간을 자유롭게 정할 수 있다고 본다.","c":"상","v":1},"공인회2026_61-18-1":{"w":"상법 제340조의2 제1항이 정관으로 정하는 바에 따라 주주총회 특별결의(제434조)로 주식매수선택권을 부여할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-18-2":{"w":"상법 제340조의5가 신주인수권부사채의 신주인수권 행사에 관한 제516조의10을 준용하므로 행사가액 전액을 납입한 때 주주가 된다.","c":"상","v":1},"공인회2026_61-18-4":{"w":"상법 제340조의2 제1항 단서가 행사가액이 실질가액보다 낮으면 차액을 금전이나 자기주식으로 지급할 수 있다고 정한다. 이때 실질가액은 행사일을 기준으로 평가한다.","c":"상","v":1},"공인회2026_61-18-5":{"w":"상법 제340조의2 제3항이 주식매수선택권으로 발행할 신주나 양도할 자기주식이 발행주식총수의 10%를 넘지 못하게 한다.","c":"상","v":1},"공인회2023_58-16-2":{"w":"상법 제335조 제1항 단서가 정관으로 주식 양도에 이사회 승인을 받도록 할 수 있다고 정한다.","c":"상","v":1},"공인회2023_58-16-3":{"w":"주권 발행 전 주식양도는 회사에 효력이 없지만 회사 성립 후 또는 신주 납입기일 후 6월이 지나면 효력이 있다(상법 제335조 제3항).","c":"상","v":1},"공인회2023_58-16-4":{"w":"판례는 6월 경과 전에 한 주권 발행 전 양도라도 그 후 6월이 지나도록 회사가 주권을 발행하지 않으면 하자가 치유되어 회사에 효력이 있다고 본다(상법 제335조 제3항 단서).","c":"상","v":1},"공인회2023_58-16-5":{"w":"상법 제341조의2 제1호가 회사의 합병 또는 다른 회사 영업 전부의 양수로 인한 경우 자기주식 취득을 허용한다.","c":"상","v":1},"공인회2023_58-15-1":{"w":"상법 제337조 제1항이 주식 이전은 취득자의 성명과 주소를 주주명부에 적지 않으면 회사에 대항하지 못한다고 정한다.","c":"상","v":1},"공인회2023_58-15-3":{"w":"상법 제354조 제2항이 폐쇄기간은 3월을 넘지 못한다고 정한다. 정관에 정함이 없으면 기간 개시 2주 전에 공고해야 한다(같은 조 제4항).","c":"상","v":1},"공인회2023_58-15-4":{"w":"상법 제352조의2 제1항이 정관으로 정하는 바에 따라 전자문서로 주주명부를 작성할 수 있게 한다.","c":"상","v":1},"공인회2023_58-15-5":{"w":"상법 제396조 제1항 후단이 명의개서대리인을 둔 경우 주주명부·사채원부나 그 복본을 명의개서대리인의 영업소에 비치할 수 있다고 정한다.","c":"상","v":1},"공인회2016_51-09-3":{"w":"상법 제345조 제4항이 상환 대가로 현금 외에 유가증권(그 회사의 다른 종류주식은 제외)이나 그 밖의 자산을 교부할 수 있게 한다. 다른 회사가 발행한 종류주식은 제외 대상이 아니다.","c":"상","v":1},"공인회2021_56-12-1":{"w":"상법 제345조 제1항의 회사상환주식이다. 정관에 상환가액, 상환기간, 방법, 주식 수를 정해야 한다.","c":"상","v":1},"공인회2021_56-12-3":{"w":"상법 제345조 제3항이 정관에 따라 주주가 회사에 상환을 청구할 수 있는 종류주식을 발행할 수 있게 한다. 정관에 상환가액, 상환청구기간, 상환방법 등을 정해야 한다.","c":"상","v":1},"공인회2021_56-12-4":{"w":"상법 제345조 제3항 후단이 주주상환주식의 정관 기재사항으로 상환청구 가능 취지, 상환가액, 상환청구기간, 상환방법, 상환할 주식 수를 정한다.","c":"상","v":1},"공인회2021_56-12-5":{"w":"상법 제345조 제5항이 상환주식은 종류주식(상환과 전환에 관한 것은 제외)에 한정하여 발행할 수 있다고 정한다. 보통주를 상환주식으로 할 수 없다.","c":"상","v":1},"공인회2024_59-11-2":{"w":"상법 제345조 제4항이 제외하는 것은 그 회사의 다른 종류주식뿐이어서 자회사가 발행한 종류주식은 유가증권으로서 상환 대가가 될 수 있다.","c":"상","v":1},"공인회2020_55-13-1":{"w":"상법 제344조의3 제2항이 의결권 없는·제한 종류주식이 발행주식총수의 4분의 1을 넘으면 회사가 지체 없이 초과하지 않도록 조치하도록 정한다.","c":"상","v":1},"공인회2020_55-13-2":{"w":"상법 제344조의3 제1항이 의결권 배제·제한 종류주식의 정관 기재사항으로 행사할 수 없는 사항과 행사·부활 조건을 정한다.","c":"상","v":1},"공인회2020_55-13-3":{"w":"상법 제345조 제1항 후단이 회사상환주식의 정관 기재사항으로 상환가액, 상환기간, 상환방법, 상환할 주식 수를 정한다.","c":"상","v":1},"공인회2020_55-13-5":{"w":"상법 제344조의2 제2항이 잔여재산분배 종류주식의 정관 기재사항으로 잔여재산의 종류, 가액 결정방법, 그 밖의 분배 내용을 정한다.","c":"상","v":1},"공인회2025_60-14-1":{"w":"상법 제348조가 전환으로 신주식을 발행하면 전환 전 주식의 발행가액을 신주식의 발행가액으로 한다고 정한다.","c":"상","v":1},"공인회2025_60-14-2":{"w":"상법 제350조 제1항이 주주가 전환을 청구한 경우 청구한 때 전환의 효력이 생긴다고 정한다. 회사 전환은 주권제출기간이 끝난 때다.","c":"상","v":1},"공인회2025_60-14-3":{"w":"상법 제344조의3 제1항이 의결권 배제·제한 종류주식의 정관에 의결권 행사 또는 부활 조건을 정할 수 있게 한다.","c":"상","v":1},"공인회2025_60-14-4":{"w":"상법 제346조 제2항이 정관에 일정 사유가 생기면 회사가 주주의 인수 주식을 다른 종류주식으로 전환할 수 있음을 정할 수 있게 한다(회사전환주식).","c":"상","v":1},"공인회2026_61-13-1":{"w":"상법 제345조 제3항이 정관에 따라 주주가 상환을 청구할 수 있는 종류주식(주주상환주식) 발행을 허용한다.","c":"상","v":1},"공인회2026_61-13-2":{"w":"상법 제344조 제3항이 종류주식을 발행하면 정관에 정함이 없어도 신주 인수, 주식의 병합·분할·소각, 합병·분할로 인한 배정에 관해 주식 종류에 따라 특수하게 정할 수 있다고 한다.","c":"상","v":1},"공인회2026_61-13-3":{"w":"상법 제344조의3 제2항이 의결권 없는·제한 종류주식이 발행주식총수의 4분의 1을 넘으면 회사가 지체 없이 초과하지 않도록 조치하도록 정한다.","c":"상","v":1},"공인회2026_61-13-4":{"w":"상법 제346조 제2항의 회사전환주식이다. 이사회가 전환할 주식, 2주 이상의 주권 제출기간 등을 정해 통지한다(제3항).","c":"상","v":1},"공인회2019_54-18-1":{"w":"판례는 정관변경으로 종류주주의 지위가 유리한 면과 불이익한 면을 함께 가지는 경우에도 상법 제435조의 종류주주에게 손해를 미치게 될 때에 해당해 종류주주총회 결의가 필요하다고 본다.","c":"상","v":1},"공인회2019_54-18-2":{"w":"상법 제435조 제2항이 종류주주총회 결의 요건을 출석 주주 의결권의 3분의 2 이상과 그 종류 발행주식총수의 3분의 1 이상으로 정한다.","c":"상","v":1},"공인회2019_54-18-3":{"w":"상법 제435조 제3항이 주주총회 규정을 종류주주총회에 준용하면서 의결권 없는 종류주식에 관한 규정은 빼므로 의결권 없는 종류주주도 그 종류주주총회에서는 의결권이 있다.","c":"상","v":1},"공인회2019_54-18-4":{"w":"종류주주총회에는 주주총회 소집 규정이 준용되므로(상법 제435조 제3항) 총회일 2주 전에 서면 또는 동의를 받은 전자문서로 통지해야 한다(제363조 제1항).","c":"상","v":1},"공인회2021_56-14-1":{"w":"상법 제338조 제1항이 주식 입질에는 주권을 질권자에게 교부하도록 정한다.","c":"상","v":1},"공인회2021_56-14-2":{"w":"상법 제338조 제2항이 질권자가 주권을 계속 점유하지 않으면 질권으로 제3자에게 대항하지 못한다고 정한다.","c":"상","v":1},"공인회2021_56-14-3":{"w":"상법 제339조가 주식의 소각, 병합, 분할, 전환으로 종전 주주가 받을 금전이나 주식에도 질권의 효력이 미친다고 정한다(물상대위).","c":"상","v":1},"공인회2021_56-14-4":{"w":"상법 제340조 제1항이 등록질권자는 이익배당, 잔여재산분배, 제339조의 금전을 회사로부터 직접 받아 다른 채권자에 우선하여 변제에 충당할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-15-1":{"w":"상법 제337조 제1항이 명의개서를 회사에 대한 대항요건으로 정한다.","c":"상","v":1},"공인회2022_57-15-2":{"w":"주권 점유자는 적법한 소지인으로 추정되므로(상법 제336조 제2항) 판례는 주권 제시 등으로 취득 사실을 증명하면 양수인이 단독으로 명의개서를 청구할 수 있다고 본다.","c":"상","v":1},"공인회2022_57-15-3":{"w":"상법 제352조의2 제2항이 전자주주명부에는 제352조 제1항의 기재사항 외에 전자우편주소를 적도록 정한다.","c":"상","v":1},"공인회2022_57-15-4":{"w":"상법 제354조 제1항이 회사가 기준일을 정할 수 있게 한다. 기준일은 권리를 행사할 날에 앞선 3월 내의 날이어야 한다(같은 조 제3항).","c":"상","v":1},"공인회2019_54-11-2":{"w":"불소지 신고로 제출된 주권은 회사가 무효로 하거나 명의개서대리인에게 임치한다(상법 제358조의2 제3항). 무효가 된 주권은 유가증권이 아니어서 선의취득의 대상이 되지 못한다.","c":"상","v":1},"공인회2019_54-11-3":{"w":"선의취득(상법 제359조, 수표법 제21조 준용)은 거래의 안전을 보호하는 제도여서 양도행위로 주권을 취득한 경우에만 인정된다. 상속이나 합병 같은 포괄승계에는 적용되지 않는다.","c":"중","v":1},"공인회2019_54-11-4":{"w":"판례는 주권의 선의취득이 양도인이 무권리자인 경우뿐 아니라 무권대리인인 경우에도 인정된다고 본다.","c":"상","v":1},"공인회2019_54-11-5":{"w":"상법 제360조 제2항이 제권판결 없이는 주권 재발행을 청구하지 못한다고 정한다.","c":"상","v":1},"공인회2021_56-16-1":{"w":"상법 제336조 제1항이 주식 양도에는 주권을 교부하도록 정한다.","c":"상","v":1},"공인회2021_56-16-2":{"w":"상법 제336조 제2항이 주권 점유자를 적법한 소지인으로 추정한다.","c":"상","v":1},"공인회2021_56-16-3":{"w":"상법 제337조 제1항이 명의개서를 회사에 대한 대항요건으로 정한다.","c":"상","v":1},"공인회2021_56-16-4":{"w":"상법 제337조 제2항이 정관으로 명의개서대리인을 둘 수 있게 한다. 대리인의 명부에 명의개서하면 회사의 주주명부에 한 것으로 본다.","c":"상","v":1},"공인회2021_56-11-4":{"w":"상법 제333조 제1항이 수인이 공동으로 주식을 인수하면 연대하여 납입할 책임을 진다고 정한다.","c":"상","v":1},"공인회2022_57-12-2":{"w":"상법 제451조 제3항이 액면주식과 무액면주식 사이의 전환으로는 자본금을 변경할 수 없다고 정한다.","c":"상","v":1},"공인회2022_57-12-3":{"w":"임시총회 소집청구권은 발행주식총수의 100분의 3 이상을 가진 주주에게 있다(상법 제366조 제1항). 상장회사 주주도 이 일반 규정으로 권리를 행사할 수 있으므로(제542조의6 제10항) 3% 이상이면 청구할 수 있다.","c":"상","v":1},"공인회2022_57-12-4":{"w":"상법 제329조의2 제1항이 주주총회 특별결의(제434조)로 주식을 분할할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-12-5":{"w":"상법 제335조 제1항 단서가 정관으로 주식 양도에 이사회 승인을 받도록 할 수 있다고 정한다.","c":"상","v":1},"공인회2020_55-10-1":{"w":"상법 제337조 제1항이 주식 이전은 취득자의 성명과 주소를 주주명부에 적지 않으면 회사에 대항하지 못한다고 정한다.","c":"상","v":1},"공인회2020_55-10-3":{"w":"상법 제339조가 주식의 소각, 병합, 분할, 전환으로 종전 주주가 받을 금전이나 주식에도 질권을 행사할 수 있다고 정한다.","c":"상","v":1},"공인회2020_55-10-4":{"w":"상법 제338조 제1항이 주식 입질에 주권 교부를 요구한다.","c":"상","v":1},"공인회2020_55-10-5":{"w":"상법 제340조 제1항이 등록질권자에게 이익배당금 등을 직접 받아 우선변제에 충당할 권리를 준다.","c":"상","v":1},"공인회2018_53-11-2":{"w":"상법 제340조의2 제4항 제2호가 자기주식을 양도하는 경우 행사가액은 부여일 기준 주식의 실질가액 이상이어야 한다고 정한다. 신주를 발행하면 실질가액과 권면액 중 높은 금액 이상이다(제1호).","c":"상","v":1},"공인회2017_52-19-2":{"w":"상법 제341조의2 제2호가 회사 권리 실행의 목적 달성에 필요한 경우 제341조에도 불구하고 자기주식을 취득할 수 있게 하므로 배당가능이익 한도가 적용되지 않는다.","c":"상","v":1},"공인회2017_52-19-3":{"w":"상법 제335조 제3항 단서가 회사 성립 후 또는 신주 납입기일 후 6월이 지난 뒤의 주권 발행 전 양도는 회사에 효력이 있다고 정한다.","c":"상","v":1},"공인회2017_52-19-4":{"w":"포괄적 교환으로 취득한 모회사 주식은 예외적 취득이므로(상법 제342조의2 제1항 제1호) 취득한 날부터 6월 내에 처분해야 한다(같은 조 제2항).","c":"상","v":1},"공인회2017_52-19-5":{"w":"상법 제342조의3이 다른 회사 발행주식총수의 10분의 1을 초과하여 취득하면 지체 없이 통지하도록 정한다.","c":"상","v":1},"공인회2017_52-27-2":{"w":"주식 양도담보는 상법에 규정이 없지만 관습법상 인정된다. 명의개서 없이 주권만 교부하는 약식양도담보와 명의개서까지 하는 등록양도담보가 모두 쓰인다.","c":"중","v":1},"공인회2017_52-27-3":{"w":"상법 제340조 제1항이 등록질권자에게 잔여재산분배금을 직접 받아 우선변제에 충당할 권리를 준다.","c":"상","v":1},"공인회2017_52-27-4":{"w":"자기주식 질취는 발행주식총수의 20분의 1이 한도지만 합병이나 다른 회사 영업전부 양수(제341조의2 제1호), 권리 실행(제2호)의 경우에는 한도를 넘을 수 있다(상법 제341조의3).","c":"상","v":1},"공인회2017_52-27-5":{"w":"상법 제339조가 소각, 병합, 분할, 전환으로 종전 주주가 받을 금전이나 주식에 질권의 효력이 미치게 한다.","c":"상","v":1},"공인회2016_51-10-1":{"w":"상법 제343조 제1항 단서가 이사회 결의로 회사가 보유한 자기주식을 소각하는 경우에는 자본금 감소 규정을 따르지 않아도 된다고 정한다.","c":"상","v":1},"공인회2016_51-10-2":{"w":"주식분할은 주주총회 특별결의로 하고(상법 제329조의2 제1항), 액면주식의 1주 금액은 정관의 절대적 기재사항이므로(제289조 제1항 제4호) 분할하려면 정관도 변경해야 한다.","c":"중","v":1},"공인회2016_51-10-3":{"w":"상법 제339조가 주식 분할로 종전 주주가 받을 주식에도 질권을 행사할 수 있게 한다.","c":"상","v":1},"공인회2016_51-10-4":{"w":"주식분할은 액면을 나누어 주식 수만 늘리는 것이다. 액면주식의 자본금은 발행주식의 액면총액이므로(상법 제451조 제1항) 총액은 그대로다.","c":"상","v":1},"공인회2017_52-26-1":{"w":"상법 제329조 제3항이 액면주식 1주의 금액은 100원 이상으로 하도록 정한다. 액면초과액은 자본거래에서 생긴 잉여금이어서 자본준비금으로 적립한다(제459조 제1항).","c":"상","v":1},"공인회2017_52-26-2":{"w":"상법 제451조 제2항이 무액면주식의 자본금을 발행가액의 2분의 1 이상으로서 이사회(또는 주주총회)가 자본금으로 계상한 금액의 총액으로 정한다.","c":"상","v":1},"공인회2017_52-26-3":{"w":"상법 제329조 제1항이 정관으로 액면주식 또는 무액면주식을 선택해 발행하도록 하면서 무액면주식을 발행하면 액면주식을 발행할 수 없다고 정한다.","c":"상","v":1},"공인회2017_52-26-4":{"w":"상법 제440조가 주식을 병합하면 1월 이상의 기간을 정해 주권 제출을 공고하고 주주와 질권자에게 각별로 통지하도록 정한다. 무액면주식 병합도 같다.","c":"상","v":1},"공인회2025_60-13-1":{"w":"상법 제329조의2 제1항이 주주총회 특별결의로 주식을 분할할 수 있게 한다.","c":"상","v":1},"공인회2025_60-13-2":{"w":"2014년 개정으로 무기명주식 규정(구 제357조)이 삭제되어 지금 주식회사는 기명주식만 발행할 수 있다.","c":"상","v":1},"공인회2025_60-13-3":{"w":"상법 제340조 제1항이 등록질권자는 회사에서 이익배당금 등을 직접 받아 다른 채권자보다 먼저 자기 채권의 변제에 충당할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-13-5":{"w":"상법 제333조 제3항이 공유자가 권리행사자를 정하지 않으면 공유자에 대한 통지나 최고는 그 1인에게 하면 된다고 정한다.","c":"상","v":1},"공인회2019_54-19-1":{"w":"상법 제352조의2가 정관으로 전자주주명부를 작성할 수 있게 하고(제1항) 거기에 전자우편주소를 적도록 정한다(제2항).","c":"상","v":1},"공인회2019_54-19-2":{"w":"상법 제354조 제1항·제2항이 권리행사자를 정하기 위해 3월 이내의 기간을 정해 주주명부 기재변경을 정지할 수 있게 한다.","c":"상","v":1},"공인회2019_54-19-4":{"w":"판례는 주주의 주주명부 열람·등사청구에 대해 회사가 그 청구에 정당한 목적이 없다는 점을 증명하면 거절할 수 있다고 본다(상법 제396조 제2항).","c":"상","v":1},"공인회2019_54-19-5":{"w":"상법 제353조 제1항이 주주나 질권자에 대한 통지·최고는 주주명부상 주소 또는 그 자가 회사에 통지한 주소로 하면 된다고 정한다.","c":"상","v":1},"공인회2019_54-12-1":{"w":"전원합의체 판례(2017년)는 주주명부에 적힌 자만 회사에 주주권을 행사할 수 있고 회사도 명부에 기재되지 않은 자의 주주권 행사를 인정할 수 없다고 본다. 명의개서를 부당하게 거절·지연한 경우 등 특별한 사정만 예외다.","c":"상","v":1},"공인회2019_54-12-3":{"w":"판례는 회사가 정당한 사유 없이 명의개서를 거절하거나 지연하면 양수인이 명의개서 없이도 회사에 주주권을 행사할 수 있다고 본다.","c":"상","v":1},"공인회2019_54-12-4":{"w":"판례는 주주명부 기재에 자격수여적 효력이 있어 명부상 주주는 실질적 권리를 증명하지 않고 권리를 행사한다고 본다. 기재만으로 주주가 되는 창설적 효력은 없다.","c":"상","v":1},"공인회2019_54-12-5":{"w":"판례는 명의개서 청구는 주식을 취득한 자가 회사에 하는 것이어서 양도인은 특별한 사정이 없으면 양수인 명의로 명의개서해 달라고 회사에 청구할 권리가 없다고 본다.","c":"상","v":1},"공인회2017_52-25-2":{"w":"상법 제360조의24 제2항 후단이 회사 아닌 주주가 발행주식총수의 50%를 초과하여 가진 회사의 보유주식도 그 주주의 보유주식과 합산한다고 정한다.","c":"상","v":1},"공인회2026_61-17-1":{"w":"상법 제360조의25 제1항이 소수주주는 언제든지 지배주주에게 매수를 청구할 수 있다고 정한다. 경영상 목적 요건은 지배주주의 매도청구(제360조의24 제1항)에만 있다.","c":"상","v":1},"공인회2026_61-17-3":{"w":"상법 제360조의25 제2항이 매수청구를 받은 지배주주는 청구일 기준 2개월 내에 주식을 매수하도록 정한다.","c":"상","v":1},"공인회2026_61-17-4":{"w":"상법 제360조의24 제8항이 매도청구일부터 30일 내에 매매가액 협의가 안 되면 소수주주나 지배주주가 법원에 결정을 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-17-5":{"w":"상법 제360조의26 제1항이 지배주주가 매매가액을 지급한 때 주식이 이전된 것으로 본다고 정한다. 공탁하면 공탁한 날에 이전된다(제2항).","c":"상","v":1},"공인회2021_56-15-1":{"w":"판례는 회사 성립 후 6월이 지난 뒤의 주권 발행 전 주식양도를 지명채권 양도 원칙에 따라 당사자 의사표시만으로 효력이 생긴다고 본다.","c":"상","v":1},"공인회2021_56-15-3":{"w":"판례는 주권 발행 전 주식양도를 회사 이외의 제3자에게 대항하려면 지명채권 양도에 준하여 확정일자 있는 증서에 의한 통지나 승낙이 있어야 한다고 본다(민법 제450조 제2항).","c":"상","v":1},"공인회2021_56-15-4":{"w":"판례는 이중양수인 사이의 우열을 확정일자 있는 통지의 도달 일시나 확정일자 있는 승낙 일시의 선후로 정한다.","c":"상","v":1},"공인회2021_56-15-5":{"w":"판례는 6월 경과 전의 주권 발행 전 양도도 그 후 6월이 지날 때까지 회사가 주권을 발행하지 않으면 하자가 치유되어 회사에 유효하다고 본다(상법 제335조 제3항).","c":"상","v":1},"공인회2024_59-14-1":{"w":"상법 제329조의2 제1항이 주식분할을 주주총회 특별결의(제434조) 사항으로 정한다.","c":"상","v":1},"공인회2017_52-20-2":{"w":"상법 제377조 제1항이 주주가 결의취소의 소를 제기하면 법원이 회사의 청구로 담보 제공을 명할 수 있다고 정한다. 그 주주가 이사나 감사이면 예외이고 회사는 주주의 악의를 소명해야 한다(제2항, 제176조 제4항).","c":"상","v":1},"공인회2017_52-20-3":{"w":"결의취소 판결은 소급효가 있으므로(상법 제376조 제2항이 제190조 단서를 준용하지 않음) 판례는 취소된 결의로 선임된 이사가 대표이사로서 한 행위도 소급하여 무효가 된다고 본다. 상대방은 부실등기 책임(제39조) 등으로 보호될 수 있다.","c":"상","v":1},"공인회2017_52-20-4":{"w":"우선주 배당률을 낮추는 정관변경은 우선주주에게 손해를 미치므로 주주총회 결의 외에 우선주 종류주주총회 결의가 있어야 효력이 생긴다(상법 제435조 제1항).","c":"상","v":1},"공인회2017_52-20-5":{"w":"판례는 대표이사가 아닌 이사가 이사회 소집결의에 따라 주주총회를 소집했다면 소집권한 없는 자의 소집이긴 하지만 이사회 결의가 있었으므로 결의취소사유에 그치고 부존재사유는 아니라고 본다.","c":"상","v":1},"공인회2022_57-18-1":{"w":"상법 제368조의4 제1항이 회사는 이사회 결의로 전자투표를 정할 수 있다고 정한다. 정관 근거는 필요 없다.","c":"상","v":1},"공인회2022_57-18-2":{"w":"상법 제368조의4 제2항이 소집통지에 전자적 방법으로 의결권을 행사할 수 있다는 내용을 적도록 정한다.","c":"상","v":1},"공인회2022_57-18-3":{"w":"상법 제368조의4 제3항 후단이 전자투표를 정한 회사에 의결권 행사 양식과 참고자료를 전자적 방법으로 제공하도록 정한다.","c":"상","v":1},"공인회2022_57-18-5":{"w":"상법 제368조의4 제5항이 전자적 기록을 총회 후 3개월간 본점에 비치·열람하게 하고 5년간 보존하도록 정한다.","c":"상","v":1},"공인회2025_60-21-1":{"w":"특별이해관계로 인한 의결권 제한(상법 제368조 제3항)은 결의마다 판단하므로 이해관계가 있는 그 결의에서만 의결권을 행사하지 못한다.","c":"상","v":1},"공인회2025_60-21-2":{"w":"감사 선임은 보통결의(상법 제368조 제1항, 제409조 제1항)로 하고 서면투표 허용 여부는 결의 요건을 바꾸지 않는다. 출석 과반수만으로 선임할 수 있는 특례는 전자투표를 허용한 경우다(제409조 제3항).","c":"상","v":1},"공인회2025_60-21-3":{"w":"상법 제368조 제2항이 대리인은 대리권을 증명하는 서면을 총회에 제출하도록 정한다. 2025년 개정으로 전자문서로도 제출할 수 있다.","c":"상","v":1},"공인회2025_60-21-4":{"w":"상법 제369조 제3항이 회사(모회사·자회사 포함)가 다른 회사 주식의 10분의 1을 초과하여 가지면 그 다른 회사가 가진 회사 또는 모회사 주식은 의결권이 없다고 정한다.","c":"상","v":1},"공인회2016_51-16-1":{"w":"회사가 주주 개인의 영업을 양수하는 결의에서 그 주주는 개인적 이해관계를 가진 특별이해관계인이므로 의결권을 행사하지 못한다(상법 제368조 제3항).","c":"상","v":1},"공인회2016_51-16-3":{"w":"특별이해관계는 주주의 지위와 관계없는 개인적 이해관계를 말하므로 자신을 이사로 선임하는 결의는 여기에 해당하지 않는다는 것이 통설·판례다. C는 의결권을 행사할 수 있다(상법 제368조 제3항).","c":"중","v":1},"공인회2016_51-16-4":{"w":"판례는 정관이 대리인 자격을 주주로 한정해도 법인 주주가 그 직원이나 피용자에게 의결권을 대리행사하게 하는 것은 허용된다고 본다. 회사 측에 위험이 없고 막으면 법인 주주의 의결권 행사가 사실상 봉쇄되기 때문이다.","c":"상","v":1},"공인회2016_51-16-5":{"w":"이사 해임은 회사 지배에 관한 결의여서 해임 대상인 주주이자 이사는 특별이해관계인이 아니라는 것이 통설이다. B는 의결권을 행사할 수 있다(상법 제368조 제3항).","c":"중","v":1},"공인회2016_51-17-1":{"w":"甲이 乙 주식의 10분의 1을 초과하여 가지므로 乙이 가진 甲 주식은 의결권이 없고(상법 제369조 제3항), 그 주식 수는 甲의 총회 결의에서 발행주식총수에 산입하지 않는다(제371조 제1항).","c":"상","v":1},"공인회2021_56-17-2":{"w":"상법 제365조 제2항이 연 2회 이상 결산기를 정한 회사는 매기에 정기총회를 소집하도록 정한다.","c":"상","v":1},"공인회2021_56-17-3":{"w":"상법 제366조 제1항이 3% 이상 주주에게 목적사항과 소집이유를 적은 서면 또는 전자문서를 이사회에 제출해 임시총회 소집을 청구할 권리를 준다.","c":"상","v":1},"공인회2021_56-17-4":{"w":"상법 제367조 제2항이 회사 또는 1% 이상 주주가 총회 전에 소집절차나 결의방법의 적법성 조사를 위한 검사인 선임을 법원에 청구할 수 있게 한다.","c":"상","v":1},"공인회2021_56-17-5":{"w":"판례는 이사회 결의와 소집절차가 없었더라도 주주 전원이 참석해 총회 개최에 동의하고 이의 없이 만장일치로 결의했다면 그 결의는 특별한 사정이 없는 한 유효하다고 본다(전원출석총회).","c":"상","v":1},"공인회2017_52-16-1":{"w":"상법 제365조 제1항·제2항이 정기총회는 매년 1회 일정 시기에 소집하되 연 2회 이상 결산기를 정하면 매기에 소집하도록 정한다.","c":"상","v":1},"공인회2017_52-16-2":{"w":"상법 제366조 제1항의 소수주주 소집청구권이다. 이사회가 지체 없이 소집하지 않으면 법원 허가를 받아 직접 소집할 수 있다(제2항).","c":"상","v":1},"공인회2017_52-16-4":{"w":"판례는 이미 통지한 주주총회 소집을 철회하거나 연기하려면 소집과 같이 이사회 결의를 거쳐 대표이사가 소집과 같은 방법으로 통지해야 한다고 본다.","c":"상","v":1},"공인회2017_52-16-5":{"w":"판례가 인정하는 전원출석총회 법리다. 주주명부상 주주 전원이 출석해 동의하고 이의 없이 만장일치로 결의하면 소집절차 하자는 문제 되지 않는다.","c":"상","v":1},"공인회2023_58-19-2":{"w":"상법 제409조 제3항이 전자투표를 허용한 회사는 발행주식총수 4분의 1 요건 없이 출석 의결권의 과반수로 감사를 선임할 수 있다고 정한다.","c":"상","v":1},"공인회2023_58-19-3":{"w":"상법 제435조 제1항이 정관변경으로 손해를 입는 종류주주의 총회 결의를 추가로 요구한다.","c":"상","v":1},"공인회2023_58-19-4":{"w":"상법 제365조 제2항이 연 2회 이상 결산기를 정한 회사에 매기 정기총회 소집을 요구한다.","c":"상","v":1},"공인회2023_58-19-5":{"w":"자기주식은 의결권이 없고(상법 제369조 제2항) 총회 결의에서 그 수를 발행주식총수에 산입하지 않는다(제371조 제1항).","c":"상","v":1},"공인회2026_61-19-1":{"w":"상법 제368조의2 제2항이 신탁 인수 등 타인을 위하여 주식을 가진 경우 외에는 회사가 불통일행사를 거부할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-19-2":{"w":"특별이해관계인은 의결권을 행사하지 못하고(상법 제368조 제3항), 그 의결권 수는 출석한 주주의 의결권 수에 산입하지 않는다(제371조 제2항).","c":"상","v":1},"공인회2026_61-19-4":{"w":"상법 제368조 제1항이 보통결의 요건을 출석 의결권의 과반수와 발행주식총수의 4분의 1 이상으로 정한다. 상법이나 정관에 다른 정함이 있으면 그에 따른다.","c":"상","v":1},"공인회2026_61-19-5":{"w":"상법 제368조의3 제1항이 정관으로 서면투표를 허용할 수 있게 한다. 같은 조 제2항은 소집통지서에 행사에 필요한 서면과 참고자료를 첨부하도록 정한다.","c":"상","v":1},"공인회2016_51-18-1":{"w":"판례는 결의취소의 소에서 주주는 다른 주주에 대한 소집절차 하자를 이유로도 소를 제기할 수 있다고 본다. 자신이 통지를 받고 참석했어도 제소권이 있다(상법 제376조 제1항).","c":"상","v":1},"공인회2016_51-18-2":{"w":"판례는 결의취소의 소 제소권자인 주주는 제소 당시 주주이면 되고 결의 당시 주주였을 필요는 없다고 본다.","c":"상","v":1},"공인회2016_51-18-3":{"w":"판례는 결의취소의 소의 피고는 회사로 한정되고 선임된 이사 개인은 피고가 될 수 없다고 본다.","c":"상","v":1},"공인회2016_51-18-5":{"w":"상법 제376조 제2항이 제190조 본문만 준용하므로 취소판결은 제3자에게도 효력이 있고(대세효), 판결의 효력을 장래로 한정하는 제190조 단서는 준용되지 않아 소급효가 있다.","c":"상","v":1},"공인회2025_60-24-2":{"w":"판례는 종류주주총회 결의를 정관변경의 효력발생요건으로 본다. 그 결의가 없으면 정관변경이 효력을 발생하지 못하는 상태가 될 뿐 주주총회 결의 자체에 하자가 있는 것은 아니다.","c":"상","v":1},"공인회2025_60-24-3":{"w":"상법 제436조가 회사 분할·분할합병, 주식교환·이전, 합병으로 어느 종류주주에게 손해를 미치는 경우에 제435조를 준용해 종류주주총회 결의를 요구한다.","c":"상","v":1},"공인회2025_60-24-4":{"w":"상법 제435조 제2항이 종류주주총회 결의를 출석 주식 의결권의 3분의 2 이상과 그 종류 발행주식총수의 3분의 1 이상으로 하도록 정한다.","c":"상","v":1},"공인회2025_60-24-5":{"w":"상법 제435조 제1항이 정관변경으로 어느 종류주주에게 손해를 미치면 주주총회 결의 외에 그 종류주주총회 결의를 요구한다.","c":"상","v":1},"공인회2024_59-18-1":{"w":"상법 제368조 제3항이 특별이해관계 있는 자의 의결권 행사를 금지한다.","c":"상","v":1},"공인회2024_59-18-2":{"w":"상법 제368조의2 제2항이 주식 신탁 인수 등 타인을 위하여 주식을 가진 경우에는 회사가 불통일행사를 거부할 수 없게 한다.","c":"상","v":1},"공인회2024_59-18-3":{"w":"상법 제368조의4 제4항이 같은 주식에 대해서는 전자적 방법과 서면 중 하나를 선택하도록 정한다.","c":"상","v":1},"공인회2024_59-18-5":{"w":"상법 제368조의3 제2항이 서면투표를 허용한 회사는 소집통지서에 필요한 서면과 참고자료를 첨부하도록 정한다.","c":"상","v":1},"공인회2023_58-24-1":{"w":"상법 제363조의2 제1항이 의결권 없는 주식을 제외한 발행주식총수의 3% 이상 주주에게 주주제안권을 준다.","c":"상","v":1},"공인회2023_58-24-2":{"w":"상장회사 특례(상법 제542조의6 제2항)는 6개월 보유를 요구하지만 일반 규정인 제363조의2의 3% 요건을 갖추면 보유기간과 관계없이 제안할 수 있다(제542조의6 제10항).","c":"상","v":1},"공인회2023_58-24-3":{"w":"상법 제363조의2 제1항·제2항이 주주총회일 6주 전에 서면 또는 전자문서로 목적사항 추가와 의안 요령의 소집통지 기재를 청구할 수 있게 한다.","c":"상","v":1},"공인회2023_58-24-5":{"w":"상법 제363조의2 제3항 후단이 제안 주주의 청구가 있으면 총회에서 그 의안을 설명할 기회를 주도록 정한다.","c":"상","v":1},"공인회2019_54-21-2":{"w":"재무제표 승인 후 2년 내 다른 결의가 없으면 이사·감사의 책임이 해제된 것으로 보는데(상법 제450조), 그 감사의 책임을 추궁하는 결의에서 감사인 주주는 개인적 이해관계가 있어 특별이해관계인이 된다(제368조 제3항).","c":"중","v":1},"공인회2019_54-21-3":{"w":"판례는 이사선임 결의가 취소되면 그 이사들로 구성된 이사회에서 선정된 대표이사도 소급하여 자격을 잃는다고 본다. 취소판결에 소급효가 있기 때문이다.","c":"상","v":1},"공인회2019_54-21-4":{"w":"판례는 여러 안건이 각각 결의된 경우 결의취소의 소의 2월 제소기간(상법 제376조 제1항) 준수 여부를 각 결의마다 따로 판단한다.","c":"상","v":1},"공인회2019_54-21-5":{"w":"상법 제377조 제1항이 주주의 결의취소 제소에 대한 담보제공명령과 이사·감사인 주주의 예외를 정한다.","c":"상","v":1},"공인회2020_55-22-1":{"w":"상법 제376조 제1항이 소집절차·결의방법의 법령·정관 위반이나 현저한 불공정, 결의내용의 정관 위반을 결의취소 사유로 하고 제소기간을 결의일부터 2월로 정한다.","c":"상","v":1},"공인회2020_55-22-3":{"w":"상법 제376조 제1항이 결의취소의 소 제소권자를 주주, 이사, 감사로 한정한다.","c":"상","v":1},"공인회2020_55-22-5":{"w":"결의취소 판결과 무효확인 판결에는 제190조 본문이 준용되어 대세효가 있다. 같은 조 단서는 준용되지 않으므로 소급효도 있다(상법 제376조 제2항, 제380조).","c":"상","v":1},"공인회2023_58-21-2":{"w":"상법 제380조가 결의내용이 법령에 위반한 경우 결의무효확인의 소를 인정한다. 제소권자와 제소기간에 제한이 없다.","c":"상","v":1},"공인회2023_58-21-3":{"w":"결의방법의 법령 위반은 취소사유이고 주주·이사·감사가 결의일부터 2월 내에 소를 제기할 수 있다(상법 제376조 제1항).","c":"상","v":1},"공인회2023_58-21-5":{"w":"상법 제376조 제2항이 제190조 본문을 준용해 대세효를 준다. 단서를 준용하지 않으므로 소급효가 있다.","c":"상","v":1},"공인회2025_60-20-3":{"w":"상법 제407조 제1항이 이사선임결의의 무효·취소의 소나 이사해임의 소가 제기되면 법원이 가처분으로 직무집행을 정지하거나 직무대행자를 선임할 수 있다고 정한다. 판례는 결의부존재확인의 소에도 같다고 본다.","c":"상","v":1},"공인회2026_61-20-1":{"w":"상법 제376조 제1항이 소집절차나 결의방법의 법령·정관 위반을 결의취소 사유로, 주주·이사·감사를 제소권자로, 결의일부터 2월을 제소기간으로 정한다.","c":"상","v":1},"공인회2026_61-20-2":{"w":"판례는 이사 지위에서 제기한 결의취소의 소는 그 지위가 일신전속적이어서 이사가 사망하면 상속되지 않고 소송이 중단 없이 종료된다고 본다.","c":"상","v":1},"공인회2026_61-20-3":{"w":"상법 제380조가 소집절차나 결의방법에 결의가 존재한다고 볼 수 없을 정도의 중대한 하자가 있으면 결의부존재확인의 소를 인정한다.","c":"상","v":1},"공인회2026_61-20-5":{"w":"상법 제379조가 결의취소의 소에서 법원의 재량기각을 인정한다.","c":"상","v":1},"공인회2024_59-20-2":{"w":"판례는 여러 안건에 대한 각 결의의 취소 제소기간을 안건별로 따로 판단한다. 한 결의에 대한 소를 제기했다고 다른 결의의 제소기간이 지켜지는 것은 아니다.","c":"상","v":1},"공인회2024_59-20-3":{"w":"상법 제381조 제2항이 제376조 제1항을 준용하므로 부당결의 취소·변경의 소도 결의일부터 2월 내에 제기해야 한다.","c":"상","v":1},"공인회2024_59-20-4":{"w":"상법 제380조가 결의부존재확인의 소에 제377조의 담보제공 규정을 준용한다. 이사나 감사인 주주에게는 담보제공을 명할 수 없다.","c":"상","v":1},"공인회2024_59-20-5":{"w":"결의취소의 소의 피고는 회사다. 감사가 제소했으면 이사와 회사 사이의 소가 아니므로 대표이사가 회사를 대표하고(상법 제389조 제3항, 제209조) 이사가 제소한 경우에만 감사가 회사를 대표한다(제394조 제1항).","c":"상","v":1},"공인회2019_54-15-1":{"w":"상법 제368조의3 제1항이 정관으로 정하면 주주가 출석하지 않고 서면으로 의결권을 행사할 수 있게 한다.","c":"상","v":1},"공인회2019_54-15-2":{"w":"상법 제368조의4 제1항이 전자투표를 이사회 결의로 정할 수 있게 한다. 서면투표와 달리 정관 근거가 필요 없다.","c":"상","v":1},"공인회2019_54-15-4":{"w":"상법 제368조 제2항 후단이 대리인에게 대리권을 증명하는 서면(2025년 개정 후 전자문서 포함)을 총회에 제출하도록 정한다.","c":"상","v":1},"공인회2019_54-15-5":{"w":"판례는 3일 전 통지 기간(상법 제368조의2 제1항)은 회사의 사무처리 편의를 위한 것이어서 늦게 도착한 불통일행사 통지를 회사가 받아들였다면 주주평등원칙을 해치는 등 특별한 사정이 없는 한 위법이 아니라고 본다.","c":"상","v":1},"공인회2021_56-18-1":{"w":"상법 제368조 제1항이 보통결의를 출석 의결권 과반수와 발행주식총수 4분의 1 이상으로 하도록 정한다.","c":"상","v":1},"공인회2021_56-18-2":{"w":"상법 제368조 제2항이 의결권 대리행사와 대리권 증명 서면 제출을 정한다.","c":"상","v":1},"공인회2021_56-18-3":{"w":"상법 제368조의2 제1항이 불통일행사를 허용하고 총회일 3일 전에 서면 또는 전자문서로 그 뜻과 이유를 통지하도록 정한다.","c":"상","v":1},"공인회2021_56-18-4":{"w":"상법 제368조의3 제1항·제2항이 서면투표의 근거와 소집통지서 첨부 의무를 정한다.","c":"상","v":1},"공인회2022_57-17-1":{"w":"상법 제368조 제1항이 보통결의 요건에 정관으로 달리 정할 여지를 두고 있으므로 정관으로 의사정족수를 두는 것도 가능하다는 것이 판례·통설이다.","c":"중","v":1},"공인회2022_57-17-3":{"w":"상법 제374조 제1항 제3호가 회사 영업에 중대한 영향을 미치는 다른 회사 영업 일부의 양수를 주주총회 특별결의 사항으로 정한다.","c":"상","v":1},"공인회2022_57-17-4":{"w":"판례는 영업용 재산의 양도라도 그로 인해 회사 영업의 전부 또는 중요한 일부를 양도하거나 폐지하는 것과 같은 결과를 가져오면 상법 제374조 제1항 제1호를 유추해 특별결의가 필요하다고 본다.","c":"상","v":1},"공인회2022_57-17-5":{"w":"상법 제374조의3 제1항이 상대방이 발행주식총수의 90% 이상을 가지면 영업 전부의 임대 등에 대한 주주총회 승인을 이사회 승인으로 갈음할 수 있게 한다.","c":"상","v":1},"공인회2021_56-19-1":{"w":"상법 제376조 제2항이 제186조를 준용해 결의취소의 소를 본점 소재지 지방법원의 전속관할로 한다.","c":"상","v":1},"공인회2021_56-19-3":{"w":"상법 제380조가 결의내용의 법령 위반을 결의무효확인의 소의 사유로 정한다.","c":"상","v":1},"공인회2021_56-19-4":{"w":"상법 제380조가 소집절차나 결의방법에 결의가 존재한다고 볼 수 없을 정도의 중대한 하자가 있으면 결의부존재확인의 소를 인정한다.","c":"상","v":1},"공인회2021_56-19-5":{"w":"상법 제381조 제2항이 제190조 본문을 준용하므로 부당결의 취소·변경 판결도 제3자에게 효력이 있다.","c":"상","v":1},"공인회2024_59-17-1":{"w":"상법 제363조 제1항 단서가 주주명부상 주소로 보낸 통지가 3년간 계속 도달하지 않으면 그 주주에게 소집통지를 하지 않아도 된다고 정한다.","c":"상","v":1},"공인회2024_59-17-2":{"w":"상법 제363조 제3항이 자본금 10억원 미만 회사는 총회일 10일 전에 서면 또는 동의를 받은 전자문서로 통지를 발송할 수 있게 한다.","c":"상","v":1},"공인회2024_59-17-3":{"w":"상법 제363조 제4항이 자본금 10억원 미만 회사는 주주 전원이 동의하면 소집절차 없이 총회를 열 수 있게 한다.","c":"상","v":1},"공인회2024_59-17-4":{"w":"상법 제542조의4 제1항과 같은 법 시행령(의결권 있는 발행주식총수의 1% 이하)이 소액주주에 대해 정관에 따라 2주 전 둘 이상 일간신문 각 2회 이상 공고나 전자적 공고로 소집통지를 갈음할 수 있게 한다.","c":"상","v":1},"공인회2020_55-18-1":{"w":"상법 제364조 제1항이 정관에 달리 정한 바가 없으면 본점 소재지나 인접한 곳에 소집하도록 정한다.","c":"상","v":1},"공인회2020_55-18-2":{"w":"상법 제363조 제2항이 소집 통지서에 회의의 목적사항을 적도록 정한다.","c":"상","v":1},"공인회2020_55-18-3":{"w":"판례는 이사회 결의와 소집절차 없이 열린 임시총회라도 주주명부상 주주 전원이 참석해 개최에 동의하고 이의 없이 만장일치로 결의했다면 특별한 사정이 없는 한 유효하다고 본다(전원출석총회).","c":"상","v":1},"공인회2020_55-18-4":{"w":"상법 제363조 제4항 전단이 자본금 10억원 미만 회사는 주주 전원 동의로 소집절차 없이 총회를 열 수 있게 한다.","c":"상","v":1},"공인회2016_51-22-1":{"w":"판례는 직무집행정지 가처분에 대세적 효력이 있어 가처분이 취소되지 않는 한 후임 대표이사를 선임해도 그 후임자는 대표이사 권한을 갖지 못한다고 본다. 그가 한 행위는 제3자에 대한 관계에서도 무효다.","c":"상","v":1},"공인회2016_51-22-2":{"w":"상법 제407조 제1항 후단이 급박한 사정이 있으면 본안소송 제기 전에도 직무집행정지·직무대행자 선임 가처분을 할 수 있다고 정한다.","c":"상","v":1},"공인회2016_51-22-4":{"w":"상법 제408조 제1항이 직무대행자는 가처분명령에 다른 정함이 있거나 법원 허가를 얻은 경우 외에는 회사의 상무에 속하지 않는 행위를 하지 못한다고 정한다.","c":"상","v":1},"공인회2016_51-22-5":{"w":"영업양도는 상무가 아니어서 직무대행자가 법원 허가 없이 하면 상법 제408조 제1항 위반이다. 그래도 회사는 선의의 제3자에게 책임을 진다(같은 조 제2항).","c":"상","v":1},"공인회2016_51-23-1":{"w":"분식결산은 법령 위반 행위이므로 대표이사는 상법 제399조 제1항에 따라 회사에 손해를 배상해야 한다. 판례는 그로 인해 회사가 낸 과징금 상당액도 배상할 손해에 포함된다고 본다.","c":"상","v":1},"공인회2016_51-23-2":{"w":"판례는 이사가 법령에 위반한 행위를 하면 그 자체가 임무 해태이고 경영판단의 원칙이 적용되지 않는다고 본다. 분식결산은 법령 위반이므로 경영판단을 내세워 면책될 수 없다.","c":"상","v":1},"공인회2016_51-23-4":{"w":"회사에 대한 영향력을 이용해 이사에게 업무집행을 지시한 자는 그 업무에 관하여 이사로 보아 회사에 손해배상책임을 진다(상법 제401조의2 제1항 제1호, 업무집행지시자).","c":"상","v":1},"공인회2016_51-23-5":{"w":"이사가 아니면서 상무 등 업무집행 권한이 있는 것으로 인정될 만한 명칭으로 회사 업무를 집행한 자는 이사로 보아 책임을 진다(상법 제401조의2 제1항 제3호, 표현이사).","c":"상","v":1},"공인회2020_55-20-1":{"w":"이사는 주주총회 보통결의로 선임하고(상법 제382조 제1항, 제368조 제1항), 해임은 제434조의 특별결의로 한다(제385조 제1항).","c":"상","v":1},"공인회2020_55-20-3":{"w":"상법 제385조 제1항 단서가 임기를 정한 이사를 정당한 이유 없이 임기 만료 전에 해임하면 그 이사가 회사에 손해배상을 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2020_55-20-4":{"w":"상법 제387조가 정관으로 이사가 가질 주식 수(자격주)를 정하면 다른 규정이 없는 한 그 주권을 감사에게 공탁하도록 정한다.","c":"상","v":1},"공인회2020_55-20-5":{"w":"상법 제386조 제2항이 법률이나 정관의 이사 원수를 결한 경우 법원이 이해관계인의 청구로 일시이사를 선임할 수 있게 한다.","c":"상","v":1},"공인회2021_56-24-1":{"w":"상법 제400조 제1항이 제399조에 따른 이사의 회사에 대한 책임은 주주 전원의 동의로 면제할 수 있다고 정한다.","c":"상","v":1},"공인회2021_56-24-2":{"w":"상법 제401조의2 제2항이 업무집행지시자 등이 책임질 때 그 지시받은 행위로 책임지는 이사와 연대하도록 정한다.","c":"상","v":1},"공인회2021_56-24-4":{"w":"상법 제403조 제1항이 1% 이상 주주에게 회사에 이사 책임 추궁의 소 제기를 청구할 권리를 준다. 회사가 30일 내에 소를 제기하지 않으면 주주가 대표소송을 할 수 있다(제3항).","c":"상","v":1},"공인회2021_56-24-5":{"w":"상법 제402조가 이사의 법령·정관 위반 행위로 회복할 수 없는 손해가 생길 염려가 있으면 감사 또는 1% 이상 주주가 회사를 위하여 유지를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-25-2":{"w":"판례는 상법 제395조가 이사 자격을 요건으로 하지만 회사가 이사 자격 없는 자에게 대표이사 같은 명칭 사용을 허용한 경우에도 유추적용된다고 본다.","c":"상","v":1},"공인회2026_61-25-3":{"w":"상법 제389조 제1항이 이사회 결의로 대표이사를 선정하되 정관으로 주주총회에서 선정하도록 정할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-25-4":{"w":"상법 제408조의3 제1항이 집행임원 임기는 정관에 다른 규정이 없으면 2년을 넘지 못한다고 정한다.","c":"상","v":1},"공인회2026_61-25-5":{"w":"상법 제408조의2 제1항 후단이 집행임원을 둔 회사는 대표이사를 두지 못한다고 정한다. 대표집행임원이 회사를 대표한다(제408조의5).","c":"상","v":1},"공인회2024_59-21-1":{"w":"이사 선임은 주주총회 보통결의(상법 제382조 제1항, 제368조 제1항)로 한다. 출석 의결권 과반수와 발행주식총수 4분의 1 이상이 필요하다.","c":"상","v":1},"공인회2024_59-21-2":{"w":"상법 제383조 제2항이 이사 임기는 3년을 넘지 못한다고 정한다. 같은 조 제3항은 정관으로 임기 중 최종 결산기에 관한 정기총회 종결 때까지 연장할 수 있게 한다.","c":"상","v":1},"공인회2024_59-21-4":{"w":"상법 제407조 제1항이 이사해임의 소가 제기되면 법원이 당사자 신청으로 가처분으로 직무집행을 정지하거나 직무대행자를 선임할 수 있게 한다.","c":"상","v":1},"공인회2024_59-21-5":{"w":"상법 제386조 제2항이 법률이나 정관의 이사 원수를 결한 경우 필요하면 법원이 이사, 감사 기타 이해관계인의 청구로 일시이사를 선임할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-21-1":{"w":"상법 제401조 제1항이 고의 또는 중대한 과실로 임무를 게을리한 이사에게 제3자에 대한 연대 배상책임을 지운다.","c":"상","v":1},"공인회2026_61-21-3":{"w":"상법 제401조의2 제2항이 업무집행지시자와 지시를 받은 이사의 연대책임을 정한다.","c":"상","v":1},"공인회2026_61-21-4":{"w":"상법 제399조 제3항이 이사회 결의에 참가해 이의를 한 기재가 의사록에 없는 이사는 그 결의에 찬성한 것으로 추정한다고 정한다.","c":"상","v":1},"공인회2026_61-21-5":{"w":"상법 제402조가 1% 이상 주주와 감사에게 위법행위 유지청구권을 준다.","c":"상","v":1},"공인회2025_60-23-4":{"w":"상법 제393조의2 제4항이 이사회 내 위원회는 결의 사항을 각 이사에게 통지하도록 정한다. 통지받은 이사는 이사회 소집을 요구할 수 있고 이사회는 그 결의를 다시 할 수 있다.","c":"상","v":1},"공인회2023_58-28-1":{"w":"상법 제317조 제2항 제8호·제9호가 회사를 대표할 집행임원과 집행임원의 성명·주민등록번호를 설립등기 사항으로 정한다.","c":"상","v":1},"공인회2023_58-28-2":{"w":"상법 제340조의2 제1항이 주식매수선택권 부여 대상에 이사, 감사, 피용자와 함께 집행임원을 넣는다.","c":"상","v":1},"공인회2023_58-28-3":{"w":"회사의 상무에 종사하는 집행임원은 사외이사가 될 수 없고 재직 중 이에 해당하게 되면 사외이사 직을 상실한다(상법 제382조 제3항).","c":"상","v":1},"공인회2023_58-28-5":{"w":"상법 제408조의2 제2항이 회사와 집행임원의 관계에 민법의 위임 규정을 준용한다.","c":"상","v":1},"공인회2018_53-22-2":{"w":"최대주주 본인과 그 특수관계인은 상장회사의 사외이사(2025년 개정 후 명칭은 독립이사)가 될 수 없다(상법 제542조의8 제2항 제5호). 자연인 최대주주의 배우자와 직계 존속·비속은 시행령이 정한 특수관계인에 들어간다.","c":"중","v":1},"공인회2023_58-20-1":{"w":"상법 제397조 제1항이 이사회 승인 없이 이사가 자기 또는 제3자의 계산으로 회사 영업부류에 속한 거래를 하거나 동종영업 회사의 무한책임사원·이사가 되는 것을 금지한다.","c":"상","v":1},"공인회2023_58-20-3":{"w":"상법 제382조의4가 이사는 재임 중뿐 아니라 퇴임 후에도 직무상 알게 된 회사 영업상 비밀을 누설하지 못한다고 정한다.","c":"상","v":1},"공인회2023_58-20-4":{"w":"상법 제385조 제1항이 이사는 언제든지 주주총회 특별결의로 해임할 수 있다고 정한다. 정당한 이유 없는 임기 중 해임이면 손해배상 문제가 남는다.","c":"상","v":1},"공인회2023_58-20-5":{"w":"상법 제401조 제1항이 고의 또는 중대한 과실로 임무를 게을리한 이사에게 제3자에 대한 연대 배상책임을 지운다. 경과실만으로는 제3자에게 책임지지 않는다.","c":"상","v":1},"공인회2023_58-22-2":{"w":"상법 제393조 제1항이 대규모 재산의 차입을 이사회 결의 사항으로 정한다.","c":"상","v":1},"공인회2023_58-22-3":{"w":"상법 제389조 제3항이 제209조를 준용해 대표이사에게 영업에 관한 재판상·재판외 모든 행위의 권한을 준다. 그 제한은 선의의 제3자에게 대항하지 못한다.","c":"상","v":1},"공인회2023_58-22-4":{"w":"상법 제393조 제4항이 이사는 3월에 1회 이상 업무 집행상황을 이사회에 보고하도록 정한다.","c":"상","v":1},"공인회2023_58-22-5":{"w":"상법 제389조 제1항 단서가 정관으로 주주총회에서 대표이사를 선정하도록 정할 수 있게 한다.","c":"상","v":1},"공인회2026_61-22-1":{"w":"상법 제387조가 정관으로 이사의 자격주 수를 정하면 다른 규정이 없는 한 이사가 그 주권을 감사에게 공탁하도록 정한다.","c":"상","v":1},"공인회2026_61-22-2":{"w":"상법 제382조의2 제1항이 2인 이상 이사 선임 총회에서 의결권 없는 주식을 제외한 3% 이상 주주가 정관에 달리 정함이 없으면 집중투표를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-22-3":{"w":"판례는 회사와의 약정으로 실질적 직무를 수행하지 않는 명목상 이사도 법적으로 이사인 이상 특별한 사정이 없으면 정관이나 주주총회 결의로 정한 보수를 청구할 수 있다고 본다(상법 제388조).","c":"상","v":1},"공인회2026_61-22-5":{"w":"상법 제408조 제1항이 직무대행자의 권한을 상무로 한정한다. 가처분명령에 다른 정함이 있거나 법원 허가가 있으면 예외다.","c":"상","v":1},"공인회2022_57-19-1":{"w":"상법 제389조 제3항이 준용하는 제209조 제1항에 따라 대표이사는 회사의 영업에 관한 재판상·재판외의 모든 행위를 할 권한이 있다.","c":"상","v":1},"공인회2022_57-19-2":{"w":"상법 제389조 제3항, 제209조 제2항에 따라 대표권 제한은 선의의 제3자에게 대항하지 못한다.","c":"상","v":1},"공인회2022_57-19-3":{"w":"상법 제393조 제1항이 지배인의 선임 또는 해임을 이사회 결의 사항으로 정한다.","c":"상","v":1},"공인회2022_57-19-4":{"w":"상법 제394조 제2항이 감사위원회 위원이 회사에 소를 제기하면 감사위원회 또는 이사가 법원에 회사를 대표할 자의 선임을 신청하도록 정한다.","c":"상","v":1},"공인회2021_56-21-1":{"w":"판례는 퇴직위로금도 재직 중 직무집행의 대가로 지급되는 보수의 일종으로 보아 정관이나 주주총회 결의로 정해야 한다고 본다(상법 제388조).","c":"상","v":1},"공인회2021_56-21-2":{"w":"판례는 명목상 이사도 특별한 사정이 없으면 정관이나 주주총회 결의로 정한 보수를 청구할 수 있다고 본다.","c":"상","v":1},"공인회2021_56-21-3":{"w":"판례는 이사의 보수가 직무와 합리적 비례관계를 유지해야 한다고 본다. 회사의 채무 상황이나 영업실적에 비추어 현저히 균형을 잃을 정도로 과다하면 그 결의는 회사재산의 부당한 유출이어서 효력이 없다.","c":"상","v":1},"공인회2021_56-21-5":{"w":"상법 제385조 제1항 단서가 해임 이사의 손해배상청구권을 정한다. 판례는 정당한 이유가 없었다는 점의 증명책임을 손해배상을 청구하는 이사에게 지운다.","c":"상","v":1},"공인회2019_54-24-1":{"w":"전원합의체 판례(2017년)는 이사 선임 결의와 피선임자의 승낙만 있으면 대표이사와 별도의 임용계약을 맺지 않아도 이사 지위를 취득한다고 본다.","c":"상","v":1},"공인회2019_54-24-3":{"w":"자산 2조원 이상 상장회사는 사외이사를 3명 이상이면서 이사 총수의 과반수로 두고 후보추천위원회를 설치해야 한다(상법 제542조의8 제1항 단서·제4항). 2025년 개정으로 이 사외이사의 명칭이 독립이사, 위원회가 독립이사 후보추천위원회로 바뀌었고 독립이사도 사외이사이므로 요건은 그대로 충족된다.","c":"중","v":1},"공인회2019_54-24-4":{"w":"판례는 상법 제385조 제1항 단서의 임기를 정한 경우를 정관이나 주주총회에서 임기를 정한 경우로 본다. 임기를 정하지 않았다면 최장기인 3년이 지나기 전에 해임되어도 손해배상을 청구할 수 없다.","c":"상","v":1},"공인회2019_54-24-5":{"w":"상법 제385조 제1항 본문이 이사는 언제든지 주주총회 특별결의로 해임할 수 있다고 정한다. 정당한 이유가 없으면 손해배상책임만 생긴다(단서).","c":"상","v":1},"공인회2019_54-26-3":{"w":"상법 제397조의2 제2항이 사업기회 유용으로 회사에 손해를 끼친 이사와 승인한 이사의 연대책임을 정한다. 이사 또는 제3자가 얻은 이익은 손해로 추정한다.","c":"상","v":1},"공인회2021_56-23-1":{"w":"상법 제397조 제1항이 이사회 승인 없이 동종영업을 목적으로 하는 다른 회사의 무한책임사원이나 이사가 되는 것을 금지한다(겸직금지).","c":"상","v":1},"공인회2021_56-23-2":{"w":"상법 제397조의2 제1항이 이사회 승인 없이 현재 또는 장래에 회사의 이익이 될 수 있는 사업기회 중 직무상 알게 되었거나 회사 정보를 이용한 것, 회사 사업과 밀접한 관계가 있는 것을 자기 또는 제3자의 이익을 위해 이용하지 못하게 한다. 승인은 이사 3분의 2 이상의 수로 한다.","c":"상","v":1},"공인회2021_56-23-4":{"w":"상법 제382조의4가 이사의 비밀유지의무를 재임 중과 퇴임 후 모두에 대해 정한다.","c":"상","v":1},"공인회2022_57-22-5":{"w":"판례는 결의에 기권했다고 의사록에 기재된 이사는 이의를 한 기재가 없는 자에 해당하지 않으므로 상법 제399조 제3항의 찬성 추정을 받지 않는다고 본다.","c":"상","v":1},"공인회2018_53-25-2":{"w":"상법 제408조의5 제1항이 2명 이상의 집행임원이 선임되면 이사회 결의로 대표집행임원을 선임하도록 정한다. 1명이면 그 집행임원이 대표집행임원이 된다.","c":"상","v":1},"공인회2025_60-25-1":{"w":"상법 제389조 제1항 단서에 따라 정관이 정하면 주주총회가 대표이사를 선정한다.","c":"상","v":1},"공인회2025_60-25-2":{"w":"상법 제317조 제2항 제10호가 수인의 대표이사가 공동으로 회사를 대표할 것을 정한 규정을 설립등기 사항으로 정한다.","c":"상","v":1},"공인회2025_60-25-3":{"w":"상법 제389조 제3항이 준용하는 제210조에 따라 대표이사가 업무집행으로 타인에게 손해를 가하면 회사가 대표이사와 연대하여 배상한다.","c":"상","v":1},"공인회2025_60-25-4":{"w":"상법 제389조 제3항이 제386조 제1항을 준용하므로 대표이사 원수를 결하면 임기만료·사임으로 퇴임한 대표이사가 후임 취임 때까지 권리의무를 가진다.","c":"상","v":1},"공인회2020_55-24-1":{"w":"상법 제389조 제1항이 대표이사는 이사회 결의로 선정하되 정관으로 주주총회에서 선정하도록 정할 수 있다고 정한다.","c":"상","v":1},"공인회2020_55-24-2":{"w":"공동대표(상법 제389조 제2항)를 정하지 않으면 대표이사는 각자 회사를 대표한다.","c":"상","v":1},"공인회2020_55-24-4":{"w":"상법 제391조의3 제3항이 주주에게 영업시간 내 이사회 의사록 열람·등사 청구권을 주고 지분 요건을 두지 않는다. 회사는 이유를 붙여 거절할 수 있고 주주는 법원 허가를 받아 열람할 수 있다(제4항).","c":"상","v":1},"공인회2020_55-24-5":{"w":"상법 제399조 제3항이 이사회 결의에 의한 행위로 이사가 책임지는 경우 결의에 참가하고 의사록에 이의 기재가 없는 이사는 찬성한 것으로 추정한다.","c":"상","v":1},"공인회2019_54-29-4":{"w":"상법 제408조의6 제3항이 집행임원은 이사회 요구가 있으면 언제든지 출석해 요구 사항을 보고하도록 정한다.","c":"상","v":1},"공인회2016_51-21-1":{"w":"대표이사가 여럿이어도 공동대표(상법 제389조 제2항)를 정하지 않았다면 각자 단독으로 회사를 대표한다.","c":"상","v":1},"공인회2016_51-21-2":{"w":"상법 제393조 제1항이 중요한 자산의 처분 및 양도를 이사회 결의 사항으로 정한다.","c":"상","v":1},"공인회2016_51-21-3":{"w":"판례는 대표권 남용 행위도 원칙적으로 유효하다고 본다. 상대방이 대표이사의 진의를 알았거나 알 수 있었을 때만 회사가 무효를 주장할 수 있으므로 상대방이 선의·무과실이면 무효를 주장하지 못한다.","c":"상","v":1},"공인회2016_51-21-5":{"w":"판례는 대표이사가 다른 이사의 위법한 업무집행을 의심할 사유가 있는데도 감시의무를 게을리해 방치하면 상법 제399조에 따라 회사의 손해를 배상해야 한다고 본다.","c":"상","v":1},"공인회2017_52-15-1":{"w":"상법 제383조 제2항이 이사 임기는 3년을 넘지 못한다고 정한다. 제3항은 정관으로 임기 중 최종 결산기에 관한 정기총회 종결 때까지 연장할 수 있게 한다.","c":"상","v":1},"공인회2017_52-15-3":{"w":"상법 제387조가 자격주를 감사에게 공탁하도록 정한다. 감사위원회에도 제387조가 준용된다(제415조의2 제7항).","c":"상","v":1},"공인회2017_52-15-4":{"w":"상법 제408조 제1항이 직무대행자는 가처분명령에 다른 정함이 있거나 법원 허가를 얻은 경우 외에는 회사의 상무에 속하지 않는 행위를 하지 못한다고 정한다.","c":"상","v":1},"공인회2017_52-15-5":{"w":"상법 제386조 제1항이 임기만료나 사임으로 이사 원수를 결하면 퇴임 이사가 새 이사 취임 때까지 권리의무가 있다고 정한다.","c":"상","v":1},"공인회2020_55-21-1":{"w":"상법 제382조 제2항이 회사와 이사의 관계에 민법의 위임 규정을 준용하므로 이사는 선관주의의무를 진다(민법 제681조).","c":"상","v":1},"공인회2020_55-21-3":{"w":"상법 제383조 제1항 단서가 자본금 10억원 미만 회사는 이사를 1명 또는 2명으로 할 수 있게 한다.","c":"상","v":1},"공인회2020_55-21-5":{"w":"상법 제383조 제2항은 1회 임기의 상한만 정하고 연임 제한 규정은 두지 않으므로 다시 선임될 수 있다.","c":"상","v":1},"공인회2021_56-20-1":{"w":"상법 제382조 제2항이 회사와 이사의 관계에 민법의 위임 규정을 준용한다.","c":"상","v":1},"공인회2021_56-20-2":{"w":"상법 제387조가 정관으로 자격주를 정하면 다른 규정이 없는 한 그 주권을 감사에게 공탁하도록 정한다.","c":"상","v":1},"공인회2021_56-20-4":{"w":"상법 제385조 제1항 본문이 이사는 언제든지 주주총회 특별결의로 해임할 수 있다고 정한다. 정당한 이유 없는 임기 중 해임이면 손해배상책임만 따른다(단서).","c":"상","v":1},"공인회2021_56-20-5":{"w":"상법 제382조의2 제1항의 집중투표 청구다. 회일 7일 전까지 서면 또는 전자문서로 청구해야 한다(제2항).","c":"상","v":1},"공인회2017_52-11-1":{"w":"판례는 상법 제399조의 책임을 위임관계에 따른 채무불이행책임으로 보아 소멸시효를 일반채권과 같이 10년으로 본다.","c":"상","v":1},"공인회2017_52-11-2":{"w":"판례는 법령 위반 행위는 그 자체로 회사에 대한 채무불이행이므로 경영판단의 원칙이 적용되지 않는다고 본다.","c":"상","v":1},"공인회2017_52-11-3":{"w":"상법 제401조 제2항이 제399조 제2항·제3항을 준용하므로 이사회 결의에 의한 행위이면 찬성한 이사도 제3자에게 연대책임을 진다.","c":"상","v":1},"공인회2017_52-11-4":{"w":"업무집행지시자는 지시한 업무에 관하여 이사로 보아 회사에 책임을 지고(상법 제401조의2 제1항 제1호, 제399조), 책임 있는 이사와 연대한다(제401조의2 제2항).","c":"상","v":1},"공인회2017_52-13-3":{"w":"상법 제398조 제2호가 이사의 배우자와 직계존비속을 자기거래 규제 대상에 넣는다. 미리 이사회에서 중요사실을 밝히고 이사 3분의 2 이상의 승인을 받아야 한다.","c":"상","v":1},"공인회2016_51-20-1":{"w":"상법 제398조가 이사 등의 자기거래에 미리 이사회에서 중요사실을 밝히고 승인받도록 정한다. 승인은 이사 3분의 2 이상의 수로 하고 거래 내용과 절차가 공정해야 한다.","c":"상","v":1},"공인회2016_51-20-2":{"w":"제398조 위반은 법령 위반이므로 이사는 상법 제399조 제1항에 따라 회사에 손해배상책임을 진다.","c":"상","v":1},"공인회2016_51-20-3":{"w":"상법 제394조 제1항이 회사가 이사에게 또는 이사가 회사에 소를 제기하면 감사가 그 소에 관하여 회사를 대표한다고 정한다.","c":"상","v":1},"공인회2016_51-20-4":{"w":"상법 제403조 제6항이 대표소송을 제기한 주주는 법원의 허가를 얻지 않으면 소의 취하, 청구의 포기·인낙, 화해를 하지 못한다고 정한다.","c":"상","v":1},"공인회2016_51-19-1":{"w":"상법 제383조 제3항이 정관으로 이사 임기를 임기 중 최종 결산기에 관한 정기총회 종결 때까지 연장할 수 있게 한다.","c":"상","v":1},"공인회2016_51-19-2":{"w":"판례는 상법 제383조 제3항의 정기총회를 임기 중에 도래하는 최종 결산기에 관한 정기총회로 본다. 임기 만료 후 처음 도래하는 결산기에 관한 정기총회가 아니다.","c":"상","v":1},"공인회2016_51-19-4":{"w":"자본금 10억원 미만 회사가 이사를 1명 또는 2명으로 두면 준비금의 자본금 전입(제461조 제1항) 등 이사회 권한을 주주총회가 행사한다(상법 제383조 제4항).","c":"상","v":1},"공인회2016_51-19-5":{"w":"법원이 선임한 일시이사(상법 제386조 제2항)는 본래 이사와 같은 권한을 가지므로 상무에 한정되는 직무대행자(제408조)와 달리 권한이 제한되지 않는다는 것이 판례다.","c":"상","v":1},"공인회2021_56-22-1":{"w":"상법 제393조 제2항이 이사회는 이사의 직무 집행을 감독한다고 정한다.","c":"상","v":1},"공인회2021_56-22-2":{"w":"판례는 정관에 특별한 정함이 없으면 이사회 소집통지에 회의의 목적사항까지 적을 필요가 없다고 본다. 이사는 이사회에서 업무에 관한 모든 사항을 논의할 수 있기 때문이다.","c":"상","v":1},"공인회2021_56-22-3":{"w":"상법 제391조의3 제2항이 이사회 의사록의 기재사항과 출석 이사·감사의 기명날인 또는 서명을 정한다.","c":"상","v":1},"공인회2021_56-22-4":{"w":"상법 제391조 제1항이 이사 과반수 출석과 출석이사 과반수를 결의 요건으로 하되 정관으로 그 비율을 높일 수 있게 한다.","c":"상","v":1},"공인회2018_53-32-1":{"w":"판례는 회사가 공동대표이사 중 1인에게 단독 대표이사 명칭 사용을 용인한 경우에도 상법 제395조를 적용해 회사가 선의의 제3자에게 책임진다고 본다.","c":"상","v":1},"공인회2018_53-32-2":{"w":"판례는 이사 자격이 없는 자에게 대표이사 같은 명칭 사용을 허락한 경우에도 상법 제395조를 유추적용한다.","c":"상","v":1},"공인회2018_53-32-3":{"w":"판례는 표현대표이사 책임의 요건으로 회사가 명칭 사용을 명시적·묵시적으로 승인해 외관 현출에 귀책사유가 있을 것을 요구한다. 명칭을 함부로 쓴 것을 몰랐다면 책임이 없다.","c":"상","v":1},"공인회2018_53-32-5":{"w":"상법 제395조는 선의의 제3자를 보호한다. 판례는 제3자에게 중대한 과실이 있으면 악의와 같이 보아 회사가 책임지지 않는다고 본다.","c":"상","v":1},"공인회2025_60-36-1":{"w":"외부감사법 제11조 제1항 제2호가 제10조의 선임기간 내에 감사인을 선임하지 않은 회사에 증권선물위원회가 3개 사업연도 범위에서 지정 회계법인을 감사인으로 선임하도록 요구할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-40-3":{"w":"공인회계사법 제21조 제2항 제2호가 재무제표 감사·증명 계약 기간 중에는 그 회사의 내부감사업무 대행을 할 수 없게 한다.","c":"상","v":1},"공인회2026_61-39-2":{"w":"공인회계사법 제15조 제3항이 직무를 행할 때 고의로 진실을 감추거나 허위보고를 하지 못하게 한다.","c":"상","v":1},"공인회2026_61-39-3":{"w":"공인회계사법 제40조의9 제2항이 외국공인회계사는 동시에 둘 이상의 회계법인(외국회계법인 포함) 및 외국공인회계사에 소속·고용되거나 겸임할 수 없다고 정한다.","c":"상","v":1},"공인회2026_61-39-4":{"w":"공인회계사법 제20조 본문이 공인회계사와 사무직원(전직 포함)의 비밀엄수 의무를 정한다. 다른 법령에 특별한 규정이 있으면 단서에 따라 예외가 된다.","c":"상","v":1},"공인회2026_61-39-5":{"w":"공인회계사법 제21조 제2항 제5호가 감사·증명 계약 기간 중 그 회사에 대한 인사 및 조직 등에 관한 지원업무를 금지한다.","c":"상","v":1},"공인회2026_61-40-1":{"w":"공인회계사법 제37조의2 제1항이 회계법인은 분할로 1개 또는 수개의 회계법인을 설립할 수 있다고 정한다. 분할계획서는 사원총회 결의를 거친다(제3항).","c":"상","v":1},"공인회2026_61-40-2":{"w":"공인회계사법 제26조 제5항이 회계법인 사원은 공인회계사(그 회계법인에 고용된 외국공인회계사 포함)여야 하고 3명 이상이어야 한다고 정한다.","c":"상","v":1},"공인회2026_61-40-4":{"w":"공인회계사법 제26조 제2항이 회계법인의 이사와 직원 중 7명 이상은 공인회계사여야 한다고 정한다.","c":"상","v":1},"공인회2026_61-40-5":{"w":"공인회계사법 제36조 제3호가 정관에 정한 사유가 생기면 사원이 당연히 탈퇴된다고 정한다.","c":"상","v":1},"공인회2025_60-39-5":{"w":"공인회계사법 제35조가 회계법인의 이사나 소속공인회계사는 자기 또는 제3자를 위해 그 회계법인의 업무범위에 속하는 업무를 하거나 다른 회계법인의 이사·소속공인회계사가 되지 못한다고 정한다.","c":"상","v":1},"공인회2020_55-19-1":{"w":"상법 제404조 제2항이 대표소송을 제기한 주주는 소 제기 후 지체 없이 회사에 소송고지를 하도록 정한다.","c":"상","v":1},"공인회2020_55-19-4":{"w":"상법 제403조 제6항이 대표소송의 당사자는 법원 허가 없이 소의 취하, 청구의 포기·인낙, 화해를 하지 못한다고 정한다.","c":"상","v":1},"공인회2020_55-19-5":{"w":"상법 제405조 제2항이 패소한 주주는 악의인 경우 외에는 회사에 손해배상책임이 없다고 정한다.","c":"상","v":1},"공인회2024_59-19-1":{"w":"상법 제466조 제1항이 회계장부 열람·등사청구권을 발행주식총수 3% 이상 주주에게 준다.","c":"상","v":1},"공인회2024_59-19-2":{"w":"상법 제466조 제1항이 청구 대상을 회계의 장부와 서류로 정한다.","c":"상","v":1},"공인회2024_59-19-3":{"w":"상법 제466조 제1항이 이유를 붙인 서면으로 청구하도록 정한다.","c":"상","v":1},"공인회2024_59-19-5":{"w":"상법 제466조 제2항이 회사는 청구가 부당함을 증명하지 않으면 거부하지 못한다고 정한다. 부당성 증명책임은 회사에 있다.","c":"상","v":1},"공인회2025_60-31-1":{"w":"상법 제466조 제1항이 발행주식총수 3% 이상 주주에게 이유를 붙인 서면으로 회계 장부와 서류의 열람·등사를 청구할 권리를 준다.","c":"상","v":1},"공인회2025_60-31-2":{"w":"판례는 열람·등사청구서의 이유는 열람 목적을 알 수 있을 정도로 구체적으로 적으면 된다고 본다. 그 이유가 사실일지 모른다는 합리적 의심이 생기게 할 정도로 쓰거나 뒷받침 자료를 첨부할 필요는 없다.","c":"상","v":1},"공인회2025_60-31-3":{"w":"판례는 회계장부 열람·등사청구권을 피보전권리로 하여 장부의 열람·등사를 명하는 가처분도 허용된다고 본다.","c":"상","v":1},"공인회2025_60-31-4":{"w":"판례는 열람권 행사가 회사 업무 운영이나 주주 공동의 이익을 해치는 경우, 경쟁자로서 얻은 정보를 경업에 이용할 우려가 있는 경우, 회사에 지나치게 불리한 시기를 택한 경우에는 정당한 목적이 없어 부당하다고 본다(상법 제466조 제2항).","c":"상","v":1},"공인회2022_57-23-1":{"w":"상법 제403조 제1항이 발행주식총수 1% 이상 주주에게 회사에 이사 책임추궁 소의 제기를 청구할 권리를 준다. 이유를 적은 서면으로 해야 한다(제2항).","c":"상","v":1},"공인회2022_57-23-2":{"w":"상법 제403조 제7항이 제176조 제3항·제4항을 준용하므로 회사가 주주의 악의를 소명하면 법원이 담보 제공을 명할 수 있다.","c":"상","v":1},"공인회2022_57-23-3":{"w":"판례는 회사의 대표소송 참가(상법 제404조 제1항)를 공동소송참가로 본다. 중복제소 금지에 걸리지 않는다는 것이 그 근거다.","c":"상","v":1},"공인회2022_57-23-5":{"w":"상법 제406조의2 제1항이 모회사 1% 이상 주주에게 자회사에 대한 자회사 이사 책임추궁 소 제기 청구권을 준다(다중대표소송).","c":"상","v":1},"공인회2024_59-23-1":{"w":"상법 제403조 제1항이 1% 이상 주주에게 이사 책임추궁 소의 제기 청구권을 준다. 회사가 30일 내에 소를 제기하지 않으면 주주가 직접 제소할 수 있다(제3항).","c":"상","v":1},"공인회2024_59-23-3":{"w":"상법 제405조 제1항이 승소한 주주는 소송비용 등 지출 비용 중 상당한 금액을 회사에 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-23-4":{"w":"상법 제405조 제2항이 대표소송에서 패소한 주주는 악의인 경우 외에는 회사에 손해배상책임이 없다고 정한다.","c":"상","v":1},"공인회2024_59-23-5":{"w":"상법 제403조 제7항이 제186조를 준용해 대표소송을 본점 소재지 지방법원의 전속관할로 한다.","c":"상","v":1},"공인회2023_58-26-2":{"w":"전원합의체 판례(2017년)는 감사도 이사와 마찬가지로 주주총회 선임 결의와 피선임자의 승낙만 있으면 대표이사와의 임용계약 없이 지위를 취득한다고 본다.","c":"상","v":1},"공인회2025_60-27-2":{"w":"상법 제409조 제2항이 감사 선임 시 의결권 제한 기준을 3%로 하되 정관으로 더 낮은 비율을 정할 수 있게 하므로 1%로 정할 수 있다.","c":"상","v":1},"공인회2026_61-24-1":{"w":"상법 제411조가 감사는 회사 및 자회사의 이사 또는 지배인 기타 사용인의 직무를 겸하지 못한다고 정한다.","c":"상","v":1},"공인회2026_61-24-2":{"w":"상법 제412조의5 제1항이 모회사 감사의 자회사 영업보고 요구권을, 제3항이 자회사의 보고 거부 금지를 정한다.","c":"상","v":1},"공인회2026_61-24-4":{"w":"상법 제415조의2 제3항이 감사위원 해임에 관한 이사회 결의는 이사 총수의 3분의 2 이상으로 하도록 정한다.","c":"상","v":1},"공인회2026_61-24-5":{"w":"상법 제409조 제4항이 자본금 10억원 미만 회사는 감사를 선임하지 않을 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-23-1":{"w":"상법 제403조 제6항이 대표소송 당사자는 법원 허가 없이 소의 취하, 청구의 포기·인낙, 화해를 하지 못한다고 정한다.","c":"상","v":1},"공인회2026_61-23-2":{"w":"상법 제405조 제1항이 승소한 주주는 소송비용과 그 밖에 지출한 비용 중 상당한 금액을 회사에 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-23-3":{"w":"상법 제405조 제2항이 패소한 주주는 악의가 아니면 회사에 손해배상책임이 없다고 정한다.","c":"상","v":1},"공인회2026_61-23-4":{"w":"상법 제406조의2 제3항이 제404조 제2항을 준용하므로 다중대표소송을 제기한 주주는 지체 없이 자회사에 소송고지를 해야 한다.","c":"상","v":1},"공인회2018_53-27-1":{"w":"상법 제424조가 법령·정관 위반이나 현저히 불공정한 방법의 신주발행으로 주주가 불이익을 받을 염려가 있으면 주주가 유지를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2018_53-27-2":{"w":"상법 제424조는 주주가 회사에 대하여 신주발행 유지를 청구한다고 정한다. 주주 자신의 불이익을 막는 권리다.","c":"상","v":1},"공인회2018_53-27-4":{"w":"상법 제402조가 이사의 법령·정관 위반 행위로 회사에 회복할 수 없는 손해가 생길 염려가 있는 경우를 위법행위유지청구의 요건으로 정한다.","c":"상","v":1},"공인회2018_53-27-5":{"w":"상법 제402조가 감사나 1% 이상 주주가 회사를 위하여 이사에게 행위 유지를 청구한다고 정한다.","c":"상","v":1},"공인회2024_59-31-2":{"w":"상법 제542조의13 제1항과 같은 법 시행령이 자산총액 5천억원 이상 상장회사에 준법통제기준 마련 의무를 지운다. 다른 법률로 내부통제기준과 준법감시인을 두어야 하는 회사는 제외된다.","c":"상","v":1},"공인회2019_54-27-5":{"w":"상법 제542조의12 제6항이 상장회사의 감사 또는 감사위원회는 감사보고서를 주주총회일 1주 전까지 이사에게 제출할 수 있다고 정한다. 일반 회사는 4주 내 제출이다(제447조의4 제1항).","c":"상","v":1},"공인회2026_61-34-1":{"w":"상법 제542조의6 제1항이 6개월 전부터 계속하여 상장회사 발행주식총수의 1천분의 15 이상을 보유한 자에게 임시총회 소집청구권을 준다.","c":"상","v":1},"공인회2026_61-34-2":{"w":"상법 제542조의6 제8항이 상장회사는 정관으로 특례 규정보다 짧은 보유기간이나 낮은 보유비율을 정할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-34-3":{"w":"상법 제542조의4 제2항이 이사 선임 총회 통지에 후보자의 성명, 약력, 추천인 등을 적도록 정한다. 제542조의5는 그 통지·공고한 후보자 중에서 선임하도록 정한다.","c":"상","v":1},"공인회2026_61-34-4":{"w":"상법 제542조의6 제7항이 6개월 전부터 계속하여 상장 모회사 발행주식총수의 1만분의 50 이상을 보유한 자에게 다중대표소송 제소청구권(제406조의2)을 준다.","c":"상","v":1},"공인회2022_57-24-1":{"w":"상법 제412조의4 제1항이 감사에게 이사회 소집청구권을 준다. 이사가 소집하지 않으면 감사가 직접 소집할 수 있다(제2항).","c":"상","v":1},"공인회2022_57-24-3":{"w":"상법 제412조 제2항이 감사는 언제든지 이사에게 영업 보고를 요구하거나 업무와 재산상태를 조사할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-24-4":{"w":"상법 제412조의5 제1항이 모회사 감사는 직무 수행에 필요하면 자회사에 영업 보고를 요구할 수 있다고 정한다. 자회사가 지체 없이 보고하지 않으면 업무와 재산상태를 조사할 수 있다(제2항).","c":"상","v":1},"공인회2022_57-24-5":{"w":"상법 제413조가 감사는 이사가 총회에 제출할 의안과 서류를 조사해 법령·정관 위반이나 현저히 부당한 사항이 있는지에 관해 총회에 의견을 진술하도록 정한다.","c":"상","v":1},"공인회2020_55-27-1":{"w":"감사는 신주발행무효의 소 제소권자이고(상법 제429조, 발행일부터 6월 내) 이사의 위법행위 유지청구권도 가진다(제402조).","c":"상","v":1},"공인회2020_55-27-2":{"w":"상법 제412조의3 제1항이 감사에게 임시총회 소집청구권을 준다.","c":"상","v":1},"공인회2020_55-27-4":{"w":"감사 해임에는 이사 해임 규정(상법 제385조)이 준용되어(제415조) 정당한 이유 없는 해임의 손해배상은 임기를 정한 경우에 인정된다. 판례는 임기를 정하지 않은 경우에는 이 손해배상을 청구할 수 없다고 본다.","c":"중","v":1},"공인회2020_55-27-5":{"w":"상법 제411조가 감사는 회사 및 자회사의 이사 또는 지배인 기타 사용인의 직무를 겸하지 못한다고 정한다. 감사 대상인 업무집행에서 독립하게 하려는 것이다.","c":"상","v":1},"공인회2016_51-24-1":{"w":"상법 제409조 제4항이 자본금 10억원 미만 회사는 감사를 선임하지 않을 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-24-1":{"w":"감사 선임은 주주총회 보통결의이고(상법 제409조 제1항, 제368조 제1항), 해임은 제415조가 준용하는 제385조에 따라 특별결의다.","c":"상","v":1},"공인회2024_59-24-3":{"w":"상법 제542조의12 제1항이 자산 2조원 이상 상장회사의 감사위원 선임·해임 권한을 주주총회에 둔다.","c":"상","v":1},"공인회2024_59-24-4":{"w":"상법 제415조의2 제6항이 감사위원회에는 이사회가 위원회 결의를 다시 결의할 수 있다는 제393조의2 제4항 후단을 적용하지 않는다고 정한다.","c":"상","v":1},"공인회2024_59-24-5":{"w":"상법 제542조의10 제1항과 같은 법 시행령이 자산 1천억원 이상 상장회사에 상근감사를 1명 이상 두도록 한다. 감사위원회를 설치하면 예외다.","c":"상","v":1},"공인회2017_52-17-1":{"w":"상법 제542조의10 제1항과 시행령의 상근감사 설치 의무다. 자산 2조원 이상이면 감사위원회 설치 의무가 있어 이 규정이 적용되지 않는다.","c":"상","v":1},"공인회2017_52-17-3":{"w":"상법 제410조가 감사 임기를 취임 후 3년 내 최종 결산기에 관한 정기총회 종결 때까지로 정한다.","c":"상","v":1},"공인회2017_52-17-5":{"w":"상법 제415조의2 제2항이 감사위원회는 3명 이상의 이사로 구성하되 사외이사가 3분의 2 이상이어야 한다고 정한다. 위원 해임의 이사회 결의는 이사 총수 3분의 2 이상이다(같은 조 제3항).","c":"상","v":1},"공인회2018_53-12-2":{"w":"상법 제424조의2 제1항이 이사와 통모해 현저히 불공정한 발행가액으로 주식을 인수한 자에게 차액 지급의무를 지운다. 같은 조 제2항이 이 청구에 대표소송 규정(제403조~제406조)을 준용한다.","c":"상","v":1},"공인회2018_53-12-3":{"w":"상법 제467조의2 제4항이 주주의 권리행사와 관련해 공여된 이익의 반환청구에 대표소송 규정을 준용한다.","c":"상","v":1},"공인회2018_53-12-4":{"w":"상법 제394조 제1항 후단이 제403조 제1항의 소 제기 청구를 받는 경우에도 감사가 회사를 대표한다고 정한다.","c":"상","v":1},"공인회2018_53-12-5":{"w":"상법 제403조 제6항이 법원 허가 없이는 소의 취하, 청구의 포기·인낙, 화해를 모두 할 수 없다고 정한다.","c":"상","v":1},"공인회2025_60-38-4":{"w":"외부감사법 제32조 제3항이 회계법인은 대통령령으로 정하는 경우 외에 공동기금을 양도하거나 담보로 제공할 수 없다고 정한다. 누구든지 이를 압류·가압류할 수도 없다.","c":"상","v":1},"공인회2025_60-36-3":{"w":"외부감사법 제17조 제3항이 감사인의 대표자가 품질관리기준에 따른 업무설계와 운영에 책임을 지고 담당 이사 1명을 지정하도록 정한다.","c":"상","v":1},"공인회2025_60-36-4":{"w":"외부감사법 제14조 제1항이 전기감사인 외의 감사인을 선임하려면 전기감사인에게 감사 또는 감사위원회에 의견을 진술할 기회를 주도록 정한다.","c":"상","v":1},"공인회2025_60-36-5":{"w":"외부감사법 제24조가 감사인이나 소속 공인회계사는 주주총회등이 요구하면 출석해 의견을 진술하거나 질문에 답변하도록 정한다.","c":"상","v":1},"공인회2026_61-38-5":{"w":"외부감사법 제21조 제2항이 연결재무제표 감사인은 회사 또는 관계회사의 감사인에게 자료 제출 등 협조를 요청할 수 있다고 정한다. 요청받은 감사인은 지체 없이 따라야 한다.","c":"상","v":1},"공인회2026_61-36-2":{"w":"외부감사법 제8조 제4항 단서가 대표자가 필요하다고 판단하면 이사회와 감사에 대한 운영실태 보고를 내부회계관리자가 하게 할 수 있다고 정한다. 주주총회 보고는 대표자가 한다.","c":"상","v":1},"공인회2026_61-36-3":{"w":"외부감사법 제8조 제5항이 감사가 운영실태를 평가해 사업연도마다 이사회에 보고하고 평가보고서를 본점에 5년간 비치하도록 정한다.","c":"상","v":1},"공인회2026_61-36-4":{"w":"외부감사법 제8조 제1항 단서가 주권상장법인이 아니면서 직전 사업연도 말 자산총액 1천억원 미만인 회사를 내부회계관리제도 의무에서 제외한다.","c":"상","v":1},"공인회2026_61-36-5":{"w":"외부감사법 제8조 제3항이 대표자가 내부회계관리제도를 책임지고 담당 상근이사 1명을 내부회계관리자로 지정하도록 정한다.","c":"상","v":1},"공인회2025_60-35-3":{"w":"외부감사법 제6조 제6항이 감사인과 소속 공인회계사는 재무제표를 대신 작성하거나 재무제표 작성과 관련된 회계처리 자문에 응하는 등의 행위를 하지 못한다고 정한다.","c":"상","v":1},"공인회2026_61-35-1":{"w":"외부감사법 제9조 제3항이 감사반 소속 공인회계사 중 1명 이상이 공인회계사법 제21조 제1항의 관계(자기 또는 배우자가 임원인 경우 등)에 있는 회사의 감사인이 될 수 없다고 정한다.","c":"상","v":1},"공인회2026_61-35-3":{"w":"외부감사법 제10조 제5항이 감사 또는 감사위원회가 감사보수, 감사시간, 필요 인력에 관한 사항을 문서로 정하도록 정한다.","c":"상","v":1},"공인회2026_61-35-4":{"w":"외부감사법 제10조 제2항이 직전 사업연도에 회계감사를 받지 않은 회사는 사업연도 개시일부터 4개월 내에 감사인을 선임하도록 정한다. 일반적인 선임기한은 45일이다(제1항).","c":"상","v":1},"공인회2026_61-35-5":{"w":"외부감사법 제11조 제1항 제6호 가목이 3개 사업연도 연속 영업이익이 0보다 작은 주권상장법인을 감사인 지정 대상으로 정한다.","c":"상","v":1},"공인회2016_51-12-1":{"w":"판례는 정관이나 이사회 결의에 신주인수권 양도에 관한 정함이 없어도 양도가 금지되는 것은 아니라고 본다. 회사가 양도를 승낙하면 그 양도는 회사에도 효력이 있다(상법 제416조 제5호 참조).","c":"상","v":1},"공인회2023_58-27-1":{"w":"상법 제416조 제6호가 이사회가 주주의 청구가 있는 때에만 신주인수권증서를 발행한다는 것과 그 청구기간을 정할 수 있게 한다.","c":"상","v":1},"공인회2023_58-27-2":{"w":"상법 제420조의3 제2항이 제336조 제2항을 준용하므로 신주인수권증서의 점유자는 적법한 소지인으로 추정된다.","c":"상","v":1},"공인회2023_58-27-3":{"w":"상법 제420조의3 제1항이 신주인수권증서가 발행된 신주인수권의 양도는 증서의 교부로만 한다고 정한다.","c":"상","v":1},"공인회2023_58-27-5":{"w":"신주인수권증서 소지인은 증서로 청약해야 하고(상법 제420조의5 제1항), 통지한 기일까지 청약하지 않으면 신주인수권을 잃는다(제419조 제3항).","c":"상","v":1},"공인회2018_53-31-2":{"w":"상법 제421조 제2항이 신주 인수인은 회사의 동의 없이 납입채무와 회사에 대한 채권을 상계할 수 없다고 정한다.","c":"상","v":1},"공인회2018_53-31-3":{"w":"상법 제420조의5 제2항이 신주인수권증서 상실자는 주식청약서로 청약할 수 있다고 정한다. 그 청약은 증서에 의한 청약이 있으면 효력을 잃는다.","c":"상","v":1},"공인회2018_53-31-4":{"w":"상법 제429조가 신주발행 무효는 주주·이사·감사만 신주를 발행한 날부터 6월 내에 소로만 주장할 수 있다고 정한다.","c":"상","v":1},"공인회2018_53-31-5":{"w":"신주발행무효 판결은 제190조 본문 준용으로 제3자에게 효력이 있고(상법 제430조), 신주는 장래에 대하여 효력을 잃는다(제431조 제1항).","c":"상","v":1},"공인회2024_59-29-2":{"w":"상법 제513조 제3항 후단이 제418조 제2항 단서를 준용하므로 주주 외의 자에 대한 전환사채 발행은 신기술 도입, 재무구조 개선 등 경영상 목적 달성에 필요한 경우로 한정된다.","c":"상","v":1},"공인회2024_59-29-3":{"w":"상법 제513조 제4항이 주주총회 결의로 전환사채 발행 사항을 정하는 경우 의안의 요령을 소집통지에 적도록 정한다.","c":"상","v":1},"공인회2024_59-29-4":{"w":"상법 제476조 제1항이 사채 모집이 완료되면 이사가 지체 없이 인수인에게 사채 전액 또는 제1회 납입을 시키도록 정한다. 전환사채에도 이 규정이 적용된다.","c":"상","v":1},"공인회2024_59-29-5":{"w":"상법 제514조의2 제1항이 전환사채를 발행하면 납입 완료일부터 2주 내에 본점 소재지에서 등기하도록 정한다.","c":"상","v":1},"공인회2020_55-29-1":{"w":"상법 제484조 제1항이 사채관리회사는 사채권자를 위해 사채에 관한 채권을 변제받거나 그 실현을 보전하는 데 필요한 재판상·재판 외의 모든 행위를 할 수 있다고 정한다.","c":"상","v":1},"공인회2021_56-32-2":{"w":"상법 제516조의2 제4항이 주주 외의 자에게 신주인수권부사채를 발행할 때 그 액, 신주인수권의 내용, 행사기간에 관해 정관에 규정이 없으면 주주총회 특별결의로 정하도록 한다.","c":"상","v":1},"공인회2021_56-32-3":{"w":"상법 제476조 제1항이 사채 모집이 완료되면 이사가 지체 없이 인수인에게 사채 전액 또는 제1회 납입을 시키도록 정한다.","c":"상","v":1},"공인회2021_56-32-4":{"w":"상법 제469조 제4항이 정관에 따라 이사회가 대표이사에게 사채의 금액과 종류를 정해 1년을 넘지 않는 기간 내에 발행하도록 위임할 수 있게 한다.","c":"상","v":1},"공인회2021_56-32-5":{"w":"상법 제498조 제1항이 사채권자집회 결의는 법원 인가로 효력이 생긴다고 정한다. 그 종류 사채권자 전원이 동의한 결의는 인가가 필요 없다(같은 항 단서).","c":"상","v":1},"공인회2019_54-30-1":{"w":"상법 제428조 제1항이 신주발행 변경등기 후 인수되지 않은 주식이나 청약이 취소된 주식은 이사가 공동으로 인수한 것으로 본다고 정한다(이사의 인수담보책임).","c":"상","v":1},"공인회2019_54-30-3":{"w":"상법 제421조 제2항이 회사의 동의가 있어야 납입채무와 회사에 대한 채권을 상계할 수 있게 한다.","c":"상","v":1},"공인회2019_54-30-4":{"w":"상법 제417조 제1항이 회사 성립 후 2년이 지나면 주주총회 특별결의와 법원 인가를 얻어 액면미달 발행을 할 수 있다고 정한다.","c":"상","v":1},"공인회2019_54-30-5":{"w":"신주발행무효 판결은 대세효가 있지만(상법 제430조, 제190조 본문) 신주는 장래에 대해서만 효력을 잃으므로(제431조 제1항) 소급효가 없다.","c":"상","v":1},"공인회2020_55-28-5":{"w":"상법 제423조 제2항이 신주 인수인이 납입기일에 납입이나 현물출자를 이행하지 않으면 권리를 잃는다고 정한다. 별도의 실권절차가 필요 없다.","c":"상","v":1},"공인회2021_56-30-1":{"w":"상법 제424조가 회사가 법령·정관에 위반하거나 현저하게 불공정한 방법으로 주식을 발행해 주주가 불이익을 받을 염려가 있으면 주주가 회사에 발행 유지를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2021_56-30-2":{"w":"상법 제424조의2 제2항이 불공정가액 인수인에 대한 차액 지급청구에 대표소송 규정(제403조~제406조)을 준용한다.","c":"상","v":1},"공인회2021_56-30-3":{"w":"상법 제423조 제2항이 신주 인수인이 납입기일에 납입하지 않으면 권리를 잃는다고 정한다. 별도의 실권 예고가 필요 없다.","c":"상","v":1},"공인회2021_56-30-5":{"w":"판례는 정관이나 이사회 결의로 신주인수권 양도를 정하지 않았더라도 회사가 양도를 승낙하면 회사에 대해서도 효력이 있다고 본다.","c":"상","v":1},"공인회2022_57-25-1":{"w":"판례는 현물출자자에게 발행하는 신주에는 기존 주주의 신주인수권(상법 제418조 제1항)이 미치지 않는다고 본다. 현물출자는 특정인의 특정 재산을 받기 위한 것이기 때문이다.","c":"상","v":1},"공인회2022_57-25-3":{"w":"상법 제419조 제1항이 신주인수권자에게 주식의 종류·수와 청약 기일까지 청약하지 않으면 권리를 잃는다는 뜻을 통지하도록 정한다. 통지는 기일 2주 전에 한다(제2항).","c":"상","v":1},"공인회2022_57-25-4":{"w":"상법 제421조 제2항이 신주 인수인은 회사의 동의 없이 납입채무와 회사에 대한 채권을 상계하지 못한다고 정한다.","c":"상","v":1},"공인회2022_57-25-5":{"w":"상법 제418조 제2항이 정관에 따라 경영상 목적 달성에 필요한 경우에만 주주 외의 자에게 신주를 배정할 수 있게 한다.","c":"상","v":1},"공인회2017_52-32-1":{"w":"상법 제424조가 현저하게 불공정한 방법의 신주발행으로 불이익을 받을 염려가 있는 주주에게 회사에 대한 발행유지청구권을 준다.","c":"상","v":1},"공인회2017_52-32-2":{"w":"상법 제424조의2 제2항이 대표소송 규정을 준용한다.","c":"상","v":1},"공인회2017_52-32-3":{"w":"상법 제429조가 신주발행 무효는 주주·이사·감사만 신주를 발행한 날부터 6월 내에 소로만 주장할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-32-5":{"w":"상법 제432조 제1항이 신주발행무효 판결이 확정되면 회사가 신주의 주주에게 납입한 금액을 반환하도록 정한다.","c":"상","v":1},"공인회2025_60-28-2":{"w":"상법 제429조가 신주발행 무효의 주장 방법을 소로 한정한다.","c":"상","v":1},"공인회2025_60-28-3":{"w":"상법 제420조의4가 신주인수권증서 발행 대신 정관에 따라 전자등록기관의 전자등록부에 신주인수권을 등록할 수 있게 한다.","c":"상","v":1},"공인회2025_60-28-4":{"w":"상법 제421조 제2항이 회사의 동의 없는 인수가액 납입의무와 회사 채권의 상계를 금지한다. 자본충실을 위한 것이다.","c":"상","v":1},"공인회2025_60-28-5":{"w":"상법 제417조 제2항이 액면미달 발행 결의에서 주식의 최저발행가액을 정하도록 정한다.","c":"상","v":1},"공인회2021_56-28-1":{"w":"상법 제421조 제2항이 회사 동의 없는 상계를 금지한다.","c":"상","v":1},"공인회2021_56-28-2":{"w":"상법 제421조 제1항이 이사는 인수인에게 배정 주수에 따라 납입기일에 인수가액 전액을 납입시키도록 정한다.","c":"상","v":1},"공인회2021_56-28-4":{"w":"상법 제427조가 변경등기일부터 1년이 지나거나 주주권을 행사하면 주식청약서 요건 흠결 등을 이유로 인수 무효를 주장하지 못한다고 정한다.","c":"상","v":1},"공인회2021_56-28-5":{"w":"상법 제428조 제1항이 신주발행 변경등기 후 인수되지 않은 주식이나 청약이 취소된 주식은 이사가 공동으로 인수한 것으로 본다고 정한다.","c":"상","v":1},"공인회2026_61-31-1":{"w":"상법 제451조 제2항이 무액면주식의 자본금은 발행가액의 2분의 1 이상으로서 이사회(정관이 정하면 주주총회)가 계상하기로 한 금액의 총액이라고 정한다.","c":"상","v":1},"공인회2026_61-31-2":{"w":"상법 제438조 제2항이 결손 보전을 위한 자본금 감소는 보통결의(제368조 제1항)로 한다고 정한다.","c":"상","v":1},"공인회2026_61-31-3":{"w":"상법 제451조 제2항 후단이 무액면주식 발행가액 중 자본금으로 계상하지 않은 금액은 자본준비금으로 계상하도록 정한다.","c":"상","v":1},"공인회2026_61-31-4":{"w":"상법 제445조가 감자무효는 자본금 감소로 인한 변경등기일부터 6개월 내에 소로만 주장할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-26-1":{"w":"상법 제418조 제1항이 주주는 가진 주식 수에 따라 신주의 배정을 받을 권리가 있다고 정한다.","c":"상","v":1},"공인회2026_61-26-2":{"w":"상법 제416조 본문 제1호가 정관에 규정이 없으면 신주의 종류와 수를 이사회가 결정하도록 정한다. 정관으로 주주총회가 결정하게 할 수 있다.","c":"상","v":1},"공인회2026_61-26-3":{"w":"상법 제423조 제2항이 납입기일에 납입이나 현물출자를 이행하지 않은 신주 인수인은 권리를 잃는다고 정한다.","c":"상","v":1},"공인회2026_61-26-5":{"w":"상법 제425조 제1항이 제302조 제1항을 준용하므로 신주 청약자는 주식청약서 2통에 인수할 주식의 종류·수와 주소를 적고 기명날인 또는 서명해야 한다.","c":"상","v":1},"공인회2026_61-32-2":{"w":"상법 제516조의2 제2항 제5호가 신주인수권 행사 청구가 있으면 사채 상환에 갈음해 발행가액으로 납입이 있은 것으로 본다는 뜻(대용납입)을 정할 수 있게 한다.","c":"상","v":1},"공인회2026_61-32-3":{"w":"상법 제516조의2 제4항이 주주 외의 자에게 신주인수권부사채를 발행할 때 그 액, 신주인수권의 내용, 행사기간에 관해 정관에 규정이 없으면 주주총회 특별결의로 정하도록 한다.","c":"상","v":1},"공인회2026_61-32-4":{"w":"상법 제516조의8 제1항이 신주인수권부사채를 발행한 때 신주인수권 행사로 발행할 주식의 발행가액 총액 등을 등기하도록 정한다.","c":"상","v":1},"공인회2026_61-32-5":{"w":"상법 제516조의2 제3항이 각 사채에 부여된 신주인수권 행사로 발행할 주식의 발행가액 합계액이 각 사채 금액을 넘지 못하게 한다.","c":"상","v":1},"공인회2019_54-31-1":{"w":"상법 제438조 제3항이 자본금 감소에 관한 의안의 주요내용을 소집통지에 적도록 정한다. 결손보전 감자도 예외가 아니다.","c":"상","v":1},"공인회2019_54-32-1":{"w":"상법 제516조 제2항이 제350조를 준용하므로 전환사채의 전환은 사채권자가 청구한 때 효력이 생긴다. 회사의 승낙이 필요 없는 형성권이다.","c":"상","v":1},"공인회2018_53-21-1":{"w":"상법 제513조 제3항이 제418조 제2항 단서를 준용해 제3자 발행을 경영상 목적이 있는 경우로 한정한다.","c":"상","v":1},"공인회2018_53-21-2":{"w":"상법 제514조의2 제1항이 전환사채를 발행하면 납입 완료일부터 2주 내에 본점 소재지에서 등기하도록 정한다.","c":"상","v":1},"공인회2018_53-21-3":{"w":"상법 제516조 제2항이 준용하는 제350조 제1항에 따라 전환 청구 시 효력이 생긴다.","c":"상","v":1},"공인회2018_53-21-5":{"w":"상법 제516조의2 제3항이 각 신주인수권부사채의 신주인수권 행사로 발행할 주식의 발행가액 합계가 그 사채 금액을 넘지 못한다고 정한다.","c":"상","v":1},"공인회2017_52-28-4":{"w":"상법 제485조 제1항이 사채관리회사가 둘 이상이면 그 권한에 속하는 행위를 공동으로 하도록 정한다.","c":"상","v":1},"공인회2022_57-30-1":{"w":"상법 제469조 제1항이 회사는 이사회 결의로 사채를 발행할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-30-2":{"w":"상법 제476조 제1항이 사채 모집 완료 후 이사가 지체 없이 인수인에게 전액 또는 제1회 납입을 시키도록 정한다.","c":"상","v":1},"공인회2022_57-30-4":{"w":"상법 제516조의2 제4항이 주주 외의 자에 대한 신주인수권부사채 발행 사항을 정관에 정하지 않았으면 주주총회 특별결의로 정하도록 한다.","c":"상","v":1},"공인회2022_57-30-5":{"w":"상법 제486조 제1항이 이권 있는 무기명사채를 상환할 때 이권이 흠결되면 그 금액을 상환액에서 공제한다고 정한다.","c":"상","v":1},"공인회2016_51-28-1":{"w":"상법 제469조 제4항이 정관에 따라 이사회가 대표이사에게 사채의 금액과 종류를 정해 1년을 넘지 않는 기간 내에 발행하도록 위임할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-23-1":{"w":"상법 제423조 제2항이 납입기일에 납입하지 않은 인수인은 권리를 잃는다고 정한다. 설립 때(제307조)와 달리 실권 예고 절차가 없다.","c":"상","v":1},"공인회2017_52-23-2":{"w":"상법 제418조 제2항이 정관에 정한 바에 따라 신기술 도입, 재무구조 개선 등 경영상 목적 달성에 필요한 경우에만 주주 외의 자에게 신주를 배정할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-23-3":{"w":"상법 제417조 제1항이 회사 성립 후 2년이 지나면 주주총회 특별결의와 법원 인가를 얻어 액면미달 발행을 할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-23-5":{"w":"상법 제420조의5 제2항이 신주인수권증서 상실자는 주식청약서로 청약할 수 있되 증서에 의한 청약이 있으면 그 청약은 효력을 잃는다고 정한다.","c":"상","v":1},"공인회2022_57-32-1":{"w":"상법 제438조 제1항이 자본금 감소에는 제434조의 특별결의를 요구한다. 결손보전 감자만 보통결의다(제2항).","c":"상","v":1},"공인회2022_57-32-2":{"w":"상법 제439조 제2항 단서가 결손 보전을 위한 자본금 감소는 채권자보호절차를 거치지 않아도 된다고 정한다.","c":"상","v":1},"공인회2022_57-32-3":{"w":"판례는 감자 결의에 취소나 무효 사유가 있어도 감자가 존재하지 않는 정도의 중대한 하자가 아니면 감자 효력 발생 후에는 감자무효의 소(상법 제445조)로만 다툴 수 있다고 본다(흡수설).","c":"상","v":1},"공인회2022_57-32-5":{"w":"상법 제445조가 감자무효의 소 제소권자를 주주·이사·감사·청산인·파산관재인·감자를 승인하지 않은 채권자로, 제소기간을 변경등기일부터 6개월로 정한다.","c":"상","v":1},"공인회2018_53-26-2":{"w":"상법 제439조 제3항이 사채권자가 이의를 제기하려면 사채권자집회 결의가 있어야 한다고 정한다.","c":"상","v":1},"공인회2018_53-26-3":{"w":"판례는 감자 결의의 하자가 극히 중대해 감자가 존재하지 않는 정도가 아니면 효력 발생 후에는 감자무효의 소로만 다툴 수 있다고 본다.","c":"상","v":1},"공인회2018_53-26-4":{"w":"감자무효의 소를 낼 수 있는 채권자는 자본금 감소를 승인하지 않은 채권자이고(상법 제445조), 이의기간 내에 이의를 제기하지 않은 채권자는 승인한 것으로 본다(제439조 제2항, 제232조 제2항).","c":"상","v":1},"공인회2018_53-26-5":{"w":"상법 제446조가 제189조를 준용하므로 하자가 보완되고 무효로 하는 것이 부적당하면 법원이 재량으로 기각할 수 있다.","c":"상","v":1},"공인회2016_51-26-4":{"w":"상법 제439조 제3항의 사채권자 이의 요건이다. 법원은 이해관계인의 청구로 사채권자 이의기간을 연장할 수 있다.","c":"상","v":1},"공인회2025_60-29-1":{"w":"상법 제438조 제2항이 결손 보전을 위한 자본금 감소는 보통결의(제368조 제1항)로 한다고 정한다. 그 밖의 감자는 특별결의다(제1항).","c":"상","v":1},"공인회2025_60-29-2":{"w":"상법 제438조 제3항이 자본금 감소에 관한 의안의 주요내용을 주주총회 소집통지에 적도록 정한다.","c":"상","v":1},"공인회2025_60-29-4":{"w":"상법 제445조가 감자무효의 소는 자본금 감소로 인한 변경등기일부터 6개월 내에 제기하도록 정한다.","c":"상","v":1},"공인회2025_60-29-5":{"w":"상법 제446조가 제191조를 준용하므로 패소 원고에게 악의 또는 중대한 과실이 있으면 회사에 연대하여 손해배상책임을 진다.","c":"상","v":1},"공인회2025_60-32-1":{"w":"상법 제484조의2 제2항이 사채관리회사는 사채권자에 대하여 선량한 관리자의 주의로 사채를 관리하도록 정한다.","c":"상","v":1},"공인회2025_60-32-2":{"w":"상법 제469조 제4항이 정관에 따라 이사회가 대표이사에게 1년 내 사채 발행을 위임할 수 있다고 정한다. 위임할 때 사채의 금액과 종류를 정해야 한다.","c":"상","v":1},"공인회2025_60-32-4":{"w":"상법 제479조 제1항이 기명사채의 이전은 사채원부에 취득자의 성명·주소를 적고 채권에 성명을 적지 않으면 회사 기타 제3자에게 대항하지 못한다고 정한다.","c":"상","v":1},"공인회2025_60-32-5":{"w":"상법 제478조 제1항이 채권은 사채 전액의 납입이 완료된 후가 아니면 발행하지 못한다고 정한다.","c":"상","v":1},"공인회2024_59-25-1":{"w":"상법 제428조 제1항이 신주발행 변경등기 후의 미인수 주식이나 청약 취소 주식을 이사가 공동으로 인수한 것으로 본다고 정한다.","c":"상","v":1},"공인회2024_59-25-2":{"w":"상법 제420조의4가 신주인수권증서를 발행하는 대신 정관에 따라 전자등록기관의 전자등록부에 신주인수권을 등록할 수 있게 한다.","c":"상","v":1},"공인회2024_59-25-3":{"w":"상법 제423조 제2항이 납입기일에 납입이나 현물출자를 이행하지 않은 인수인의 실권을 정한다.","c":"상","v":1},"공인회2024_59-25-4":{"w":"상법 제423조 제1항이 납입 또는 현물출자 이행을 한 인수인은 납입기일 다음 날부터 주주의 권리의무가 있다고 정한다.","c":"상","v":1},"공인회2017_52-29-1":{"w":"상법 제464조가 이익배당은 각 주주가 가진 주식 수에 따라 하되 제344조 제1항의 종류주식(이익배당 종류주식 등)은 예외로 한다고 정한다.","c":"상","v":1},"공인회2017_52-29-2":{"w":"상법 제462조의2 제1항이 주주총회 결의로 이익배당을 새로 발행하는 주식으로 할 수 있게 하면서 그 배당은 이익배당총액의 2분의 1을 넘지 못한다고 정한다. 상장회사는 자본시장법 특례로 전부를 주식배당할 수 있다.","c":"상","v":1},"공인회2017_52-29-3":{"w":"배당 결의로 구체적 배당금 지급청구권이 생기면 주식과 분리된 금전채권이 되어 독립하여 양도할 수 있다. 그 소멸시효는 5년이다(상법 제464조의2 제2항).","c":"상","v":1},"공인회2017_52-29-4":{"w":"판례는 대주주가 스스로 배당받을 권리를 포기하거나 소액주주보다 낮은 배당률을 받기로 한 차등배당 결의는 주주평등원칙에 반하지 않아 유효하다고 본다. 불이익을 받는 주주 스스로 동의한 것이기 때문이다.","c":"상","v":1},"공인회2022_57-29-1":{"w":"상법 제451조 제2항 후단이 무액면주식 발행가액 중 자본금으로 계상하지 않은 금액을 자본준비금으로 계상하도록 정한다.","c":"상","v":1},"공인회2022_57-29-2":{"w":"상법 제461조 제1항이 회사는 이사회 결의로 준비금의 전부 또는 일부를 자본금에 전입할 수 있다고 정한다. 정관으로 주주총회에서 결정하도록 정하면 예외다.","c":"상","v":1},"공인회2022_57-29-4":{"w":"상법 제462조의2 제1항 단서가 주식배당은 이익배당총액의 2분의 1을 넘지 못한다고 정한다.","c":"상","v":1},"공인회2022_57-29-5":{"w":"상법 제462조의2 제6항이 제340조 제1항의 등록질권자의 권리는 주식배당으로 받을 주식에 미친다고 정한다.","c":"상","v":1},"공인회2022_57-28-1":{"w":"상법 제446조의2가 회사의 회계는 상법과 대통령령으로 규정한 것을 제외하고 일반적으로 공정하고 타당한 회계관행에 따른다고 정한다.","c":"상","v":1},"공인회2022_57-28-2":{"w":"상법 제447조의2 제1항이 영업보고서를 작성해 이사회 승인을 받도록 정한다. 그 영업보고서는 정기총회에 제출해 보고한다(제449조 제2항).","c":"상","v":1},"공인회2022_57-28-3":{"w":"상법 제448조 제2항이 주주와 회사채권자는 영업시간 내에 언제든지 재무제표 등을 열람하고 비용을 내고 등본이나 초본을 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-28-4":{"w":"상법 제448조 제1항이 정기총회 회일 1주 전부터 재무제표와 부속명세서, 영업보고서, 감사보고서를 본점에 5년간, 등본을 지점에 3년간 비치하도록 정한다.","c":"상","v":1},"공인회2026_61-27-1":{"w":"영업보고서는 이사가 작성해 이사회 승인을 받고(상법 제447조의2 제1항) 정기총회에 제출해 그 내용을 보고한다(제449조 제2항). 재무제표와 달리 총회 승인 대상이 아니다.","c":"상","v":1},"공인회2026_61-27-2":{"w":"상법 제462조의2 제2항이 주식배당은 권면액으로 하고 종류주식을 발행한 회사는 각각 같은 종류의 주식으로 할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-27-4":{"w":"상법 제447조의4 제1항이 감사는 제447조의3의 서류를 받은 날부터 4주 내에 감사보고서를 이사에게 제출하도록 정한다.","c":"상","v":1},"공인회2026_61-27-5":{"w":"상법 제449조 제3항이 재무제표에 대한 총회 승인을 얻으면 이사가 지체 없이 대차대조표를 공고하도록 정한다.","c":"상","v":1},"공인회2023_58-25-1":{"w":"상법 제461조 제4항이 주주총회 결의로 준비금을 자본금에 전입하면 그 결의가 있은 때부터 주주가 신주의 주주가 된다고 정한다. 이사회 결의로 하면 배정기준일에 주주가 된다(제3항).","c":"상","v":1},"공인회2023_58-29-5":{"w":"상법 제462조의2 제4항이 주식배당을 받은 주주는 그 결의가 있는 주주총회가 종결한 때부터 신주의 주주가 된다고 정한다.","c":"상","v":1},"공인회2024_59-27-1":{"w":"상법 제462조의4가 정관으로 현물배당을 정할 수 있게 하고(제1항), 일정 수 미만의 주식을 가진 주주에게 현물 대신 금전을 지급하기로 정할 수 있게 한다(제2항 제2호).","c":"상","v":1},"공인회2024_59-27-2":{"w":"상법 제462조의3 제1항이 연 1회 결산기 회사는 정관으로 영업연도 중 1회에 한해 이사회 결의로 일정한 날을 정해 중간배당을 할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-27-4":{"w":"상법 제462조의2 제2항이 주식배당은 주식의 권면액으로 하고 종류주식을 발행한 회사는 각각 같은 종류의 주식으로 할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-27-5":{"w":"상법 제462조 제3항이 배당가능이익 한도를 위반한 이익배당에 대해 회사채권자가 배당한 이익을 회사에 반환하라고 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-33-1":{"w":"상법 제461조 제1항이 이사회 결의로 준비금의 전부 또는 일부를 자본금에 전입할 수 있게 하면서 정관으로 주주총회가 결정하도록 정하면 예외로 한다.","c":"상","v":1},"공인회2026_61-33-2":{"w":"상법 제461조의2가 자본준비금과 이익준비금의 총액이 자본금의 1.5배를 초과하면 주주총회 결의로 그 초과 범위에서 감액할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-33-3":{"w":"상법 제461조 제4항이 주주총회 결의로 전입하면 결의가 있은 때부터 신주의 주주가 된다고 정한다.","c":"상","v":1},"공인회2026_61-33-5":{"w":"상법 제460조가 법정준비금은 자본금 결손 보전에 충당하는 경우 외에는 처분하지 못한다고 정한다. 자본전입(제461조)과 감액(제461조의2)은 별도 규정으로 허용된다.","c":"상","v":1},"공인회2018_53-30-1":{"w":"상법 제391조의3 제3항이 주주에게 이사회 의사록 열람·등사 청구권을 준다. 회사는 이유를 붙여 거절할 수 있고 그러면 주주는 법원 허가를 얻어 열람할 수 있다(같은 조 제4항).","c":"상","v":1},"공인회2018_53-30-2":{"w":"상법 제396조 제1항이 주주총회 의사록을 본점과 지점에 비치하도록 정한다. 주주와 회사채권자는 영업시간 내에 열람·등사를 청구할 수 있다(같은 조 제2항).","c":"상","v":1},"공인회2018_53-30-3":{"w":"상법 제448조 제1항이 감사보고서 등을 정기총회 회일 1주 전부터 본점에 5년간 비치하도록 정한다. 주주와 회사채권자는 영업시간 내에 언제든지 열람할 수 있다(같은 조 제2항).","c":"상","v":1},"공인회2018_53-30-5":{"w":"상법 제522조의2 제1항이 합병계약서 등을 총회 2주 전부터 합병한 날 이후 6개월이 지나는 날까지 본점에 비치하도록 정한다. 주주와 회사채권자는 영업시간 내에 열람을 청구할 수 있다(같은 조 제2항).","c":"상","v":1},"공인회2017_52-24-1":{"w":"상법 제448조 제2항이 주주와 회사채권자의 재무제표 열람과 등본·초본 교부청구권을 정한다.","c":"상","v":1},"공인회2017_52-24-2":{"w":"상법 제461조 제1항 단서가 정관으로 주주총회에서 준비금 자본전입을 결정하도록 정할 수 있게 한다.","c":"상","v":1},"공인회2017_52-24-4":{"w":"상법 제459조 제1항이 자본거래에서 발생한 잉여금을 대통령령이 정하는 회계기준에 따라 자본준비금으로 적립하도록 정한다.","c":"상","v":1},"공인회2017_52-24-5":{"w":"상법 제461조의2가 자본준비금과 이익준비금 총액이 자본금의 1.5배를 넘으면 주주총회 결의로 그 초과 범위에서 감액할 수 있다고 정한다.","c":"상","v":1},"공인회2020_55-32-2":{"w":"상법 제458조가 자본금의 2분의 1이 될 때까지 매 결산기 이익배당액의 10분의 1 이상을 이익준비금으로 적립하되 주식배당은 제외한다고 정한다.","c":"상","v":1},"공인회2020_55-32-3":{"w":"상법 제462조의4 제1항이 정관으로 금전 외의 재산으로 배당할 수 있음을 정할 수 있게 한다.","c":"상","v":1},"공인회2020_55-32-4":{"w":"상법 제461조의2가 법정준비금 총액이 자본금의 1.5배를 초과하면 주주총회 결의로 초과분 범위에서 감액할 수 있게 한다.","c":"상","v":1},"공인회2020_55-32-5":{"w":"상법 제462조의3 제1항이 연 1회 결산기를 정한 회사는 정관으로 영업연도 중 1회에 한해 이사회 결의로 중간배당을 할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-30-1":{"w":"이사는 이사회 승인을 받은 재무제표를 정기총회에 제출해 승인을 요구하고(상법 제449조 제1항), 승인을 얻으면 지체 없이 대차대조표를 공고한다(같은 조 제3항). 정관과 요건을 갖추면 이사회가 승인할 수 있다(제449조의2).","c":"상","v":1},"공인회2025_60-30-3":{"w":"상법 제460조가 이익준비금과 자본준비금을 자본금의 결손 보전에 충당할 수 있게 한다.","c":"상","v":1},"공인회2025_60-30-4":{"w":"상법 제459조 제2항이 합병이나 분할·분할합병의 경우 소멸·분할되는 회사의 법정준비금을 존속·신설회사가 승계할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-30-5":{"w":"상법 제458조가 자본금의 2분의 1이 될 때까지 매 결산기 이익배당액의 10분의 1 이상을 이익준비금으로 적립하도록 정하고 주식배당은 제외한다.","c":"상","v":1},"공인회2022_57-31-1":{"w":"상법 제542조 제1항이 제245조를 준용하므로 해산한 회사도 청산의 목적 범위에서 존속하는 것으로 본다.","c":"상","v":1},"공인회2022_57-31-2":{"w":"상법 제539조 제1항이 법원이 선임한 청산인 외에는 언제든지 주주총회 결의로 청산인을 해임할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-31-3":{"w":"상법 제539조 제2항이 청산인이 현저하게 부적임하거나 중대한 임무 위반을 하면 3% 이상 주주가 법원에 해임을 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-31-5":{"w":"상법 제534조 제1항이 감사가 있는 회사의 청산인은 정기총회 회일 4주 전에 대차대조표와 부속명세서, 사무보고서를 작성해 감사에게 제출하도록 정한다.","c":"상","v":1},"공인회2021_56-09-5":{"w":"상법 제176조 제1항 제2호가 정당한 사유 없이 설립 후 1년 내에 영업을 개시하지 않으면 법원이 이해관계인·검사의 청구 또는 직권으로 해산을 명할 수 있게 한다.","c":"상","v":1},"공인회2025_60-34-1":{"w":"상법 제518조가 해산 결의는 제434조의 특별결의로 하도록 정한다.","c":"상","v":1},"공인회2025_60-34-3":{"w":"상법 제520조 제1항 제1호가 업무가 현저한 정돈상태를 계속해 회복할 수 없는 손해가 생기거나 생길 염려가 있고 부득이한 사유가 있으면 10% 이상 주주가 해산판결을 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-34-4":{"w":"상법 제519조가 존립기간 만료 등 정관 사유나 해산 결의로 해산한 경우 주주총회 특별결의로 회사를 계속할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-34-5":{"w":"상법 제521조가 회사가 해산하면 파산의 경우 외에는 이사가 지체 없이 주주에게 통지하도록 정한다.","c":"상","v":1},"공인회2017_52-10-1":{"w":"상법 제176조 제1항 제1호가 설립목적이 불법한 경우를 해산명령 사유로 정한다. 법원은 직권으로도 해산을 명할 수 있다.","c":"상","v":1},"공인회2017_52-10-2":{"w":"상법 제176조 제1항 제2호가 정당한 사유 없는 1년 이상의 영업 휴지를 해산명령 사유로 정한다.","c":"상","v":1},"공인회2017_52-10-3":{"w":"상법 제176조 제1항 제3호가 이사나 업무집행사원이 법령·정관에 위반해 회사 존속을 허용할 수 없는 행위를 한 경우를 해산명령 사유로 정한다. 검사의 청구로도 명할 수 있다.","c":"상","v":1},"공인회2017_52-10-5":{"w":"상법 제176조 제2항이 해산명령 전이라도 이해관계인이나 검사의 청구 또는 직권으로 관리인 선임 등 회사재산 보전에 필요한 처분을 할 수 있다고 정한다.","c":"상","v":1},"공인회2016_51-30-1":{"w":"상법 제530조의3 제1항·제2항이 분할계획서를 작성해 주주총회 특별결의(제434조)로 승인받도록 정한다.","c":"상","v":1},"공인회2016_51-30-3":{"w":"상법 제530조의9 제1항이 분할회사와 단순분할신설회사는 분할 전 분할회사 채무에 대해 연대책임을 진다고 정한다. 분할계획서로 책임을 제한하려면 채권자보호절차를 거쳐야 한다(제2항·제4항).","c":"상","v":1},"공인회2016_51-30-4":{"w":"상법 제530조의10이 단순분할신설회사는 분할회사의 권리와 의무를 분할계획서에서 정하는 바에 따라 승계한다고 정한다.","c":"상","v":1},"공인회2016_51-30-5":{"w":"상법 제530조의11 제1항이 합병무효의 소에 관한 제529조를 준용하므로 감사도 분할등기일부터 6월 내에 분할무효의 소를 제기할 수 있다.","c":"상","v":1},"공인회2023_58-30-1":{"w":"상법 제530조의11 제1항이 제526조를 준용하므로 분할승계회사의 이사회는 공고로 주주총회 보고를 갈음할 수 있다(제526조 제3항).","c":"상","v":1},"공인회2026_61-30-2":{"w":"상법은 분할합병에만 반대주주 주식매수청구권을 준다(제530조의11 제2항, 제522조의3). 단순분할은 물적분할을 포함해 주주의 지분 가치가 그대로여서 매수청구권이 없다.","c":"상","v":1},"공인회2022_57-27-2":{"w":"상법 제523조의2 제1항이 합병대가에 존속회사의 모회사주식이 포함되면 존속회사가 그 지급을 위해 모회사주식을 취득할 수 있게 한다(삼각합병). 합병 효력 발생일부터 6개월 내에 남은 주식을 처분해야 한다(제2항).","c":"상","v":1},"공인회2022_57-27-3":{"w":"상법 제525조 제1항이 합병 당사회사 일방이 합명회사나 합자회사이고 존속·신설회사가 주식회사이면 총사원의 동의를 얻어 합병계약서를 작성하도록 정한다.","c":"상","v":1},"공인회2022_57-27-4":{"w":"상법 제529조 제2항이 합병무효의 소는 합병등기일부터 6월 내에 제기하도록 정한다.","c":"상","v":1},"공인회2022_57-27-5":{"w":"판례는 현저하게 불공정한 합병비율을 정한 합병계약은 신의성실·공평의 원칙에 비추어 무효라고 본다. 각 회사의 주주는 합병무효의 소(상법 제529조)로 다툴 수 있다.","c":"상","v":1},"공인회2024_59-22-1":{"w":"상법 제523조 제4호가 합병계약서에 소멸회사 주주에게 합병대가의 전부 또는 일부로 금전이나 그 밖의 재산을 제공하는 사항을 정할 수 있게 한다(교부금합병).","c":"상","v":1},"공인회2024_59-22-2":{"w":"상법 제341조의2 제1호가 합병으로 인한 경우 제341조의 배당가능이익 제한 없이 자기주식을 취득할 수 있게 한다.","c":"상","v":1},"공인회2024_59-22-3":{"w":"상법 제527조의5 제2항이 간이합병과 소규모합병에서는 이사회 승인결의를 주주총회 승인결의로 보아 채권자보호절차를 적용하므로 존속회사와 소멸회사 모두 이를 거쳐야 한다.","c":"상","v":1},"공인회2024_59-22-5":{"w":"상법 제529조 제1항이 합병무효의 주장 방법과 제소권자를 이렇게 한정한다.","c":"상","v":1},"공인회2026_61-16-1":{"w":"상법 제360조의9 제1항이 완전모회사가 될 회사가 완전자회사가 될 회사 주식의 90% 이상을 가지면 완전자회사의 주주총회 승인을 이사회 승인으로 갈음할 수 있게 한다(간이주식교환).","c":"상","v":1},"공인회2026_61-16-2":{"w":"상법 제360조의3 제5항이 주식교환으로 관련 회사 주주의 부담이 가중되면 주주총회·종류주주총회 결의 외에 그 주주 전원의 동의를 요구한다.","c":"상","v":1},"공인회2026_61-16-3":{"w":"상법 제360조의13이 완전모회사의 이사·감사로서 교환 전에 취임한 자는 계약서에 다른 정함이 없으면 교환 후 최초 결산기에 관한 정기총회 종료 때 퇴임한다고 정한다.","c":"상","v":1},"공인회2026_61-16-5":{"w":"상법 제360조의3 제6항이 교환대가에 완전모회사가 될 회사의 모회사 주식이 포함되면 그 지급을 위해 모회사 주식을 취득할 수 있게 한다(삼각주식교환).","c":"상","v":1},"공인회2022_57-26-1":{"w":"상법 제360조의23 제4항이 제190조(단서 포함)를 준용하므로 주식이전무효 판결은 제3자에게 효력이 있고 장래에 대해서만 효력이 생긴다.","c":"상","v":1},"공인회2022_57-26-2":{"w":"상법 제360조의3 제1항·제2항이 주식교환계약서를 작성해 주주총회 특별결의로 승인받도록 정한다.","c":"상","v":1},"공인회2022_57-26-4":{"w":"상법 제436조가 주식이전으로 어느 종류의 주주에게 손해를 미치면 제435조를 준용해 종류주주총회 결의를 요구한다.","c":"상","v":1},"공인회2022_57-26-5":{"w":"상법 제360조의14 제2항이 주식교환무효의 소를 완전모회사가 되는 회사의 본점 소재지 지방법원 전속관할로 정한다.","c":"상","v":1},"공인회2020_55-16-1":{"w":"상법 제360조의18이 주식이전으로 설립하는 완전모회사의 자본금은 완전자회사의 현존 순자산액에서 그 주주에게 제공할 금전 등의 가액을 뺀 금액을 넘지 못한다고 정한다.","c":"상","v":1},"공인회2020_55-16-2":{"w":"간이주식교환에서는 완전자회사의 주주총회 승인을 이사회 승인으로 갈음할 수 있고(상법 제360조의9 제1항), 반대 의사를 통지한 주주에게 주식매수청구권이 인정된다(제360조의5 제2항).","c":"상","v":1},"공인회2020_55-16-4":{"w":"주식회사에서 유한회사로의 조직변경은 총주주 동의 결의로 하고 법원 인가가 필요 없지만(상법 제604조), 유한회사에서 주식회사로의 조직변경은 법원 인가가 없으면 효력이 없다(제607조 제3항).","c":"상","v":1},"공인회2020_55-16-5":{"w":"상법 제287조의43 제1항이 주식회사의 유한책임회사로의 조직변경을 허용한다. 유한회사와 유한책임회사 사이의 조직변경 규정은 없다.","c":"상","v":1},"공인회2021_56-29-1":{"w":"상법 제360조의2 제2항이 완전자회사가 되는 회사 주주의 주식은 주식교환일에 완전모회사가 되는 회사로 이전한다고 정한다.","c":"상","v":1},"공인회2021_56-29-3":{"w":"상법 제360조의23 제4항이 제193조를 준용하므로 주식이전무효 판결이 확정되면 완전모회사는 해산의 경우에 준하여 청산한다.","c":"상","v":1},"공인회2021_56-29-4":{"w":"상법 제360조의9 제1항이 완전모회사가 될 회사가 완전자회사가 될 회사 주식의 90% 이상을 가지면 완전자회사의 주주총회 승인을 이사회 승인으로 갈음할 수 있게 한다.","c":"상","v":1},"공인회2021_56-29-5":{"w":"주식이전은 완전모회사가 본점 소재지에서 2주 내에 등기를 함으로써 효력이 생긴다(상법 제360조의20, 제360조의21).","c":"상","v":1},"공인회2026_61-15-3":{"w":"상법 제360조의23 제4항이 제193조를 준용하므로 주식이전무효 판결이 확정되면 완전모회사는 해산에 준하여 청산한다.","c":"상","v":1},"공인회2017_52-31-1":{"w":"상법 제530조의2 제2항이 분할로 1개 또는 수개의 존립 중의 회사와 합병(분할합병)할 수 있게 한다.","c":"상","v":1},"공인회2017_52-31-2":{"w":"상법 제530조의3 제3항이 분할 승인 특별결의에는 제344조의3 제1항에 따라 의결권이 배제되는 주주도 의결권이 있다고 정한다.","c":"상","v":1},"공인회2017_52-31-4":{"w":"상법 제530조의9 제1항이 분할회사와 단순분할신설회사의 연대책임을 원칙으로 정한다.","c":"상","v":1},"공인회2017_52-31-5":{"w":"상법 제530조의3 제6항이 분할·분할합병으로 관련 회사 주주의 부담이 가중되면 주주총회와 종류주주총회 결의 외에 그 주주 전원의 동의를 요구한다.","c":"상","v":1},"공인회2018_53-20-5":{"w":"상법 제530조의10이 단순분할신설회사는 분할회사의 권리와 의무를 분할계획서에서 정하는 바에 따라 승계한다고 정한다.","c":"상","v":1},"공인회2020_55-31-1":{"w":"상법 제530조의3 제3항이 의결권 배제 주주에게도 분할 승인 결의의 의결권을 준다.","c":"상","v":1},"공인회2020_55-31-2":{"w":"주식매수청구권은 분할합병에 대해서만 인정되고(상법 제530조의11 제2항, 제522조의3) 단순분할에는 규정이 없다.","c":"상","v":1},"공인회2020_55-31-3":{"w":"물적분할도 단순분할이므로 상법상 반대주주의 주식매수청구권이 인정되지 않는다(제530조의12, 제530조의11 제2항).","c":"상","v":1},"공인회2020_55-31-5":{"w":"상법 제530조의10이 단순분할신설회사의 권리의무 승계 범위를 분할계획서에 따르도록 정한다.","c":"상","v":1},"공인회2016_51-29-1":{"w":"상법 제522조 제2항이 합병계약의 요령을 소집통지에 적도록 정한다.","c":"상","v":1},"공인회2016_51-29-3":{"w":"상법 제523조의2 제1항이 소멸회사 주주에게 주는 재산에 존속회사의 모회사주식이 포함되면 존속회사가 그 지급을 위해 모회사주식을 취득할 수 있게 한다.","c":"상","v":1},"공인회2016_51-29-4":{"w":"상법 제527조의5 제1항이 합병 승인결의일부터 2주 내에 1월 이상의 이의제출 기간을 공고하고 알고 있는 채권자에게 따로 최고하도록 정한다.","c":"상","v":1},"공인회2016_51-29-5":{"w":"상법 제527조의4 제1항이 존속회사의 이사·감사로서 합병 전에 취임한 자는 계약서에 다른 정함이 없으면 합병 후 최초 결산기에 관한 정기총회 종료 때 퇴임한다고 정한다.","c":"상","v":1},"공인회2018_53-19-1":{"w":"상법 제522조 제2항이 합병계약서 승인 총회의 소집통지에 합병계약의 요령을 적도록 정한다.","c":"상","v":1},"공인회2018_53-19-2":{"w":"상법 제523조의2 제1항이 삼각합병에서 존속회사의 모회사주식 취득을 허용한다. 자회사의 모회사주식 취득 금지(제342조의2)의 예외다.","c":"상","v":1},"공인회2018_53-19-3":{"w":"상법 제527조의2 제1항이 존속회사가 소멸회사 주식의 90% 이상을 가지면 소멸회사 주주총회 승인을 이사회 승인으로 갈음할 수 있게 한다(간이합병).","c":"상","v":1},"공인회2018_53-19-5":{"w":"상법 제528조 제2항이 존속·신설회사가 합병으로 전환사채나 신주인수권부사채를 승계하면 합병등기와 동시에 사채등기를 하도록 정한다.","c":"상","v":1},"공인회2020_55-30-3":{"w":"상법 제527조의3 제1항 단서가 소멸회사 주주에게 제공할 금전 등이 존속회사 순자산액의 5%를 넘으면 소규모합병을 할 수 없게 하므로 존속회사 주주총회 특별결의가 필요하다.","c":"상","v":1},"공인회2018_53-24-2":{"w":"상법 제287조의44가 제607조 제2항을 준용하므로 유한책임회사가 주식회사로 변경할 때 발행하는 주식의 발행가액 총액은 현존 순재산액을 넘지 못한다.","c":"상","v":1},"공인회2026_61-10-1":{"w":"상법 제286조 제1항이 합자회사는 사원 전원의 동의로 합명회사로 조직변경할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-10-2":{"w":"상법 제287조의43 제1항이 주식회사는 총회에서 총주주의 동의로 결의하면 유한책임회사로 조직변경할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-10-3":{"w":"상법 제604조 제1항 단서가 사채 상환을 완료하지 않은 주식회사는 유한회사로 조직변경할 수 없다고 정한다. 유한회사는 사채를 발행할 수 없기 때문이다.","c":"상","v":1},"공인회2026_61-10-5":{"w":"상법 제607조 제3항이 유한회사의 주식회사로의 조직변경은 법원 인가를 받지 않으면 효력이 없다고 정한다.","c":"상","v":1},"공인회2017_52-30-1":{"w":"상법 제523조 제4호가 합병대가로 금전이나 그 밖의 재산을 제공할 수 있게 한다.","c":"상","v":1},"공인회2017_52-30-3":{"w":"상법 제527조의3 제1항 단서가 소멸회사 주주에게 제공할 금전 등이 존속회사 순자산액의 5%를 넘으면 소규모합병을 할 수 없다고 정한다.","c":"상","v":1},"공인회2017_52-30-4":{"w":"판례는 합병비율이 현저하게 불공정하면 합병계약이 무효가 되어 주주가 합병무효의 소를 제기할 수 있다고 본다.","c":"상","v":1},"공인회2017_52-30-5":{"w":"상법 제523조의2 제1항이 자회사인 존속회사가 합병대가 지급을 위해 모회사주식을 취득할 수 있게 한다. 모회사주식 취득 금지(제342조의2)의 예외다.","c":"상","v":1},"공인회2021_56-31-1":{"w":"상법 제174조 제3항이 해산 후의 회사는 존립 중의 회사를 존속회사로 하는 경우에만 합병할 수 있다고 정한다.","c":"상","v":1},"공인회2021_56-31-3":{"w":"상법 제527조의3 제5항이 소규모합병에는 제522조의3(반대주주의 주식매수청구권)을 적용하지 않는다고 정한다.","c":"상","v":1},"공인회2021_56-31-4":{"w":"판례는 합병 승인 결의의 하자는 합병등기 전에는 결의무효확인의 소 등으로 다툴 수 있지만 합병 효력이 생긴 뒤에는 합병무효의 소로만 다툴 수 있다고 본다(흡수설).","c":"상","v":1},"공인회2021_56-31-5":{"w":"상법 제530조 제2항이 준용하는 제239조 제1항에 따라 합병무효 판결이 확정되면 합병한 회사들이 존속회사가 합병 후 부담한 채무에 연대책임을 진다.","c":"상","v":1},"공인회2017_52-18-1":{"w":"상법 제185조가 합명회사 사원이 채권자를 해할 것을 알고 회사를 설립하면 채권자가 그 사원과 회사를 상대로 설립취소의 소를 제기할 수 있다고 정한다.","c":"상","v":1},"공인회2021_56-27-1":{"w":"상법 제287조의23 제1항이 유한책임회사는 정관을 변경해 새 사원을 가입시킬 수 있다고 정한다. 가입은 정관을 변경한 때 효력이 생기되 출자를 이행하지 않았으면 이행한 때 효력이 생긴다(제2항).","c":"상","v":1},"공인회2022_57-10-1":{"w":"상법 제287조의7이 유한책임회사 사원의 책임은 다른 규정이 없으면 출자금액을 한도로 한다고 정한다.","c":"상","v":1},"공인회2022_57-10-3":{"w":"업무집행자의 성명·주소는 정관 기재사항이고(상법 제287조의3 제4호) 업무집행자는 정관으로 정하므로(제287조의12 제1항) 이를 바꾸려면 정관변경(제287조의16)이 필요하다.","c":"상","v":1},"공인회2022_57-10-4":{"w":"상법 제287조의20이 대표 업무집행자의 업무집행으로 타인에게 손해를 입히면 회사가 그와 연대하여 배상한다고 정한다.","c":"상","v":1},"공인회2022_57-10-5":{"w":"상법 제287조의37 제2항이 잉여금 한도(제1항)를 위반한 분배에 대해 회사채권자가 분배받은 자에게 회사에 반환하라고 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-26-1":{"w":"상법 제287조의4 제1항이 신용·노무 출자를 금지한다. 출자는 설립등기 때까지 전부 이행해야 한다(같은 조 제2항).","c":"상","v":1},"공인회2024_59-26-2":{"w":"상법 제287조의9 제1항이 유한책임회사의 자기지분 양수를 금지한다. 회사가 지분을 취득하면 그 지분은 취득한 때 소멸한다(같은 조 제2항).","c":"상","v":1},"공인회2024_59-26-4":{"w":"상법 제287조의16이 정관에 다른 규정이 없으면 정관 변경에 총사원의 동의를 요구한다.","c":"상","v":1},"공인회2024_59-26-5":{"w":"상법 제287조의18이 유한책임회사의 내부관계에 정관이나 상법에 다른 규정이 없으면 합명회사 규정을 준용한다고 정한다.","c":"상","v":1},"공인회2016_51-32-5":{"w":"유한책임회사는 사원이면 누구나 대표소송 제기를 청구할 수 있고(상법 제287조의22 제1항), 유한회사는 자본금 총액 3% 이상의 출자좌수를 가진 사원만 청구할 수 있다(제565조 제1항).","c":"상","v":1},"공인회2017_52-22-3":{"w":"상법 제607조 제1항이 유한회사의 주식회사로의 조직변경은 총사원 일치 총회 결의로 하되 정관으로 정하면 제585조의 특별결의로 할 수 있다고 정한다. 법원 인가도 필요하다(제3항).","c":"상","v":1},"공인회2020_55-26-1":{"w":"상법 제562조 제2항이 유한회사 이사가 수인이면 정관에 다른 정함이 없는 한 사원총회에서 대표이사를 선정하도록 정한다.","c":"상","v":1},"공인회2020_55-26-2":{"w":"상법 제550조 제1항이 현물출자 재산의 회사 성립 당시 실가가 정관에 정한 가격에 현저히 부족하면 성립 당시 사원이 그 부족액을 연대하여 지급하도록 정한다.","c":"상","v":1},"공인회2020_55-26-3":{"w":"상법 제552조 제1항이 유한회사 설립무효는 사원, 이사, 감사만 회사 성립일부터 2년 내에 소로만 주장할 수 있다고 정한다.","c":"상","v":1},"공인회2020_55-26-4":{"w":"상법 제547조 제1항이 정관으로 이사를 정하지 않으면 회사 성립 전에 사원총회를 열어 선임하도록 정한다.","c":"상","v":1},"공인회2021_56-25-4":{"w":"상법 제593조 제1항이 증자 시 현물출자 재산의 실가가 증자 결의로 정한 가격에 현저히 부족하면 그 결의에 동의한 사원이 부족액을 연대하여 지급하도록 정한다.","c":"상","v":1},"공인회2025_60-11-1":{"w":"상법 제543조 제2항 제4호가 각 사원의 출자좌수를 유한회사 정관의 절대적 기재사항으로 정한다.","c":"상","v":1},"공인회2025_60-11-3":{"w":"상법 제565조 제1항이 자본금 총액 3% 이상의 출자좌수를 가진 사원에게 이사 책임추궁 소의 제기 청구권을 준다.","c":"상","v":1},"공인회2025_60-11-4":{"w":"상법 제568조 제1항이 유한회사는 정관으로 1명 또는 여러 명의 감사를 둘 수 있다고 정하므로 감사는 임의기관이다.","c":"상","v":1},"공인회2025_60-11-5":{"w":"상법 제592조가 유한회사의 자본금 증가는 본점 소재지에서 증가 등기를 함으로써 효력이 생긴다고 정한다.","c":"상","v":1},"공인회2024_59-32-1":{"w":"상법 제571조 제2항이 사원총회 소집은 총회일 1주 전에 각 사원에게 서면 또는 동의를 받은 전자문서로 통지서를 발송하도록 정한다. 주식회사(2주 전)보다 짧다.","c":"상","v":1},"공인회2024_59-32-2":{"w":"상법 제572조 제1항이 자본금 총액 3% 이상의 출자좌수를 가진 사원에게 총회 소집청구권을 준다. 정관으로 이 요건을 달리 정할 수 있다(같은 조 제2항).","c":"상","v":1},"공인회2024_59-32-4":{"w":"상법 제574조가 사원총회 보통결의를 총사원 의결권 과반수 출석과 출석 의결권 과반수로 정한다. 주식회사와 달리 의사정족수가 있다.","c":"상","v":1},"공인회2024_59-32-5":{"w":"상법 제575조가 각 사원은 출자 1좌마다 1개의 의결권을 가지되 정관으로 다르게 정할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-09-2":{"w":"상법 제208조 제1항이 합명회사는 정관 또는 총사원의 동의로 수인의 사원이 공동으로 회사를 대표하도록 정할 수 있다고 정한다.","c":"상","v":1},"공인회2016_51-31-4":{"w":"상법 제199조가 합명회사 사원은 다른 사원 과반수의 결의가 있어야 자기 또는 제3자의 계산으로 회사와 거래할 수 있다고 정한다.","c":"상","v":1},"공인회2019_54-09-4":{"w":"상법 제198조 제1항은 경업금지 대상을 사원으로 정하고 업무집행권이나 대표권 유무를 구별하지 않으므로 모든 사원이 다른 사원 전원의 동의 없이 경업하지 못한다.","c":"상","v":1},"공인회2025_60-09-1":{"w":"상법 제204조가 합명회사 정관 변경에 총사원의 동의를 요구한다.","c":"상","v":1},"공인회2025_60-09-2":{"w":"상법 제194조 제1항이 설립무효·취소 판결이 확정되어도 원인이 특정 사원에 한정되면 다른 사원 전원의 동의로 회사를 계속할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-09-4":{"w":"상법 제223조가 사원 지분의 압류는 장래 이익배당과 지분환급 청구권에도 효력이 있다고 정한다.","c":"상","v":1},"공인회2025_60-09-5":{"w":"상법 제227조 제3호가 사원이 1인으로 된 때를 합명회사 해산 사유로 정한다. 새 사원을 가입시켜 계속할 수 있다(제229조 제2항).","c":"상","v":1},"공인회2026_61-09-1":{"w":"상법 제197조가 사원은 다른 사원의 동의를 얻지 않으면 지분의 전부 또는 일부를 양도하지 못한다고 정한다.","c":"상","v":1},"공인회2026_61-09-2":{"w":"상법 제198조 제1항이 다른 사원의 동의 없는 영업부류 거래와 동종영업 회사의 무한책임사원·이사 겸직을 금지한다.","c":"상","v":1},"공인회2026_61-09-3":{"w":"상법 제199조가 합명회사 사원은 다른 사원 과반수의 결의가 있어야 자기 또는 제3자의 계산으로 회사와 거래할 수 있다고 정한다.","c":"상","v":1},"공인회2026_61-09-4":{"w":"상법 제230조가 합명회사의 합병에 총사원의 동의를 요구한다.","c":"상","v":1},"공인회2021_56-26-4":{"w":"상법 제275조가 유한책임사원은 다른 사원의 동의 없이 자기 또는 제3자의 계산으로 회사 영업부류의 거래를 하고 동종영업 회사의 무한책임사원·이사가 될 수 있다고 정한다.","c":"상","v":1},"공인회2020_55-06-1":{"w":"상법 제86조의4 제1항이 업무집행조합원은 합자조합 설립 후 2주 내에 주된 영업소 소재지에서 등기하도록 정한다.","c":"상","v":1},"공인회2020_55-06-3":{"w":"상법 제86조의6 제1항이 유한책임조합원은 출자가액에서 이행한 부분을 뺀 가액을 한도로 조합채무를 변제할 책임이 있다고 정한다.","c":"상","v":1},"공인회2020_55-06-4":{"w":"상법 제86조의5 제1항이 업무집행조합원은 조합계약에 다른 규정이 없으면 각자 업무를 집행하고 대리할 권리와 의무가 있다고 정한다.","c":"상","v":1},"공인회2020_55-06-5":{"w":"상법 제86조의7 제3항이 유한책임조합원의 지분 양수인은 양도인의 조합에 대한 권리·의무를 승계한다고 정한다.","c":"상","v":1},"공인회2024_59-05-5":{"w":"상법 제86조의7 제1항이 업무집행조합원은 다른 조합원 전원의 동의 없이 지분을 양도하지 못한다고 정한다. 유한책임조합원 지분은 조합계약에 따라 양도한다(제2항).","c":"상","v":1},"공인회2018_53-28-3":{"w":"합자회사에도 제205조가 준용되고(상법 제269조), 판례는 유한책임사원도 업무집행사원의 권한상실 선고를 청구할 수 있다고 본다.","c":"상","v":1},"공인회2020_55-25-1":{"w":"상법 제277조 제2항이 중요한 사유가 있으면 유한책임사원은 언제든지 법원 허가를 얻어 회사의 업무와 재산상태를 검사할 수 있다고 정한다.","c":"상","v":1},"공인회2022_57-16-1":{"w":"상법 제270조가 합자회사 정관에 제179조의 사항 외에 각 사원의 무한책임 또는 유한책임인 것을 적도록 정한다.","c":"상","v":1},"공인회2022_57-16-2":{"w":"상법 제272조가 유한책임사원은 신용 또는 노무를 출자의 목적으로 하지 못한다고 정한다.","c":"상","v":1},"공인회2022_57-16-4":{"w":"상법 제285조 제1항이 무한책임사원 또는 유한책임사원 전원이 퇴사하면 합자회사가 해산된다고 정한다. 남은 사원 전원 동의로 새 사원을 가입시켜 계속할 수 있다(제2항).","c":"상","v":1},"공인회2022_57-16-5":{"w":"상법 제283조 제1항이 유한책임사원이 사망하면 상속인이 지분을 승계해 사원이 된다고 정한다. 무한책임사원의 사망은 퇴사 원인이다(제218조).","c":"상","v":1},"공인회2025_60-10-1":{"w":"신용·노무 출자 금지(상법 제272조)는 유한책임사원에게만 적용되므로 무한책임사원은 합명회사 사원처럼 신용이나 노무를 출자할 수 있다(제269조).","c":"상","v":1},"공인회2025_60-10-2":{"w":"상법 제274조가 합자회사 지배인의 선임과 해임은 업무집행사원이 있는 경우에도 무한책임사원 과반수의 결의로 하도록 정한다.","c":"상","v":1},"공인회2025_60-10-4":{"w":"상법 제276조가 유한책임사원은 무한책임사원 전원의 동의가 있으면 지분을 양도할 수 있다고 정한다.","c":"상","v":1},"공인회2025_60-10-5":{"w":"상법 제279조 제1항이 유한책임사원은 출자가액에서 이행한 부분을 뺀 가액을 한도로 회사채무를 변제할 책임이 있다고 정한다.","c":"상","v":1},"공인회2018_53-23-1":{"w":"합명회사 정관에는 사원의 출자의 목적과 가액 또는 평가표준을 적어야 한다(상법 제179조 제4호). 출자는 사원 지위의 본질적 요소여서 정관으로 출자의무 없는 사원을 둘 수 없다는 것이 통설이다.","c":"중","v":1},"공인회2018_53-23-3":{"w":"상법 제287조의29가 제224조를 준용하므로 지분압류채권자는 영업연도 말에 그 사원을 퇴사시킬 수 있되 6월 전에 회사와 사원에게 예고해야 한다.","c":"상","v":1},"공인회2018_53-23-4":{"w":"상법 제287조의27이 사원 제명에 제220조를 준용하므로 경업금지 위반 등이 있으면 다른 사원 과반수 결의로 법원에 제명 선고를 청구할 수 있다. 결의 요건은 정관으로 달리 정할 수 있다.","c":"중","v":1},"공인회2018_53-23-5":{"w":"상법 제556조가 유한회사 사원은 지분의 전부 또는 일부를 양도하거나 상속할 수 있다고 정한다. 정관으로 양도를 제한할 수 있다.","c":"상","v":1},"공인회2016_51-33-1":{"w":"어음·수표상의 권리는 증권을 작성해 발행함으로써 비로소 생기므로 설권증권이다. 이미 존재하는 권리를 표창하는 주권·화물상환증과 다르다.","c":"중","v":1},"공인회2016_51-33-2":{"w":"어음·수표상의 권리는 원인관계의 존부나 효력에 영향을 받지 않는 무인증권이다. 원인관계의 하자는 직접 당사자 사이의 인적항변(어음법 제17조, 수표법 제22조)으로만 주장된다.","c":"중","v":1},"공인회2016_51-33-3":{"w":"어음법 제11조 제1항과 수표법 제14조 제1항이 지시식으로 발행하지 않았어도 배서로 양도할 수 있다고 정하므로 법률상 당연한 지시증권이다. 배서금지 문구가 있으면 예외다.","c":"상","v":1},"공인회2016_51-33-5":{"w":"발행인의 기명날인 또는 서명은 환어음(어음법 제1조 제8호), 약속어음(제75조 제7호), 수표(수표법 제1조 제6호)의 필수 요건이고 보충 규정이 없다.","c":"상","v":1},"공인회2018_53-35-3":{"w":"전원합의체 판례(2010년)는 백지 상태로 어음금 청구의 소를 제기했다가 시효 완성 후 변론종결 전에 백지를 보충해도 소 제기로 시효가 중단된 것으로 본다. 백지보충권의 시효와 어음금 채권의 시효를 구별한 것이다.","c":"상","v":1},"공인회2019_54-37-1":{"w":"추심위임배서는 피배서인에게 어음상 권리를 행사할 대리권을 줄 뿐 권리를 이전하지 않는다(어음법 제18조 제1항).","c":"상","v":1},"공인회2019_54-37-3":{"w":"어음법 제18조 제1항 단서가 추심위임배서의 피배서인은 대리를 위한 배서만 할 수 있다고 정하므로 다시 추심위임배서를 할 수 있다.","c":"상","v":1},"공인회2019_54-37-4":{"w":"추심위임배서의 피배서인은 배서인의 대리인 지위에서 어음상 모든 권리를 행사하고(어음법 제18조 제1항), 배서의 자격수여적 효력에 따라 대리권이 있는 것으로 추정된다.","c":"중","v":1},"공인회2019_54-37-5":{"w":"추심위임배서로는 권리가 이전되지 않으므로 배서인 B는 여전히 어음상 권리자다. 판례는 B가 어음을 회수했다면 그 배서를 말소하지 않아도 권리를 행사할 수 있다고 본다.","c":"중","v":1},"공인회2020_55-34-1":{"w":"무권대리인이 대리인으로서 어음에 기명날인하면 본인은 책임이 없다. 어음법 제8조에 따라 무권대리인 자신이 어음상 책임을 진다.","c":"상","v":1},"공인회2020_55-34-2":{"w":"판례는 어음행위에도 민법의 표현대리 규정이 적용된다고 보아 표현대리가 성립하면 본인 甲이 어음상 책임을 진다.","c":"상","v":1},"공인회2020_55-34-3":{"w":"표현대리는 상대방 보호 제도이므로 표현대리가 성립해도 무권대리인의 어음법 제8조 책임은 그대로 남는다. 소지인은 본인과 무권대리인 중 선택하여 청구할 수 있다는 것이 통설이다.","c":"중","v":1},"공인회2020_55-34-4":{"w":"대리권 있는 대리인이 본인을 위한 것임을 표시하고 기명날인하면 어음행위의 효과는 본인에게 귀속하므로 소지인은 甲에게 어음상 권리를 가진다.","c":"상","v":1},"공인회2021_56-38-4":{"w":"어음법 제37조 제1항이 발행지와 세력이 다른 지에서 확정일에 지급할 환어음의 만기일은 지급지의 세력에 따라 정한 것으로 본다고 정한다.","c":"상","v":1},"공인회2023_58-34-1":{"w":"어음법 제1조 제2호가 환어음 요건으로 조건 없이 일정한 금액을 지급할 것을 위탁하는 뜻을 정한다.","c":"상","v":1},"공인회2023_58-34-3":{"w":"어음법 제26조 제1항이 인수는 조건 없이 하되 지급인은 어음금액의 일부만 인수할 수 있다고 정한다.","c":"상","v":1},"공인회2023_58-34-4":{"w":"수표법 제15조 제1항이 배서에 붙인 조건은 적지 않은 것으로 본다고 정한다. 일부의 배서는 무효다(같은 조 제2항).","c":"상","v":1},"공인회2023_58-34-5":{"w":"수표법 제54조 제2항이 지급보증으로 수표의 기재사항을 변경한 부분은 변경하지 않은 것으로 본다고 정한다. 지급보증은 조건 없이 해야 한다(제1항).","c":"상","v":1},"공인회2021_56-36-2":{"w":"이득상환청구권은 어음상 권리가 소멸한 뒤 생기는 지명채권이어서 어음의 선의취득(어음법 제16조 제2항) 대상이 아니라는 것이 판례·통설이다.","c":"상","v":1},"공인회2021_56-36-3":{"w":"어음법 제16조 제2항 단서가 소지인이 악의 또는 중대한 과실로 취득한 경우 반환의무를 지운다. 선의취득이 부정되는 것이다.","c":"상","v":1},"공인회2021_56-36-4":{"w":"판례는 어음의 선의취득으로 치유되는 하자에 양도인이 무권리자인 경우뿐 아니라 대리권 흠결이나 양도행위의 하자 등도 포함된다고 본다.","c":"상","v":1},"공인회2021_56-36-5":{"w":"판례는 양도인이나 어음 자체에 양도인의 무권리를 의심할 사정이 있는데도 상당한 조사 없이 만연히 양수하면 중대한 과실을 인정한다.","c":"상","v":1},"공인회2018_53-38-1":{"w":"환어음은 만기와 수취인이 요건이지만(어음법 제1조 제4호·제6호) 수표는 일람출급이고(수표법 제28조) 소지인출급식도 허용되어(제5조) 둘 다 요건이 아니다(제1조).","c":"상","v":1},"공인회2021_56-33-1":{"w":"수표법 제38조 제1항이 일반횡선수표의 지급인은 은행 또는 지급인의 거래처에만 지급할 수 있다고 정한다.","c":"상","v":1},"공인회2021_56-33-2":{"w":"어음법 제5조 제1항이 이자 약정은 일람출급·일람후정기출급 어음에만 적을 수 있고 그 밖의 어음에는 적어도 적지 않은 것으로 본다고 정한다.","c":"상","v":1},"공인회2021_56-33-3":{"w":"어음법 제6조 제1항이 금액을 글자와 숫자로 적어 차이가 있으면 글자로 적은 금액을 어음금액으로 한다고 정한다. 제77조 제2항이 이를 약속어음에 준용한다.","c":"상","v":1},"공인회2021_56-33-4":{"w":"어음법 제59조 제1항이 참가지급은 만기나 만기 전에 상환청구권을 행사할 수 있는 모든 경우에 할 수 있다고 정한다. 지급은 피참가인이 지급할 전액으로 해야 한다(같은 조 제2항).","c":"상","v":1},"공인회2024_59-35-1":{"w":"어음법 제9조 제1항이 환어음 발행인은 인수와 지급을 담보한다고 정한다. 수표 발행인은 지급만 담보한다(수표법 제12조). 수표에는 인수 제도가 없다.","c":"상","v":1},"공인회2024_59-35-2":{"w":"수표법 제12조 후단이 지급무담보 문구는 적지 않은 것으로 본다고 정한다. 환어음 발행인은 인수무담보 문구는 적을 수 있다(어음법 제9조 제2항).","c":"상","v":1},"공인회2024_59-35-4":{"w":"판례는 요건이 빠진 어음은 백지어음으로 추정되므로 그것이 백지어음이 아닌 불완전어음이어서 무효라는 점은 발행인이 증명해야 한다고 본다.","c":"상","v":1},"공인회2024_59-35-5":{"w":"어음법 제78조 제1항이 약속어음 발행인은 환어음 인수인과 같은 의무를 부담한다고 정한다.","c":"상","v":1},"공인회2020_55-38-4":{"w":"어음법 제20조 제1항이 만기 후 배서도 지급거절증서 작성 전이나 작성기간 경과 전이면 만기 전 배서와 같은 효력이 있다고 정한다. 만기일 당일 배서는 이에 해당한다.","c":"상","v":1},"공인회2022_57-34-1":{"w":"어음법 제5조 제1항이 일람출급 또는 일람후정기출급 환어음에는 이자 약정을 적을 수 있다고 정한다. 이율도 적어야 효력이 있다(제2항).","c":"상","v":1},"공인회2022_57-34-2":{"w":"어음법 제6조 제1항이 금액을 글자와 숫자로 적어 차이가 있으면 글자로 적은 금액을 어음금액으로 한다고 정한다.","c":"상","v":1},"공인회2022_57-34-4":{"w":"판례는 확정일출급 어음에서 발행일이 만기보다 뒤로 적혀 있으면 어음요건의 기재가 그 자체로 불가능하여 무효라고 본다.","c":"상","v":1},"공인회2022_57-34-5":{"w":"어음법 제3조 제1항이 환어음은 발행인 자신을 지급받을 자로 하여 발행할 수 있다고 정한다(자기지시어음).","c":"상","v":1},"공인회2022_57-33-1":{"w":"어음법 제31조 제3항이 지급인이나 발행인이 아닌 자가 환어음 앞면에 단순히 기명날인 또는 서명하면 보증을 한 것으로 본다고 정한다.","c":"상","v":1},"공인회2022_57-39-2":{"w":"어음법 제39조 제2항이 소지인은 일부지급을 거절하지 못한다고 정한다. 상환의무자의 부담을 줄이기 위한 것이다.","c":"상","v":1},"공인회2022_57-39-3":{"w":"어음법 제40조 제3항이 만기에 지급하는 지급인은 사기 또는 중대한 과실이 없으면 책임을 면한다고 정한다. 배서의 연속은 조사하되 배서인의 기명날인·서명까지 조사할 의무는 없다.","c":"상","v":1},"공인회2022_57-39-4":{"w":"어음법 제38조 제1항이 확정일출급, 발행일자후정기출급, 일람후정기출급 어음의 소지인은 지급할 날 또는 그 후 2거래일 내에 지급제시를 하도록 정한다.","c":"상","v":1},"공인회2022_57-39-5":{"w":"어음법 제41조 제4항이 발행국과 지급국에서 명칭은 같으나 가치가 다른 통화로 금액을 정하면 지급지의 통화로 정한 것으로 추정한다고 정한다.","c":"상","v":1},"공인회2022_57-35-1":{"w":"어음법 제26조 제1항 단서가 지급인의 일부인수를 허용한다.","c":"상","v":1},"공인회2022_57-35-2":{"w":"어음법 제28조 제2항이 만기에 지급받지 못한 소지인은 상환청구할 수 있는 모든 금액에 관해 인수인에게 직접청구권을 가진다고 정한다.","c":"상","v":1},"공인회2022_57-35-3":{"w":"어음법 제26조 제2항이 기재사항을 변경한 인수는 인수거절로 보되 인수인은 그 인수 문구에 따라 책임을 진다고 정한다.","c":"상","v":1},"공인회2022_57-35-4":{"w":"어음법 제24조 제2항이 소지인은 인수를 위해 제시한 어음을 지급인에게 교부할 필요가 없다고 정한다.","c":"상","v":1},"공인회2016_51-34-2":{"w":"판례는 법인의 어음행위는 대표기관이 법인을 위한 것임을 표시하고 자기 기명날인을 해야 한다고 본다. 대표자 기명날인 없이 법인 명칭과 법인 인감만 찍은 것은 무효다.","c":"상","v":1},"공인회2016_51-36-1":{"w":"어음법 제2조 제3호가 지급지가 없으면 지급인 명칭에 부기한 지를 지급지 및 지급인의 주소지로 본다고 정한다.","c":"상","v":1},"공인회2016_51-36-2":{"w":"어음법 제2조 제4호가 발행지가 없으면 발행인 명칭에 부기한 지를 발행지로 본다고 정한다.","c":"상","v":1},"공인회2016_51-36-3":{"w":"어음법 제76조 제3항이 약속어음에 지급지가 없으면 발행지를 지급지 및 발행인의 주소지로 본다고 정한다.","c":"상","v":1},"공인회2016_51-36-5":{"w":"수표법 제2조 제2호가 지급지 기재와 지급인 명칭에 부기한 지가 모두 없으면 발행지에서 지급할 것으로 한다고 정한다.","c":"상","v":1},"공인회2017_52-38-5":{"w":"기한후배서인지는 배서한 날을 기준으로 정한다. 그래서 판례는 거절증서 작성기간 경과 전에 백지식배서로 취득한 자가 기간 경과 후 백지를 보충해도 기한후배서가 되지 않는다고 본다.","c":"상","v":1},"공인회2021_56-38-1":{"w":"어음법 제35조 제1항이 일람후정기출급 환어음의 만기는 인수한 날짜나 거절증서의 날짜에 따라 정한다고 정한다.","c":"상","v":1},"공인회2021_56-38-2":{"w":"어음법 제36조 제3항이 1개월 반 또는 수개월 반 후 지급할 환어음은 먼저 전월을 계산한다고 정한다.","c":"상","v":1},"공인회2021_56-38-5":{"w":"어음법 제36조 제1항이 1개월 또는 수개월 후 지급할 어음은 지급할 달의 대응일을 만기로 하고 대응일이 없으면 그 달의 말일로 한다고 정한다.","c":"상","v":1},"공인회2021_56-39-1":{"w":"어음법 제11조 제3항이 배서는 인수 여부와 관계없이 지급인, 발행인, 그 밖의 어음채무자에게도 할 수 있다고 정한다(환배서).","c":"상","v":1},"공인회2021_56-39-3":{"w":"어음법 제18조 제2항이 추심위임배서의 경우 어음채무자는 배서인에게 대항할 수 있는 항변으로만 소지인에게 대항할 수 있다고 정한다.","c":"상","v":1},"공인회2021_56-39-4":{"w":"어음법 제20조 제1항 단서가 지급거절증서 작성 후 또는 작성기간 경과 후의 배서는 지명채권 양도의 효력만 있다고 정한다. 이것이 기한후배서다.","c":"상","v":1},"공인회2021_56-39-5":{"w":"어음법 제11조 제2항이 발행인이 지시금지 문구를 적으면 지명채권 양도 방식과 효력으로만 양도할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-37-1":{"w":"어음법 제30조 제1항이 어음금액의 전부 또는 일부의 지급을 보증할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-37-2":{"w":"판례는 어음보증에 조건을 붙여도 보증 전체가 무효가 되지 않고 보증인은 그 조건부 보증에 따른 책임을 진다고 보아 조건을 유익적 기재사항으로 본다.","c":"상","v":1},"공인회2017_52-37-4":{"w":"어음법 제31조 제4항이 보증에는 누구를 위한 것인지 표시해야 하고 표시가 없으면 발행인을 위해 보증한 것으로 본다고 정한다.","c":"상","v":1},"공인회2017_52-37-5":{"w":"어음법 제31조 제3항이 지급인이나 발행인의 기명날인이 아닌 앞면의 단순한 기명날인 또는 서명을 보증으로 본다고 정한다.","c":"상","v":1},"공인회2018_53-39-1":{"w":"어음법 제16조 제2항이 사유를 묻지 않고 어음의 점유를 잃은 경우에 선의취득을 인정하므로 도난·유실 어음도 선의취득의 대상이다.","c":"상","v":1},"공인회2018_53-36-3":{"w":"원인관계가 취소되면 직접 당사자인 발행인 A는 수취인 B에게 원인관계 소멸을 인적항변으로 주장해 지급을 거절할 수 있다(어음법 제17조 반대해석, 제77조 제1항).","c":"상","v":1},"공인회2023_58-33-1":{"w":"어음법 제9조 제2항 후단이 환어음 발행인의 지급무담보 문구는 적지 않은 것으로 본다고 정한다.","c":"상","v":1},"공인회2023_58-33-2":{"w":"어음법 제9조 제2항 전단이 환어음 발행인은 인수를 담보하지 않는다는 내용을 적을 수 있다고 정한다.","c":"상","v":1},"공인회2023_58-33-4":{"w":"어음법 제53조 제2항이 발행인이 정한 기간 내에 인수제시를 하지 않은 소지인은 지급거절과 인수거절로 인한 상환청구권을 잃는다고 정한다. 문구로 보아 인수담보의무만 면할 의사였음을 알 수 있으면 예외다.","c":"상","v":1},"공인회2023_58-33-5":{"w":"어음법 제19조 제1항이 입질배서의 소지인은 어음상 모든 권리를 행사할 수 있으나 그가 한 배서는 대리를 위한 배서의 효력만 있다고 정한다.","c":"상","v":1},"공인회2020_55-33-4":{"w":"어음법 제4조가 환어음은 지급인의 주소지에 있든 다른 지에 있든 관계없이 제3자방에서 지급하는 것으로 할 수 있다고 정한다.","c":"상","v":1},"공인회2023_58-35-1":{"w":"어음법 제3조 제1항이 자기지시어음을, 제2항이 발행인 자신을 지급인으로 하는 자기앞어음을 허용한다.","c":"상","v":1},"공인회2023_58-35-2":{"w":"어음법 제4조가 지급인의 주소지에 있든 다른 지에 있든 관계없이 제3자방 지급 기재를 허용한다. 제3자방은 지급지 안에 있어야 한다는 것이 통설이다.","c":"중","v":1},"공인회2023_58-35-3":{"w":"수표법 제12조가 수표 발행인의 지급담보책임과 무담보 문구의 무익적 기재를 정한다.","c":"상","v":1},"공인회2023_58-35-4":{"w":"어음법 제8조 후단이 무권대리인이 어음금을 지급하면 본인과 같은 권리를 가진다고 정한다.","c":"상","v":1},"공인회2023_58-40-1":{"w":"어음법 제40조 제1항이 환어음 소지인은 만기 전에 지급을 받을 의무가 없다고 정한다.","c":"상","v":1},"공인회2023_58-40-2":{"w":"어음법 제40조 제2항이 만기 전에 지급하는 지급인은 자기의 위험부담으로 하는 것이라고 정한다. 만기 지급의 면책(제3항)이 적용되지 않는다.","c":"상","v":1},"공인회2023_58-40-4":{"w":"수표법 제35조 제1항이 배서로 양도할 수 있는 수표의 지급인은 배서의 연속은 조사하되 배서인의 기명날인·서명을 조사할 의무는 없다고 정한다.","c":"상","v":1},"공인회2023_58-40-5":{"w":"수표법 제35조 제2항이 제31조 제2항에 따른 정보처리시스템 지급제시에서는 지급인이 배서 연속 조사를 제시은행에 위임할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-36-3":{"w":"수표법 제15조 제3항이 지급인의 배서는 무효로 한다고 정한다. 수표 지급인은 어음상 채무를 지지 않는 구조이기 때문이다.","c":"상","v":1},"공인회2024_59-34-1":{"w":"어음법 제5조 제1항이 일람후정기출급 환어음에 이자 약정을 적을 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-34-3":{"w":"어음법 제5조 제2항이 이율을 적지 않으면 이자 약정을 하지 않은 것으로 본다고 정한다.","c":"상","v":1},"공인회2024_59-34-4":{"w":"어음법 제5조 제1항 후단이 확정일출급과 발행일자후정기출급 어음의 이자 약정은 적지 않은 것으로 본다고 정한다. 만기에 이자를 미리 계산해 금액에 넣을 수 있기 때문이다.","c":"상","v":1},"공인회2024_59-34-5":{"w":"수표법 제7조가 수표에 적은 이자 약정은 적지 않은 것으로 본다고 정한다.","c":"상","v":1},"공인회2024_59-39-2":{"w":"어음법 제40조 제2항이 만기 전에 지급하는 지급인은 자기의 위험부담으로 하는 것이라고 정한다. 만기 지급인의 면책(제3항)이 적용되지 않는다.","c":"상","v":1},"공인회2024_59-39-3":{"w":"수표법 제28조 제2항이 기재된 발행일 전에 제시된 수표도 제시된 날에 지급하도록 정한다(선일자수표). 수표는 일람출급이기 때문이다(제1항).","c":"상","v":1},"공인회2024_59-39-4":{"w":"수표법 제33조가 발행 후 발행인이 사망하거나 무능력자가 되어도 수표의 효력에 영향이 없다고 정한다.","c":"상","v":1},"공인회2024_59-39-5":{"w":"수표법 제32조 제1항이 지급위탁 취소는 제시기간 경과 후에만 효력이 있다고 정한다. 취소가 없으면 지급인은 제시기간 후에도 지급할 수 있다(같은 조 제2항).","c":"상","v":1},"공인회2019_54-33-1":{"w":"약속어음은 발행인이 주채무자이지만(어음법 제78조 제1항) 환어음은 지급인이 인수해야 주채무자가 생기므로(제28조 제1항) 인수 전에는 주채무자가 없다.","c":"상","v":1},"공인회2016_51-37-1":{"w":"어음법 제5조 제1항이 일람출급 환어음에 이자 약정을 적을 수 있다고 정한다.","c":"상","v":1},"공인회2016_51-37-2":{"w":"어음법 제5조 제1항이 일람후정기출급 환어음에도 이자 약정을 허용한다.","c":"상","v":1},"공인회2016_51-37-4":{"w":"어음법 제5조 제2항이 이율 기재가 없으면 이자를 약정하지 않은 것으로 본다고 정한다.","c":"상","v":1},"공인회2016_51-37-5":{"w":"어음법 제48조 제1항 제2호가 소지인은 상환청구로 연 6퍼센트 이율의 만기 이후 이자를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-37-2":{"w":"어음법 제20조 제1항 단서가 지급거절증서 작성 후 또는 작성기간 경과 후의 배서는 지명채권 양도의 효력만 있다고 정한다.","c":"상","v":1},"공인회2024_59-37-3":{"w":"어음법 제20조 제2항이 날짜를 적지 않은 배서는 거절증서 작성기간 경과 전에 한 것으로 추정한다고 정한다.","c":"상","v":1},"공인회2024_59-37-4":{"w":"기한후배서는 지명채권 양도 효력만 있어 인적항변이 절단되지 않는다. 판례도 어음채무자가 피배서인의 선의·악의와 관계없이 배서 당시 배서인에 대한 항변으로 대항할 수 있다고 본다.","c":"상","v":1},"공인회2024_59-37-5":{"w":"판례는 기한후배서는 지명채권 양도의 효력만 가질 뿐 그 방식은 배서이므로 민법상 지명채권 양도의 대항요건(통지·승낙)을 갖추지 않아도 권리가 이전된다고 본다.","c":"상","v":1},"공인회2018_53-33-1":{"w":"어음법 제12조 제3항이 소지인출급의 배서는 백지식 배서와 같은 효력이 있다고 정한다.","c":"상","v":1},"공인회2018_53-33-3":{"w":"어음법 제15조 제1항이 배서인은 반대 문구가 없으면 인수와 지급을 담보한다고 정한다.","c":"상","v":1},"공인회2018_53-33-4":{"w":"무담보 문구를 적은 배서인은 담보책임을 지지 않고(어음법 제15조 제1항), 이 효과는 직접 피배서인뿐 아니라 그 후의 모든 취득자에게 미친다. 배서금지배서(제2항)와 다르다.","c":"상","v":1},"공인회2018_53-33-5":{"w":"입질배서는 질권 설정을 목적으로 하므로 권리이전적 효력이 없고 피배서인은 질권자로서 권리를 행사한다(어음법 제19조).","c":"상","v":1},"공인회2024_59-33-1":{"w":"어음법 제1조 제1호가 증권 본문 중에 작성 국어로 환어음임을 표시하는 글자를 요건으로 정한다.","c":"상","v":1},"공인회2024_59-33-2":{"w":"어음법 제2조 제1호가 만기가 적혀 있지 않으면 일람출급 환어음으로 본다고 정한다.","c":"상","v":1},"공인회2024_59-33-4":{"w":"어음법 제2조 제4호가 발행지가 없으면 발행인 명칭에 부기한 지를 발행지로 본다고 정한다.","c":"상","v":1},"공인회2024_59-33-5":{"w":"어음법 제1조 제6호가 지급받을 자 또는 지급받을 자를 지시할 자의 명칭을 환어음 요건으로 정한다.","c":"상","v":1},"공인회2018_53-37-3":{"w":"어음법 제26조 제2항이 기재사항(만기 포함)을 변경한 인수는 인수거절로 보되 인수인은 그 문구에 따라 책임진다고 정한다.","c":"상","v":1},"공인회2021_56-37-1":{"w":"어음법 제11조 제3항이 인수한 지급인에게도 배서할 수 있다고 정한다. 그 지급인은 다시 배서할 수 있다.","c":"상","v":1},"공인회2021_56-37-2":{"w":"어음법 제29조 제1항이 인수를 기재한 지급인이 어음 반환 전에 말소하면 인수를 거절한 것으로 본다고 정한다. 말소는 반환 전에 한 것으로 추정한다.","c":"상","v":1},"공인회2021_56-37-4":{"w":"어음법 제25조 제1항 후단이 어음 앞면의 지급인의 단순한 기명날인 또는 서명을 인수로 본다고 정한다.","c":"상","v":1},"공인회2021_56-37-5":{"w":"어음법 제22조 제3항이 발행인은 일정한 기일 전의 인수제시를 금지할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-38-1":{"w":"어음법 제26조 제2항이 기재사항을 변경한 인수는 인수거절로 보되 인수인은 그 인수 문구에 따라 책임진다고 정한다.","c":"상","v":1},"공인회2024_59-38-3":{"w":"어음법 제22조 제3항이 발행인은 일정한 기일 전의 인수제시를 금지할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-38-4":{"w":"어음법 제22조 제1항이 발행인은 기간을 정하거나 정하지 않고 인수제시를 명할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-38-5":{"w":"어음법 제25조 제1항 후단이 어음 앞면에 지급인의 단순한 기명날인 또는 서명이 있으면 인수로 본다고 정한다.","c":"상","v":1},"공인회2019_54-35-1":{"w":"어음법 제22조 제1항이 발행인은 기간을 정하거나 정하지 않고 인수제시를 명하는 문구를 적을 수 있다고 정한다.","c":"상","v":1},"공인회2019_54-35-2":{"w":"어음법 제22조 제2항 단서가 제3자방 지급 어음, 지급인 주소지 아닌 지에서 지급할 어음, 일람후정기출급 어음은 인수제시 금지를 적을 수 없다고 정한다.","c":"상","v":1},"공인회2019_54-35-4":{"w":"일람후정기출급 어음은 발행일부터 1년 내에 인수제시를 해야 하고(어음법 제23조 제1항) 발행인은 이 기간을 단축하거나 연장할 수 있으므로(제2항) 6개월로 정할 수 있다.","c":"상","v":1},"공인회2019_54-35-5":{"w":"어음법 제24조 제1항이 지급인은 첫 번째 제시일의 다음 날에 두 번째 제시를 할 것을 청구할 수 있다고 정한다(숙려기간).","c":"상","v":1},"공인회2017_52-36-1":{"w":"이득상환청구권은 완성된 어음상 권리가 시효나 절차 흠결로 소멸한 경우에 생긴다(어음법 제79조). 판례는 백지를 보충하지 않은 미완성어음은 어음상 권리가 성립하지 않은 상태이므로 이득상환청구권이 생기지 않는다고 본다.","c":"상","v":1},"공인회2017_52-36-3":{"w":"판례와 통설은 이득상환청구권을 어음상 권리가 아닌 지명채권으로 보므로 어음의 선의취득 규정(어음법 제16조 제2항)이 적용되지 않는다고 한다.","c":"상","v":1},"공인회2017_52-36-4":{"w":"어음법 제79조는 어음상 권리가 절차 흠결이나 시효로 소멸한 경우에 이득상환청구권을 인정한다. 선의취득으로 권리를 잃은 자는 이 요건에 해당하지 않는다.","c":"중","v":1},"공인회2017_52-39-5":{"w":"판례는 장래 발생할 구상금채무를 담보하려고 발행한 어음은 그 채무가 현실로 발생해야 어음상 권리를 행사할 수 있으므로 피담보채무가 발생한 때를 시효의 기산점으로 본다.","c":"중","v":1},"공인회2021_56-35-2":{"w":"수표법 제58조가 지급보증을 한 지급인에 대한 청구권은 제시기간이 지난 후 1년간 행사하지 않으면 시효로 소멸한다고 정한다.","c":"상","v":1},"공인회2021_56-35-3":{"w":"어음법 제70조 제3항이 배서인의 다른 배서인과 발행인에 대한 청구권은 환수한 날 또는 제소된 날부터 6개월이 지나면 시효로 소멸한다고 정한다.","c":"상","v":1},"공인회2021_56-35-4":{"w":"수표법 제51조 제1항이 소지인의 상환청구권은 제시기간이 지난 후 6개월간 행사하지 않으면 시효로 소멸한다고 정한다.","c":"상","v":1},"공인회2021_56-35-5":{"w":"어음법 제70조 제1항이 인수인에 대한 환어음상 청구권은 만기일부터 3년간 행사하지 않으면 시효로 소멸한다고 정한다.","c":"상","v":1},"공인회2016_51-35-2":{"w":"판례는 어음채무자가 자기 기명날인의 위조를 주장하면 어음소지인이 그 기명날인이 진정함을 증명해야 한다고 본다.","c":"상","v":1},"공인회2016_51-35-3":{"w":"위조된 어음행위는 피위조자에게 처음부터 효력이 없으므로 위조의 항변은 물적항변이다. 판례는 피위조자가 소지인의 선의·악의와 관계없이 이를 주장할 수 있다고 본다.","c":"상","v":1},"공인회2016_51-35-4":{"w":"어음법 제69조와 수표법 제50조가 변조 전에 기명날인 또는 서명한 자는 원래 문구에 따라 책임을 진다고 정한다.","c":"상","v":1},"공인회2016_51-35-5":{"w":"어음법 제69조와 수표법 제50조가 변조 후에 기명날인 또는 서명한 자는 변조된 문구에 따라 책임을 진다고 정한다.","c":"상","v":1},"공인회2016_51-39-2":{"w":"어음법 제70조 제2항이 소지인의 배서인과 발행인에 대한 청구권은 적법 기간 내 작성한 거절증서 날짜부터 1년이 지나면 시효로 소멸한다고 정한다. 무비용상환 문구가 있으면 만기일부터 1년이다.","c":"상","v":1},"공인회2016_51-39-3":{"w":"어음법 제70조 제3항이 배서인의 다른 배서인과 발행인에 대한 청구권은 환수한 날 또는 제소된 날부터 6개월이 지나면 시효로 소멸한다고 정한다.","c":"상","v":1},"공인회2016_51-39-4":{"w":"수표법 제51조 제1항이 소지인의 배서인, 발행인, 그 밖의 채무자에 대한 상환청구권은 제시기간 경과 후 6개월이 지나면 시효로 소멸한다고 정한다.","c":"상","v":1},"공인회2016_51-39-5":{"w":"수표법 제51조 제2항이 수표 채무자의 다른 채무자에 대한 상환청구권은 환수한 날 또는 제소된 날부터 6개월이 지나면 시효로 소멸한다고 정한다.","c":"상","v":1},"공인회2017_52-39-2":{"w":"어음법 제70조 제2항 후단이 무비용상환 문구가 있으면 소지인의 배서인·발행인에 대한 청구권 시효를 만기일부터 1년으로 정한다. 거절증서가 없으므로 기산점을 만기일로 한 것이다.","c":"상","v":1},"공인회2017_52-39-3":{"w":"어음법 제70조 제3항이 재상환청구권의 시효를 환수일 또는 제소일부터 6개월로 정한다.","c":"상","v":1},"공인회2017_52-39-4":{"w":"판례는 시효가 완성된 채무를 일부 변제하면 액수에 다툼이 없는 한 채무 전체를 묵시적으로 승인하고 시효이익을 포기한 것으로 추정한다.","c":"상","v":1},"공인회2017_52-34-1":{"w":"어음법 제18조 제2항이 추심위임배서에서 어음채무자는 배서인에게 대항할 수 있는 항변으로만 소지인에게 대항할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-34-2":{"w":"어음법 제19조 제2항이 입질배서에서 어음채무자는 소지인이 채무자를 해할 것을 알고 취득한 경우가 아니면 배서인에 대한 인적항변으로 소지인에게 대항하지 못한다고 정한다. 질권자는 고유한 이익이 있기 때문이다.","c":"상","v":1},"공인회2017_52-34-3":{"w":"어음요건 흠결이나 시효 소멸은 어음 자체의 효력이나 권리 존부에 관한 물적항변이어서 모든 소지인에게 대항할 수 있다.","c":"상","v":1},"공인회2017_52-34-5":{"w":"판례는 어음법 제17조 단서의 해의를 항변사유의 존재 인식만으로 인정하지 않는다. 자기 취득으로 항변이 절단되어 채무자가 손해를 입게 된다는 사정까지 알아야 한다.","c":"상","v":1},"공인회2021_56-34-1":{"w":"판례가 정의하는 융통어음이다. 상거래 대가 없이 피융통자가 제3자에게 할인 등으로 금융을 얻게 하려고 발행·교부하는 어음이다.","c":"상","v":1},"공인회2021_56-34-2":{"w":"판례는 융통어음 발행인이 피융통자에게는 어음상 책임을 지지 않는다고 본다. 융통 사실은 직접 당사자 사이의 인적항변이 된다.","c":"상","v":1},"공인회2021_56-34-3":{"w":"어음법 제20조 제1항 단서가 기한후배서에 지명채권 양도의 효력만 주므로 인적항변 절단(제17조)이 생기지 않는다.","c":"상","v":1},"공인회2021_56-34-4":{"w":"어음법 제17조 단서가 소지인이 채무자를 해할 것을 알고 취득하면 인적항변 절단이 일어나지 않는다고 정한다(악의의 항변).","c":"상","v":1},"공인회2017_52-36-5":{"w":"판례는 이득상환의무자가 반환할 이득을 어음금이 아니라 원인관계에서 실제로 얻은 이익, 발행인의 경우 수취인에게서 받은 대가로 본다.","c":"상","v":1},"공인회2016_51-40-1":{"w":"어음법 제43조 전단이 만기에 지급되지 않으면 소지인이 배서인, 발행인, 그 밖의 채무자에게 상환청구권을 행사할 수 있다고 정한다.","c":"상","v":1},"공인회2016_51-40-2":{"w":"어음법 제43조 제1호가 인수의 전부 또는 일부 거절을 만기 전 상환청구 사유로 정한다.","c":"상","v":1},"공인회2016_51-40-3":{"w":"어음법 제44조 제3항이 확정일출급, 발행일자후정기출급, 일람후정기출급 어음의 지급거절증서는 지급할 날 이후 2거래일 내에 작성하도록 정한다.","c":"상","v":1},"공인회2016_51-40-4":{"w":"어음법 제44조 제3항 후단이 일람출급 어음의 지급거절증서는 인수제시에 관한 조건에 따라 작성하도록 정한다. 인수제시 기간 내에 작성해야 한다는 뜻이다.","c":"상","v":1},"공인회2023_58-36-1":{"w":"어음법 제43조가 만기에 지급되지 않으면 소지인이 발행인, 배서인, 그 밖의 어음채무자에게 상환청구권을 행사할 수 있다고 정한다.","c":"상","v":1},"공인회2023_58-36-2":{"w":"어음법 제45조 제1항이 소지인은 거절증서 작성일 이후 4거래일 내에 자기의 배서인과 발행인에게 거절 사실을 통지하도록 정한다.","c":"상","v":1},"공인회2023_58-36-3":{"w":"어음법 제46조 제1항이 발행인, 배서인, 보증인은 무비용상환 또는 거절증서 불필요 문구를 적고 기명날인·서명해 거절증서 작성을 면제할 수 있다고 정한다.","c":"상","v":1},"공인회2023_58-36-5":{"w":"어음법 제46조 제3항이 발행인이 면제 문구를 적었는데도 소지인이 거절증서를 작성하면 그 비용은 소지인이 부담한다고 정한다.","c":"상","v":1},"공인회2024_59-40-1":{"w":"어음법 제50조 제2항이 환어음을 환수한 배서인은 자기와 후자의 배서를 말소할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-40-2":{"w":"어음법 제50조 제1항이 상환청구를 받은 채무자는 지급과 상환으로 거절증서, 영수 계산서, 어음의 교부를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-40-3":{"w":"어음법 제51조가 일부인수 후 상환청구에서 인수되지 않은 금액을 지급하는 자는 지급 사실의 어음 기재와 영수증 교부를 청구할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-40-4":{"w":"어음법 제52조 제1항이 반대 문구가 없으면 상환청구권자는 전자 중 1명을 지급인으로 하는 일람출급의 새 어음(역어음)을 발행해 상환청구권을 행사할 수 있다고 정한다.","c":"상","v":1},"공인회2019_54-39-1":{"w":"수표법 제6조 제1항이 수표는 발행인 자신을 지급받을 자로 하여 발행할 수 있다고 정한다(자기지시수표).","c":"상","v":1},"공인회2019_54-39-2":{"w":"수표법 제5조 제2항이 기명식 수표에 또는 소지인에게라는 글자를 적으면 소지인출급식 수표로 본다고 정한다(선택무기명식).","c":"상","v":1},"공인회2019_54-39-3":{"w":"수표법 제28조 제1항이 수표는 일람출급으로 하고 이에 위반되는 문구는 적지 않은 것으로 본다고 정한다.","c":"상","v":1},"공인회2019_54-39-4":{"w":"수표법 제34조 제2항이 소지인은 일부지급을 거절하지 못한다고 정한다.","c":"상","v":1},"공인회2019_54-40-4":{"w":"국내 수표의 지급제시기간은 10일이므로(수표법 제29조 제1항) 1개월 뒤의 배서는 제시기간 경과 후 배서로서 지명채권 양도의 효력만 있다(제24조 제1항). 그래서 B는 담보책임에 따른 상환의무를 지지 않는다.","c":"상","v":1},"공인회2020_55-39-1":{"w":"수취인을 적지 않은 수표는 소지인출급식으로 보므로(수표법 제5조 제3항) 교부만으로 양도할 수 있다.","c":"상","v":1},"공인회2020_55-39-3":{"w":"지시식 수표는 배서로 양도할 수 있다(수표법 제14조 제1항).","c":"상","v":1},"공인회2020_55-39-4":{"w":"선택무기명식 수표는 소지인출급식으로 보므로(수표법 제5조 제2항) 배서 없이 교부만으로 양도할 수 있다.","c":"상","v":1},"공인회2020_55-39-5":{"w":"수표법 제14조 제2항이 기명식 수표에 지시금지 문구를 적으면 지명채권 양도 방식과 효력으로만 양도할 수 있다고 정한다.","c":"상","v":1},"공인회2021_56-40-1":{"w":"수표법 제7조가 수표에 적은 이자 약정은 적지 않은 것으로 본다고 정한다. 수표는 일람출급이어서 이자를 붙일 여지가 없다.","c":"상","v":1},"공인회2021_56-40-2":{"w":"수표법 제4조가 수표는 인수하지 못하고 인수 문구는 적지 않은 것으로 본다고 정한다. 신용증권화를 막으려는 것이다.","c":"상","v":1},"공인회2021_56-40-3":{"w":"수표법 제15조 제4항이 소지인출급 배서는 백지식 배서와 같은 효력이 있다고 정한다.","c":"상","v":1},"공인회2021_56-40-5":{"w":"수표법 제12조 후단이 발행인의 지급무담보 문구는 적지 않은 것으로 본다고 정한다.","c":"상","v":1},"공인회2022_57-37-4":{"w":"수표법 제20조가 소지인출급 수표에 배서한 자는 상환청구에 관한 규정에 따라 책임을 지되 그 수표가 지시식으로 바뀌지는 않는다고 정한다.","c":"상","v":1},"공인회2023_58-37-1":{"w":"수표법 제26조 제1항이 보증은 수표 또는 보충지에 하도록 정한다. 지급보증은 수표의 앞면에 해야 한다(제53조 제2항).","c":"상","v":1},"공인회2023_58-37-3":{"w":"수표법 제26조 제3항이 발행인이나 지급인이 아닌 자의 앞면 단순 기명날인 또는 서명을 보증으로 본다고 정한다.","c":"상","v":1},"공인회2023_58-37-4":{"w":"수표법 제27조 제3항이 지급한 보증인은 보증된 자와 그 자의 수표상 채무자에게 수표상 권리를 취득한다고 정한다.","c":"상","v":1},"공인회2023_58-37-5":{"w":"수표법 제55조 제1항이 지급보증인은 제시기간 내 제시된 경우에만 지급의무를 진다고 정한다. 발행인 등은 지급보증으로 책임을 면하지 못한다(제56조).","c":"상","v":1},"공인회2022_57-40-1":{"w":"수표법 제24조 제2항이 날짜 없는 배서는 거절증서 등 작성 전 또는 제시기간 경과 전에 한 것으로 추정한다고 정한다.","c":"상","v":1},"공인회2022_57-40-2":{"w":"수표법 제16조 제2항 후단이 백지식 배서는 수표의 뒷면이나 보충지에 하지 않으면 효력이 없다고 정한다.","c":"상","v":1},"공인회2022_57-40-3":{"w":"수표법 제19조 후단이 백지식 배서 다음에 다른 배서가 있으면 그 배서를 한 자는 백지식 배서로 수표를 취득한 것으로 본다고 정한다.","c":"상","v":1},"공인회2022_57-40-5":{"w":"수표법 제17조 제2항 제3호가 백지식 배서의 소지인은 백지를 보충하지 않고 배서도 하지 않은 채 교부만으로 양도할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-35-1":{"w":"수표법 제2조 제1호 후단이 지급인 명칭에 여러 지를 부기하면 수표의 맨 앞에 적은 지에서 지급할 것으로 한다고 정한다.","c":"상","v":1},"공인회2017_52-35-3":{"w":"전원합의체 판례(1999년)는 국내수표는 발행지 기재가 없어도 유효하다고 보아 국내어음과 같이 취급한다.","c":"상","v":1},"공인회2017_52-35-4":{"w":"판례는 발행일란에 기재가 없어도 수표면의 다른 부분에 일정한 날이 표시되어 있으면 그 날을 발행일로 보아야 한다고 본다.","c":"중","v":1},"공인회2017_52-35-5":{"w":"수표법 제14조 제2항이 기명식 수표에 지시금지 문구를 적으면 지명채권 양도 방식과 효력으로만 양도할 수 있다고 정한다.","c":"상","v":1},"공인회2017_52-40-5":{"w":"수표법 제32조 제1항이 지급위탁 취소는 제시기간이 지난 후에만 효력이 생긴다고 정한다.","c":"상","v":1},"공인회2018_53-34-1":{"w":"수표법 제55조 제1항이 지급보증을 한 지급인은 제시기간 경과 전에 제시된 경우에만 지급의무를 진다고 정한다.","c":"상","v":1},"공인회2018_53-34-3":{"w":"수표법 제58조가 지급보증인에 대한 청구권은 제시기간 경과 후 1년간 행사하지 않으면 시효로 소멸한다고 정한다.","c":"상","v":1},"공인회2018_53-34-4":{"w":"수표법 제53조 제2항이 지급보증은 수표 앞면에 지급보증 또는 지급하겠다는 뜻을 적고 날짜를 부기해 지급인이 기명날인하거나 서명하도록 정한다.","c":"상","v":1},"공인회2018_53-34-5":{"w":"수표법 제54조 제1항이 지급보증은 조건 없이 하도록 정한다. 지급보증으로 기재사항을 변경한 부분은 변경하지 않은 것으로 본다(같은 조 제2항).","c":"상","v":1},"공인회2020_55-21-2":{"w":"상법 제382조의3은 이사가 법령과 정관에 따라 직무를 충실하게 수행하도록 정한다. 2025.7.22. 개정으로 그 대상이 「회사 및 주주」로 넓어지고 총주주의 이익 보호 의무(제2항)가 더해졌지만 회사를 위한 충실의무는 그대로다.","c":"중","v":1},"공인회2021_56-23-5":{"w":"상법 제382조의3은 이사가 법령과 정관에 따라 직무를 충실하게 수행하도록 정한다. 2025.7.22. 개정으로 그 대상이 「회사 및 주주」로 넓어지고 총주주의 이익 보호 의무(제2항)가 더해졌지만 회사를 위한 충실의무는 그대로다.","c":"중","v":1},"공인회2021_56-01-5":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 지배인 등기는 영업소 소재지에서 하되 회사는 본점 소재지에서만 하므로, 상인 일반에 대해 본점 또는 지점 소재지라고 한 이 문장은 틀린 문장이다(상법 제13조)."},"공인회2023_58-03-3":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 지점 소재지 등기를 정한 제35조가 삭제되어 본점 등기사항을 지점에서 다시 등기하지 않으므로 틀린 문장이다(상법 제35조 삭제)."},"공인회2023_58-03-4":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 지점 소재지 등기 제도와 함께 제38조가 삭제되어 이 규정은 더 이상 없으므로 틀린 문장이다(상법 제38조 삭제)."},"공인회2019_54-10-5":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 유한책임회사 업무집행자의 직무집행정지·직무대행자 선임 가처분 등기는 본점이 있는 곳의 등기소에서만 하므로 틀린 문장이다(상법 제287조의5 제5항)."},"공인회2016_51-25-3":{"old":1,"ow":"출제 당시 정답 O. 2025.9.9 개정(2026.9.10 시행)으로 대규모 상장회사는 정관으로 집중투표를 배제할 수 없게 되면서 배제 의안을 따로 상정하라는 제542조의7 제4항이 삭제되었으므로 틀린 문장이다(상법 제542조의7 제3항, 제4항 삭제)."},"공인회2016_51-25-4":{"old":1,"ow":"출제 당시 정답 O. 2025.9.9 개정(2026.9.10 시행)으로 대규모 상장회사는 정관으로 집중투표를 배제할 수 없게 되어, 배제 정관을 바꿀 때 3% 초과분 의결권을 막던 규정이 없어졌으므로 틀린 문장이다(상법 제542조의7 제3항)."},"공인회2020_55-22-4":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 결의취소 판결이 확정되면 본점 소재지에서만 등기하므로 틀린 문장이다(상법 제378조)."},"공인회2023_58-21-1":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 지점 소재지 등기가 없어져 결의부존재 확인판결이 확정되면 본점 소재지에서만 등기하므로 틀린 문장이다(상법 제380조, 제378조)."},"공인회2017_52-17-2":{"old":1,"ow":"출제 당시 정답 O. 대법원 2017.3.23. 선고 2016다251215 전원합의체 판결로 판례가 바뀌어, 감사는 주주총회 선임결의와 피선임자의 승낙만으로 지위를 취득하고 대표이사와 임용계약을 맺을 필요가 없으므로 틀린 문장이다."},"공인회2020_55-19-3":{"old":1,"ow":"출제 당시 정답 O. 2020.12.29 개정으로 다중대표소송이 명문화되어 모회사 주주가 자회사 이사의 책임을 묻는 소를 낼 수 있으므로 지금은 틀린 문장이다(상법 제406조의2)."},"공인회2018_53-09-5":{"old":1,"ow":"출제 당시 정답 O. 2020년 개정(2020.12.29 시행)으로 이 내용을 정한 상법 제350조 제3항이 삭제되었다. 지금은 전환 시기와 관계없이 배당기준일의 주주에게 같은 조건으로 배당하므로 정관으로 직전 영업연도 말 전환을 의제하는 규정이 없다."}};
